function formatEditableScenePrompt(meta) {
    if (!meta) return '';
    const base = String(meta.desc || meta.prompt || '').trim();
    const caps = Array.isArray(meta.charCaptions) ? meta.charCaptions.filter(Boolean) : [];
    const panels = Array.isArray(meta.panelPrompts) ? meta.panelPrompts.filter(Boolean) : [];
    const quotes = Array.isArray(meta.comicQuotes) ? meta.comicQuotes.filter(q => q && q.text) : [];
    const showBase = panels.length < 2 ? base : '';
    return [
        showBase,
        ...(panels.length < 2 ? caps.map((c, idx) => `CHAR${idx + 1}: ${c}`) : []),
        ...panels.map((p, idx) => `PANEL${idx + 1}: ${p}`),
        ...quotes.map((q, idx) => `QUOTE${idx + 1}: ${q.kind === 'thought' ? `THOUGHT | ${q.speaker || ''} | ` : (q.kind === 'narration' || !q.speaker ? 'NARRATION | ' : `${q.speaker} | `)}${q.text}`),
    ].filter(Boolean).join('\n');
}

function applyEditedScenePromptToMeta(meta, rawText) {
    if (!meta) return;
    const text = String(rawText || '').trim();
    if (!text) return;
    const baseLines = [];
    const newCaps = [];
    const newPanels = [];
    const newQuotes = [];
    for (const line of text.split(/\r?\n/)) {
        const trimmed = line.trim();
        if (!trimmed) continue;
        let m = trimmed.match(/^CHAR\s*(\d+)\s*[:：—–-]\s*(.+)$/i);
        if (m) {
            const cap = m[2].trim().replace(/\]$/, '');
            if (cap) newCaps.push(cap);
            continue;
        }
        m = trimmed.match(/^PANEL\s*(\d+)\s*[:：—–-]\s*(.+)$/i);
        if (m) {
            const pTxt = m[2].trim().replace(/\]$/, '');
            if (pTxt) newPanels.push(pTxt);
            continue;
        }
        m = trimmed.match(/^QUOTE\s*(\d*)\s*[:：—–-]\s*(.+)$/i);
        if (m) {
            const parsedQObj = parseRawQuoteLinePayload(m[2], Number(m[1]) || (newQuotes.length + 1));
            if (parsedQObj) newQuotes.push(parsedQObj);
            continue;
        }
        baseLines.push(trimmed.replace(/^SCENE\s*[:：—–-]\s*/i, ''));
    }
    if (baseLines.length) {
        meta.desc = baseLines.join(', ').replace(/,\s*,+/g, ', ').trim();
    } else if (newPanels.length) {
        meta.desc = newPanels[0].split(/\s*\|\|\s*CHAR\s*\d+\s*[:：—–-]/i)[0].trim();
    }
    meta.prompt = meta.desc || (newPanels[0] ? newPanels[0].split(/\s*\|\|\s*CHAR\s*\d+\s*[:：—–-]/i)[0].trim() : '');
    meta.charCaptions = newCaps;
    if (newPanels.length) meta.panelPrompts = newPanels;
    if (newQuotes.length || /QUOTE\s*\d*\s*[:：—–-]/i.test(text)) meta.comicQuotes = newQuotes;
}

function hasValidSceneMeta(m) {
    return !!(m && (m.prompt || m.desc || (Array.isArray(m.panelPrompts) && m.panelPrompts.length)));
}

function findSavedSceneMeta(mesId) {
    const c = ctx();
    const st = store();
    if (Number.isInteger(mesId) && hasValidSceneMeta(c.chat?.[mesId]?.extra?.nnbScene)) {
        return c.chat[mesId].extra.nnbScene;
    }
    if (!Number.isInteger(mesId) && Array.isArray(c.chat)) {
        for (let i = c.chat.length - 1; i >= 0; i--) {
            if (c.chat[i] && !c.chat[i].is_system) {
                if (hasValidSceneMeta(c.chat[i].extra?.nnbScene)) return c.chat[i].extra.nnbScene;
                break;
            }
        }
    }
    if (hasValidSceneMeta(st?.lastSceneMeta)) return st.lastSceneMeta;
    return null;
}

async function askSceneCameraMode(existingMeta = null, forceAsk = false, mesId = undefined) {
    const mode = settings().sceneCameraMode || 'ask';
    if (!forceAsk && mode !== 'ask' && !hasValidSceneMeta(existingMeta)) return { mode };
    return new Promise(resolve => {
        const el = $('<div class="nnb-pop"><h3>🎬 Как нарисовать эту сцену?</h3></div>');
        let settled = false;
        const finish = val => {
            if (settled) return;
            settled = true;
            if (val) {
                try { startBackgroundGenerationKeepAlive(); } catch (e) { /* ignore */ }
            }
            closePopupOf(el);
            resolve(val);
        };

        if (hasValidSceneMeta(existingMeta)) {
            const reuseBox = $('<div class="nnb-note" style="padding:10px 12px; margin-bottom:10px; border-color:var(--SmartThemeQuoteColor, #8b78c4); background:color-mix(in srgb, var(--SmartThemeQuoteColor, #8b78c4) 12%, transparent);"></div>');
            reuseBox.append('<div style="font-weight:700; margin-bottom:4px;">🔄 Уже есть готовый промпт для этой сцены</div>');
            const previewText = existingMeta.desc || existingMeta.prompt;
            reuseBox.append($('<div class="nnb-npc-status" style="font-size:0.82em; margin-bottom:8px; max-height:70px; overflow-y:auto;"></div>').text(previewText));
            const reuseBtns = $('<div style="display:flex; gap:8px; flex-wrap:wrap;"></div>');
            const sameBtn = $('<div class="menu_button nnb-btn-primary" style="margin:0;"><i class="fa-solid fa-rotate"></i> Перерисовать по тому же промпту (без создания нового)</div>').on('click', () => {
                finish({ mode: existingMeta.camMode || 'third', reuseMeta: existingMeta });
            });
            const editPromptBtn = $('<div class="menu_button" style="margin:0;"><i class="fa-solid fa-pen"></i> Подправить промпт и перерисовать</div>').on('click', async () => {
                const edited = await askText('Промпт сцены на английском (и слоты CHAR1 / CHAR2, если есть):', formatEditableScenePrompt(existingMeta));
                if (edited && edited.trim()) {
                    const cloned = structuredClone(existingMeta);
                    applyEditedScenePromptToMeta(cloned, edited.trim());
                    finish({
                        mode: existingMeta.camMode || 'third',
                        reuseMeta: cloned,
                    });
                }
            });
            reuseBtns.append(sameBtn, editPromptBtn);
            reuseBox.append(reuseBtns);
            if (Array.isArray(existingMeta.history) && existingMeta.history.length > 1) {
                const histRow = $('<div style="margin-top:8px; padding-top:8px; border-top:1px solid var(--SmartThemeBorderColor);"></div>');
                histRow.append($('<div style="font-size:0.82em; font-weight:600; margin-bottom:6px;"></div>').text(`🖼 Сохранённые варианты этой сцены (${existingMeta.history.length}) — нажми, чтобы поставить в пост:`));
                const thumbs = $('<div style="display:flex; gap:8px; overflow-x:auto; padding-bottom:4px;"></div>');
                existingMeta.history.forEach((hUrl, hIdx) => {
                    const thWrap = $('<div style="display:flex; flex-direction:column; align-items:center; gap:3px; cursor:pointer;"></div>');
                    const th = $('<img alt="" style="width:68px; height:68px; object-fit:cover; border-radius:8px; border:2px solid transparent;">').attr('src', hUrl);
                    if (hUrl === existingMeta.url) th.css('border-color', 'var(--SmartThemeQuoteColor, #e0c068)');
                    const lbl = $('<span style="font-size:0.75em;"></span>').text(`Вариант ${hIdx + 1}`);
                    thWrap.append(th, lbl);
                    thWrap.on('click', async () => {
                        await attachToLastMessage(hUrl, existingMeta.mesId, { ...existingMeta, url: hUrl });
                        finish(null);
                    });
                    thumbs.append(thWrap);
                });
                histRow.append(thumbs);
                reuseBox.append(histRow);
            }
            el.append(reuseBox);
        }

        const st = store();
        const names = storyNames();
        const selectedCast = new Set();

        const castBox = $('<div class="nnb-note" style="padding:8px 10px; margin:6px 0;"></div>');
        castBox.append('<div style="font-size:0.84em; font-weight:600; margin-bottom:4px;">👥 Кто в кадре? <span style="font-weight:400; opacity:0.8;">(оставь «Авто по тексту» или отметь вручную, чтобы никого не потерять)</span></div>');
        const castChips = $('<div class="nnb-chips-row" style="justify-content:flex-start; gap:6px;"></div>');
        const autoChip = $('<div class="nnb-travel-chip active" style="font-size:0.8em; padding:3px 8px;" tabindex="0">✨ Авто по тексту поста</div>');
        const candidateNames = [names.user, ...(names.chars || [names.char]), ...((st?.npcs || []).slice(0, 35).map(n => n.name))].filter((v, i, a) => v && a.indexOf(v) === i);

        const syncCastChips = () => {
            autoChip.toggleClass('active', selectedCast.size === 0);
            castChips.find('.nnb-cast-person').each(function () {
                const nm = $(this).attr('data-name');
                $(this).toggleClass('active', selectedCast.has(nm));
            });
        };
        autoChip.on('click', () => {
            selectedCast.clear();
            syncCastChips();
        });
        castChips.append(autoChip);
        candidateNames.forEach(cName => {
            const ch = $('<div class="nnb-travel-chip nnb-cast-person" style="font-size:0.8em; padding:3px 8px;" tabindex="0"></div>').attr('data-name', cName).text(cName);
            ch.on('click', () => {
                if (selectedCast.has(cName)) selectedCast.delete(cName);
                else selectedCast.add(cName);
                syncCastChips();
            });
            castChips.append(ch);
        });
        castBox.append(castChips);
        el.append(castBox);

        const getForcedCast = () => (selectedCast.size ? [...selectedCast] : null);

        // Поле «✎ Шёпот режиссёру» (как в Мяфля · Кадр)
        const whisperBox = $('<div class="nnb-note" style="padding:8px 10px; margin:6px 0;"></div>');
        whisperBox.append('<div style="font-size:0.84em; font-weight:600; margin-bottom:4px;">✎ Шёпот режиссёру <span style="font-weight:400; opacity:0.75;">(необязательно — особое пожелание к кадру или комиксу)</span></div>');
        const whisperInp = $('<input type="text" class="text_pole" style="width:100%; margin:0; font-size:0.86em;" placeholder="например: крупный план рук, вид со спины, дождь за окном, она смеётся…">');
        whisperBox.append(whisperInp);
        el.append(whisperBox);
        const getWhisper = () => String(whisperInp.val() || '').trim();

        el.append('<div class="nnb-pop-sub">1️⃣ Обычная иллюстрация сцены (1 кадр):</div>');
        const grid = $('<div style="display:flex; flex-direction:column; gap:8px; margin-top:6px;"></div>');
        const thirdBtn = $(`
            <div class="nnb-look" tabindex="0" style="padding:10px 12px; display:flex; align-items:center; gap:10px;">
                <i class="fa-solid fa-film" style="font-size:1.3em; color:var(--SmartThemeQuoteColor, #8b78c4);"></i>
                <div>
                    <div style="font-weight:700;">🎥 Взгляд со стороны (кинокадр — все, кто в сцене)</div>
                    <div style="font-size:0.84em; opacity:0.8;">Рисует всех присутствующих в сцене (героиню, чара, всех НПС в комнате или локацию); персонажи смотрят друг на друга, а не в объектив</div>
                </div>
            </div>
        `).on('click', () => finish({ mode: 'third', forcedCast: getForcedCast(), whisper: getWhisper() }));

        const povHandsBtn = $(`
            <div class="nnb-look" tabindex="0" style="padding:10px 12px; display:flex; align-items:center; gap:10px;">
                <i class="fa-solid fa-hand-sparkles" style="font-size:1.3em; color:var(--SmartThemeQuoteColor, #8b78c4);"></i>
                <div>
                    <div style="font-weight:700;">🤚 POV с эффектом присутствия (рука / жест в кадре)</div>
                    <div style="font-size:0.84em; opacity:0.8;">Вид из глаз твоей героини с её рукой или прикосновением на переднем плане (без головы и спины, чтобы не ломался ракурс)</div>
                </div>
            </div>
        `).on('click', () => finish({ mode: 'pov_hands', forcedCast: getForcedCast(), whisper: getWhisper() }));

        const povCleanBtn = $(`
            <div class="nnb-look" tabindex="0" style="padding:10px 12px; display:flex; align-items:center; gap:10px;">
                <i class="fa-solid fa-eye" style="font-size:1.3em; color:var(--SmartThemeQuoteColor, #8b78c4);"></i>
                <div>
                    <div style="font-weight:700;">👁 Чистый взгляд из глаз (собеседник / вид напротив)</div>
                    <div style="font-size:0.84em; opacity:0.8;">Ровный кадр на уровне взгляда прямо перед тобой без рук и частей тела героини в кадре</div>
                </div>
            </div>
        `).on('click', () => finish({ mode: 'pov_clean', forcedCast: getForcedCast(), whisper: getWhisper() }));

        grid.append(thirdBtn, povHandsBtn, povCleanBtn);
        el.append(grid);

        // 2️⃣ Блок Комиксов, Манги и Вебтунов (адаптировано из «Мяфля · Кадр»)
        const comicBox = $('<div class="nnb-note" style="padding:10px 12px; margin-top:12px; border:1.5px solid var(--SmartThemeQuoteColor, #e0c068); background:color-mix(in srgb, var(--SmartThemeQuoteColor, #8b78c4) 10%, transparent);"></div>');
        comicBox.append('<div style="font-weight:700; font-size:0.96em; margin-bottom:4px;">💬 Нарисовать Комикс / Мангу / Вебтун по сцене</div>');
        comicBox.append('<div class="nnb-npc-status" style="font-size:0.82em; margin-bottom:8px;">Разбивает сцену на фреймы (с крупным планом глаз, действием и реакцией) и проверяет реальные реплики из поста, чтобы не было выдуманного текста:</div>');

        const styleRow = $('<div style="display:flex; gap:6px; align-items:center; flex-wrap:wrap; margin-bottom:8px;"></div>');
        const styleSel = $('<select class="text_pole" style="flex:1; min-width:200px; margin:0; font-size:0.86em;"></select>');
        const fillComicStylesSel = () => {
            styleSel.empty();
            const curId = settings().comicStyleId || 'comicbright';
            getAllComicStyles().forEach(stObj => {
                const opt = $('<option></option>').val(stObj.id).text(`${stObj.name}`);
                if (stObj.id === curId) opt.prop('selected', true);
                styleSel.append(opt);
            });
        };
        fillComicStylesSel();
        styleSel.on('change', function () {
            settings().comicStyleId = String($(this).val() || 'comicbright');
            saveSettings();
        });

        const addCustomStyleBtn = $('<div class="menu_button" style="margin:0; padding:5px 9px; font-size:0.8em; width:auto;" title="Добавить свой стиль комикса или манги"><i class="fa-solid fa-plus"></i> Свой стиль</div>').on('click', async () => {
            const sName = await askText('Название твоего стиля комикса/арта:', 'Моя манга');
            if (!sName || !sName.trim()) return;
            const sTags = await askText('Описание стиля или теги Danbooru на английском:', 'comic, multi-panel, monochrome, screentones, dramatic lighting');
            if (!sTags || !sTags.trim()) return;
            if (!Array.isArray(settings().customComicStyles)) settings().customComicStyles = [];
            const newId = 'custom_comic_' + Date.now();
            settings().customComicStyles.push({
                id: newId,
                name: '⭐ ' + sName.trim(),
                group: 'Мои стили',
                isPage: true,
                naiTags: sTags.trim(),
                promptEn: sTags.trim(),
            });
            settings().comicStyleId = newId;
            saveSettings();
            fillComicStylesSel();
            toastr.success(`Стиль «${escapeHtml(sName.trim())}» добавлен!`, '💬 Стиль комикса', { escapeHtml: false });
        });
        styleRow.append(styleSel, addCustomStyleBtn);
        comicBox.append(styleRow);

        const chatArr = ctx().chat || [];
        let targetPostIdx = Number.isInteger(mesId) ? mesId : (chatArr.length - 1);
        while (targetPostIdx >= 0 && (!chatArr[targetPostIdx] || chatArr[targetPostIdx].is_system)) targetPostIdx--;
        const targetPostRaw = chatArr[targetPostIdx]?.mes || '';
        const postChunks = splitPostIntoComicChunks(targetPostRaw);

        const framesAndLinesRow = $('<div style="display:grid; grid-template-columns:repeat(auto-fill, minmax(210px, 1fr)); gap:8px; margin-bottom:8px; font-size:0.84em;"></div>');
        const framesCol = $('<div><div style="opacity:0.85; margin-bottom:2px;">Фреймов на одной странице:</div></div>');
        const framesSel = $('<select class="text_pole" style="width:100%; margin:0; font-size:0.95em; padding:3px 8px;"></select>');
        framesSel.append('<option value="3">3 фрейма (1 сверху + 2 снизу)</option>');
        framesSel.append('<option value="4">4 фрейма (манхва: 1 + 2 + 1)</option>');
        framesSel.val(String(settings().comicFramesPerPage || 3));
        framesSel.on('change', function () {
            settings().comicFramesPerPage = Number($(this).val()) === 4 ? 4 : 3;
            saveSettings();
        });
        framesCol.append(framesSel);

        const linesCol = $('<div><div style="opacity:0.85; margin-bottom:2px;">Облачка с репликами (внизу фреймов):</div></div>');
        const linesSel = $('<select class="text_pole" style="width:100%; margin:0; font-size:0.95em; padding:3px 8px;"></select>');
        linesSel.append('<option value="auto">💬 Полные реплики из отрывка (внизу, не закрывают лица)</option>');
        linesSel.append('<option value="off">🎨 Без текста (чистые фреймы без облачков)</option>');
        linesSel.val(settings().comicLinesMode || 'auto');
        linesSel.on('change', function () {
            settings().comicLinesMode = String($(this).val() || 'auto');
            saveSettings();
        });
        linesCol.append(linesSel);
        framesAndLinesRow.append(framesCol, linesCol);
        comicBox.append(framesAndLinesRow);

        const chunkRow = $('<div style="margin-bottom:8px; font-size:0.84em;"></div>');
        chunkRow.append(`<div style="font-weight:600; margin-bottom:3px;">📖 Режим страниц манхвы по посту <span style="font-weight:400; opacity:0.8;">(пост разбит на ${postChunks.length} эп. — все страницы выдаются сразу сверху вниз, как в манхве!)</span></div>`);
        const chunkSel = $('<select class="text_pole" style="width:100%; margin:0; font-size:0.94em; padding:4px 8px;"></select>');
        if (postChunks.length > 1) {
            chunkSel.append($('<option value="all_chunks"></option>').text(`📚 Сразу ВСЯ ГЛАВА сверху вниз (${postChunks.length} стр. по кусочкам поста — рекомендуется!)`));
        }
        postChunks.forEach((chObj, cIdx) => {
            chunkSel.append($('<option></option>').val(String(cIdx)).text(`📄 Только страница ${cIdx + 1} из ${postChunks.length} (кусочек #${cIdx + 1}: «${chObj.preview}»)`));
        });
        chunkSel.append('<option value="full_post">📝 Весь пост целиком сжать на 1 страницу</option>');
        chunkSel.val(postChunks.length > 1 ? 'all_chunks' : '0');
        chunkRow.append(chunkSel);
        comicBox.append(chunkRow);

        const buildComicPayload = (overrideChunkVal = null) => {
            const cVal = overrideChunkVal !== null ? overrideChunkVal : String(chunkSel.val() || '0');
            const fPerPage = Number(framesSel.val()) === 4 ? 4 : 3;
            if (cVal === 'all_chunks' && postChunks.length > 1) {
                return {
                    mode: 'third',
                    forcedCast: getForcedCast(),
                    whisper: getWhisper(),
                    multiChunkChapter: postChunks,
                    comicOpts: {
                        enabled: true,
                        stripMode: true,
                        framesPerPage: fPerPage,
                        styleId: String(styleSel.val() || 'comicbright'),
                        linesMode: String(linesSel.val() || 'auto'),
                        chunkTotal: postChunks.length,
                    },
                };
            }
            const cIdx = cVal === 'full_post' ? -1 : Number(cVal);
            const chosenChunk = (cIdx >= 0 && postChunks[cIdx]) ? postChunks[cIdx] : null;
            return {
                mode: 'third',
                forcedCast: getForcedCast(),
                whisper: getWhisper(),
                comicOpts: {
                    enabled: true,
                    stripMode: true,
                    framesPerPage: fPerPage,
                    styleId: String(styleSel.val() || 'comicbright'),
                    linesMode: String(linesSel.val() || 'auto'),
                    chunkIndex: chosenChunk ? chosenChunk.index : 0,
                    chunkTotal: chosenChunk ? chosenChunk.total : 1,
                    chunkText: chosenChunk ? chosenChunk.text : '',
                },
            };
        };

        const comicBtns = $('<div style="display:flex; flex-direction:column; gap:6px;"></div>');
        const stripComicBtn = $(`
            <div class="menu_button nnb-btn-primary" style="margin:0; padding:9px 12px; display:flex; align-items:center; justify-content:center; gap:8px; font-weight:700;" title="Рисует все страницы манхвы по кусочкам поста и сразу выкладывает их сверху вниз под сообщением!">
                <i class="fa-solid fa-book-open"></i> ${postChunks.length > 1 ? `📚 Нарисовать манхву по посту сверху вниз (${postChunks.length} стр.)` : '🎞 Нарисовать страницу манхвы по посту'}
            </div>
        `).on('click', () => finish(buildComicPayload()));
        comicBtns.append(stripComicBtn);

        const singleComicBtn = $(`
            <div class="menu_button" style="margin:0; padding:7px 12px; display:flex; align-items:center; justify-content:center; gap:8px; font-weight:600; font-size:0.92em;" title="Рисует 1 одиночный кадр в выбранном стиле манги/манхвы/комикса (без деления листа на панели)">
                <i class="fa-solid fa-image"></i> 🖼 Нарисовать 1 одиночный кадр в этом стиле (без панелей)
            </div>
        `).on('click', () => finish({
            mode: 'third',
            forcedCast: getForcedCast(),
            whisper: getWhisper(),
            comicOpts: {
                enabled: true,
                stripMode: false,
                styleId: String(styleSel.val() || 'comicbright'),
                linesMode: String(linesSel.val() || 'auto'),
            },
        }));

        comicBtns.append(singleComicBtn);
        comicBox.append(comicBtns);
        el.append(comicBox);
        openPopup(el).then(() => {
            if (!settled) { settled = true; resolve(null); }
        });
    });
}


function stripMultiPanelTagsForSingleFrame(styleTags) {
    if (!styleTags) return '';
    return String(styleTags)
        .split(',')
        .map(t => t.trim())
        .filter(t => t && !/^(?:comic|4koma|3koma|multi-panel|panel layout|clean panel borders|thick panel borders|diagonal panel border|white gutters|vertical strip|four equal panels|comic page|eye close-up inset|small chibi reaction inset|cute chibi inset in corner|close-up inset(?:\s+on\s+eyes)?)$/i.test(t))
        .join(', ');
}

function sanitizeLiteralMetaphorTags(promptStr) {
    if (!promptStr) return '';
    return String(promptStr)
        .replace(/\blion(?:'s)?\s+mane\b/gi, 'thick voluminous wild hair')
        .replace(/\bgreenish[-\s]+pale\b/gi, 'pale skin, unwell, sweatdrop')
        .replace(/\bgreenish\s+(?:skin|face|complexion)\b/gi, 'pale skin, unwell');
}

function isDetailOrMacroPanelPrompt(rawPrompt) {
    const p = String(rawPrompt || '').toLowerCase();
    if (!p) return false;
    if (/\b(no humans|animal focus|object focus|food focus|vehicle focus|scenery|weapon focus|still life|flower focus|head out of frame|face out of frame|cropped head|headless|hand focus|hands focus|focus on hands|foot focus|feet focus|lower body focus|pelvic focus|groin focus|intimate close-up|penetration close-up|sex close-up|macro shot|windshield|wipers|windshield wipers)\b/i.test(p)) {
        return true;
    }
    // Если в промпте кадра вообще нет ни одного человека (нет 1girl/1boy/woman/man/person/portrait) — это 100% безлюдный кадр детали/окружения!
    const hasAnyHumanTag = /\b([1-6]girls?|[1-6]boys?|woman|women|man|men|female|male|person|people|portrait|upper body|cowboy shot|full body)\b/i.test(p);
    if (!hasAnyHumanTag) {
        return true;
    }
    const hasCloseUp = /\b(close-up|extreme close-up|macro|focus on)\b/i.test(p);
    const hasPortraitFace = /\b(portrait|face focus|expressive face|looking at viewer|looking back|looking at another|hair|eyes|cat ears|animal ears|smiling|grinning|pouting|blushing|frowning|glaring|laughing|crying|yawning|speaking|talking|glasses|sunglasses|2girls|2boys|multiple girls|multiple boys)\b/i.test(p);
    const hasExplicitHeadlessOrFocus = /\b(head out of frame|face out of frame|cropped head|neck focus|hands focus|hand focus|object focus|food focus|no humans|eyes only|extreme close-up)\b/i.test(p);
    if (hasCloseUp && (hasExplicitHeadlessOrFocus || !hasPortraitFace)) {
        if (/\b(snake|python|cobra|viper|serpent|lizard|reptile|terrarium|spider|scorpion|frog|toad|turtle|hamster|rat|mouse|rabbit|ferret|parrot|raven|crow|owl|fish|aquarium|handbag|purse|compact mirror|keys|keychain|jam|thumb|finger|tail under skirt|tarot|cards|card|deck|arcana|knocking|knuckles|fist|door|boots|calves|sack|alabaster)\b/i.test(p)) {
            return true;
        }
        if (/\b(genitals|penis|erection|testicles|pussy|vagina|clitoris|labia|anus|crotch|groin|pubic|insertion|penetration|vaginal|anal|cum|ejaculation|creampie|fellatio|cunnilingus|handjob|fingering|paizuri|nipples|areolae|breasts focus|ass focus|butt focus|thighs focus)\b/i.test(p)) {
            return true;
        }
    }
    return false;
}

function enforceSoloFrameOutfitFromPage(rawFrameDesc, panel1Desc = '', charCaptions = []) {
    let p = String(rawFrameDesc || '').trim();
    if (!p) return p;
    const sourcePool = [ ...(Array.isArray(charCaptions) ? charCaptions : []), String(panel1Desc || '') ].join(' | ');
    if (isDetailOrMacroPanelPrompt(p)) {
        // Если это крупный план губ/вейпа/щеки/уха (lips/mouth/vape/cheek/ear), обязательно сохраняем цвет волос героя из 1-го кадра, чтобы у темноволосой Этель не вырастали рыжие волосы!
        if (/\b(lips|mouth|vape|biting|cheek|ear)\b/i.test(p) && !/\b(black|brown|dark|blonde|red|ginger|orange|silver|grey|white)\s+hair\b/i.test(p)) {
            const p1Hair = sourcePool.match(/\b((?:dark\s+brown|black|brown|dark|blonde|silver|grey|white|red|ginger|orange)\s+(?:long\s+|short\s+|wavy\s+|messy\s+)?hair)\b/i);
            if (p1Hair && p1Hair[1]) {
                p += `, ${p1Hair[1]}`;
            }
        }
        return p;
    }
    const isSoloGirl = /\b1girl\b/i.test(p) && !/\b([2-6]girls|[1-6]boys)\b/i.test(p);
    const isSoloBoy = /\b1boy\b/i.test(p) && !/\b([2-6]boys|[1-6]girls)\b/i.test(p);
    if (!isSoloGirl && !isSoloBoy) return p;
    const hairMatch = p.match(/\b(black|brown|dark|blonde|red|ginger|orange|copper|caramel|auburn|chestnut|ashy|ash|golden|platinum|pink|white|silver|grey|gray)\s+(?:wavy\s+|curly\s+|long\s+|short\s+|straight\s+|messy\s+|leonine\s+)?(?:hair|mane)\b/i);
    const hairColor = hairMatch ? hairMatch[1].toLowerCase() : '';
    const eyeMatch = p.match(/\b(green|emerald|hazel|amber|brown|blue|grey-blue|red|dark red|crimson|purple|violet|yellow|gold|golden|caramel|grey|gray|black)\s+eyes\b/i);
    const eyeColor = eyeMatch ? eyeMatch[1].toLowerCase() : '';
    const pAlreadyHasOutfit = /\b(jacket|coat|vest|waistcoat|shirt|blouse|dress|hospital gown|gown|sweater|turtleneck|cardigan|hoodie|suit|blazer|inner top|tank top|t-shirt)\b/i.test(p);

    const candidateSegments = sourcePool.split(/\|\||\|/).map(s => s.trim()).filter(Boolean);
    const sameGenderSegCount = candidateSegments.filter(seg =>
        (isSoloGirl && /\b1girl\b/i.test(seg) && !/\b1boy\b/i.test(seg))
        || (isSoloBoy && /\b1boy\b/i.test(seg) && !/\b1girl\b/i.test(seg))
    ).length;
    for (const seg of candidateSegments) {
        if (isSoloGirl && /\b1boy\b/i.test(seg) && !/\b1girl\b/i.test(seg)) continue;
        if (isSoloBoy && /\b1girl\b/i.test(seg) && !/\b1boy\b/i.test(seg)) continue;
        if (isSoloBoy && /\b(shirtless|bare chest|bare torso|topless|naked torso)\b/i.test(seg)) {
            p = p.replace(/\b(?:black\s+|white\s+|grey\s+|dark\s+|open\s+|unbuttoned\s+)?(?:t-shirt|shirt|coat|leather coat|trench coat|jacket|suit jacket|blazer|sweater|hoodie)\b\s*,?/gi, '');
            if (!/\b(shirtless|bare chest)\b/i.test(p)) {
                p += ', shirtless, bare chest, bare shoulders';
            }
            break;
        }
        // Если на странице 2+ персонажа одного пола и не определились ни цвет волос, ни цвет глаз — не копируем чужую одежду!
        if (!hairColor && !eyeColor && sameGenderSegCount >= 2) continue;
        if (hairColor && !new RegExp(`\\b${hairColor}\\b`, 'i').test(seg)) continue;
        // Если у сольного героя указан цвет глаз, а в слоте — другой цвет глаз (например, зелёные у Кайлара vs ореховые у Яна), пропускаем чужой слот!
        if (eyeColor && /\beyes\b/i.test(seg) && !new RegExp(`\\b${eyeColor}\\s+eyes\\b`, 'i').test(seg)) continue;
        // Если у сольного портрета уже описан верх одежды, не доклеиваем чужие пиджаки/галстуки поверх
        if (pAlreadyHasOutfit) continue;

        const outfitRe = /\b((?:black|dark|brown|beige|cream|white|grey|gray|green|emerald|burgundy|cherry|crimson|maroon|blue|navy|fitted|woolen|fur|knitted|stretched|oversized|ruffled|silk|formal|three-piece)?\s*(?:three-piece suit|suit jacket|suit|waistcoat|vest|coat|fur coat|jacket|blazer|cardigan|trench coat|sweater|turtleneck|blouse|shirt|dress|knitted dress|robe|hoodie|oversized hoodie|cargo pants))\b/gi;
        const matches = [];
        let om;
        while ((om = outfitRe.exec(seg)) !== null) {
            const item = om[1].trim();
            if (item.length >= 4) matches.push(item);
        }
        if (matches.length) {
            const toAdd = [];
            for (const mItem of matches.slice(0, 2)) {
                const noun = mItem.split(/\s+/).pop();
                if (!new RegExp(`\\b${noun}\\b`, 'i').test(p)) {
                    toAdd.push(mItem);
                }
            }
            if (/\b(necktie|tie)\b/i.test(seg) && !/\b(necktie|tie)\b/i.test(p)) {
                toAdd.push('necktie');
            }
            if (toAdd.length) {
                // Если в сольном кадре по ошибке вылез чужой "white lab coat", а в 1-м кадре на герое костюм (suit) или кардиган (cardigan) — заменяем!
                if (toAdd.some(x => /\b(suit|cardigan)\b/i.test(x))) {
                    p = p.replace(/\b(?:white\s+)?lab\s+coat\b\s*,?/gi, '');
                }
                p += `, wearing ${toAdd.join(', ')}`;
                break;
            }
        }
    }
    return p;
}

function cleanSingleComicPanelPrompt(rawPrompt, panelIdx = 0, pageContextPrompt = '') {
    let p = sanitizeLiteralMetaphorTags(String(rawPrompt || '').trim());
    if (!p) return '';

    // 0) Убираем любые текстовые звуковые эффекты ("Purrrrr", "PURR", "BOOM", sfx, sound effect), чтобы NovelAI не писал буквы поверх волос героев!
    p = p
        .replace(/["'«»“”]?\b(?:purr+|grrr+|boom+|knock+|tap+|clink+|sigh+|mumm+|huff+|pant+|gulp+)\b["'«»“”]?/gi, '')
        .replace(/\b(?:sound effect|sfx|onomatopoeia|text overlay|floating text|written text)\b\s*,?/gi, '')
        .replace(/\b(?:crimson|raspberry|red)\s+(?:spots|blotches|patches|stains)\s+on\s+neck\b/gi, 'deeply blushing neck and ears, flushed red skin on neck')
        .replace(/\b(?:plasters?|bandages?|band-aids?)\s+on\s+fingers\b/gi, 'a single small band-aid on one index finger')
        .replace(/\bbandaged\s+fingers\b/gi, 'one small band-aid on index finger');

    // Если в кадре есть человек (1boy/1girl), убираем буквальное "under glass / behind glass" (возникающее из фразы «спрятала рисунок кота под стекло рамки»), чтобы NovelAI не заворачивал самого человека в битое стекло или плёнку!
    if (/\b([1-4]boys?|[1-4]girls?|man|woman|male|female)\b/i.test(p) && !/\b(window|aquarium|terrarium|paludarium)\b/i.test(p)) {
        p = p.replace(/\b(?:hidden\s+)?(?:under|behind|beneath)\s+glass\b/gi, 'framed picture on desk');
    }

    // Если герои чокаются чашками или держат чашку у губ — жёстко фиксируем "holding one teacup only", чтобы NovelAI не рисовал Софии по чашке в каждой руке одновременно!
    if (/\b(teacups?|cups?|porcelain cup|drinking tea)\b/i.test(p) && /\b([1-4]girls?|[1-4]boys?)\b/i.test(p)) {
        p = p.replace(/\bclinking\s+(?:tea)?cups\b/gi, 'holding one teacup only, clinking teacup with another');
        if (!/\bone teacup\b/i.test(p)) {
            p += ', holding one teacup only';
        }
    }

    // 1) Если персонаж потягивается, зевает ИЛИ смеётся/ухмыляется — вырезаем ложные триггеры плача и пижамных футболок!
    if (/\b(yawn|yawning|stretch|stretching|arms overhead|arms raised|tired|exhausted|sigh|sighing|sleepy|drowsy|laugh|laughing|grin|grinning|cackling|pointing|amused|teasing)\b/i.test(p) && !/\b(sad|grief|weeping|heartbroken|funeral|tragedy)\b/i.test(p)) {
        p = p.replace(/\b(?:crying|tears|tearing up|teardrops|watery eyes|tears of laughter|streaming tears|tears streaming[^,]*|sobbing|weeping|pajamas|nightgown|sleepwear|oversized white t-shirt|oversized t-shirt|oversized shirt|bed|bedroom|waking up)\b\s*,?/gi, '');
    }

    // 2) Если в кадре есть змея — заменяем "hook" на "long smooth metal snake-handling rod"
    if (/\b(snake|python|viper|serpent|reptile|paludarium|terrarium)\b/i.test(p)) {
        p = p
            .replace(/\b(?:chrome|metal|steel|iron|snake)?\s*hook\b/gi, 'long smooth metal snake-handling rod')
            .replace(/\b(?:hanging|suspended|dangling)\s+(?:from|on)\b/gi, 'resting across');
        if (!/\bsingle snake\b/i.test(p) && /\b(snake|viper|python|serpent)\b/i.test(p)) {
            p = `single snake, one snake head only, ${p}`;
        }
    }

    // 2а) Если в кадре упоминаются усики-антенны на макушке (ant antennae / insect antennae / antennae on head) — запрещаем NovelAI рисовать настоящего жука/муравья/таракана!
    if (/\b(ant antennae|insect antennae|antennae|feelers)\b/i.test(p)) {
        p = p
            .replace(/\b(?:ant|insect)\s+antennae\b/gi, 'two thin dark head antennae on silver-black hair')
            .replace(/\banimal focus\b\s*,?/gi, '');
        if (!/\b1boy\b/i.test(p) && !/\b1girl\b/i.test(p)) {
            p = `1boy, solo, close-up of head and messy silver-black hair with two thin dark antennae on head, purple skin, pointed elf ears, ${p}`;
        }
    }

    // 2б) Если в кадре описан хвост деми-человека (black cat tail hitting safe door / tail under skirt) или рисунок акварельного кота в рамке — запрещаем NovelAI рисовать живого четвероногого домашнего кота!
    if (/\b(cat tail|fluffy black tail|tail hitting|tail under|watercolor cat|painting of a cat|framed cat)\b/i.test(p)) {
        p = p.replace(/\banimal focus\b\s*,?/gi, 'object focus, ');
        if (/\b(tail hitting|safe door)\b/i.test(p)) {
            p = `close-up of a long fluffy black tail against a dark cast-iron safe door, kemonomimi tail only, no animal head, no cat face, ${p.replace(/\bcat\s+tail\b/gi, 'black fluffy tail')}`;
        }
    }

    // 3) Если в кадре есть варенье/повидло/джем — уточняем "sweet strawberry jam", чтобы NovelAI не рисовал кровь на пальцах!
    if (/\b(jam|jelly|preserve|marmalade|strawberry|berry)\b/i.test(p) && !/\b(blood|injury|wound|horror)\b/i.test(p)) {
        p = p.replace(/\bred\s+(?:liquid|smear|stain|dab|drop)\b/gi, 'sweet glossy strawberry jam');
    }

    // 3б) Если в кадре тасуют карты Таро — заменяем "shuffling" на удержание карт двумя руками
    if (/\b(tarot|cards|deck|shuffling)\b/i.test(p)) {
        p = p.replace(/\bshuffling\s+(?:worn\s+|tarot\s+|playing\s+)?(?:cards|deck)\b/gi, 'holding tarot cards in two hands, two hands only')
             .replace(/\bshuffling\b/gi, 'holding cards in two hands');
    }

    // 3b) Если это крупный план шеи / ключиц / синяка / следа укуса — ЗАПРЕЩАЕМ head out of frame / headless / no humans, иначе NovelAI рисует обезглавленный пень шеи!
    const isNeckOrCollarboneDetail = /\b(neck focus|bruise on neck|hickey|bite mark|collarbone|clavicle|throat|\bneck\b)\b/i.test(p) && !/\b(hand focus|hands focus|focus on hands|holding|gripping|fingers|palm|wrist|knuckles)\b/i.test(p);
    if (isNeckOrCollarboneDetail && isDetailOrMacroPanelPrompt(p)) {
        p = p
            .replace(/\b(?:head out of frame|face out of frame|cropped head|headless|no humans)\b\s*,?/gi, '')
            .replace(/,\s*,+/g, ', ')
            .replace(/^,\s*|,\s*$/g, '')
            .trim();
        if (!/\b(jawline|chin|lower face|upper body|portrait)\b/i.test(p)) {
            p = `close-up, upper body, jawline, chin, collarbone, ${p}`;
        }
    }

    // 4) Если это кадр фокуса на руках / сумочке / пуговице / чайнике / пластыре — определяем ПОЛ рук (мужские 1boy или женские 1girl по самому промпту и по контексту страницы pageContextPrompt!), чтобы мужские или когтистые лапы (Кайлара/Лайоса/Яна) никогда не превращались в женские руки с маникюром!
    const isActualHandDetail = !isNeckOrCollarboneDetail && (/\b(hand focus|hands focus|focus on hands|head out of frame|face out of frame|cropped head)\b/i.test(p) || (isDetailOrMacroPanelPrompt(p) && /\b(unbuttoning|inside bag|inside handbag|rummaging|holding keys|keys|thumb|finger|fingernail|jam|band-aid|plaster|teapot|kettle|pouring|knocking|fist|knuckles)\b/i.test(p)));
    if (isActualHandDetail) {
        p = p
            .replace(/\b(?:no humans|multiple girls|multiple boys|[2-9]girls|[2-9]boys|four hands|multiple hands)\b\s*,?/gi, '')
            .replace(/,\s*,+/g, ', ')
            .replace(/^,\s*|,\s*$/g, '')
            .trim();
        const combinedCtx = `${p} ${pageContextPrompt || ''}`;
        const hasGloves = /\b(?:gloves?|gloved)\b/i.test(p);
        const isMaleHand = /\b(1boy|male|man|his|masculine|clawed|furry hand|lion|band-aid|bandaged|knuckles|fist|tattooed|purple skin|cargo pants|crate|canister|nose ring|lip piercing|four arms|upper hands|lower hands)\b/i.test(p) || (!/\b(1girl|female|woman|her|manicure|handbag|purse|skirt|pen)\b/i.test(p) && /\b1boy\b/i.test(combinedCtx) && !/\b1girl\b/i.test(combinedCtx));
        const hasFourArms = /\b(four arms|four hands|lower pair of|upper hands|lower hands)\b/i.test(p);
        if (!/\btwo hands only\b/i.test(p) && !hasFourArms) {
            const gPrefix = isMaleHand ? '1boy, male hands' : (hasGloves ? '1girl' : '1girl, bare hands');
            p = p.replace(/^\s*(?:1girl|1boy)\s*,\s*(?:solo\s*,\s*)?/i, '');
            p = `${gPrefix}, solo, two hands only, ${p}`;
        } else if (hasFourArms && isMaleHand && !/\b1boy\b/i.test(p)) {
            p = `1boy, solo, male hands, ${p}`;
        }
        if (!hasGloves && !/\bbare hands\b/i.test(p)) {
            p += ', bare hands';
        }
    }

    // Если в макро-кадре показаны мужские треники / бугор в паху / голый мужской торс со шрамами (sweatpants / bulge / erection / abs / pectoral / chest scars) — жёстко фиксируем мужскую анатомию (1boy, solo, male body, masculine physique), чтобы NovelAI никогда не рисовал женские бёдра в белых трусиках!
    if (/\b(sweatpants|bulge|erection|groin|crotch|abs|pectorals?|muscular chest|scars on chest|claw marks on chest)\b/i.test(p)) {
        p = p.replace(/\b(1girl|female|woman|panties|underwear)\b\s*,?/gi, '');
        if (!/\b1boy\b/i.test(p)) {
            p = `1boy, solo, male body, masculine physique, ${p}`;
        }
    }

    if (isDetailOrMacroPanelPrompt(p)) {
        const hasHandsOrBody = /\b(hand focus|hands|fingers|thumb|neck|collarbone|clavicle|lips|mouth|cheek|ear|thighs|hips|legs|calves|feet|tail|sweatpants|bulge|groin|crotch|abs|chest|nsfw|explicit|intimate|genitals|penis|pussy|breasts)\b/i.test(p);
        const hasAnimal = /\b(animal focus|snake|viper|python|dog|bird|horse)\b/i.test(p) || (/\bcat\b/i.test(p) && !/\b(cat ears|cat tail|watercolor cat|framed cat|painting|felt|plush)\b/i.test(p));
        // 5) Если это чисто предметный кадр без людей и без живых животных (лобовое стекло с дворниками, окно, рамка с рисунком на столе, скомканная бумага в корзине, шпингалет двери) — жёстко ставим no humans!
        if (!hasHandsOrBody && !hasAnimal) {
            p = p.replace(/\b(?:reflection|face|eyes|watching|staring|silhouette|shadow of[^,]*)\b\s*,?/gi, '');
            if (!/\bno humans\b/i.test(p)) p = `no humans, still life, object focus, ${p}`;
        }
        p = p
            .replace(/1\.3::tall lean adult man[^:]*::\s*,?/gi, '')
            .replace(/-1\.5::otoko no ko[^:]*::\s*,?/gi, '')
            .replace(/\b(tall lean adult man|adult male proportions|broad masculine shoulders|wider male shoulders|long male legs|mature adult face|wide shot|full body|cowboy shot|medium shot|establishing shot|[2-6]boys|[2-6]girls|multiple boys|multiple girls)\b\s*,?/gi, '');
        if (!hasHandsOrBody && !/\bno humans\b/i.test(p)) {
            p = p.replace(/\b(1boy|1girl|solo)\b\s*,?/gi, '');
            p = `no humans, ${p}`;
        } else if (hasHandsOrBody && !/\b(no humans|head out of frame|face out of frame|cropped)\b/i.test(p) && !/\b(cheek|ear|lips|mouth|neck|collarbone|clavicle|throat|hickey|bruise)\b/i.test(p)) {
            p = `head out of frame, cropped, ${p}`;
        }
    } else {
        if (!/\b([1-4]boys?|[1-4]girls?)\b/i.test(p) && /\b(nose ring|lip piercing|labret|purple skin|four eyes|multiple eyes|silver-black hair|shaggy bangs|ant antennae|antennae)\b/i.test(p)) {
            p = `1boy, solo, ${p}`;
        }
        if (/\b(plum|burgundy|crimson)\s+blush\b/i.test(p)) {
            p = p.replace(/\b(?:plum|burgundy|crimson)\s+blush\b/gi, 'deep blush on cheeks');
        }
        if (panelIdx === 2 && !/\b(close-up|portrait|upper body)\b/i.test(p)) {
            p = `close-up, portrait, upper body, ${p}`;
        }
    }

    return p.replace(/,\s*,+/g, ', ').replace(/^\s*,\s*|\s*,\s*$/g, '').replace(/\s{2,}/g, ' ').trim();
}

function stripActionAndPropTagsFromCharCaption(cap) {
    if (!cap) return '';
    const actionRe = /\b(sitting|lying|standing|holding|peeling|eating|drinking|reaching|touching|hugging|kissing|leaning|kneeling|crouching|walking|running|gesturing|turning|stuffing|clutching|plastic container|container|shrimp|food|bowl|plate|cup|mug|glass|phone|cigarette|bed|hospital bed|pillow|blanket|sheet|table|chair|looking at|hand on|hands|arms|crossed arms|reaching out|wide shot|full body|wide establishing shot|medium two-shot|six people|five people|four people)\b/i;
    const identityRe = /\b(man|woman|boy|girl|male|female|hair|eyes|ears|tail|horns|wings|piercings|glasses|suit|shirt|jacket|dress|coat|sweater|uniform|tall|short|curvy|lean|muscular|pale|freckles|beard|scars|demi-cat|demi-dog)\b/i;
    return sanitizeLiteralMetaphorTags(String(cap))
        .split(',')
        .map(t => {
            const tr = t.trim();
            if (!tr) return '';
            if (!actionRe.test(tr)) return tr;
            if (identityRe.test(tr)) {
                // Оставляем внешность/одежду героя в начале фразы, отрезая только хвост с действием и мебелью
                const cleanedClause = tr.replace(/\s+\b(?:beside|behind|near|at the|by the|walking|standing|sitting|lying|turning|gesturing|holding|clutching|stuffing|peeling|eating|drinking|looking|leaning|reaching|crouching|kneeling)\b.*$/i, '').trim();
                if (cleanedClause && identityRe.test(cleanedClause)) return cleanedClause;
            }
            return '';
        })
        .filter(Boolean)
        .join(', ');
}


function transliterateRuNameVariants(ruName) {
    const clean = String(ruName || '').replace(/\([^)]*\)/g, '').trim().toLowerCase().replace(/ё/g, 'е');
    if (!clean) return [];
    const map = {
        а:'a', б:'b', в:'v', г:'g', д:'d', е:'e', ж:'zh', з:'z', и:'i', й:'y',
        к:'k', л:'l', м:'m', н:'n', о:'o', п:'p', р:'r', с:'s', т:'t', у:'u',
        ф:'f', х:'kh', ц:'ts', ч:'ch', ш:'sh', щ:'shch', ъ:'', ы:'y', ь:'', э:'e', ю:'yu', я:'ya'
    };
    const firstWord = clean.split(/\s+/)[0];
    let tr = '';
    for (const ch of firstWord) tr += (map[ch] !== undefined ? map[ch] : ch);
    const variants = new Set([tr]);
    if (tr === 'doyl') variants.add('doyle');
    if (tr === 'dzhuliya') { variants.add('julia'); variants.add('julie'); }
    if (tr === 'kaylar') { variants.add('kailar'); variants.add('kylar'); }
    if (tr === 'etel') variants.add('ethel');
    if (tr === 'sofiya') { variants.add('sofia'); variants.add('sophia'); }
    if (tr === 'endzhel') variants.add('angel');
    if (tr === 'layos') variants.add('laios');
    if (tr === 'rey') { variants.add('ray'); variants.add('rei'); }
    return Array.from(variants).filter(v => v.length >= 2);
}

// Страж внешности: если у NPC в карточке задан каноничный тег вида «denji (chainsaw man)», то
// 1) возвращаем ему скобочную форму (модель пишет «denji, chainsaw man», и NovelAI узнаёт персонажа хуже);
// 2) вычищаем цвета волос, которых нет в его тегах (модель тащит «black hair» из прошлых кадров и с главного героя).
const NNB_HAIR_COLOR_RE = /^(?:(?:messy|short|long|spiky|shaggy|wavy|curly|straight|tousled|fluffy|medium|very long|very short)\s+)*(?:jet[- ]black|black|dark|dark brown|brown|light brown|blonde|blond|golden|yellow|white|silver|grey|gray|platinum|red|crimson|orange|ginger|auburn|copper|caramel|blue|navy|green|purple|violet|pink|teal)[- ]hair(?:ed)?$/i;
function hairColorWords(tags) {
    return (String(tags || '').match(/\b(?:jet[- ]black|black|dark brown|light brown|dark|brown|blonde|blond|golden|yellow|white|silver|grey|gray|platinum|red|crimson|orange|ginger|auburn|copper|caramel|blue|navy|green|purple|violet|pink|teal)(?=[- ]hair)/gi) || []).map(x => x.toLowerCase().replace(/\s+/g, ' '));
}
function enforceNpcCanonAppearance(rawPromptStr, st) {
    let out = String(rawPromptStr || '');
    if (!out || !st) return out;
    const cards = [...(st.npcs || [])];
    if (st.mainCharCard) cards.push(st.mainCharCard);
    for (const npc of cards) {
        const appEn = String(npc?.appearanceEn || '').trim();
        const canonP = parseCanonFromAppearance(appEn);
        if (!canonP) continue;
        const cName = canonP.name, cSeries = canonP.series;
        const canonTag = canonP.tag;
        const escN = cName.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
        const escS = cSeries.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
        const ownHair = hairColorWords(appEn);
        const segs = out.split(/(\s*\|\|\s*)/);
        for (let i = 0; i < segs.length; i += 2) {
            let seg = segs[i];
            const hasCanon = new RegExp(`(^|,)\\s*${escN}\\b`, 'i').test(seg);
            if (!hasCanon) continue;
            // «name, series» → «name»; убираем одиночные «series»; одиночное «name» → канон-тег (без дублей серии)
            seg = seg
                .replace(new RegExp(`\\b${escN}\\s*,\\s*${escS}\\b`, 'gi'), cName)
                .replace(new RegExp(`(^|,)\\s*${escS}\\s*(?=,|$)`, 'gi'), '$1')
                .replace(new RegExp(`(^|,)\\s*${escN}\\s*(?=,|$)`, 'gi'), `$1 ${canonTag}`)
                .replace(/,\s*,/g, ',');
            let toks = seg.split(',').map(t => t.trim()).filter(Boolean);
            const canonIdx = toks.findIndex(t => t.toLowerCase() === canonTag.toLowerCase());
            const isSoloSeg = /\bsolo\b/i.test(seg) || /^\s*1(?:boy|girl)\s*,/i.test(seg) && !/\b1(?:boy|girl)\b[\s\S]*\b1(?:boy|girl)\b/i.test(seg) || i > 0;
            toks = toks.map((t, idx) => {
                if (!NNB_HAIR_COLOR_RE.test(t)) return t;
                if (hairColorWords(t).some(c => ownHair.includes(c))) return t;
                // в сольном кадре / в его CHAR-слоте убираем любой чужой цвет волос; в общем кадре — только рядом с его тегом
                if (isSoloSeg || (canonIdx >= 0 && idx > canonIdx && idx - canonIdx <= 8)) {
                    const style = t.replace(/[- ]?hair(?:ed)?$/i, '').split(/\s+/).filter(w => /^(messy|short|long|spiky|shaggy|wavy|curly|straight|tousled|fluffy)$/i.test(w));
                    return style.length ? `${style.join(' ')} hair` : '';
                }
                return t;
            }).filter(Boolean);
            segs[i] = (segs[i].match(/^\s*/)[0]) + toks.join(', ');
        }
        out = segs.join('');
    }
    return out;
}

const NNB_CANON_SERIES_RE = /^(?:jujutsu kaisen|chainsaw man|naruto|bleach|one piece|genshin impact|honkai(?::| )star rail|demon slayer|kimetsu no yaiba|attack on titan|shingeki no kyojin|jojo(?:'s bizarre adventure)?|boku no hero academia|my hero academia|bungou stray dogs|tokyo revengers|blue lock|haikyuu!?|devil may cry|resident evil|final fantasy(?: [ivx0-9]+)?|persona(?: [0-9]+)?|baldur'?s gate(?: [0-9]+)?|arcane|hazbin hotel|helluva boss|overwatch|league of legends|valorant|arknights|wuthering waves|zenless zone zero|blue archive|touhou|evangelion|berserk|vagabond|vinland saga|hunter x hunter|fullmetal alchemist|death note|code geass|spy x family|dandadan|kagurabachi|sakamoto days|solo leveling|omniscient reader(?:'s viewpoint)?|heaven official'?s blessing|mo dao zu shi|undertale|deltarune|elden ring|dark souls|the witcher|cyberpunk(?: 2077)?|metal gear(?: solid)?|silent hill|yakuza|dragon ball(?: z| super)?|sailor moon|inuyasha|gintama|mob psycho 100|one punch man|sousou no frieren|frieren|dungeon meshi|kusuriya no hitorigoto|oshi no ko|bocchi the rock!?|steins;gate|re:zero|mushoku tensei|overlord|konosuba|sword art online|tokyo ghoul|kuroshitsuji|black butler|vanitas no carte|pandora hearts|d\.gray-man|soul eater|fire force|fairy tail|black clover|dr\. stone|kuroko no basuke|yuri!!!? on ice|banana fish|link click|alien stage|love and deepspace|twisted wonderland|ensemble stars!?|project sekai|vocaloid|hololive|nijisanji|fate\/[a-z0-9 ]+)$/i;
const NNB_NON_CANON_NAME_RE = /^(?:1boy|1girl|2boys|2girls|solo|male|female|adult|man|woman|boy|girl|medium shot|cowboy shot|close-up|upper body|full body|portrait|indoors|outdoors|character not looking at viewer|dynamic angle|depth of field|looking at viewer)$/i;
const NNB_NON_SERIES_PAREN_RE = /^(?:original|cosplay|outfit|style|young|adult|old|male|female|top|bottom|left|right|character|oc)$/i;

// Канон-тег из карточки: «toji (jujutsu kaisen)» или «fushiguro touji, jujutsu kaisen»; ведущие 1boy/male и т.п. пропускаем
function parseCanonFromAppearance(appEn) {
    const toks = String(appEn || '').split(',').map(x => x.trim()).filter(Boolean);
    let gender = '';
    const gTxt = String(appEn || '').toLowerCase();
    if (/\b(1boy|boy|male|man|husband|father)\b/.test(gTxt) && !/\b(1girl|girl|female|woman)\b/.test(gTxt)) gender = 'boy';
    else if (/\b(1girl|girl|female|woman)\b/.test(gTxt) && !/\b(1boy|male|man)\b/.test(gTxt)) gender = 'girl';
    while (toks.length && /^(?:1boy|1girl|solo|male|female|adult|man|woman|boy|girl|mature male|mature female)$/i.test(toks[0])) toks.shift();
    if (!toks.length) return null;
    const pm = toks[0].match(/^([^()]{2,60}?)\s*\(\s*([^)]{2,60}?)\s*\)$/);
    if (pm && !NNB_NON_CANON_NAME_RE.test(pm[1].trim()) && !NNB_NON_SERIES_PAREN_RE.test(pm[2].trim())) return { name: pm[1].trim(), series: pm[2].trim(), tag: `${pm[1].trim()} (${pm[2].trim()})`, paren: true, gender };
    if (toks.length >= 2 && NNB_CANON_SERIES_RE.test(toks[1]) && !NNB_NON_CANON_NAME_RE.test(toks[0])) return { name: toks[0], series: toks[1], tag: `${toks[0]}, ${toks[1]}`, paren: false, gender };
    return null;
}
function guessCardGender(n, canon) {
    if (canon?.gender) return canon.gender;
    let t = `${n?.card || ''} ${n?.status || ''}`.toLowerCase();
    if (n?.isMainChar) {
        try {
            const c = ctx();
            const d = c.characterId !== undefined ? c.characters?.[c.characterId]?.description : '';
            if (d) t += ' ' + String(c.substituteParams(String(d))).toLowerCase().slice(0, 3000);
        } catch (e) { /* ignore */ }
    }
    const he = (t.match(/(?:^|[^а-яё])(?:он|его|ему|ним|сам)(?=[^а-яё]|$)/g) || []).length;
    const she = (t.match(/(?:^|[^а-яё])(?:она|её|ее|ей|ней|сама)(?=[^а-яё]|$)/g) || []).length;
    const isBoyRu = /(?:^|[^а-яё])(?:мужчин|парн|парен|юнош|муж(?=[^а-яё]|$)|отец|брат|сын|папа|дедушк|дядя|король|принц|барон|лорд|мистер|господин)/i.test(t);
    const isGirlRu = /(?:^|[^а-яё])(?:женщин|девушк|девочк|жена|мать|сестр|дочь|мама|бабушк|т[её]тя|королев|принцесс|леди|мисс|миссис|госпож|подруг|невест|юристка|журналистка|бухгалтерша|врачиха|докторша|деми-кошка|кошка)/i.test(t);
    if (isBoyRu && !isGirlRu) return 'boy';
    if (isGirlRu && !isBoyRu) return 'girl';
    if (he >= 2 && he >= she * 2) return 'boy';
    if (she >= 2 && she >= he * 2) return 'girl';
    if (isBoyRu) return 'boy';
    if (isGirlRu) return 'girl';
    if (/\b(1boy|male|man|boy)\b/.test(t) && !/\b(1girl|female|woman|girl)\b/.test(t)) return 'boy';
    if (/\b(1girl|female|woman|girl)\b/.test(t) && !/\b(1boy|male|man|boy)\b/.test(t)) return 'girl';
    return '';
}
// Канон-теги героев, которые реально в сцене, — прямо из их карточек (не ждём, пока модель сама их напишет)
function canonByGenderFromCards(st, cast, sceneText) {
    const res = { boy: '', girl: '', boyCast: [], girlCast: [] };
    const pp = presentPeopleByGender(st, cast, sceneText);
    if (pp.unknown.length) return res; // кто-то в сцене неясного пола — сплошную подстановку не делаем
    // сплошная подстановка — только если этот герой ЕДИНСТВЕННЫЙ своего пола в сцене (канонный или нет — неважно)
    if (pp.boy.length === 1 && pp.boy[0].tag) { res.boy = pp.boy[0].tag; res.boyCast = [String(pp.boy[0].name).toLowerCase()]; }
    if (pp.girl.length === 1 && pp.girl[0].tag) { res.girl = pp.girl[0].tag; res.girlCast = [String(pp.girl[0].name).toLowerCase()]; }
    return res;
}

// Несколько канонных героев одного пола в сцене: определяем, кто в кадре/слоте, по совпадению примет из карточки
// (уши, хвост, шрам, цвет волос, очки…) и по имени в реплике этого кадра. Тег ставим, только если победитель явный.
const NNB_GENERIC_APPEAR_TOK_RE = /^(?:1boy|1girl|boy|girl|male|female|man|woman|adult|solo|mature male|mature female|tall|short|slim|muscular|handsome|beautiful|young|anime|manga)$/i;
function canonCandidatesFromCards(st, cast, sceneText) {
    // кандидаты для угадывания по приметам: ВСЕ герои пола (в т.ч. без канона — если победит такой, тег не ставим)
    const pp = presentPeopleByGender(st, cast, sceneText);
    for (const p of pp.unknown) { if (p.tag) try { logImageDiag(`Страж внешности: у «${p.name}» есть канон-тег, но не понятен пол — добавь в его теги 1boy или 1girl`); } catch (e) { /* ignore */ } }
    const out = { boy: [], girl: [] };
    for (const g of ['boy', 'girl']) {
        if (pp[g].some(p => p.tag) && (pp[g].length >= 2 || pp.unknown.length)) out[g] = [...pp[g], ...pp.unknown];
    }
    return out;
}
function signatureScore(seg, sig) {
    const segToks = String(seg || '').toLowerCase().split(',').map(t => t.trim()).filter(Boolean);
    let score = 0;
    for (const t of sig) {
        if (segToks.includes(t)) { score += (/\beyes\b/.test(t) ? 3 : 2); continue; }
        // мягкое совпадение по ключевому слову: «dog ears» ~ «black dog ears», «scar on mouth» ~ «scar on lip»
        const words = t.split(/\s+/).filter(w => w.length >= 4 && !/^(hair|eyes|ears|tail|tails|horns|wings|with|black|white|short|long|small|large|animal)$/.test(w));
        if (words.length && words.every(w => segToks.some(st => st.includes(w)))) score += 1;
    }
    return score;
}
function assignCanonBySignature(rawPromptStr, candidates, hintText = '') {
    let out = String(rawPromptStr || '');
    if (!out) return out;
    const segs = out.split(/(\s*\|\|\s*)/);
    for (let i = 0; i < segs.length; i += 2) {
        let seg = segs[i];
        if (!seg || /\b(?:no humans|head out of frame|hand focus|object focus|animal focus)\b/i.test(seg)) continue;
        if (hasAnyCanonTagInSegment(seg)) continue;
        for (const g of ['boy', 'girl']) {
            const list = candidates[g] || [];
            if (list.length < 2) continue; // одиночного героя уже ставит canonByGenderFromCards
            const gTok = g === 'boy' ? '1boy' : '1girl';
            const multiRe = g === 'boy' ? /\b(?:2boys|3boys|4boys|multiple boys)\b/i : /\b(?:2girls|3girls|4girls|multiple girls)\b/i;
            if (!new RegExp(`\\b${gTok}\\b`, 'i').test(seg) || multiRe.test(seg)) continue;
            const scored = list.map(c => ({ c, s: signatureScore(seg, c.sig) + (hintText && isNameMentionedInText(c.name, hintText) ? 3 : 0) }))
                .sort((a, b) => b.s - a.s);
            if (!scored.length || scored[0].s <= 0 || (scored[1] && scored[0].s - scored[1].s < 2)) continue; // ничья — не гадаем
            const tagVal = scored[0].c.tag;
            if (!tagVal) continue; // по приметам это герой без канона (напр. Кайлар) — ничего не подставляем
            if (/^\s*(?:CHAR\d+\s*:\s*)?(?:1boy\s*,\s*1girl|1girl\s*,\s*1boy)\b/i.test(seg)) {
                seg = seg.replace(/(^\s*(?:CHAR\d+\s*:\s*)?(?:1boy\s*,\s*1girl|1girl\s*,\s*1boy)\s*,?)/i, `$1 ${tagVal},`);
            } else {
                seg = seg.replace(new RegExp(`(\\b${gTok}\\s*,?)`, 'i'), `$1 ${tagVal},`);
            }
            seg = seg.replace(/,\s*,/g, ',');
        }
        segs[i] = seg;
    }
    return segs.join('');
}

function stripAbsentCardCanons(rawPromptStr, st, cast, sceneText) {
    let out = String(rawPromptStr || '');
    if (!out || !st) return out;
    const castNorm = (cast || []).map(x => String(x || '').toLowerCase().replace(/ё/g, 'е')).filter(Boolean);
    const cards = [...(st.npcs || [])];
    if (st.mainCharCard) cards.push(st.mainCharCard);
    for (const n of cards) {
        if (!n?.name) continue;
        const canon = parseCanonFromAppearance(n.appearanceEn);
        if (!canon) continue;
        const nm = String(n.name).toLowerCase().replace(/ё/g, 'е');
        const nmToks = nm.split(/[\s-]+/).filter(Boolean);
        const present = castNorm.length
            ? castNorm.some(c => {
                if (c === nm) return true;
                const cToks = c.split(/[\s-]+/).filter(Boolean);
                if (cToks.some(ct => nmToks.includes(ct))) return true;
                return nm.length >= 4 && c.length >= 4 && (c.includes(nm) || nm.includes(c));
            })
            : !!(sceneText && isNameMentionedInText(n.name, sceneText));
        if (present) continue;
        const escN = canon.name.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
        const escS = canon.series.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
        out = out
            .replace(new RegExp(`(^|,)\\s*${escN}\\s*\\(\\s*${escS}\\s*\\)\\s*(?=,|\\|\\||$)`, 'gi'), '$1')
            .replace(new RegExp(`(^|,)\\s*${escN}\\s*,\\s*${escS}\\s*(?=,|\\|\\||$)`, 'gi'), '$1')
            .replace(new RegExp(`(^|,)\\s*${escN}\\s*(?=,|\\|\\||$)`, 'gi'), '$1')
            .replace(/,\s*,/g, ',').replace(/,\s*(\|\|)/g, ' $1').replace(/^\s*,\s*/, '');
    }
    return out;
}

// Звериные уши/хвост/рога/крылья из тегов карточки: если в кадре единственный герой этого пола из сцены, а модель приметы забыла — дописываем
const NNB_BODY_FEATURE_RE = /\b(?:ears?|tails?|horns?|wings?|halo|antennae|fangs)\b/i;
function injectCardBodyFeatures(rawPromptStr, st, cast, sceneText) {
    let out = String(rawPromptStr || '');
    if (!out || !st) return out;
    const pp = presentPeopleByGender(st, cast, sceneText);
    if (pp.unknown.length) return out;
    const segs = out.split(/(\s*\|\|\s*)/);
    for (let i = 0; i < segs.length; i += 2) {
        let seg = segs[i];
        if (!seg || /\b(?:no humans|head out of frame|hand focus|object focus)\b/i.test(seg)) continue;
        for (const g of ['boy', 'girl']) {
            if (pp[g].length !== 1 || !pp[g][0].feats.length) continue; // в сцене двое одного пола — не гадаем, чьи уши
            const gTok = g === 'boy' ? '1boy' : '1girl';
            const otherTok = g === 'boy' ? '1girl' : '1boy';
            const multiRe = g === 'boy' ? /\b(?:2boys|3boys|4boys|multiple boys)\b/i : /\b(?:2girls|3girls|4girls|multiple girls)\b/i;
            if (!new RegExp(`\\b${gTok}\\b`, 'i').test(seg) || multiRe.test(seg)) continue;
            if (new RegExp(`\\b${otherTok}\\b`, 'i').test(seg) && i === 0 && segs.length > 1) continue;
            const low = seg.toLowerCase();
            const missing = pp[g][0].feats.filter(f => !low.includes(f.toLowerCase()));
            if (!missing.length) continue;
            seg = seg.replace(/\s*$/, '') + ', ' + missing.join(', ');
        }
        segs[i] = seg;
    }
    return segs.join('');
}

// Все, кто реально в сцене (NPC, главный герой карточки и героиня игрока), разложенные по полу.
// Нужен, чтобы не отдать канон-тег/уши одного героя другому того же пола, у которого канона нет.
function presentPeopleByGender(st, cast, sceneText) {
    const res = { boy: [], girl: [], unknown: [] };
    if (!st) return res;
    const castNorm = (cast || []).map(x => String(x || '').toLowerCase().replace(/ё/g, 'е')).filter(Boolean);
    const isPresent = name => {
        const nm = String(name || '').toLowerCase().replace(/ё/g, 'е');
        if (!nm) return false;
        // если модель дала CAST — верим ему: упоминание имени в реплике («Дойл вчера…») ещё не значит, что герой в кадре
        if (castNorm.length) {
            const nmToks = nm.split(/[\s-]+/).filter(Boolean);
            return castNorm.some(c => {
                if (c === nm) return true;
                const cToks = c.split(/[\s-]+/).filter(Boolean);
                if (cToks.some(ct => nmToks.includes(ct))) return true;
                return nm.length >= 4 && c.length >= 4 && (c.includes(nm) || nm.includes(c));
            });
        }
        return !!(sceneText && isNameMentionedInText(name, sceneText));
    };
    const cards = [...(st.npcs || [])];
    if (st.mainCharCard) cards.push(st.mainCharCard);
    try {
        const c = ctx();
        const userName = c.name1 || '';
        if (userName && !cards.some(n => String(n?.name || '').toLowerCase() === String(userName).toLowerCase())) {
            const pd = c.powerUserSettings?.persona_description || c.extensionSettings?.persona?.description || '';
            cards.push({ name: userName, card: String(pd), appearanceEn: '', __persona: true });
        }
    } catch (e) { /* ignore */ }
    const seen = new Set();
    for (const n of cards) {
        if (!n?.name || seen.has(String(n.name).toLowerCase())) continue;
        seen.add(String(n.name).toLowerCase());
        if (!isPresent(n.name)) continue;
        const appEn = String(n.appearanceEn || '');
        const canon = parseCanonFromAppearance(appEn);
        let g = guessCardGender(n, canon);
        if (!g) {
            const tx = appEn.toLowerCase();
            if (/\b(1girl|girl|female|woman)\b/.test(tx)) g = 'girl';
            else if (/\b(1boy|boy|male|man)\b/.test(tx)) g = 'boy';
        }
        const sig = appEn.split(',').map(t => t.trim().toLowerCase()).filter(t => t && !NNB_GENERIC_APPEAR_TOK_RE.test(t)
            && (!canon || (t !== canon.name.toLowerCase() && t !== canon.series.toLowerCase() && t !== canon.tag.toLowerCase())));
        const feats = appEn.split(',').map(t => t.trim()).filter(t => t && NNB_BODY_FEATURE_RE.test(t) && t.split(/\s+/).length <= 4);
        (res[g] || res.unknown).push({ name: n.name, tag: canon ? canon.tag : '', core: canon ? canon.name : '', sig, feats });
    }
    return res;
}

function extractCanonTagsByGender(promptsList) {
    const found = { boy: '', girl: '' };
    const list = Array.isArray(promptsList) ? promptsList : [];
    for (const raw of list) {
        const segs = String(raw || '').split(/\s*\|\|\s*/);
        for (const seg of segs) {
            if (!seg || /\b(?:no humans|head out of frame|hand focus|object focus|animal focus)\b/i.test(seg)) continue;
            const hasBoy = /\b1boy\b/i.test(seg) && !/\b(?:2boys|3boys|multiple boys)\b/i.test(seg);
            const hasGirl = /\b1girl\b/i.test(seg) && !/\b(?:2girls|3girls|multiple girls)\b/i.test(seg);
            const isSoloBoy = hasBoy && !hasGirl;
            const isSoloGirl = hasGirl && !hasBoy;
            if (!isSoloBoy && !isSoloGirl) continue;
            const genderKey = isSoloBoy ? 'boy' : 'girl';
            if (found[genderKey]) continue;

            const toks = seg.replace(/^CHAR\d+\s*:\s*/i, '').split(',').map(t => t.trim()).filter(Boolean);
            for (let i = 0; i < toks.length; i++) {
                const tk = toks[i];
                const pm = tk.match(/^([a-z][a-z0-9' _.-]{1,40})\s*\(\s*([a-z0-9][a-z0-9' :_./!-]{2,45})\s*\)$/i);
                if (pm && !NNB_NON_CANON_NAME_RE.test(pm[1].trim()) && !NNB_NON_SERIES_PAREN_RE.test(pm[2].trim())) {
                    found[genderKey] = `${pm[1].trim()} (${pm[2].trim()})`;
                    break;
                }
                if (i > 0 && NNB_CANON_SERIES_RE.test(tk) && !NNB_NON_CANON_NAME_RE.test(toks[i - 1])) {
                    found[genderKey] = `${toks[i - 1]}, ${tk}`;
                    break;
                }
            }
        }
    }
    return found;
}

function hasAnyCanonTagInSegment(seg) {
    const toks = String(seg || '').replace(/^CHAR\d+\s*:\s*/i, '').split(',').map(t => t.trim()).filter(Boolean);
    for (let i = 0; i < toks.length; i++) {
        const tk = toks[i];
        const pm = tk.match(/^([a-z][a-z0-9' _.-]{1,40})\s*\(\s*([a-z0-9][a-z0-9' :_./!-]{2,45})\s*\)$/i);
        if (pm && !NNB_NON_CANON_NAME_RE.test(pm[1].trim()) && !NNB_NON_SERIES_PAREN_RE.test(pm[2].trim())) return true;
        if (i > 0 && NNB_CANON_SERIES_RE.test(tk) && !NNB_NON_CANON_NAME_RE.test(toks[i - 1])) return true;
    }
    return false;
}

function carryOverChapterCanonTags(rawPromptStr, canonByGender, activeCast = [], activeChunkText = '') {
    let out = String(rawPromptStr || '');
    if (!out || !canonByGender || (!canonByGender.boy && !canonByGender.girl)) return out;
    const castNorm = (Array.isArray(activeCast) ? activeCast : []).map(x => String(x || '').toLowerCase().replace(/ё/g, 'е')).filter(Boolean);
    const chunkNorm = String(activeChunkText || '').toLowerCase().replace(/ё/g, 'е');
    const segs = out.split(/(\s*\|\|\s*)/);
    for (let i = 0; i < segs.length; i += 2) {
        let seg = segs[i];
        if (!seg || /\b(?:no humans|head out of frame|hand focus|object focus|animal focus)\b/i.test(seg)) continue;
        // Если в этом слоте уже есть какой-то каноничный тег Danbooru — не трогаем
        if (hasAnyCanonTagInSegment(seg)) continue;
        for (const [genderKey, tagVal, ownerNames] of [
            ['boy', canonByGender.boy, canonByGender.boyCast || []],
            ['girl', canonByGender.girl, canonByGender.girlCast || []],
        ]) {
            if (!tagVal) continue;
            // Проверяем, что герой с этим канон-тегом реально присутствует в текущем куске/CAST, а не сменился на другого персонажа
            if (ownerNames.length) {
                const ownerPresent = ownerNames.some(nm =>
                    castNorm.some(c => c.includes(nm) || nm.includes(c))
                    || (chunkNorm && isNameMentionedInText(nm, chunkNorm))
                );
                if (!ownerPresent) continue;
            }
            const gTok = genderKey === 'boy' ? '1boy' : '1girl';
            const multiRe = genderKey === 'boy' ? /\b(?:2boys|3boys|4boys|multiple boys)\b/i : /\b(?:2girls|3girls|4girls|multiple girls)\b/i;
            if (!new RegExp(`\\b${gTok}\\b`, 'i').test(seg) || multiRe.test(seg)) continue;
            const coreName = tagVal.split(/[,(]/)[0].trim();
            if (!coreName) continue;
            const escCore = coreName.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
            if (new RegExp(`\\b${escCore}\\b`, 'i').test(seg)) continue;
            // Insert canonical tag right after 1boy / 1girl (or after 1boy, 1girl pair)
            if (/^\s*(?:CHAR\d+\s*:\s*)?(?:1boy\s*,\s*1girl|1girl\s*,\s*1boy)\b/i.test(seg)) {
                seg = seg.replace(/(^\s*(?:CHAR\d+\s*:\s*)?(?:1boy\s*,\s*1girl|1girl\s*,\s*1boy)\s*,?)/i, `$1 ${tagVal},`);
            } else {
                seg = seg.replace(new RegExp(`(\\b${gTok}\\s*,?)`, 'i'), `$1 ${tagVal},`);
            }
            seg = seg.replace(/,\s*,/g, ',');
        }
        segs[i] = seg;
    }
    return segs.join('');
}

function replaceOriginalPlaceholderWithNpcAppearance(rawPromptStr, st) {
    let out = String(rawPromptStr || '');
    if (!out || !st) return out;
    const cards = [...(st.npcs || [])];
    if (st.mainCharCard) cards.push(st.mainCharCard);
    for (const npc of cards) {
        const appEn = String(npc?.appearanceEn || '').trim();
        if (!appEn || !npc?.name) continue;
        const enVars = transliterateRuNameVariants(npc.name);
        for (const ev of enVars) {
            const esc = ev.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
            const origRe = new RegExp(`\\b${esc}\\s*\\(\\s*original\\s*\\)`, 'gi');
            if (origRe.test(out)) {
                out = out.replace(origRe, appEn);
            }
        }
    }
    return out;
}

function parsePanelTextAndCharSlots(rawPanelStr) {
    const raw = String(rawPanelStr || '').trim();
    if (!raw) return { prompt: '', charCaptions: [] };
    const segments = raw.split(/\s*\|\|\s*/);
    const baseParts = [];
    const charCaps = [];
    for (const seg of segments) {
        const m = seg.trim().match(/^CHAR\s*(\d+)\s*[:：—–-]\s*(.+)$/i);
        if (m && m[2].trim()) {
            charCaps.push(m[2].trim().replace(/\]$/, ''));
        } else if (seg.trim()) {
            baseParts.push(seg.trim());
        }
    }
    return {
        prompt: baseParts.join(', ').replace(/,\s*,+/g, ', ').trim(),
        charCaptions: charCaps,
    };
}

function buildDistinctComicPanelsFallback(baseDesc, charCaptions, isNai = true) {
    const cleanBase = sanitizeLiteralMetaphorTags(String(baseDesc || '').trim());
    const caps = Array.isArray(charCaptions) ? charCaptions.filter(Boolean).map(c => sanitizeLiteralMetaphorTags(c)) : [];

    // Если слоты CHAR не пришли, но в строке SCENE перечислены несколько людей (man/woman/boy/girl), выделяем их описания отдельно, чтобы не пихать всю толпу в каждый кадр!
    const allTokens = cleanBase.split(',').map(t => t.trim()).filter(Boolean);
    const charTokenRe = /\b(man|woman|boy|girl|male|female|demi-cat|demi-dog|blonde|dark-haired|copper hair|grey hair|greying)\b/i;
    const countOrCamRe = /\b([1-9]boys?|[1-9]girls?|multiple boys|multiple girls|wide shot|full body|wide establishing shot|medium shot|two-shot|six people|five people|four people|three people|standing apart)\b/i;
    const envTokens = allTokens.filter(t => !charTokenRe.test(t) && !countOrCamRe.test(t)).slice(0, 6);
    const charClauses = allTokens.filter(t => charTokenRe.test(t) && !/^(?:[1-9]boys?|[1-9]girls?|multiple boys|multiple girls)$/i.test(t));

    const char1Identity = caps[0] ? stripActionAndPropTagsFromCharCaption(caps[0]) : (charClauses[0] || '');
    const char2Identity = caps[1] ? stripActionAndPropTagsFromCharCaption(caps[1]) : (charClauses[1] || '');
    const char3Identity = caps[2] ? stripActionAndPropTagsFromCharCaption(caps[2]) : (charClauses[2] || charClauses[0] || '');
    const envStr = envTokens.join(', ') || 'indoors, detailed background';

    // Кадр 1: 1–2 персонажа из завязки сцены (средний план)
    let panel1 = '';
    if (char1Identity && char2Identity) {
        const g1 = /\b(woman|girl|female|1girl)\b/i.test(char1Identity) ? '1girl' : '1boy';
        const g2 = /\b(woman|girl|female|1girl)\b/i.test(char2Identity) ? '1girl' : '1boy';
        const countTag = (g1 === '1boy' && g2 === '1boy') ? '2boys, multiple boys' : ((g1 === '1girl' && g2 === '1girl') ? '2girls, multiple girls' : '1boy, 1girl');
        panel1 = `${countTag}, medium shot, cowboy shot, ${envStr}, ${char1Identity}, ${char2Identity} || CHAR1: ${g1}, ${char1Identity} || CHAR2: ${g2}, ${char2Identity}`;
    } else {
        panel1 = `medium shot, ${cleanBase}`;
    }

    // Кадр 2: смена ракурса и действия (второй и третий персонаж ИЛИ смена позы вблизи, без толпы и без wide shot)
    let panel2 = '';
    const p2A = char2Identity || char1Identity;
    const p2B = (charClauses.length >= 3 ? char3Identity : char1Identity);
    if (p2A && p2B && p2A !== p2B) {
        const gA = /\b(woman|girl|female|1girl)\b/i.test(p2A) ? '1girl' : '1boy';
        const gB = /\b(woman|girl|female|1girl)\b/i.test(p2B) ? '1girl' : '1boy';
        const countTag2 = (gA === '1boy' && gB === '1boy') ? '2boys, multiple boys' : ((gA === '1girl' && gB === '1girl') ? '2girls, multiple girls' : '1boy, 1girl');
        const stripA = stripActionAndPropTagsFromCharCaption(p2A) || p2A;
        const stripB = stripActionAndPropTagsFromCharCaption(p2B) || p2B;
        panel2 = `${countTag2}, dynamic angle, medium close-up, upper body, expressive dialogue, gesturing, ${stripA}, ${stripB}, ${envStr}, depth of field || CHAR1: ${gA}, ${stripA}, speaking, expressive hand gesture, upper body || CHAR2: ${gB}, ${stripB}, looking at speaker, emotional reaction, upper body`;
    } else if (p2A) {
        const gA = /\b(woman|girl|female|1girl)\b/i.test(p2A) ? '1girl, solo' : '1boy, solo';
        panel2 = `${gA}, dynamic angle, medium close-up, upper body, ${stripActionAndPropTagsFromCharCaption(p2A) || p2A}, expressive hand gesture, shifting posture, ${envStr}, depth of field`;
    } else {
        panel2 = cleanSingleComicPanelPrompt(`dynamic angle, medium close-up, upper body, ${stripActionAndPropTagsFromCharCaption(cleanBase)}`, 1);
    }

    // Кадр 3: строго СОЛЬНЫЙ крупный эмоциональный план одного героя (1boy, solo, close-up ИЛИ 1girl, solo, close-up) БЕЗ толпы и БЕЗ wide shot/full body!
    const soloTarget = char3Identity || char2Identity || char1Identity;
    let panel3 = '';
    if (soloTarget) {
        const genderTag = /\b(woman|girl|female|1girl)\b/i.test(soloTarget) ? '1girl, solo' : '1boy, solo';
        const cleanedSolo = stripActionAndPropTagsFromCharCaption(soloTarget).replace(/\b([1-9]girls?|[1-9]boys?|multiple boys|multiple girls|wide shot|full body)\b\s*,?/gi, '').trim();
        panel3 = `${genderTag}, close-up, portrait, upper body, focus on face and expressive eyes, ${cleanedSolo}, emotional reaction, detailed eyes, blurry background, bokeh, dramatic lighting`;
    } else {
        panel3 = `solo, close-up, portrait, upper body, expressive emotional reaction, detailed eyes, blurry background, bokeh`;
    }

    const panel4 = char1Identity
        ? `${/\b(woman|girl|female|1girl)\b/i.test(char1Identity) ? '1girl, solo' : '1boy, solo'}, medium close-up, dynamic angle, upper body, ${stripActionAndPropTagsFromCharCaption(char1Identity).replace(/\b([1-9]girls?|[1-9]boys?|multiple boys|multiple girls|wide shot|full body)\b\s*,?/gi, '').trim()}, expressive reaction, detailed background, dramatic lighting`
        : panel2;
    return [panel1, panel2, panel3, panel4];
}

function buildRefsForSingleComicFrame(baseRefs, frameDesc, frameCharCaps, fIdx, whoNames = []) {
    const cleanDesc = String(frameDesc || '');
    // Если этот фрейм — крупный план детали (животное/змея, предмет, руки или 18+ интимный крупный план без головы/лица),
    // НЕ передаём в NovelAI портретный аватар-референс (images) и слоты полных фигур (charCaptions), чтобы NovelAI не пытался пририсовать поверх змеи или детали стоящего человека с лицом!
    const comicCleanArtNeg = 'speech bubble, text, english text, romanji, letters, word, purr text, korean text, hangul, japanese text, sound effects, sfx, watermark, signature, username, artist name, two cups in hands, holding two cups, mummy hands, all fingers bandaged, broken glass in air, plastic wrap';
    const isNsfwOrBareAllowed = /\b(nsfw|explicit|nude|naked|undressing|topless|lingerie|swimsuit|bikini|bath|shower|sex|intimate|bed|bedroom|collarbone|bite mark|hickey|strapless)\b/i.test(cleanDesc);
    const nonNsfwClothingNeg = !isNsfwOrBareAllowed ? 'bare shoulders, strapless, strapless dress, off-shoulder, topless, nude, undressed' : '';
    const isJamOrSweetFrame = /\b(jam|jelly|preserve|marmalade|strawberry|berry|syrup)\b/i.test(cleanDesc) && !/\b(blood|wound|injury|horror)\b/i.test(cleanDesc);
    const jamNotBloodNeg = isJamOrSweetFrame ? 'blood, bleeding, gore, wound, injury, bloody hands, cut' : '';
    const isDemiTailOrFramedCat = /\b(fluffy tail|cat tail|safe door|kemonomimi tail|antennae|feelers)\b/i.test(cleanDesc);
    const noRealCatNeg = isDemiTailOrFramedCat ? 'real cat, animal, cat head, cat face, cat eyes, whiskers, four-legged animal, pet cat, real insect, bug, ant, cockroach, beetle, arthropod, insect head, compound eyes, mandibles, six legs' : '';
    const noGlovesNeg = !/\bgloves?\b/i.test(cleanDesc) ? 'gloves, work gloves, rubber gloves, mittens' : '';
    const isMaleBodyDetail = /\b(sweatpants|bulge|erection|abs|pectorals?|muscular chest|scars on chest|1boy, solo, male body)\b/i.test(cleanDesc);
    const maleBodyAntiFemaleNeg = isMaleBodyDetail ? '1girl, female, woman, female body, panties, white panties, bikini bottom, wide female hips, feminine waist, bra' : '';
    const isSnakeFrame = /\b(snake|python|viper|serpent|reptile)\b/i.test(cleanDesc);
    const snakeAntiMutantNeg = isSnakeFrame ? 'fishing hook, fishhook, meat hook, metal ring, chain, tied, knotted, two-headed, multiple heads, extra head, split body, two snakes, mutated animal, deformed animal' : '';
    const isFoodFrame = /\b(profiteroles|cream puffs|pastry|cake|bun|bread|food|dessert|tea|cups|crumbs)\b/i.test(cleanDesc);
    const foodAntiMascotNeg = isFoodFrame ? 'face on food, eyes on food, anthropomorphic food, mascot, cute face on object, living food' : '';
    const isPureObjectNoHumans = /\b(no humans|object focus|food focus|still life|crumbs|windowsill|windshield|wipers)\b/i.test(cleanDesc) && !isSnakeFrame && !/\b(animal focus|cat|dog|bird|hand focus|hands|fingers|thumb|neck|collarbone|nsfw|explicit|intimate)\b/i.test(cleanDesc);
    const objectNoFaceNeg = isPureObjectNoHumans ? '1girl, 1boy, human, person, face, eyes, nose, mouth, mascot, cute creature, chibi, blob, slime, face in window, reflection of face, ghostly face, creepy face, pareidolia' : '';

    if (isDetailOrMacroPanelPrompt(cleanDesc)) {
        const isHandDetail = /\b(hand focus|hands focus|focus on hands|hands|fingers|thumb|palm|wrist|clasped|intertwined|interlaced|unbuttoning|holding|bag|handbag|keys|jam|tarot|cards|deck|knocking|fist|knuckles)\b/i.test(cleanDesc);
        const handAntiMutantNeg = isHandDetail ? 'extra hands, multiple hands, 3 hands, 4 hands, extra arms, 3 arms, disembodied hands, mutated hands, malformed hands, bad hands, extra fingers, too many fingers, 6 fingers, 7 fingers, fused fingers, tangled fingers, extra digits, motion blur hands, text on cards, letters on cards' : '';
        const isNeckMacro = /\b(neck|collarbone|clavicle|throat|hickey|bruise|bite mark)\b/i.test(cleanDesc);
        const neckAntiDecapNeg = isNeckMacro ? 'headless, decapitated, severed head, severed neck, gore, guro, grotesque, meat, flesh cross-section, eye on neck, face on neck, disembodied, body horror' : '';
        const mergedNeg = [baseRefs?.extraNeg || '', comicCleanArtNeg, handAntiMutantNeg, neckAntiDecapNeg, jamNotBloodNeg, noRealCatNeg, noGlovesNeg, maleBodyAntiFemaleNeg, snakeAntiMutantNeg, foodAntiMascotNeg, objectNoFaceNeg].filter(Boolean).join(', ');
        return { ...(baseRefs || {}), images: [], charCaptions: [], extraNeg: mergedNeg, note: '' };
    }
    const hasGirls = /\b([1-6]girls?|female|woman|girl)\b/i.test(cleanDesc);
    const hasBoys = /\b([1-6]boys?|male|man|boy)\b/i.test(cleanDesc);
    const hasMultiGirls = /\b([2-6]girls|multiple girls|two women|two girls)\b/i.test(cleanDesc);
    const hasMultiBoys = /\b([2-6]boys|multiple boys|two men|two boys)\b/i.test(cleanDesc);
    const isExplicitSolo = /\bsolo\b/i.test(cleanDesc) || (hasGirls && !hasBoys && !hasMultiGirls) || (hasBoys && !hasGirls && !hasMultiBoys);

    let activeCharCaps = [];
    if (!isExplicitSolo) {
        if (Array.isArray(frameCharCaps) && frameCharCaps.length >= 2) {
            activeCharCaps = frameCharCaps;
        } else if (Array.isArray(baseRefs?.charCaptions) && baseRefs.charCaptions.length >= 2) {
            if (fIdx === 0) {
                activeCharCaps = baseRefs.charCaptions;
            } else {
                // Во 2-м и 3-м кадрах НИКОГДА не передаём старые позы и предметы (креветки/контейнер/кровать) из 1-го кадра!
                activeCharCaps = baseRefs.charCaptions.map(c => stripActionAndPropTagsFromCharCaption(c)).filter(Boolean);
            }
        }
    }

    if (!baseRefs) {
        return activeCharCaps.length ? { images: [], extraNeg: '', charCaptions: activeCharCaps, note: '' } : null;
    }

    return {
        ...baseRefs,
        extraNeg: [baseRefs.extraNeg || '', comicCleanArtNeg, nonNsfwClothingNeg, jamNotBloodNeg, noRealCatNeg, noGlovesNeg, maleBodyAntiFemaleNeg, snakeAntiMutantNeg, foodAntiMascotNeg].filter(Boolean).join(', '),
        charCaptions: activeCharCaps,
    };
}

let bgKeepAliveAudioCtx = null;
let bgKeepAliveOsc = null;
let bgKeepAliveAudioEl = null;
let bgKeepAliveWavUrl = '';
let bgKeepAliveWakeLock = null;
let bgKeepAliveLockResolver = null;
let bgKeepAliveRtc1 = null;
let bgKeepAliveRtc2 = null;
let bgKeepAliveRtcDc = null;
let bgKeepAliveWorker = null;
let bgWorkerTimerSeq = 0;
const bgWorkerTimerCallbacks = new Map();
let multiPageKeepAliveActive = false;

function ensureBackgroundTimerWorker() {
    if (bgKeepAliveWorker) return bgKeepAliveWorker;
    try {
        const workerCode = `
            const timers = new Map();
            self.onmessage = function(e) {
                const d = e.data || {};
                if (d.cmd === 'sleep') {
                    const tid = setTimeout(() => {
                        timers.delete(d.id);
                        self.postMessage({ id: d.id });
                    }, d.ms || 0);
                    timers.set(d.id, tid);
                } else if (d.cmd === 'cancel') {
                    const tid = timers.get(d.id);
                    if (tid) { clearTimeout(tid); timers.delete(d.id); }
                }
            };
        `;
        const blob = new Blob([workerCode], { type: 'application/javascript' });
        const wUrl = URL.createObjectURL(blob);
        const w = new Worker(wUrl);
        w.onmessage = (e) => {
            const id = e.data?.id;
            const cb = bgWorkerTimerCallbacks.get(id);
            if (cb) {
                bgWorkerTimerCallbacks.delete(id);
                cb();
            }
        };
        bgKeepAliveWorker = w;
    } catch (e) { /* fallback to setTimeout */ }
    return bgKeepAliveWorker;
}

// Таймер ожидания, который НЕ замораживается и НЕ замедляется до 60 сек. в фоновой вкладке!
function bgSafeSleep(ms) {
    const w = ensureBackgroundTimerWorker();
    if (!w) return new Promise(r => setTimeout(r, ms));
    return new Promise(resolve => {
        const id = ++bgWorkerTimerSeq;
        const fallbackTid = setTimeout(() => {
            if (bgWorkerTimerCallbacks.has(id)) {
                bgWorkerTimerCallbacks.delete(id);
                resolve();
            }
        }, ms + 1500);
        bgWorkerTimerCallbacks.set(id, () => {
            clearTimeout(fallbackTid);
            resolve();
        });
        try {
            w.postMessage({ cmd: 'sleep', id, ms });
        } catch (e) {
            bgWorkerTimerCallbacks.delete(id);
            clearTimeout(fallbackTid);
            setTimeout(resolve, ms);
        }
    });
}

function buildInaudibleKeepAliveWavUrl() {
    if (bgKeepAliveWavUrl) return bgKeepAliveWavUrl;
    try {
        const sampleRate = 8000;
        const numSamples = sampleRate; // 1 секунда в петле
        const buf = new ArrayBuffer(44 + numSamples * 2);
        const view = new DataView(buf);
        const writeStr = (off, s) => { for (let i = 0; i < s.length; i++) view.setUint8(off + i, s.charCodeAt(i)); };
        writeStr(0, 'RIFF');
        view.setUint32(4, 36 + numSamples * 2, true);
        writeStr(8, 'WAVE');
        writeStr(12, 'fmt ');
        view.setUint32(16, 16, true);
        view.setUint16(20, 1, true); // PCM
        view.setUint16(22, 1, true); // Mono
        view.setUint32(24, sampleRate, true);
        view.setUint32(28, sampleRate * 2, true);
        view.setUint16(32, 2, true);
        view.setUint16(34, 16, true);
        writeStr(36, 'data');
        view.setUint32(40, numSamples * 2, true);
        // 16 Гц инфразвук с амплитудой 48/32767 (~0.0014) — выше порога SilentAudioDetector в Chromium, но 100% ниже порога слышимости человека!
        for (let i = 0; i < numSamples; i++) {
            const val = Math.round(Math.sin((2 * Math.PI * 16 * i) / sampleRate) * 48);
            view.setInt16(44 + i * 2, val, true);
        }
        bgKeepAliveWavUrl = URL.createObjectURL(new Blob([buf], { type: 'audio/wav' }));
    } catch (e) { /* ignore */ }
    return bgKeepAliveWavUrl;
}

function startBackgroundGenerationKeepAlive() {
    ensureBackgroundTimerWorker();
    // 1. Web Lock API
    try {
        if (typeof navigator !== 'undefined' && navigator.locks && typeof navigator.locks.request === 'function' && !bgKeepAliveLockResolver) {
            navigator.locks.request('nnb_background_manhwa_generation', { mode: 'exclusive' }, () => new Promise(res => {
                bgKeepAliveLockResolver = res;
            })).catch(() => {});
        }
    } catch (e) { /* ignore */ }
    // 2. Screen WakeLock
    try {
        if (typeof navigator !== 'undefined' && navigator.wakeLock && typeof navigator.wakeLock.request === 'function' && !bgKeepAliveWakeLock) {
            navigator.wakeLock.request('screen').then(wl => { bgKeepAliveWakeLock = wl; }).catch(() => {});
        }
    } catch (e) { /* ignore */ }
    // 3. HTML5 <audio loop> с не-нулевым инфразвуковым WAV (удерживает Android PARTIAL_WAKE_LOCK и не отключается SilentAudioDetector!)
    try {
        const wavUrl = buildInaudibleKeepAliveWavUrl();
        if (wavUrl && typeof Audio === 'function') {
            if (!bgKeepAliveAudioEl) {
                const aEl = new Audio(wavUrl);
                aEl.loop = true;
                aEl.volume = 0.02;
                aEl.setAttribute('playsinline', '');
                bgKeepAliveAudioEl = aEl;
            }
            if (bgKeepAliveAudioEl.paused) {
                bgKeepAliveAudioEl.play().catch(() => {});
            }
        }
    } catch (e) { /* ignore */ }
    // 4. Web Audio API (16 Hz инфразвук с gain 0.0015 — не считается тишиной в Chromium!)
    try {
        const AudioCtx = window.AudioContext || window.webkitAudioContext;
        if (AudioCtx && !bgKeepAliveAudioCtx) {
            bgKeepAliveAudioCtx = new AudioCtx();
            const osc = bgKeepAliveAudioCtx.createOscillator();
            const gain = bgKeepAliveAudioCtx.createGain();
            osc.frequency.value = 16;
            gain.gain.value = 0.0015;
            osc.connect(gain);
            gain.connect(bgKeepAliveAudioCtx.destination);
            osc.start();
            bgKeepAliveOsc = osc;
        } else if (bgKeepAliveAudioCtx && bgKeepAliveAudioCtx.state === 'suspended') {
            bgKeepAliveAudioCtx.resume().catch(() => {});
        }
    } catch (e) { /* ignore */ }
    // 5. Локальная петля WebRTC (RTCPeerConnection): в Chromium PageScheduler наличие активного RTCPeerConnection жёстко запрещает заморозку фоновой вкладки (HasActiveWebRTCConnection = true), даже если звук перехвачен другим приложением!
    try {
        if (typeof RTCPeerConnection === 'function' && !bgKeepAliveRtc1) {
            const pc1 = new RTCPeerConnection();
            const pc2 = new RTCPeerConnection();
            const dc = pc1.createDataChannel('nnb_keepalive');
            pc1.onicecandidate = e => { if (e.candidate) pc2.addIceCandidate(e.candidate).catch(() => {}); };
            pc2.onicecandidate = e => { if (e.candidate) pc1.addIceCandidate(e.candidate).catch(() => {}); };
            pc1.createOffer()
                .then(offer => pc1.setLocalDescription(offer).then(() => pc2.setRemoteDescription(offer)))
                .then(() => pc2.createAnswer())
                .then(answer => pc2.setLocalDescription(answer).then(() => pc1.setRemoteDescription(answer)))
                .catch(() => {});
            bgKeepAliveRtc1 = pc1;
            bgKeepAliveRtc2 = pc2;
            bgKeepAliveRtcDc = dc;
        }
    } catch (e) { /* ignore */ }
}

function stopBackgroundGenerationKeepAlive() {
    try {
        if (bgKeepAliveLockResolver) {
            const r = bgKeepAliveLockResolver;
            bgKeepAliveLockResolver = null;
            r();
        }
    } catch (e) { /* ignore */ }
    try {
        if (bgKeepAliveWakeLock) {
            bgKeepAliveWakeLock.release().catch(() => {});
            bgKeepAliveWakeLock = null;
        }
    } catch (e) { /* ignore */ }
    try {
        if (bgKeepAliveAudioEl) {
            bgKeepAliveAudioEl.pause();
            bgKeepAliveAudioEl = null;
        }
    } catch (e) { /* ignore */ }
    try {
        if (bgKeepAliveOsc) {
            bgKeepAliveOsc.stop();
            bgKeepAliveOsc.disconnect();
            bgKeepAliveOsc = null;
        }
        if (bgKeepAliveAudioCtx) {
            bgKeepAliveAudioCtx.close().catch(() => {});
            bgKeepAliveAudioCtx = null;
        }
    } catch (e) { /* ignore */ }
    try {
        if (bgKeepAliveRtcDc) { bgKeepAliveRtcDc.close(); bgKeepAliveRtcDc = null; }
        if (bgKeepAliveRtc1) { bgKeepAliveRtc1.close(); bgKeepAliveRtc1 = null; }
        if (bgKeepAliveRtc2) { bgKeepAliveRtc2.close(); bgKeepAliveRtc2 = null; }
    } catch (e) { /* ignore */ }
}

let sceneDrawing = false;
async function drawScene(popupEl, mesId, camMode = 'third', reuseMeta = null, forcedCast = null, directorWhisper = '', comicOpts = null) {
    if (sceneDrawing) {
        const elapsed = sceneDrawingStartedAt ? Math.round((Date.now() - sceneDrawingStartedAt) / 1000) : 0;
        if (elapsed > 240) {
            logImageDiag(`Предыдущая генерация висела ${elapsed} сек. — автоматический сброс`);
            sceneDrawing = false;
        } else {
            toastr.info(`Сцена уже рисуется (${elapsed} сек.). Если генерация зависла — открой «⚙️ Настройки → 📋 Диагностика и лог картинок → Сбросить».`, '🎬 Сцена', { timeOut: 6000 });
            return null;
        }
    }
    if (!canDrawScene()) return toastr.warning('Не выбрано, чем рисовать: настрой «Чем рисовать» в настройках блокнота.', '🎬 Сцена', { timeOut: 8000 });
    const st = store();
    if (!st || !ctx().chat?.length) return toastr.warning('Сначала открой чат', '🎬 Сцена');
    sceneDrawing = true;
    sceneDrawingStartedAt = Date.now();
    startBackgroundGenerationKeepAlive();
    const status = popupEl?.find('.nnb-scene-status');
    const say = t => status?.text(t);
    try {
        if (reuseMeta?.camMode) camMode = reuseMeta.camMode;
        const isPov = camMode === 'pov' || camMode === 'pov_hands' || camMode === 'pov_clean' || camMode === true;
        const isPovHands = camMode === 'pov' || camMode === 'pov_hands' || camMode === true;
        let desc = '';
        let extraNeg = reuseMeta?.extraNeg || '';
        let cast = [];
        let charCaptions = Array.isArray(reuseMeta?.charCaptions) ? [...reuseMeta.charCaptions] : [];
        const panelPrompts = Array.isArray(reuseMeta?.panelPrompts) ? [...reuseMeta.panelPrompts] : [];
        const rawLlmQuotes = [];

        if (reuseMeta && hasValidSceneMeta(reuseMeta)) {
            const splitReuse = splitPositiveAndNegativePrompt(reuseMeta.desc || reuseMeta.prompt);
            desc = splitReuse.positive;
            if (splitReuse.negative) extraNeg = [extraNeg, splitReuse.negative].filter(Boolean).join(', ');
            cast = Array.isArray(reuseMeta.cast) ? reuseMeta.cast : [];
            logImageDiag('Перерисовка по готовому промпту', desc);
        } else {
            // 1) описание сцены текстовой моделью (через отдельную модель промптов картинок, например GLM, если она выбрана!)
            const promptSrcLabel = settings().imgPromptSource || settings().textSource || 'основной чат';
            const isComicMode = !!(comicOpts && comicOpts.enabled);
            const cStyleObj = isComicMode ? getComicStyleById(comicOpts.styleId) : null;
            logImageDiag(`Шаг 1/2: запрос промпта ${isComicMode ? `комикса (${cStyleObj?.name || ''})` : 'сцены'} (источник: ${promptSrcLabel}, ракурс: ${camMode})`);
            const raw = await withBusy(isComicMode ? '💬 Модель составляет раскадровку комикса и проверяет реплики…' : '🎬 Модель составляет промпт для картинки…', () => quietGenerateImagePrompt(scenePromptRequest(st, mesId, camMode, forcedCast, directorWhisper, comicOpts)));
            logImageDiag('Ответ модели промптов получен', raw ? String(raw).slice(0, 500) : '(пусто)');
            // Поддержка ответа в формате <nai_imagen> (если пользователь вставил промпт из ext-blocks-custom) и многострочного SCENE:
            const rawCleaned = cleanAnswer(raw || '');
            const iigMatch = rawCleaned.match(/data-iig-instruction\s*=\s*['"]\s*\{[\s\S]*?"prompt"\s*:\s*"([^"]+)"/i);
            if (iigMatch && iigMatch[1]) {
                desc = iigMatch[1].trim();
            }
            const sceneLines = [];
            let inSceneBlock = false;
            let lastPanelIndex = -1;
            for (const rawLine of answerLines(raw || '')) {
                const line = rawLine.replace(/^[\s>*_#-]+/, '').replace(/[*_]+(?=\s*[:：—–-])/g, '').trim();
                let mp = line.match(/^(?:\d+[.)]\s*)?(?:PANEL|FRAME|КАДР|ФРЕЙМ)\s*[_#№]?\s*([1-4])\s*[:：—–.-]\s*(.+)$/i);
                if (mp) {
                    inSceneBlock = false;
                    const pTxt = mp[2].trim().replace(/\]$/, '');
                    if (pTxt) {
                        panelPrompts.push(pTxt);
                        lastPanelIndex = panelPrompts.length - 1;
                    }
                    continue;
                }
                let mq = line.match(/^(?:QUOTE|РЕПЛИКА|ЦИТАТА)\s*(\d*)\s*[:：—–-]\s*(.+)$/i);
                if (mq) {
                    inSceneBlock = false;
                    lastPanelIndex = -1;
                    const parsedQObj = parseRawQuoteLinePayload(mq[2], Number(mq[1]) || (rawLlmQuotes.length + 1));
                    if (parsedQObj) rawLlmQuotes.push(parsedQObj);
                    continue;
                }
                let m = line.match(/^CAST\s*[:：—–-]\s*(.+)$/i);
                if (m) {
                    inSceneBlock = false;
                    lastPanelIndex = -1;
                    const rawCast = m[1].trim();
                    if (/^(none|никого|нет|пусто|-)$/i.test(rawCast)) cast = ['__none__'];
                    else cast = rawCast.split(/[,;]/).map(x => x.trim().toLowerCase().replace(/ё/g, 'е')).filter(Boolean);
                    continue;
                }
                m = line.match(/^(?:NEGATIVE(?:\s+PROMPT)?|UNDESIRED(?:\s+CONTENT)?|UC)\s*[:：—–-]\s*(.+)$/i);
                if (m) {
                    inSceneBlock = false;
                    lastPanelIndex = -1;
                    extraNeg = [extraNeg, m[1].trim().replace(/\]$/, '')].filter(Boolean).join(', ');
                    continue;
                }
                m = line.match(/^CHAR\s*(\d+)\s*[:：—–-]\s*(.+)$/i);
                if (m) {
                    inSceneBlock = false;
                    const chCap = m[2].trim().replace(/\]$/, '');
                    if (chCap) {
                        // Приклеиваем CHAR к конкретному PANEL только если это 1-й кадр ИЛИ в предыдущих кадрах уже были свои слоты || CHAR;
                        // если же модель вывела общие CHAR1..CHAR4 в самом конце ответа после всех PANEL1..3, складываем их в общий массив charCaptions!
                        const isPerPanelChar = lastPanelIndex === 0 || (lastPanelIndex > 0 && panelPrompts[0] && /\|\|\s*CHAR\d+/i.test(panelPrompts[0]));
                        if (lastPanelIndex >= 0 && panelPrompts[lastPanelIndex] && isPerPanelChar) {
                            panelPrompts[lastPanelIndex] += ` || CHAR${m[1]}: ${chCap}`;
                        } else {
                            charCaptions.push(chCap);
                        }
                    }
                    continue;
                }
                m = line.match(/^SCENE\s*[:：—–-]\s*(.*)$/i);
                if (m) {
                    inSceneBlock = true;
                    if (m[1].trim()) sceneLines.push(m[1].trim().replace(/\]$/, ''));
                    continue;
                }
                if (inSceneBlock && !/^(CAST|CHAR\s*\d+|NEGATIVE|UNDESIRED|UC|NEXT|SKIP)\s*[:：—–-]/i.test(line)) {
                    sceneLines.push(line.replace(/\]$/, '').trim());
                }
            }
            if (!desc && sceneLines.length) {
                desc = sceneLines.join(', ').replace(/,\s*,+/g, ', ').trim();
            }
            if (!desc && panelPrompts.length) {
                desc = parsePanelTextAndCharSlots(panelPrompts[0]).prompt || panelPrompts[0];
            }
            if (!desc && raw) {
                const fallbackLines = answerLines(raw).filter(l => !/^(CAST|NEGATIVE|UC|PANEL\s*\d+|QUOTE\s*\d*|CHAR\s*\d+)\s*[:：—–-]/i.test(l) && !/^<\/?nai_imagen>/i.test(l));
                if (fallbackLines.length) desc = fallbackLines.join(', ').trim();
            }
            const splitDesc = splitPositiveAndNegativePrompt(desc);
            desc = sanitizeLiteralMetaphorTags(splitDesc.positive);
            if (splitDesc.negative) {
                extraNeg = [extraNeg, splitDesc.negative].filter(Boolean).join(', ');
                logImageDiag('Из строки SCENE автоматически вырезан блок | NEGATIVE и перенесён в негативный промпт', splitDesc.negative);
            }
            if (Array.isArray(forcedCast) && forcedCast.length) {
                const targetPostForCast = ctx().chat?.[Number.isInteger(mesId) ? mesId : (ctx().chat.length - 1)]?.mes || '';
                const effForced = (comicOpts?.enabled && comicOpts?.chunkText)
                    ? filterForcedCastForChunk(forcedCast, comicOpts.chunkText, targetPostForCast)
                    : forcedCast;
                effForced.forEach(fc => {
                    const nFc = fc.trim().toLowerCase().replace(/ё/g, 'е');
                    if (nFc && (!isPov || nFc !== storyNames().user.toLowerCase().replace(/ё/g, 'е')) && !cast.some(c => c.includes(nFc) || nFc.includes(c))) {
                        cast.push(nFc);
                    }
                });
            }
            if (!desc) throw new Error('модель не описала сцену (в ответе нет строки SCENE) — открой лог диагностики в настройках блокнота');
        }

        desc = replaceOriginalPlaceholderWithNpcAppearance(desc, st);
        charCaptions = charCaptions.map(c => replaceOriginalPlaceholderWithNpcAppearance(c, st));
        for (let pi = 0; pi < panelPrompts.length; pi++) {
            panelPrompts[pi] = replaceOriginalPlaceholderWithNpcAppearance(panelPrompts[pi], st);
        }
        {
            const beforeFix = [desc, ...charCaptions, ...panelPrompts].join(' ### ');
            desc = enforceNpcCanonAppearance(desc, st);
            charCaptions = charCaptions.map(c => enforceNpcCanonAppearance(c, st));
            for (let pi = 0; pi < panelPrompts.length; pi++) panelPrompts[pi] = enforceNpcCanonAppearance(panelPrompts[pi], st);
            {
                const cardSceneTxt = (comicOpts?.enabled && comicOpts?.chunkText) ? String(comicOpts.chunkText) : String(ctx().chat?.[Number.isInteger(mesId) ? mesId : (ctx().chat.length - 1)]?.mes || '');
                {
                    const b0 = [desc, ...charCaptions, ...panelPrompts].join(' ### ');
                    desc = stripAbsentCardCanons(desc, st, cast, cardSceneTxt);
                    charCaptions = charCaptions.map(c => stripAbsentCardCanons(c, st, cast, cardSceneTxt));
                    for (let pi = 0; pi < panelPrompts.length; pi++) panelPrompts[pi] = stripAbsentCardCanons(panelPrompts[pi], st, cast, cardSceneTxt);
                    if ([desc, ...charCaptions, ...panelPrompts].join(' ### ') !== b0) logImageDiag('Страж внешности: убраны канон-теги героев, которых нет в этой сцене (затащены из прошлых кадров)');
                }
                const fromCards = canonByGenderFromCards(st, cast, cardSceneTxt);
                const multiCanon = canonCandidatesFromCards(st, cast, cardSceneTxt);
                {
                    const ppD = presentPeopleByGender(st, cast, cardSceneTxt);
                    const fmt = arr => arr.map(c => `${c.name}${c.tag ? ` → ${c.tag}` : ' (без канона)'}`).join('; ') || '—';
                    logImageDiag('Страж внешности: кто в сцене', `парни: ${fmt(ppD.boy)} | девушки: ${fmt(ppD.girl)} | пол неясен: ${fmt(ppD.unknown)} | CAST: ${(cast || []).join(', ') || '—'}`);
                }
                if (multiCanon.boy.length >= 2 || multiCanon.girl.length >= 2) {
                    const qFor = idx => (Array.isArray(rawLlmQuotes) ? rawLlmQuotes.filter(q => Number(q?.panel) === idx + 1 && q?.kind !== 'narration').map(q => `${q?.speaker || ''}`).join(' ') : '');
                    desc = assignCanonBySignature(desc, multiCanon, '');
                    charCaptions = charCaptions.map(c => assignCanonBySignature(c, multiCanon, ''));
                    for (let pi = 0; pi < panelPrompts.length; pi++) panelPrompts[pi] = assignCanonBySignature(panelPrompts[pi], multiCanon, qFor(pi));
                }
                if (fromCards.boy || fromCards.girl || multiCanon.boy.length >= 2 || multiCanon.girl.length >= 2) {
                    desc = carryOverChapterCanonTags(desc, fromCards, cast, cardSceneTxt);
                    charCaptions = charCaptions.map(c => carryOverChapterCanonTags(c, fromCards, cast, cardSceneTxt));
                    for (let pi = 0; pi < panelPrompts.length; pi++) panelPrompts[pi] = carryOverChapterCanonTags(panelPrompts[pi], fromCards, cast, cardSceneTxt);
                    desc = enforceNpcCanonAppearance(desc, st);
                    charCaptions = charCaptions.map(c => enforceNpcCanonAppearance(c, st));
                    for (let pi = 0; pi < panelPrompts.length; pi++) panelPrompts[pi] = enforceNpcCanonAppearance(panelPrompts[pi], st);
                }
            }
            {
                const featTxt = (comicOpts?.enabled && comicOpts?.chunkText) ? String(comicOpts.chunkText) : String(ctx().chat?.[Number.isInteger(mesId) ? mesId : (ctx().chat.length - 1)]?.mes || '');
                const bF = [desc, ...charCaptions, ...panelPrompts].join(' ### ');
                desc = injectCardBodyFeatures(desc, st, cast, featTxt);
                charCaptions = charCaptions.map(c => injectCardBodyFeatures(c, st, cast, featTxt));
                for (let pi = 0; pi < panelPrompts.length; pi++) panelPrompts[pi] = injectCardBodyFeatures(panelPrompts[pi], st, cast, featTxt);
                if ([desc, ...charCaptions, ...panelPrompts].join(' ### ') !== bF) logImageDiag('Страж внешности: дописаны забытые уши/хвост/рога из карточек героев');
            }
            let chapterCanonSafe = comicOpts?.chapterCanonByGender ? { ...comicOpts.chapterCanonByGender } : null;
            if (chapterCanonSafe) {
                const ccTxt = (comicOpts?.enabled && comicOpts?.chunkText) ? String(comicOpts.chunkText) : '';
                const pp2 = presentPeopleByGender(st, cast, ccTxt);
                for (const g of ['boy', 'girl']) {
                    // переносим канон со стр. 1, только если в сцене ровно один герой этого пола и это его канон
                    if (pp2.unknown.length || pp2[g].length !== 1 || !pp2[g][0].tag) chapterCanonSafe[g] = '';
                    else chapterCanonSafe[g] = pp2[g][0].tag;
                }
            }
            if (chapterCanonSafe && (chapterCanonSafe.boy || chapterCanonSafe.girl)) {
                const activeCheckTxt = [
                    comicOpts.chunkText || '',
                    ...(Array.isArray(rawLlmQuotes) ? rawLlmQuotes.map(q => `${q?.speaker || ''} ${q?.text || ''}`) : []),
                ].join(' ');
                desc = carryOverChapterCanonTags(desc, chapterCanonSafe, cast, activeCheckTxt);
                charCaptions = charCaptions.map(c => carryOverChapterCanonTags(c, chapterCanonSafe, cast, activeCheckTxt));
                for (let pi = 0; pi < panelPrompts.length; pi++) panelPrompts[pi] = carryOverChapterCanonTags(panelPrompts[pi], chapterCanonSafe, cast, activeCheckTxt);
            }
            const afterFix = [desc, ...charCaptions, ...panelPrompts].join(' ### ');
            if (afterFix !== beforeFix) logImageDiag('Страж внешности: восстановлен канон-тег NPC / сцены', afterFix);
        }

        // 2) образцы: аватар персоны (только если НЕ вид от первого лица!) и аватары тех, кто реально в кадре
        say('🎨 Рисую сцену…');
        const names = storyNames();
        const norm = x => String(x || '').toLowerCase().replace(/ё/g, 'е');
        // Если GLM не вывела строку CAST:, определяем участников сцены по тексту отрывка/поста, чтобы чужой аватар (например Кайлар) не прикреплялся к сцене без него!
        if (!cast.length) {
            const targetMsgForCast = ctx().chat?.[Number.isInteger(mesId) ? mesId : (ctx().chat.length - 1)]?.mes || '';
            const activeTxtForCast = (comicOpts?.enabled && comicOpts?.chunkText) ? String(comicOpts.chunkText) : String(targetMsgForCast);
            const allKnownNames = [names.user, ...(names.chars || [names.char]), ...(st.npcs || []).map(n => n.name)].filter(Boolean);
            for (const kn of allKnownNames) {
                if (isNameMentionedInText(kn, activeTxtForCast)) {
                    const nKn = norm(kn);
                    if (nKn && !cast.includes(nKn)) cast.push(nKn);
                }
            }
        }
        const noOneInFrame = cast.length === 1 && cast[0] === '__none__';
        const inFrame = n => !noOneInFrame && cast.length > 0 && cast.some(c => c.includes(norm(n)) || norm(n).includes(c));
        const images = [];
        const who = [];
        const isNai = settings().imageSource === 'novelai';
        if (settings().imageRef && !noOneInFrame) {
            if (isNai) {
                // Правило для NovelAI: если в кадре есть char (или оба — char и user), берём картинку-референс ТОЛЬКО для char (а user идёт по текстовому описанию внешности).
                // Если же char в кадре нет, а есть только user — берём картинку-референс для user!
                // Аватар главного персонажа карточки (напр. Кайлара) прикрепляем, только если он реально назван в рисуемом отрывке —
                // иначе его лицо уезжает на NPC в кадре (Дойл рисовался Кайларом)
                const refChunkTxt = String((comicOpts?.enabled && comicOpts?.chunkText) ? comicOpts.chunkText : (ctx().chat?.[Number.isInteger(mesId) ? mesId : (ctx().chat.length - 1)]?.mes || ''));
                const reallyInChunk = n => isNameMentionedInText(n, refChunkTxt);
                for (const ch of characterAvatars()) {
                    if (!inFrame(ch.name) || !reallyInChunk(ch.name)) continue;
                    const img = await fileToDataUrl(ch.file);
                    if (img) { images.push(img); who.push(ch.name); break; }
                }
                if (!images.length && st.mainCharCard?.avatar && inFrame(st.mainCharCard.name) && reallyInChunk(st.mainCharCard.name)) {
                    const img = await fileToDataUrl(st.mainCharCard.avatar);
                    if (img) { images.push(img); who.push(st.mainCharCard.name); }
                }
                if (!images.length && !isPov && inFrame(names.user)) {
                    const me = await personaAvatarDataUrl();
                    if (me) { images.push(me); who.push(names.user); }
                }
                if (!images.length) {
                    for (const npc of (st.npcs || [])) {
                        if (!inFrame(npc.name) || !npc.avatar) continue;
                        const img = await fileToDataUrl(npc.avatar);
                        if (img) { images.push(img); who.push(npc.name); break; }
                    }
                }
                if (images.length) logImageDiag('NovelAI: картинка-референс внешности взята с аватара', who.join(', '));
            } else {
                for (const ch of characterAvatars()) {
                    if (images.length >= 4 || !inFrame(ch.name)) continue;
                    const img = await fileToDataUrl(ch.file);
                    if (img) { images.push(img); who.push(ch.name); }
                }
                if (!isPov && inFrame(names.user) && images.length < 4) {
                    const me = await personaAvatarDataUrl();
                    if (me) { images.push(me); who.push(names.user); }
                }
                for (const npc of (st.npcs || [])) {
                    if (images.length >= 4 || !inFrame(npc.name) || !npc.avatar) continue;
                    const img = await fileToDataUrl(npc.avatar);
                    if (img) { images.push(img); who.push(npc.name); }
                }
            }
        }
        // Проверяем, есть ли в CAST персонажи/NPC, у которых НЕ оказалось картинки-референса (из-за чего GPT раньше рисовал только тех, чьи аватары прикреплены!)
        const unreferencedInCast = noOneInFrame ? [] : cast.filter(cName => !who.some(wName => norm(wName).includes(cName) || cName.includes(norm(wName))));
        const totalPeopleCount = noOneInFrame ? 0 : Math.max(cast.length, who.length);
        const unrefNote = unreferencedInCast.length
            ? ` CRITICAL: There are ${totalPeopleCount} people in this scene in total (${cast.join(', ')}), NOT just ${who.length}! Reference portraits are provided ONLY for ${who.join(' and ')}, while the remaining character(s) (${unreferencedInCast.join(', ')}) do not have reference portraits — you MUST draw ALL ${totalPeopleCount} people together in the scene according to the text description, do NOT omit ${unreferencedInCast.join(', ')}!`
            : '';
        const gazeNote = isPovHands
            ? `First-person POV perspective seen through ${names.user}'s eyes (pov hands in foreground allowed, but ${names.user}'s head, face and back are completely out of frame).`
            : isPov
                ? `Eye-level shot seen directly from ${names.user}'s perspective; ${names.user} is not in the frame.`
                : `Candid cinematic third-person scene: characters are looking at each other or at their activity in the scene, NEVER looking into the camera or at the viewer.`;
        const refModeSetting = String(settings().naiCharRefMode || 'char_no_style');
        const styleInstruction = refModeSetting === 'char_and_style'
            ? 'Keep both their facial/hair features AND the visual art style from the reference image.'
            : refModeSetting === 'style_only'
                ? 'Use the attached reference image ONLY for the visual art style, rendering, and color palette, while drawing the characters strictly according to the text description.'
                : 'Use the attached reference image ONLY for character identity (hair color, eye color, facial features) — DO NOT copy the art style, proportions, framing, or lighting of the reference avatar!';
        // Если в SCENE указано 2boys / 3boys, убираем внутренние "1boy:" внутри строки SCENE (заменяя на "male:"), чтобы NovelAI не слепливал двух парней в одного!
        if (/\b[2-6]boys\b/i.test(desc)) {
            desc = desc.replace(/\b1boy\s*:/gi, 'male:').replace(/,\s*1boy\b/gi, ', male');
        }
        if (/\b[2-6]girls\b/i.test(desc)) {
            desc = desc.replace(/\b1girl\s*:/gi, 'female:').replace(/,\s*1girl\b/gi, ', female');
        }
        const refs = (images.length || extraNeg || charCaptions.length)
            ? {
                images,
                extraNeg,
                charCaptions,
                note: images.length
                    ? `The attached pictures are character references, in this order: ${who.map((n, i) => `${i + 1}) ${n}`).join(', ')}. ${styleInstruction} Clothing, adult body proportions, pose and setting must strictly follow the text description.${unrefNote} ${gazeNote}`
                    : '',
            }
            : null;
        // Для NovelAI НИКОГДА не добавляем литературную фразу "Scene with X people...", которая ломает счётчик 2boys, 2girls!
        const countPrefix = (!isNai && !isPov && totalPeopleCount >= 3 && !/\b(three|four|five|3|4|5)\s+(people|characters|figures)\b/i.test(desc))
            ? `Scene with ${totalPeopleCount} people visible in frame (${cast.join(', ')}): `
            : '';
        const cameraSuffix = isPovHands
            ? `first-person POV, pov hands in foreground, viewer head and torso out of frame, eye-level perspective, single illustration, no text, no captions.`
            : isPov
                ? `eye-level medium shot from viewer's perspective, single illustration, no text, no captions.`
                : (totalPeopleCount >= 3
                    ? `candid cinematic group scene with all ${totalPeopleCount} characters clearly visible in frame, characters looking at each other and interacting naturally, NOT looking at viewer, NOT looking at camera, single illustration, no text, no captions.`
                    : totalPeopleCount === 2
                        ? `candid cinematic scene, characters looking at each other, interacting naturally, NOT looking at viewer, NOT looking at camera, single illustration, no text, no captions.`
                        : `candid cinematic scene, natural gaze, NOT looking at camera, single illustration, no text, no captions.`);
        // Для NovelAI отправляем чистый промпт SCENE (как в ext-blocks-custom и на сайте NovelAI) без довешивания длинного системного cameraSuffix!
        const rawCombinedPrompt = (reuseMeta?.prompt && reuseMeta.desc === desc)
            ? splitPositiveAndNegativePrompt(reuseMeta.prompt).positive
            : (isNai
                ? cleanForCommand(`${countPrefix}${desc}`)
                : cleanForCommand(`${countPrefix}${desc}. ${cameraSuffix}`));
        let prompt = splitPositiveAndNegativePrompt(rawCombinedPrompt).positive;
        let targetMesIdx = Number.isInteger(mesId) ? mesId : (ctx().chat.length - 1);
        while (targetMesIdx >= 0 && (!ctx().chat[targetMesIdx] || ctx().chat[targetMesIdx].is_system)) targetMesIdx--;

        const activeComicOpts = comicOpts || reuseMeta?.comicOpts || null;
        let verifiedQuotes = Array.isArray(reuseMeta?.comicQuotes) ? reuseMeta.comicQuotes : [];
        if (activeComicOpts?.enabled) {
            const cStyle = getComicStyleById(activeComicOpts.styleId);
            if (cStyle) {
                if (isMonochromeComicStyle(cStyle)) {
                    extraNeg = [extraNeg, 'color, colorful, full color, chromatic, pastel colors, saturated colors, colorized, spot color, yellow, orange, pink, red, blue, green, purple, brown, blonde, watercolor'].filter(Boolean).join(', ');
                    if (refs) {
                        refs.extraNeg = extraNeg;
                        if (Array.isArray(refs.charCaptions)) {
                            refs.charCaptions = refs.charCaptions.map(c => enforceMonochromeMangaPrompt(c, false));
                        }
                    }
                    prompt = enforceMonochromeMangaPrompt(prompt, isNai);
                }
                if (isNai && cStyle.naiTags) {
                    const effectiveNaiTags = stripMultiPanelTagsForSingleFrame(cStyle.naiTags);
                    const firstTag = (effectiveNaiTags.split(',')[0] || '').trim().toLowerCase();
                    if (effectiveNaiTags && (!firstTag || !prompt.toLowerCase().includes(firstTag))) {
                        prompt = `${effectiveNaiTags}, ${prompt}`;
                    }
                } else if (!isNai && cStyle.promptEn && !prompt.includes(cStyle.promptEn.slice(0, 30))) {
                    prompt = `${cStyle.promptEn} Scene: ${prompt}`;
                }
            }
            if (activeComicOpts.linesMode !== 'off' && !verifiedQuotes.length) {
                const targetMsgObj = ctx().chat?.[targetMesIdx];
                const prevMsgObj = targetMesIdx > 0 ? ctx().chat?.[targetMesIdx - 1] : null;
                const fullPostTxt = String(targetMsgObj?.mes || '');
                // Если рисуется конкретный кусочек поста (chunkText), проверяем и извлекаем реплики в первую очередь именно из этого кусочка!
                const primaryQuoteSource = (activeComicOpts.chunkText && String(activeComicOpts.chunkText).trim())
                    ? String(activeComicOpts.chunkText).trim()
                    : fullPostTxt;
                const storyTxt = [prevMsgObj?.mes || '', fullPostTxt].join('\n');
                verifiedQuotes = verifyComicQuotesAgainstStory(rawLlmQuotes, fullPostTxt || storyTxt, primaryQuoteSource, '', cast, st, Number(activeComicOpts.framesPerPage) === 4 ? 4 : 3);
                if (!isNai && verifiedQuotes.length) {
                    prompt += `\nSpeech bubbles (Cyrillic text written exactly as given, never invent other words): ` +
                        verifiedQuotes.map((q, idx) => `Panel ${idx + 1}${q.speaker ? ` (${q.speaker})` : ''}: «${q.text}»`).join('; ');
                }
            }
        }

        let url = '';
        let cleanUnletteredUrl = '';
        if (activeComicOpts?.enabled && activeComicOpts.stripMode) {
            const cStyle = getComicStyleById(activeComicOpts.styleId);
            const isWebtoonStrip = cStyle?.id === 'webtoon' || cStyle?.id === 'yonkoma';
            const framesCount = Number(activeComicOpts.framesPerPage) === 4 ? 4 : 3;
            if (!Array.isArray(panelPrompts) || panelPrompts.length < 2) {
                const generatedFallbackPanels = buildDistinctComicPanelsFallback(desc || prompt, charCaptions, isNai);
                panelPrompts.length = 0;
                panelPrompts.push(...generatedFallbackPanels.slice(0, framesCount));
                logImageDiag(`Модель промптов не вернула отдельные строки PANEL1..PANEL${framesCount} — автоматически построены ${framesCount} разных кадра`, panelPrompts.join('\n'));
            } else {
                const p0 = String(panelPrompts[0] || '').toLowerCase();
                const p2 = String(panelPrompts[2] || '').toLowerCase();
                if (panelPrompts.length >= 3 && p0 && p2 && p0 === p2) {
                    const distinct = buildDistinctComicPanelsFallback(desc || panelPrompts[0], charCaptions, isNai);
                    panelPrompts[1] = distinct[1];
                    panelPrompts[2] = distinct[2];
                }
                while (panelPrompts.length < framesCount) {
                    const distinct = buildDistinctComicPanelsFallback(desc || panelPrompts[0], charCaptions, isNai);
                    panelPrompts.push(distinct[panelPrompts.length] || distinct[distinct.length - 1]);
                }
            }
            const framesToDraw = panelPrompts.slice(0, framesCount);
            const singleFrameNaiStyle = stripMultiPanelTagsForSingleFrame(cStyle?.naiTags || '');
            const frameUrls = [];
            for (let fIdx = 0; fIdx < framesToDraw.length; fIdx++) {
                sceneDrawingStartedAt = Date.now(); // обновляем таймер на каждом кадре полосы, чтобы 3–4 кадра не сбрасывались по таймауту!
                const parsedPanel = parsePanelTextAndCharSlots(framesToDraw[fIdx]);
                let rawFrameDesc = cleanSingleComicPanelPrompt(parsedPanel.prompt || framesToDraw[fIdx], fIdx, framesToDraw[0] || desc);
                if (fIdx > 0) {
                    rawFrameDesc = enforceSoloFrameOutfitFromPage(rawFrameDesc, framesToDraw[0], charCaptions);
                }
                if (/\b[2-6]boys\b/i.test(rawFrameDesc)) {
                    rawFrameDesc = rawFrameDesc.replace(/\b1boy\s*:/gi, 'male:').replace(/,\s*1boy\b/gi, ', male');
                }
                if (/\b[2-6]girls\b/i.test(rawFrameDesc)) {
                    rawFrameDesc = rawFrameDesc.replace(/\b1girl\s*:/gi, 'female:').replace(/,\s*1girl\b/gi, ', female');
                }
                const isMonoComic = isMonochromeComicStyle(cStyle);
                const cleanRawFrame = isMonoComic ? enforceMonochromeMangaPrompt(rawFrameDesc, false) : rawFrameDesc;
                const framePrompt = isNai
                    ? cleanForCommand(isMonoComic ? enforceMonochromeMangaPrompt([singleFrameNaiStyle, cleanRawFrame].filter(Boolean).join(', '), true) : [singleFrameNaiStyle, cleanRawFrame].filter(Boolean).join(', '))
                    : cleanForCommand(`${cStyle?.promptEn || ''} Frame ${fIdx + 1}: ${cleanRawFrame}`);
                const cleanPanelCaps = isMonoComic
                    ? (parsedPanel.charCaptions || []).map(c => enforceMonochromeMangaPrompt(c, false))
                    : parsedPanel.charCaptions;
                const frameRefs = buildRefsForSingleComicFrame(refs, cleanRawFrame, cleanPanelCaps, fIdx, who);
                // Для 3 кадров: 1-й landscape + 2-й и 3-й portrait; для 4 кадров (манхва 1+2+1): 1-й и 4-й landscape, 2-й и 3-й portrait
                const isWideRowFrame = (framesToDraw.length === 3 && fIdx === 0) || (framesToDraw.length === 4 && (fIdx === 0 || fIdx === 3));
                const frameOrient = isWebtoonStrip ? 'square' : (isWideRowFrame ? 'landscape' : 'portrait');
                logImageDiag(`Комикс-полоса: рисуем кадр ${fIdx + 1} из ${framesToDraw.length} (${frameOrient}, слотов CHAR: ${frameRefs?.charCaptions?.length || 0})`, framePrompt);
                say(`🎨 Рисую кадр манхвы ${fIdx + 1} из ${framesToDraw.length}…`);
                const fUrl = await withSharedKeyRetry(async () => {
                    const outUrl = await withTimeout(drawPicture(framePrompt, frameRefs, frameOrient), 120000, `кадр манхвы ${fIdx + 1}`);
                    if (!outUrl) throw new Error(`Пустой ответ на кадре ${fIdx + 1}`);
                    return outUrl;
                }, `кадр ${fIdx + 1}/${framesToDraw.length}`, 4, 5500);
                if (fUrl) frameUrls.push(fUrl);
            }
            if (!frameUrls.length) throw new Error('Не удалось сгенерировать кадры для склейки комикса');
            if (verifiedQuotes.length > 1 && framesToDraw.length > 1) {
                verifiedQuotes = alignQuotesToPanelsSemantics(verifiedQuotes, framesToDraw);
            }
            if (verifiedQuotes.length > 0) {
                const fullPostForSpk = String(ctx().chat?.[targetMesIdx]?.mes || '');
                verifiedQuotes = reconcileQuoteSpeakersWithPanels(verifiedQuotes, framesToDraw, cast, fullPostForSpk, st);
            }
            const wantBubbles = activeComicOpts.linesMode !== 'off' && verifiedQuotes.length > 0;
            const stitchedBundle = await stitchComicFramesOnCanvas(frameUrls, verifiedQuotes, activeComicOpts.styleId, wantBubbles, true);
            const stitchedData = typeof stitchedBundle === 'object' ? stitchedBundle.letteredDataUrl : stitchedBundle;
            const stitchedCleanData = typeof stitchedBundle === 'object' ? stitchedBundle.cleanDataUrl : '';
            url = await storeImage(stitchedData);
            if (wantBubbles && stitchedCleanData) {
                cleanUnletteredUrl = await storeImage(stitchedCleanData);
            }
            if (!cleanUnletteredUrl) cleanUnletteredUrl = url;
        } else {
            logImageDiag(`Шаг 2/2: отправка промпта в генератор (${imageSourceName()})`, `Референсов: ${images.length} (${who.join(', ') || 'нет'}), режим референса: ${refModeSetting}`);
            const rawUrl = await withTimeout(drawPicture(prompt, refs, imgOrient()), 120000, 'рисунок сцены');
            url = rawUrl;
            // Если это комикс в NovelAI и включены реплики из поста — накладываем аккуратные русские облачка реплик (а чистую версию без текста тоже сохраняем в историю поста!)
            if (activeComicOpts?.enabled && isNai && activeComicOpts.linesMode !== 'off' && verifiedQuotes.length > 0 && rawUrl) {
                cleanUnletteredUrl = rawUrl;
                const letteredDataUrl = await overlayComicBubblesOnDataUrl(rawUrl, verifiedQuotes, activeComicOpts);
                if (letteredDataUrl && letteredDataUrl !== rawUrl) {
                    url = await storeImage(letteredDataUrl);
                }
            }
        }

        logImageDiag('Картинка успешно получена и сохранена!', url ? String(url).slice(0, 120) : '');
        const prevCleanMap = (reuseMeta?.cleanUrlMap && typeof reuseMeta.cleanUrlMap === 'object') ? { ...reuseMeta.cleanUrlMap } : {};
        if (url && cleanUnletteredUrl) prevCleanMap[url] = cleanUnletteredUrl;
        const prevPageMetaMap = (reuseMeta?.pageMetaMap && typeof reuseMeta.pageMetaMap === 'object') ? { ...reuseMeta.pageMetaMap } : {};
        if (url) {
            prevPageMetaMap[url] = {
                desc,
                prompt,
                charCaptions: [...charCaptions],
                panelPrompts: [...panelPrompts],
                comicQuotes: [...verifiedQuotes],
                comicOpts: activeComicOpts ? { ...activeComicOpts } : null,
                cleanUnletteredUrl: cleanUnletteredUrl || url,
            };
        }
        const sceneMeta = {
            desc,
            extraNeg,
            cast,
            charCaptions,
            camMode,
            prompt,
            pov: isPov,
            mesId: targetMesIdx,
            comicOpts: activeComicOpts,
            comicQuotes: verifiedQuotes,
            panelPrompts,
            cleanUnletteredUrl: cleanUnletteredUrl || '',
            cleanUrlMap: prevCleanMap,
            pageMetaMap: prevPageMetaMap,
        };
        st.lastSceneMeta = sceneMeta;
        if (!Array.isArray(st.scenes)) st.scenes = [];
        // Сохраняем все сгенерированные варианты без автоудаления, чтобы можно было спокойно сравнить и выбрать лучший (а лишние удалить вручную кнопкой)!
        // Чистый фон без текста хранится в sceneMeta.cleanUrlMap[url] для мгновенного редактирования облачков, не засоряя Альбом дублями каждой страницы
        st.scenes.push({ url, mesId: targetMesIdx, at: ctx().chat.length, date: st.time?.date || '', desc, extraNeg, cast, charCaptions, camMode, prompt, pov: isPov, comicOpts: activeComicOpts, comicQuotes: verifiedQuotes, panelPrompts, cleanUnletteredUrl: cleanUnletteredUrl || '' });
        if (st.scenes.length > 120) st.scenes.shift();
        await ctx().saveMetadata();
        renderPanel();
        return { url, sceneMeta };
    } catch (err) {
        console.warn('[npc_notebook] scene', err);
        logImageDiag('ОШИБКА генерации сцены', err?.message || String(err));
        toastr.warning(`Сцену нарисовать не вышло: ${escapeHtml(err?.message || err)}<br><small>Нажми «📋 Диагностика и лог картинок» в настройках блокнота для подробностей.</small>`, '🎬 Сцена', { escapeHtml: false, timeOut: 10000 });
        return null;
    } finally {
        sceneDrawing = false;
        sceneDrawingStartedAt = 0;
        if (!multiPageKeepAliveActive) {
            stopBackgroundGenerationKeepAlive();
        }
    }
}

async function attachToLastMessage(url, mesId, sceneMeta = null, silentToast = false) {
    const c = ctx();
    for (let i = Number.isInteger(mesId) ? mesId : c.chat.length - 1; i >= 0; i--) {
        const m = c.chat[i];
        if (!m || m.is_system) continue;
        m.extra = m.extra || {};
        const oldScene = m.extra.nnbScene || {};
        let prevHistory;
        if (sceneMeta?.replaceHistory && Array.isArray(sceneMeta.history) && sceneMeta.history.length > 0) {
            prevHistory = [...sceneMeta.history];
            if (url && !prevHistory.includes(url)) prevHistory.push(url);
        } else {
            prevHistory = Array.isArray(oldScene.history) ? [...oldScene.history] : (oldScene.url ? [oldScene.url] : []);
            if (url && !prevHistory.includes(url)) prevHistory.push(url);
        }
        prevHistory = [...new Set(prevHistory.filter(Boolean))];
        if (sceneMeta) {
            const mergedCleanMap = { ...(oldScene.cleanUrlMap || {}), ...(sceneMeta.cleanUrlMap || {}) };
            if (url && sceneMeta.cleanUnletteredUrl) mergedCleanMap[url] = sceneMeta.cleanUnletteredUrl;
            const mergedPageMetaMap = { ...(oldScene.pageMetaMap || {}), ...(sceneMeta.pageMetaMap || {}) };
            const activePageMeta = mergedPageMetaMap[url] || null;
            const tempSceneObj = {
                ...oldScene,
                ...sceneMeta,
                ...(activePageMeta ? {
                    desc: activePageMeta.desc || sceneMeta.desc,
                    prompt: activePageMeta.prompt || sceneMeta.prompt,
                    charCaptions: activePageMeta.charCaptions || sceneMeta.charCaptions,
                    panelPrompts: activePageMeta.panelPrompts || sceneMeta.panelPrompts,
                    comicQuotes: activePageMeta.comicQuotes || sceneMeta.comicQuotes,
                    comicOpts: activePageMeta.comicOpts || sceneMeta.comicOpts,
                    cleanUnletteredUrl: activePageMeta.cleanUnletteredUrl || sceneMeta.cleanUnletteredUrl,
                } : {}),
                url,
                history: prevHistory,
                cleanUrlMap: mergedCleanMap,
                pageMetaMap: mergedPageMetaMap,
                mesId: i,
            };
            tempSceneObj.history = getSortedManhwaHistoryUrls(tempSceneObj);
            m.extra.nnbScene = tempSceneObj;
        } else if (m.extra.nnbScene) {
            m.extra.nnbScene.url = url;
            m.extra.nnbScene.history = prevHistory;
            const pageData = m.extra.nnbScene.pageMetaMap?.[url];
            if (pageData) {
                m.extra.nnbScene.desc = pageData.desc || m.extra.nnbScene.desc;
                m.extra.nnbScene.prompt = pageData.prompt || m.extra.nnbScene.prompt;
                m.extra.nnbScene.charCaptions = pageData.charCaptions || m.extra.nnbScene.charCaptions;
                m.extra.nnbScene.panelPrompts = pageData.panelPrompts || m.extra.nnbScene.panelPrompts;
                m.extra.nnbScene.comicQuotes = pageData.comicQuotes || m.extra.nnbScene.comicQuotes;
                m.extra.nnbScene.comicOpts = pageData.comicOpts || m.extra.nnbScene.comicOpts;
                m.extra.nnbScene.cleanUnletteredUrl = pageData.cleanUnletteredUrl || m.extra.nnbScene.cleanUnletteredUrl;
            }
        }
        // Все варианты сохраняются в галерее поста и в альбоме до ручной очистки пользователем
        const imgDesc = Object.getOwnPropertyDescriptor(m.extra, 'image');
        const newApi = Array.isArray(m.extra.media) || (imgDesc && typeof imgDesc.get === 'function') || typeof c.appendMediaToMessage === 'function';
        if (newApi) {
            // Все сгенерированные варианты надёжно хранятся в m.extra.nnbScene.history и в Альбоме (st.scenes),
            // а в DOM-массиве m.extra.media держим только 1 активный выбранный кадр (плюс не-наши вложения),
            // чтобы Таверна не рендерила в чате десятки тяжёлых скрытых DOM-галерей одновременно!
            const nonNnbMedia = Array.isArray(m.extra.media)
                ? m.extra.media.filter(x => x && x.source !== 'generated' && !String(x.title || '').startsWith('Сцена') && !String(x.title || '').startsWith('Комикс'))
                : [];
            m.extra.media = [...nonNnbMedia, { url, type: 'image', title: 'Сцена', source: 'generated' }];
            m.extra.media_index = m.extra.media.length - 1;
            m.extra.media_display = 'inline';
        } else {
            m.extra.image = url;
            m.extra.title = 'Сцена';
        }
        m.extra.inline_image = true; // текст поста остаётся на месте
        try { if (typeof c.updateMessageBlock === 'function') c.updateMessageBlock(i, m); } catch (e) { /* ignore */ }
        await c.saveChat();
        placeMesButtonsSoon();
        const totalSaved = prevHistory.length;
        if (!silentToast) {
            toastr.success(
                totalSaved > 1
                    ? `Новая картинка добавлена под пост (вариантов: ${totalSaved} — листай стрелками ◀ ▶ под картинкой или жми ▶ для ещё одной генерации по тому же промпту)!`
                    : 'Картинка сцены добавлена под пост! Жми стрелку вправо ▶ под картинкой, чтобы сгенерировать ещё вариант по тому же промпту.',
                '🎬 Сцена',
                { timeOut: 5500 }
            );
        }
        return;
    }
}

// 🖼 Альбом: сцены и листы образов этого чата
function albumItems(st) {
    const items = [];
    (st.scenes || []).forEach((x, i) => items.push({ kind: 'scene', url: x.url, date: x.date, title: '🎬 Сцена', text: x.desc || '', ref: i }));
    (st.wardrobe?.history || []).forEach((h, i) => { if (h.image) items.push({ kind: 'look', url: h.image, date: h.date, title: `👗 ${h.title}`, text: h.occasion || '', ref: i }); });
    return items.reverse();
}
// Окно просмотра иллюстрации сцены с кнопками ◀ и ▶ (стрелка вправо на последнем кадре сразу делает ещё одну генерацию по тому же промпту прямо в этом окне!)
async function openSceneImageViewer(mesId, fallbackSceneObj = null) {
    const c = ctx();
    const st = store();
    if (!st) return;

    let targetIdx = Number.isInteger(mesId) ? mesId : undefined;
    if (targetIdx === undefined && Array.isArray(c.chat)) {
        for (let i = c.chat.length - 1; i >= 0; i--) {
            if (c.chat[i] && !c.chat[i].is_system && c.chat[i].extra?.nnbScene) {
                targetIdx = i;
                break;
            }
        }
    }
    const getMeta = () => {
        if (Number.isInteger(targetIdx) && c.chat?.[targetIdx]?.extra?.nnbScene) {
            return c.chat[targetIdx].extra.nnbScene;
        }
        return fallbackSceneObj || st.lastSceneMeta || null;
    };

    let meta = getMeta();
    if (!meta || (!meta.url && (!Array.isArray(meta.history) || !meta.history.length))) {
        return showScenePopup(targetIdx);
    }
    if (!Array.isArray(meta.history) || !meta.history.length) {
        meta.history = meta.url ? [meta.url] : [];
    }

    const el = $('<div class="nnb-pop nnb-pop-visual"></div>');
    let generatingMore = false;

    const renderViewer = () => {
        el.empty();
        meta = getMeta() || meta;
        if (!Array.isArray(meta.history) || !meta.history.length) {
            meta.history = meta.url ? [meta.url] : [];
        }
        let curIdx = meta.history.indexOf(meta.url);
        if (curIdx < 0) curIdx = meta.history.length - 1;
        const curUrl = meta.history[curIdx] || meta.url || '';
        const isLast = curIdx >= meta.history.length - 1;

        el.append($('<h3 style="margin-bottom:4px;"></h3>').text(`🎬 Иллюстрация сцены (Вариант ${curIdx + 1} из ${meta.history.length})`));
        el.append('<div class="nnb-pop-sub" style="margin-bottom:8px;">Листай варианты стрелками <b>◀</b> и <b>▶</b>. На последнем варианте нажатие <b>стрелки вправо ▶</b> сразу рисует ещё одну картинку по тому же самому промпту прямо в этом окне!</div>');

        // Главный блок с картинкой и боковыми стрелками ◀ и ▶
        const stage = $('<div style="position:relative; display:flex; align-items:center; justify-content:center; gap:8px; margin:6px 0;"></div>');

        const leftArrow = $(`<div class="menu_button" style="padding:14px 12px; font-size:1.15em; border-radius:12px; flex-shrink:0; ${curIdx <= 0 || generatingMore ? 'opacity:0.35; pointer-events:none;' : ''}" title="Предыдущий вариант (◀)"><i class="fa-solid fa-chevron-left"></i></div>`);
        leftArrow.on('click', async () => {
            if (curIdx <= 0 || generatingMore) return;
            const prevUrl = meta.history[curIdx - 1];
            meta.url = prevUrl;
            if (Number.isInteger(targetIdx)) {
                await attachToLastMessage(prevUrl, targetIdx, meta, true);
            }
            renderViewer();
        });

        const imgBox = $('<div class="nnb-album-big" style="flex:1; text-align:center; position:relative; min-height:220px; display:flex; align-items:center; justify-content:center;"></div>');
        if (curUrl) {
            const img = $('<img alt="Сцена" style="max-height:62vh; max-width:100%; border-radius:12px; object-fit:contain; cursor:pointer; box-shadow:0 4px 18px rgba(0,0,0,0.35);">')
                .attr('src', curUrl)
                .attr('title', 'Нажми, чтобы открыть картинку в новой вкладке')
                .on('click', () => window.open(curUrl, '_blank'));
            imgBox.append(img);
        }
        if (generatingMore) {
            const overlay = $('<div style="position:absolute; inset:0; background:rgba(15,12,24,0.72); border-radius:12px; display:flex; flex-direction:column; align-items:center; justify-content:center; gap:10px; color:#fff; font-weight:600; padding:16px; text-align:center;"></div>');
            overlay.append('<i class="fa-solid fa-spinner fa-spin" style="font-size:2em; color:var(--SmartThemeQuoteColor, #e0c068);"></i>');
            overlay.append($('<div></div>').text(`🎨 Рисую ещё один вариант по тому же промпту через ${imageSourceName()}…`));
            imgBox.append(overlay);
        }

        const rightTitle = isLast
            ? 'Сгенерировать ещё одну картинку по тому же промпту прямо здесь (▶)'
            : 'Следующий вариант (▶)';
        const rightArrow = $(`<div class="menu_button ${isLast ? 'nnb-btn-primary' : ''}" style="padding:14px 12px; font-size:1.15em; border-radius:12px; flex-shrink:0; display:flex; flex-direction:column; align-items:center; gap:3px; ${generatingMore ? 'opacity:0.45; pointer-events:none;' : ''}" title="${rightTitle}">
            <i class="fa-solid fa-chevron-right"></i>
            ${isLast ? '<span style="font-size:0.62em; font-weight:700; white-space:nowrap;">+ Ещё</span>' : ''}
        </div>`);

        const triggerRightAction = async () => {
            if (generatingMore) return;
            if (!isLast) {
                const nextUrl = meta.history[curIdx + 1];
                meta.url = nextUrl;
                if (Number.isInteger(targetIdx)) {
                    await attachToLastMessage(nextUrl, targetIdx, meta, true);
                }
                renderViewer();
                return;
            }
            // Мы на последнем кадре — генерируем ещё одну картинку по тому же промпту прямо в этом окне!
            generatingMore = true;
            renderViewer();
            try {
                const res = await drawScene(null, targetIdx, meta.camMode || 'third', meta);
                if (res?.url) {
                    if (!meta.history.includes(res.url)) meta.history.push(res.url);
                    meta.url = res.url;
                    meta.prompt = res.sceneMeta?.prompt || meta.prompt;
                    meta.desc = res.sceneMeta?.desc || meta.desc;
                    if (Number.isInteger(targetIdx)) {
                        await attachToLastMessage(res.url, targetIdx, meta, true);
                    }
                }
            } finally {
                generatingMore = false;
                renderViewer();
            }
        };

        rightArrow.on('click', triggerRightAction);
        stage.append(leftArrow, imgBox, rightArrow);
        el.append(stage);

        // Полоска миниатюр всех вариантов этой сцены + кнопка «Ещё по этому промпту (▶)»
        const bar = $('<div style="display:flex; align-items:center; justify-content:center; gap:8px; flex-wrap:wrap; margin:8px 0;"></div>');
        meta.history.forEach((hUrl, hIdx) => {
            const thumbBtn = $(`<div class="menu_button ${hIdx === curIdx ? 'nnb-btn-primary' : ''}" style="padding:3px 10px; font-size:0.82em; margin:0;">Вариант ${hIdx + 1}</div>`).on('click', async () => {
                if (generatingMore) return;
                meta.url = hUrl;
                if (Number.isInteger(targetIdx)) {
                    await attachToLastMessage(hUrl, targetIdx, meta, true);
                }
                renderViewer();
            });
            bar.append(thumbBtn);
        });
        const moreBtn = $(`<div class="menu_button nnb-btn-primary" style="padding:4px 12px; font-size:0.84em; margin:0; ${generatingMore ? 'opacity:0.5; pointer-events:none;' : ''}" title="Сделать ещё одну генерацию по тому же промпту прямо в этом окне">
            <i class="fa-solid fa-rotate-right"></i> Ещё генерация по этому промпту ▶
        </div>`).on('click', async () => {
            if (generatingMore) return;
            generatingMore = true;
            renderViewer();
            try {
                const res = await drawScene(null, targetIdx, meta.camMode || 'third', meta);
                if (res?.url) {
                    if (!meta.history.includes(res.url)) meta.history.push(res.url);
                    meta.url = res.url;
                    if (Number.isInteger(targetIdx)) {
                        await attachToLastMessage(res.url, targetIdx, meta, true);
                    }
                }
            } finally {
                generatingMore = false;
                renderViewer();
            }
        });
        bar.append(moreBtn);
        el.append(bar);

        // Раскрывающийся блок с промптом — можно подправить теги/описание прямо тут и нажать ▶!
        const promptDet = $('<details class="nnb-note" style="margin-top:8px; padding:8px 10px;"><summary style="cursor:pointer; font-weight:600; font-size:0.86em;">📝 Промпт этой картинки (можно подправить вручную и нажать ▶)</summary></details>');
        const promptArea = $('<textarea class="text_pole" rows="3" style="width:100%; margin-top:6px; font-size:0.84em;"></textarea>').val(formatEditableScenePrompt(meta));
        promptArea.on('input change', function () {
            const val = String($(this).val() || '').trim();
            if (val) {
                applyEditedScenePromptToMeta(meta, val);
            }
        });
        promptDet.append(promptArea);
        el.append(promptDet);

        const botRow = $('<div class="nnb-pop-row nnb-pop-links" style="margin-top:8px; justify-content:space-between; flex-wrap:wrap; gap:8px;"></div>');
        botRow.append($('<div class="menu_button"><i class="fa-solid fa-up-right-and-down-left-from-center"></i> Открыть в полном размере</div>').on('click', () => window.open(curUrl, '_blank')));
        botRow.append($('<div class="menu_button"><i class="fa-solid fa-camera-rotate"></i> Выбрать другой ракурс / новый промпт</div>').on('click', async () => {
            closePopupOf(el);
            await showScenePopup(targetIdx, true);
        }));
        el.append(botRow);
    };

    renderViewer();
    await openPopup(el, true);
}

async function deleteAlbumItem(st, item) {
    if (!st || !item) return;
    if (item.kind === 'scene') {
        if (Array.isArray(st.scenes) && item.ref >= 0 && item.ref < st.scenes.length) {
            st.scenes.splice(item.ref, 1);
        }
    } else if (item.kind === 'look') {
        if (Array.isArray(st.wardrobe?.history) && item.ref >= 0 && item.ref < st.wardrobe.history.length) {
            st.wardrobe.history[item.ref].image = '';
        }
    }
    await commit();
    toastr.info('Фото удалено из альбома', '🖼 Альбом');
}

let isOffloadingImages = false;
const checkedDiskPngUrls = new Set();
async function offloadAllBase64InChatAndMeta(st) {
    if (!st || isOffloadingImages) return 0;
    isOffloadingImages = true;
    let offloadedCount = 0;
    let mediaSlimmed = 0;
    const cache = new Map();
    const convertOne = async (val) => {
        if (!val || typeof val !== 'string') return val;
        if (cache.has(val)) return cache.get(val);
        if (val.startsWith('data:image/')) {
            const saved = await storeImage(val);
            if (saved && saved !== val) {
                cache.set(val, saved);
                offloadedCount++;
                return saved;
            }
            return val;
        }
        // Сжимаем старые тяжёлые .png файлы на диске Таверны (>260 КБ, по 3–6 МБ каждый) в лёгкие .jpg (~180 КБ)!
        if (/^(?:\/|user\/|characters\/|api\/).*\.png(?:\?.*)?$/i.test(val) && !checkedDiskPngUrls.has(val)) {
            checkedDiskPngUrls.add(val);
            try {
                const fetchUrl = val.startsWith('/') || val.startsWith('http') ? val : '/' + val;
                const res = await fetch(fetchUrl);
                if (res.ok) {
                    const blob = await res.blob();
                    if (blob && blob.size > 260 * 1024 && blob.type.startsWith('image/')) {
                        const rawDataUrl = await new Promise(r => {
                            const fr = new FileReader();
                            fr.onload = () => r(String(fr.result || ''));
                            fr.onerror = () => r('');
                            fr.readAsDataURL(blob);
                        });
                        if (rawDataUrl && rawDataUrl.startsWith('data:image/')) {
                            const compressedDataUrl = await compressDataUrlIfHeavy(rawDataUrl, 1440, 0.90);
                            if (compressedDataUrl && compressedDataUrl.startsWith('data:image/jpeg')) {
                                const newPath = await storeImage(compressedDataUrl);
                                if (newPath && newPath !== val && !newPath.startsWith('data:')) {
                                    cache.set(val, newPath);
                                    offloadedCount++;
                                    return newPath;
                                }
                            }
                        }
                    }
                }
            } catch (e) { /* ignore single file error */ }
        }
        return val;
    };
    const offloadField = async (obj, key) => {
        if (obj && typeof obj[key] === 'string' && obj[key].startsWith('data:image/')) {
            obj[key] = await convertOne(obj[key]);
        }
    };
    const offloadArray = async (arr) => {
        if (!Array.isArray(arr)) return;
        for (let i = 0; i < arr.length; i++) {
            if (typeof arr[i] === 'string' && arr[i].startsWith('data:image/')) {
                arr[i] = await convertOne(arr[i]);
            }
        }
    };
    try {
        const c = ctx();
        const chat = Array.isArray(c.chat) ? c.chat : [];
        for (let i = 0; i < chat.length; i++) {
            const m = chat[i];
            if (!m || !m.extra) continue;
            await offloadField(m.extra, 'image');
            const sc = m.extra.nnbScene;
            if (sc) {
                await offloadField(sc, 'url');
                await offloadField(sc, 'cleanUnletteredUrl');
                await offloadArray(sc.history);
                if (sc.cleanUrlMap && typeof sc.cleanUrlMap === 'object') {
                    const nextCleanMap = {};
                    for (const [k, v] of Object.entries(sc.cleanUrlMap)) {
                        const nk = await convertOne(k);
                        const nv = await convertOne(v);
                        if (nk) nextCleanMap[nk] = nv;
                    }
                    sc.cleanUrlMap = nextCleanMap;
                }
                if (sc.pageMetaMap && typeof sc.pageMetaMap === 'object') {
                    const nextPageMap = {};
                    for (const [k, v] of Object.entries(sc.pageMetaMap)) {
                        const nk = await convertOne(k);
                        if (v && typeof v === 'object') {
                            await offloadField(v, 'cleanUnletteredUrl');
                        }
                        if (nk) nextPageMap[nk] = v;
                    }
                    sc.pageMetaMap = nextPageMap;
                }
            }
            if (Array.isArray(m.extra.media)) {
                for (const med of m.extra.media) {
                    await offloadField(med, 'url');
                }
                // Если в посте с нашей сценой накопилось несколько объектов в m.extra.media (галерея Таверны),
                // переносим их адреса в sc.history (чтобы ни один вариант не пропал!), а в m.extra.media оставляем 1 активный кадр
                if (sc && sc.url && m.extra.media.length > 1) {
                    if (!Array.isArray(sc.history)) sc.history = [sc.url];
                    m.extra.media.forEach(med => {
                        if (med?.url && (med.source === 'generated' || String(med.title || '').startsWith('Сцена')) && !sc.history.includes(med.url)) {
                            sc.history.push(med.url);
                        }
                    });
                    const nonNnb = m.extra.media.filter(x => x && x.source !== 'generated' && !String(x.title || '').startsWith('Сцена') && !String(x.title || '').startsWith('Комикс'));
                    const newMedia = [...nonNnb, { url: sc.url, type: 'image', title: 'Сцена', source: 'generated' }];
                    if (newMedia.length < m.extra.media.length) {
                        m.extra.media = newMedia;
                        m.extra.media_index = m.extra.media.length - 1;
                        m.extra.media_display = 'inline';
                        mediaSlimmed++;
                    }
                }
            }
        }
        for (const sc of (st.scenes || [])) await offloadField(sc, 'url');
        if (st.lastSceneMeta) {
            await offloadField(st.lastSceneMeta, 'url');
            await offloadField(st.lastSceneMeta, 'cleanUnletteredUrl');
            await offloadArray(st.lastSceneMeta.history);
        }
        for (const cl of (st.wardrobe?.closet || [])) await offloadField(cl, 'image');
        for (const bx of (st.wardrobe?.box || [])) await offloadField(bx, 'image');
        for (const hs of (st.wardrobe?.history || [])) await offloadField(hs, 'image');
        if (st.wardrobe?.active) {
            const wa = st.wardrobe.active;
            await offloadField(wa, 'image');
            await offloadField(wa, 'accentImage');
            if (wa.look) await offloadField(wa.look, 'image');
            for (const opt of (wa.options || [])) await offloadField(opt, 'image');
            for (const ac of (wa.accents || [])) await offloadField(ac, 'image');
            for (const sac of (wa.selectedAccents || [])) await offloadField(sac, 'image');
            await offloadArray(wa.individualImages);
            await offloadArray(wa.individualAccentImages);
            for (const he of (wa.imageHistory || [])) {
                await offloadField(he, 'url');
                await offloadArray(he.individualImages);
            }
        }
        for (const np of (st.npcs || [])) await offloadField(np, 'avatar');
        if (st.mainCharCard) await offloadField(st.mainCharCard, 'avatar');
        if (st.home) {
            await offloadField(st.home, 'image');
            await offloadArray(st.home.images);
        }
        for (const tr of (st.trends || [])) await offloadField(tr, 'image');
        await offloadArray(st.trendsImageHistory);
        for (const tl of (st.time?.timeline || [])) await offloadField(tl, 'image');

        if (offloadedCount > 0 || mediaSlimmed > 0) {
            if (cache.size > 0) {
                $('#chat img.mes_img').each(function () {
                    const curSrc = $(this).attr('src');
                    if (curSrc && cache.has(curSrc)) {
                        $(this).attr('src', cache.get(curSrc));
                    }
                    const origSrc = $(this).attr('data-nnb-orig-src');
                    if (origSrc && cache.has(origSrc)) {
                        $(this).attr('data-nnb-orig-src', cache.get(origSrc));
                    }
                });
            }
            await c.saveMetadata();
            await c.saveChat();
        }
    } catch (e) {
        console.warn('[npc_notebook] offloadAllBase64InChatAndMeta error:', e);
    } finally {
        isOffloadingImages = false;
    }
    return offloadedCount;
}

let autoOffloadTimer = null;
function scheduleAutoChatImageOptimization() {
    clearTimeout(autoOffloadTimer);
    autoOffloadTimer = setTimeout(async () => {
        if (typeof sceneDrawing !== 'undefined' && sceneDrawing) return;
        const st = store();
        if (!st) return;
        const count = await offloadAllBase64InChatAndMeta(st);
        if (count > 0) {
            placeMesButtonsSoon();
            logImageDiag(`Авто-оптимизация: ${count} base64-картинок перенесено на диск`);
        }
    }, 1500);
}

async function cleanupBloatedAlbumAndChat(st) {
    if (!st) return;
    const c = ctx();
    const chat = Array.isArray(c.chat) ? c.chat : [];
    let removedVariants = 0;
    const activeSceneByMes = new Map();

    const discardedDraftUrls = new Set();
    const chosenUrls = new Set();

    // 1. В каждом сообщении чата оставляем только текущий выбранный вариант картинки (удаляем невыбранные дубли из history и media)
    chat.forEach((m, idx) => {
        if (!m || !m.extra) return;
        const sc = m.extra.nnbScene;
        if (sc && sc.url) {
            chosenUrls.add(sc.url);
            if (Array.isArray(sc.history) && sc.history.length > 1) {
                // Если в истории поста лежит многостраничная глава манхвы (разные кусочки поста chunkIndex в pageMetaMap),
                // бережно сохраняем последнюю страницу каждого кусочка главы, удаляя только старые черновые дубли одного и того же кусочка!
                const keptByChunk = new Map();
                let hasMultiChunkPages = false;
                sc.history.forEach(u => {
                    const pm = sc.pageMetaMap?.[u];
                    if (pm?.comicOpts?.stripMode && Number(pm?.comicOpts?.chunkTotal) > 1) {
                        hasMultiChunkPages = true;
                        keptByChunk.set(Number(pm.comicOpts.chunkIndex) || 0, u);
                    }
                });
                const keptSet = new Set([sc.url]);
                if (hasMultiChunkPages) {
                    for (const u of keptByChunk.values()) {
                        if (u) {
                            keptSet.add(u);
                            chosenUrls.add(u);
                        }
                    }
                }
                const nextHist = [];
                sc.history.forEach(u => {
                    if (u && keptSet.has(u) && !nextHist.includes(u)) {
                        nextHist.push(u);
                    } else if (u) {
                        discardedDraftUrls.add(u);
                    }
                });
                removedVariants += Math.max(0, sc.history.length - nextHist.length);
                sc.history = nextHist.length ? nextHist : [sc.url];
            }
            if (Array.isArray(m.extra.media) && m.extra.media.length > 1) {
                m.extra.media = m.extra.media.filter(x => x.url === sc.url || x.source !== 'generated');
                m.extra.media_index = Math.max(0, m.extra.media.length - 1);
            }
            activeSceneByMes.set(idx, {
                url: sc.url,
                mesId: idx,
                at: idx + 1,
                date: st.time?.date || '',
                desc: sc.desc || '',
                extraNeg: sc.extraNeg || '',
                cast: sc.cast || [],
                charCaptions: Array.isArray(sc.charCaptions) ? [...sc.charCaptions] : [],
                camMode: sc.camMode || 'third',
                prompt: sc.prompt || '',
                pov: !!sc.pov,
            });
        }
    });

    // 2. В альбоме (st.scenes) убираем только отвергнутые черновые варианты и дубликаты URL,
    // но БЕРЕЖНО СОХРАНЯЕМ все памятные фото из прошлых глав (перенесённые при переезде чата)!
    const oldScenesCount = (st.scenes || []).length;
    if (Array.isArray(st.scenes)) {
        const seen = new Set();
        st.scenes = st.scenes.filter(x => {
            if (!x?.url) return false;
            if (discardedDraftUrls.has(x.url) && !chosenUrls.has(x.url)) return false;
            if (seen.has(x.url)) return false;
            seen.add(x.url);
            return true;
        });
    }
    const removedAlbum = Math.max(0, oldScenesCount - (st.scenes || []).length);

    // 3. Очищаем временные буферы невыбранных нарядов в гардеробе
    if (st.wardrobe?.active && st.wardrobe.active.status === 'worn') {
        delete st.wardrobe.active.individualImages;
        delete st.wardrobe.active.imageHistory;
    }

    // 4. Выгружаем застрявшие тяжёлые base64-картинки (data:image/...) из САМОГО ЧАТА (c.chat) И из метаданных на диск Таверны!
    const offloadedCount = await offloadAllBase64InChatAndMeta(st);

    await c.saveChat();
    await commit();
    placeMesButtonsSoon();
    toastr.success(`Память очищена и ускорена! Убрано дублей из альбома: ${removedAlbum}, черновых вариантов из постов: ${removedVariants}${offloadedCount ? `, сжато тяжёлых картинок в файлы: ${offloadedCount}` : ''}.`, '🧹 Очистка и ускорение Таверны', { timeOut: 7000 });
}

async function showAlbumItem(item) {
    const st = store();
    const el = $('<div class="nnb-pop nnb-pop-visual"></div>');
    el.append($('<div class="nnb-album-big" style="text-align:center;"></div>').append($('<img alt="" style="max-height:65vh; max-width:100%; border-radius:10px; object-fit:contain;">').attr('src', item.url)));
    el.append($('<div class="nnb-look-title" style="margin-top:8px;"></div>').text([item.title, item.date ? formatDate(item.date) : ''].filter(Boolean).join(' · ')));
    if (item.text) el.append($('<div class="nnb-pop-sub"></div>').text(item.text.length > 350 ? item.text.slice(0, 350) + '…' : item.text));
    const row = $('<div class="nnb-pop-row nnb-pop-links" style="margin-top:10px; display:flex; gap:8px; flex-wrap:wrap; justify-content:space-between;"></div>');
    row.append($('<div class="menu_button"><i class="fa-solid fa-up-right-and-down-left-from-center"></i> Открыть в полном размере</div>').on('click', () => window.open(item.url, '_blank')));
    if (item.kind === 'scene' && st?.scenes?.[item.ref]) {
        row.append($('<div class="menu_button"><i class="fa-solid fa-sliders"></i> Варианты и промпт сцены</div>').on('click', () => {
            closePopupOf(el);
            openSceneImageViewer(st.scenes[item.ref].mesId, st.scenes[item.ref]);
        }));
    }
    row.append($('<div class="menu_button" style="border-color:#d9534f; color:#ff8a84;"><i class="fa-solid fa-trash"></i> Удалить фото из альбома</div>').on('click', async () => {
        closePopupOf(el);
        await deleteAlbumItem(st, item);
    }));
    el.append(row);
    await openPopup(el, true);
}

function renderAlbum(st) {
    const root = $('#nnb_album_box').empty();
    const items = albumItems(st);
    const det = $('<details open class="nnb-section"><summary></summary></details>');
    det.find('summary').text(`🖼 Альбом (${items.length})`);

    const tools = $('<div style="display:flex; gap:8px; flex-wrap:wrap; align-items:center; margin-bottom:10px;"></div>');
    tools.append($('<div class="menu_button" style="padding:5px 10px; font-size:0.83em; width:auto;" title="Убрать из альбома и сообщений все невыбранные дубли генераций, оставив только те картинки, которые сейчас стоят в постах"><i class="fa-solid fa-broom"></i> 🧹 Очистить дубли и черновики (ускорить Таверну)</div>').on('click', () => cleanupBloatedAlbumAndChat(st)));
    if (items.length > 0) {
        tools.append($('<div class="menu_button" style="padding:5px 10px; font-size:0.83em; width:auto;" title="Очистить весь альбом"><i class="fa-solid fa-trash-can"></i> Очистить весь альбом</div>').on('click', async () => {
            if (!confirm(`Удалить все фотографии (${items.length} шт.) из альбома этого чата?`)) return;
            st.scenes = [];
            (st.wardrobe?.history || []).forEach(h => { h.image = ''; });
            await commit();
            toastr.info('Альбом полностью очищен', '🖼 Альбом');
        }));
    }
    det.append(tools);
    det.append('<div class="nnb-npc-status" style="margin-bottom:8px; font-size:0.82em;">Все генерации сохраняются, чтобы ты могла спокойно выбрать лучшую. Ненужные фото можно удалить кнопкой <b>🗑️</b> в углу карточки или кнопкой ручной чистки выше.</div>');

    if (!items.length) {
        det.append('<div class="nnb-empty">Пока пусто: здесь будут выбранные картинки сцен (🎬) и образов.</div>');
        root.append(det);
        return;
    }

    const grid = $('<div class="nnb-album"></div>');
    items.forEach(it => {
        const card = $('<div class="nnb-album-thumb" tabindex="0" style="position:relative; overflow:hidden; background:rgba(0,0,0,0.25);"></div>').attr('title', it.title);
        const imgEl = $('<img loading="lazy" decoding="async" alt="" style="width:100%; height:100%; object-fit:cover; display:block;">').attr('src', it.url);
        const delBtn = $('<div title="Удалить фото из альбома" style="position:absolute; top:5px; right:5px; width:26px; height:26px; border-radius:7px; background:rgba(20,16,28,0.82); color:#ff8a84; display:flex; align-items:center; justify-content:center; cursor:pointer; font-size:0.82em; border:1px solid rgba(255,255,255,0.18); z-index:2;"><i class="fa-solid fa-trash"></i></div>');
        delBtn.on('click', async e => {
            e.stopPropagation();
            await deleteAlbumItem(st, it);
        });
        card.append(imgEl, delBtn);
        card.on('click', () => showAlbumItem(it));
        grid.append(card);
    });
    det.append(grid);
    root.append(det);
}

async function showAlbum() {
    openBook('album');
}

async function redrawSceneBySamePrompt(mesId, customMeta = null) {
    if (!Number.isInteger(mesId)) mesId = undefined;
    if (sceneDrawing) return toastr.info('Сцена уже рисуется — картинка появится под постом сама', '🎬 Сцена');
    const meta = customMeta || findSavedSceneMeta(mesId);
    if (!hasValidSceneMeta(meta)) {
        return showScenePopup(mesId);
    }
    const note = toastr.info('Рисую ещё один вариант по тому же промпту (без запроса к текстовой модели)…', '🔄 Ещё вариант сцены', { timeOut: 60000, extendedTimeOut: 15000, tapToDismiss: true });
    let res = null;
    try {
        res = await drawScene(null, mesId, meta.camMode || 'third', meta);
    } catch (e) {
        console.error('[npc_notebook] redrawSceneBySamePrompt error:', e);
    } finally {
        sceneDrawing = false;
        try { toastr.clear(note); } catch (e) { /* ignore */ }
    }
    if (res?.url) {
        await attachToLastMessage(res.url, mesId, res.sceneMeta);
    }
}

// 🎬: рисуем в фоне и ставим картинку отдельным блоком под постом (с поддержкой многостраничной главы манхвы по кусочкам поста!)
async function showScenePopup(mesId, forceAsk = false) {
    if (!Number.isInteger(mesId)) mesId = undefined;
    if (sceneDrawing) return toastr.info('Сцена уже рисуется — картинка появится под постом сама', '🎬 Сцена');
    const existingMeta = findSavedSceneMeta(mesId);
    const choice = await askSceneCameraMode(existingMeta, forceAsk, mesId);
    if (!choice) return;
    const camMode = choice.mode || 'third';
    const reuseMeta = choice.reuseMeta || null;
    const forcedCast = choice.forcedCast || null;
    const whisper = choice.whisper || '';
    const comicOpts = choice.comicOpts || null;

    if (Array.isArray(choice.multiChunkChapter) && choice.multiChunkChapter.length > 1 && comicOpts?.enabled) {
        const chunks = choice.multiChunkChapter;
        const cInit = ctx();
        let tIdxInit = Number.isInteger(mesId) ? mesId : (cInit.chat.length - 1);
        if (!Number.isInteger(mesId)) {
            while (tIdxInit >= 0 && (!cInit.chat[tIdxInit] || cInit.chat[tIdxInit].is_system)) tIdxInit--;
        }
        multiPageKeepAliveActive = true;
        startBackgroundGenerationKeepAlive();
        const note = toastr.info(`Рисуем главу манхвы (страница 1 из ${chunks.length})… Все страницы появятся под постом разом по готовности, чтобы текст не скакал!`, '📚 Глава манхвы', { timeOut: 300000, extendedTimeOut: 60000, tapToDismiss: true });
        const completedPages = [];
        let chapterPassport = '';
        let chapterCanonByGender = { boy: '', girl: '', boyCast: [], girlCast: [] };
        let lastSceneSegIdx = -1;
        const fullRawMesForPassport = String(cInit.chat?.[tIdxInit]?.mes || '');
        try {
            for (let i = 0; i < chunks.length; i++) {
                const chObj = chunks[i];
                const curSeg = getActiveSceneSegmentFromFullPost(chObj.text, fullRawMesForPassport);
                if (curSeg.sceneIndex !== lastSceneSegIdx) {
                    chapterPassport = '';
                    chapterCanonByGender = { boy: '', girl: '', boyCast: [], girlCast: [] };
                    lastSceneSegIdx = curSeg.sceneIndex;
                }
                try {
                    if (note && note.find) {
                        note.find('.toast-message').text(`Рисуем главу манхвы: страница ${i + 1} из ${chunks.length}… По готовности выложим всю главу разом!`);
                    }
                } catch (e) { /* ignore */ }
                logImageDiag(`Глава манхвы: рисуем страницу ${i + 1} из ${chunks.length}`);
                const chunkComicOpts = {
                    ...comicOpts,
                    chunkIndex: chObj.index,
                    chunkTotal: chObj.total,
                    chunkText: chObj.text,
                    chapterCharPassport: chapterPassport,
                    chapterCanonByGender: {
                        boy: chapterCanonByGender.boy,
                        girl: chapterCanonByGender.girl,
                        boyCast: [...chapterCanonByGender.boyCast],
                        girlCast: [...chapterCanonByGender.girlCast],
                    },
                };
                let pageRes = null;
                for (let pageAttempt = 1; pageAttempt <= 4; pageAttempt++) {
                    pageRes = await drawScene(null, mesId, camMode, null, forcedCast, whisper, chunkComicOpts);
                    if (pageRes?.url) break;
                    if (pageAttempt < 4) {
                        const waitSec = 5 + pageAttempt * 2;
                        toastr.warning(`⏳ Ключ был занят на странице ${i + 1} из ${chunks.length} — ждём ${waitSec} сек. и повторяем эту страницу…`, '🔄 Очередь страниц манхвы', { timeOut: waitSec * 1000 });
                        await bgSafeSleep(waitSec * 1000);
                    }
                }
                if (pageRes?.url) {
                    if (pageRes.sceneMeta) {
                        pageRes.sceneMeta.inlineViewMode = 'vertical';
                        const caps = Array.isArray(pageRes.sceneMeta.charCaptions) ? pageRes.sceneMeta.charCaptions : [];
                        const p1 = pageRes.sceneMeta.panelPrompts?.[0] || pageRes.sceneMeta.desc || '';
                        const hasNewBoy = /\b1boy\b/i.test(p1) && !/\b1boy\b/i.test(chapterPassport);
                        const hasNewGirl = /\b1girl\b/i.test(p1) && !/\b1girl\b/i.test(chapterPassport);
                        const hasNewTail = /\b(?:puma|cougar|cat|dog|wolf|fox|lion|animal)_?\s*tail\b/i.test(p1) && !/\b(?:puma|cougar|cat|dog|wolf|fox|lion|animal)_?\s*tail\b/i.test(chapterPassport);
                        if (!chapterPassport) {
                            chapterPassport = [
                                caps.length ? caps.map((c, idx) => `CHAR${idx + 1}: ${c}`).join('\n') : '',
                                p1 ? `Образец одежды и внешности из 1-й страницы этой сцены: ${p1}` : '',
                            ].filter(Boolean).join('\n').slice(0, 1800);
                        } else if ((hasNewBoy || hasNewGirl || hasNewTail) && chapterPassport.length < 1800) {
                            const extraSample = [
                                caps.length ? caps.map((c, idx) => `CHAR${idx + 1}: ${c}`).join('\n') : '',
                                p1 ? `Дополнение внешности нового участника со страницы ${i + 1}: ${p1}` : '',
                            ].filter(Boolean).join('\n');
                            if (extraSample) {
                                chapterPassport = (chapterPassport + '\n' + extraSample).slice(0, 2200);
                            }
                        }
                        const extractedCanon = extractCanonTagsByGender([
                            ...(Array.isArray(pageRes.sceneMeta.panelPrompts) ? pageRes.sceneMeta.panelPrompts : []),
                            ...(Array.isArray(pageRes.sceneMeta.charCaptions) ? pageRes.sceneMeta.charCaptions : []),
                            pageRes.sceneMeta.desc || '',
                        ]);
                        const pageCastNorm = (Array.isArray(pageRes.sceneMeta.cast) ? pageRes.sceneMeta.cast : []).map(x => String(x || '').trim().toLowerCase().replace(/ё/g, 'е')).filter(Boolean);
                        const matchOwnerCast = (canonTagStr) => {
                            const core = String(canonTagStr || '').split(/[,(]/)[0].trim().toLowerCase();
                            const coreWords = core.split(/[\s_-]+/).filter(w => w.length >= 3);
                            const matched = pageCastNorm.filter(ruName => {
                                const vars = transliterateRuNameVariants(ruName).map(v => v.toLowerCase());
                                return vars.some(v => core.includes(v) || coreWords.some(cw => cw.includes(v) || v.includes(cw)));
                            });
                            return matched.length ? matched : pageCastNorm;
                        };
                        if (extractedCanon.boy && !chapterCanonByGender.boy) {
                            chapterCanonByGender.boy = extractedCanon.boy;
                            chapterCanonByGender.boyCast = matchOwnerCast(extractedCanon.boy);
                        }
                        if (extractedCanon.girl && !chapterCanonByGender.girl) {
                            chapterCanonByGender.girl = extractedCanon.girl;
                            chapterCanonByGender.girlCast = matchOwnerCast(extractedCanon.girl);
                        }
                    }
                    completedPages.push(pageRes);
                }
            }
            if (completedPages.length > 0) {
                if (cInit.chat?.[tIdxInit]?.extra?.nnbScene) {
                    cInit.chat[tIdxInit].extra.nnbScene.history = [];
                    cInit.chat[tIdxInit].extra.nnbScene.pageMetaMap = {};
                }
                const batchHistory = [];
                const batchCleanMap = {};
                const batchPageMetaMap = {};
                for (const pr of completedPages) {
                    if (!pr?.url) continue;
                    if (!batchHistory.includes(pr.url)) batchHistory.push(pr.url);
                    if (pr.sceneMeta?.cleanUrlMap) Object.assign(batchCleanMap, pr.sceneMeta.cleanUrlMap);
                    if (pr.sceneMeta?.pageMetaMap) Object.assign(batchPageMetaMap, pr.sceneMeta.pageMetaMap);
                }
                const lastPr = completedPages[completedPages.length - 1];
                const combinedMeta = {
                    ...(lastPr.sceneMeta || {}),
                    url: lastPr.url,
                    history: batchHistory,
                    replaceHistory: true,
                    cleanUrlMap: batchCleanMap,
                    pageMetaMap: batchPageMetaMap,
                    inlineViewMode: 'vertical',
                };
                await attachToLastMessage(lastPr.url, mesId, combinedMeta, true);
                delete combinedMeta.replaceHistory;
                toastr.success(`Готова глава манхвы из ${completedPages.length} страниц! Все страницы выложены сверху вниз под постом.`, '📚 Глава манхвы', { timeOut: 7000 });
            }
        } catch (e) {
            console.error('[npc_notebook] multiChunkChapter error:', e);
        } finally {
            sceneDrawing = false;
            multiPageKeepAliveActive = false;
            stopBackgroundGenerationKeepAlive();
            try { toastr.clear(note); } catch (e) { /* ignore */ }
        }
        return;
    }
    const isPov = camMode === 'pov' || camMode === 'pov_hands' || camMode === 'pov_clean' || camMode === true;
    const chunkBadge = (comicOpts?.stripMode && Number(comicOpts?.chunkTotal) > 1)
        ? ` [стр. ${(Number(comicOpts.chunkIndex) || 0) + 1}/${Number(comicOpts.chunkTotal)}]`
        : '';
    const toastMsg = reuseMeta
        ? 'Перерисовываю сцену по готовому промпту… Нажми на уведомление, чтобы скрыть.'
        : comicOpts?.enabled
            ? (comicOpts.stripMode ? `Рисую страницу манхвы${chunkBadge} (${Number(comicOpts.framesPerPage) === 4 ? 4 : 3} кадра) и склеиваю с полными репликами…` : 'Рисую страницу комикса / манги по текущей сцене…')
            : (isPov ? 'Рисую сцену от первого лица (POV)… Нажми на уведомление, чтобы скрыть.' : 'Рисую сцену (взгляд со стороны)… Нажми на уведомление, чтобы скрыть.');
    const note = toastr.info(toastMsg, comicOpts?.enabled ? '💬 Манхва / Комикс' : '🎬 Сцена', { timeOut: 60000, extendedTimeOut: 15000, tapToDismiss: true });
    let res = null;
    try {
        res = await drawScene(null, mesId, camMode, reuseMeta, forcedCast, whisper, comicOpts);
    } catch (e) {
        console.error('[npc_notebook] showScenePopup error:', e);
    } finally {
        sceneDrawing = false;
        try { toastr.clear(note); } catch (e) { /* ignore */ }
    }
    if (res?.url) {
        await attachToLastMessage(res.url, mesId, res.sceneMeta);
    }
}

function findNextUndrawnChunkIndex(sceneMeta, totalChunks) {
    if (!sceneMeta || totalChunks <= 1) return -1;
    const drawnIndices = new Set();
    const hist = Array.isArray(sceneMeta.history) && sceneMeta.history.length ? sceneMeta.history : (sceneMeta.url ? [sceneMeta.url] : []);
    for (const u of hist) {
        const pm = sceneMeta.pageMetaMap?.[u];
        const cOpts = pm?.comicOpts || (u === sceneMeta.url ? sceneMeta.comicOpts : null);
        if (cOpts?.stripMode && Number.isInteger(Number(cOpts.chunkIndex))) {
            drawnIndices.add(Number(cOpts.chunkIndex));
        }
    }
    if (!drawnIndices.size && sceneMeta.comicOpts?.stripMode) {
        drawnIndices.add(Number(sceneMeta.comicOpts.chunkIndex) || 0);
    }
    for (let i = 0; i < totalChunks; i++) {
        if (!drawnIndices.has(i)) return i;
    }
    return -1;
}

async function drawNextComicChunkPage(mesId, baseSceneMeta) {
    if (sceneDrawing) return toastr.info('Сцена уже рисуется — подожди завершения текущего кадра', '📖 Манхва');
    const c = ctx();
    let targetIdx = Number.isInteger(mesId) ? mesId : (c.chat.length - 1);
    if (!Number.isInteger(mesId)) {
        while (targetIdx >= 0 && (!c.chat[targetIdx] || c.chat[targetIdx].is_system)) targetIdx--;
    }
    const msg = c.chat?.[targetIdx];
    if (!msg?.mes) return;
    const chunks = splitPostIntoComicChunks(msg.mes);
    if (chunks.length <= 1) {
        return toastr.info('Этот пост короткий и целиком помещается на одну страницу!', '📖 Манхва');
    }
    const liveSceneMeta = c.chat?.[targetIdx]?.extra?.nnbScene || baseSceneMeta;
    const prevOpts = baseSceneMeta?.comicOpts || liveSceneMeta?.comicOpts || {};
    let nextIdx = findNextUndrawnChunkIndex(liveSceneMeta, chunks.length);
    if (nextIdx < 0) {
        nextIdx = Math.min(chunks.length - 1, (Number(prevOpts.chunkIndex) || 0) + 1);
    }
    const chObj = chunks[nextIdx];
    const nextComicOpts = {
        enabled: true,
        stripMode: true,
        framesPerPage: Number(prevOpts.framesPerPage) === 4 ? 4 : (Number(settings().comicFramesPerPage) === 4 ? 4 : 3),
        styleId: prevOpts.styleId || settings().comicStyleId || 'comicbright',
        linesMode: prevOpts.linesMode || settings().comicLinesMode || 'auto',
        chunkIndex: chObj.index,
        chunkTotal: chObj.total,
        chunkText: chObj.text,
    };
    const note = toastr.info(`Рисуем страницу манхвы ${nextIdx + 1} из ${chunks.length} (кусочек #${nextIdx + 1}: «${escapeHtml(chObj.preview)}»)…`, '📖 Следующая страница манхвы', { escapeHtml: false, timeOut: 75000, extendedTimeOut: 15000 });
    let res = null;
    try {
        res = await drawScene(null, targetIdx, baseSceneMeta?.camMode || 'third', null, baseSceneMeta?.cast?.filter(x => x !== '__none__') || null, '', nextComicOpts);
    } finally {
        sceneDrawing = false;
        try { toastr.clear(note); } catch (e) { /* ignore */ }
    }
    if (res?.url) {
        await attachToLastMessage(res.url, targetIdx, res.sceneMeta);
        toastr.success(`Страница ${nextIdx + 1} из ${chunks.length} готова и добавлена к посту!`, '📖 Манхва');
    }
}

function getSortedManhwaHistoryUrls(sceneMeta) {
    const rawUrls = Array.isArray(sceneMeta?.history) && sceneMeta.history.length ? [...sceneMeta.history] : (sceneMeta?.url ? [sceneMeta.url] : []);
    if (rawUrls.length <= 1) return rawUrls;
    const pmMap = sceneMeta?.pageMetaMap || {};
    const hasChunkPages = rawUrls.some(u => pmMap[u]?.comicOpts?.stripMode && Number(pmMap[u]?.comicOpts?.chunkTotal) > 1);
    if (!hasChunkPages) return rawUrls;
    // Если в истории есть страницы многостраничной главы, отфильтровываем старые черновики без chunkTotal > 1 и сортируем строго по chunkIndex (0, 1, 2, 3...)!
    const chunkEntries = rawUrls
        .map((u, origIdx) => {
            const cOpts = pmMap[u]?.comicOpts;
            const isChunkPage = !!(cOpts?.stripMode && Number(cOpts?.chunkTotal) > 1);
            const chIdx = isChunkPage ? (Number(cOpts.chunkIndex) || 0) : -1;
            return { u, origIdx, isChunkPage, chIdx };
        })
        .filter(x => x.isChunkPage);
    if (!chunkEntries.length) return rawUrls;
    chunkEntries.sort((a, b) => (a.chIdx !== b.chIdx ? a.chIdx - b.chIdx : a.origIdx - b.origIdx));
    return chunkEntries.map(x => x.u);
}

async function triggerBrowserDownloadUrl(urlOrData, filename) {
    if (!urlOrData) return;
    const dUrl = urlOrData.startsWith('data:') ? urlOrData : (await fileToDataUrl(urlOrData) || urlOrData);
    const a = document.createElement('a');
    a.href = dUrl;
    a.download = filename;
    document.body.appendChild(a);
    a.click();
    setTimeout(() => a.remove(), 250);
}

function getCleanUrlForManhwaPage(sceneMeta, pUrl) {
    if (!sceneMeta || !pUrl) return '';
    const fromMap = sceneMeta.cleanUrlMap?.[pUrl];
    if (fromMap && fromMap !== pUrl) return fromMap;
    const fromPage = sceneMeta.pageMetaMap?.[pUrl]?.cleanUnletteredUrl;
    if (fromPage && fromPage !== pUrl) return fromPage;
    if (sceneMeta.cleanUnletteredUrl && sceneMeta.cleanUnletteredUrl !== pUrl && (!Array.isArray(sceneMeta.history) || sceneMeta.history.length <= 1)) {
        return sceneMeta.cleanUnletteredUrl;
    }
    return '';
}

async function downloadAllManhwaPagesSequentially(mesId, sceneMeta, useCleanUnlettered = false) {
    const rawUrls = getSortedManhwaHistoryUrls(sceneMeta);
    if (!rawUrls.length) return;
    const wantClean = useCleanUnlettered || !!sceneMeta?.showCleanUnlettered;
    const urls = rawUrls.map(u => (wantClean ? (getCleanUrlForManhwaPage(sceneMeta, u) || u) : u));
    toastr.info(`Подготавливаю и скачиваю все страницы${wantClean ? ' (без текста)' : ''} (${urls.length} шт.) строго по порядку с паузой 1.1 сек. (чтобы в галерее телефона они легли строго 1 → ${urls.length})…`, '📦 Скачивание по порядку', { timeOut: urls.length * 1200 + 2000 });
    // 1. Сначала заранее загружаем все файлы в память, чтобы разный размер картинок не менял порядок их сохранения на диск!
    const preloaded = [];
    for (let i = 0; i < urls.length; i++) {
        const u = urls[i];
        const dUrl = u.startsWith('data:') ? u : (await fileToDataUrl(u) || u);
        const pageNumStr = String(i + 1).padStart(2, '0');
        const cleanSuffix = wantClean ? '_clean' : '';
        preloaded.push({ dUrl, filename: `${pageNumStr}_manhwa_post${Number.isInteger(mesId) ? mesId : 0}_page${pageNumStr}${cleanSuffix}.png` });
    }
    // 2. Сохраняем строго по очереди с интервалом 1100 мс (1.1 сек.), чтобы система и галерея телефона фиксировали точный порядок!
    for (let i = 0; i < preloaded.length; i++) {
        await triggerBrowserDownloadUrl(preloaded[i].dUrl, preloaded[i].filename);
        if (i + 1 < preloaded.length) {
            await new Promise(r => setTimeout(r, 1100));
        }
    }
    toastr.success(`Все ${preloaded.length} страниц${wantClean ? ' (без текста)' : ''} скачаны строго по порядку (01 → ${String(preloaded.length).padStart(2, '0')})!`, '📦 Скачивание завершено');
}

async function downloadAllPagesAsSingleVerticalStrip(mesId, sceneMeta, useCleanUnlettered = false) {
    const rawUrls = getSortedManhwaHistoryUrls(sceneMeta);
    if (!rawUrls.length) return;
    const wantClean = useCleanUnlettered || !!sceneMeta?.showCleanUnlettered;
    const urls = rawUrls.map(u => (wantClean ? (getCleanUrlForManhwaPage(sceneMeta, u) || u) : u));
    if (urls.length === 1) {
        await triggerBrowserDownloadUrl(urls[0], `manhwa_post${Number.isInteger(mesId) ? mesId : 0}_page1${wantClean ? '_clean' : ''}.png`);
        return;
    }
    toastr.info(`Склеиваю все ${urls.length} страниц${wantClean ? ' (без текста)' : ''} сверху вниз в единый длинный свиток манхвы…`, '📥 Склейка главы', { timeOut: 5000 });
    const loaded = [];
    for (const u of urls) {
        const dUrl = await fileToDataUrl(u) || u;
        const im = await new Promise(res => {
            const img = new Image();
            img.crossOrigin = 'anonymous';
            img.onload = () => res(img);
            img.onerror = () => res(null);
            img.src = dUrl;
        });
        if (im) loaded.push(im);
    }
    if (!loaded.length) return;
    const W = 1200;
    const gap = 16;
    const heights = loaded.map(im => Math.round((im.naturalHeight || 1680) * (W / (im.naturalWidth || 1200))));
    const totalH = heights.reduce((a, b) => a + b, 0) + gap * (loaded.length - 1);
    const cv = document.createElement('canvas');
    cv.width = W;
    cv.height = totalH;
    const ctx2d = cv.getContext('2d');
    ctx2d.fillStyle = '#141218';
    ctx2d.fillRect(0, 0, W, totalH);
    let curY = 0;
    for (let i = 0; i < loaded.length; i++) {
        ctx2d.drawImage(loaded[i], 0, curY, W, heights[i]);
        curY += heights[i] + gap;
    }
    const scrollDataUrl = cv.toDataURL('image/jpeg', 0.94);
    await triggerBrowserDownloadUrl(scrollDataUrl, `manhwa_full_chapter_post${Number.isInteger(mesId) ? mesId : 0}_${loaded.length}pages.jpg`);
    toastr.success(`Вся глава (${loaded.length} стр.) склеена и скачана одним файлом!`, '📥 Манхва скачана');
}

function formatQuotesForEditorText(quotes) {
    return (quotes || []).map(q => {
        if (!q || !q.text) return '';
        if (q.kind === 'narration' || !q.speaker) return `NARRATION | ${q.text}`;
        if (q.kind === 'thought') return `💭 ${q.speaker} | ${q.text}`;
        return `${q.speaker} | ${q.text}`;
    }).filter(Boolean).join('\n');
}

async function editQuotesForSpecificPageUrl(mesId, sceneMeta, targetUrl) {
    if (!sceneMeta || !targetUrl) return;
    const curPageMeta = sceneMeta.pageMetaMap?.[targetUrl] || null;
    const activeComicOptsForSlide = curPageMeta?.comicOpts || sceneMeta.comicOpts;
    const activeQuotes = curPageMeta?.comicQuotes || sceneMeta.comicQuotes || [];
    const curQuotesText = formatQuotesForEditorText(activeQuotes);
    const editedQ = await askText(
        'Текст для фреймов этой страницы манхвы (по одному на строку):\n• Прямая речь: Имя | текст реплики\n• Мысли (серым курсивом): 💭 Имя | текст мысли\n• Авторское описание (без имени!): NARRATION | текст описания (или просто текст без черты |)\n(Оставь поле пустым, чтобы показать чистый арт без облачков):',
        curQuotesText
    );
    if (editedQ === null) return;
    const parsedQ = [];
    for (const ql of String(editedQ).split(/\r?\n/)) {
        const clLine = ql.trim().replace(/^QUOTE\s*\d*\s*[:：—–-]\s*/i, '');
        if (!clLine) continue;
        const pObj = parseRawQuoteLinePayload(clLine, parsedQ.length + 1);
        if (pObj) parsedQ.push(pObj);
    }
    if (!sceneMeta.cleanUrlMap || typeof sceneMeta.cleanUrlMap !== 'object') sceneMeta.cleanUrlMap = {};
    const baseCleanUrl = sceneMeta.cleanUrlMap[targetUrl] || curPageMeta?.cleanUnletteredUrl || sceneMeta.cleanUnletteredUrl || targetUrl;
    sceneMeta.cleanUrlMap[targetUrl] = baseCleanUrl;
    if (!parsedQ.length) {
        const idxInHist = Array.isArray(sceneMeta.history) ? sceneMeta.history.indexOf(targetUrl) : -1;
        if (idxInHist >= 0) sceneMeta.history[idxInHist] = baseCleanUrl;
        if (sceneMeta.url === targetUrl) sceneMeta.url = baseCleanUrl;
        await attachToLastMessage(sceneMeta.url || baseCleanUrl, mesId, sceneMeta, true);
        toastr.info('Показана чистая версия страницы без облачков текста', '💬 Текст страницы');
        return;
    }
    const newLetteredData = await overlayComicBubblesOnDataUrl(baseCleanUrl, parsedQ, activeComicOptsForSlide);
    const savedUrl = await storeImage(newLetteredData);
    sceneMeta.cleanUrlMap[savedUrl] = baseCleanUrl;
    if (!sceneMeta.pageMetaMap || typeof sceneMeta.pageMetaMap !== 'object') sceneMeta.pageMetaMap = {};
    sceneMeta.pageMetaMap[savedUrl] = {
        ...(curPageMeta || {}),
        comicQuotes: parsedQ,
        comicOpts: activeComicOptsForSlide,
        cleanUnletteredUrl: baseCleanUrl,
    };
    const idxInHist = Array.isArray(sceneMeta.history) ? sceneMeta.history.indexOf(targetUrl) : -1;
    if (idxInHist >= 0) sceneMeta.history[idxInHist] = savedUrl;
    if (sceneMeta.url === targetUrl) sceneMeta.url = savedUrl;
    sceneMeta.replaceHistory = true;
    await attachToLastMessage(sceneMeta.url || savedUrl, mesId, sceneMeta, true);
    delete sceneMeta.replaceHistory;
    toastr.success('Облачка речи, мыслей и описания обновлены на этой странице!', '💬 Текст манхвы');
}

async function rerollSpecificManhwaPageInPlace(mesId, sceneMeta, targetUrl, regeneratePromptFromChunk = false) {
    if (sceneDrawing) return toastr.info('Сцена уже рисуется — подожди завершения текущего кадра', '🔄 Перерисовка страницы');
    const idxInHist = Array.isArray(sceneMeta?.history) ? sceneMeta.history.indexOf(targetUrl) : -1;
    const pMeta = sceneMeta?.pageMetaMap?.[targetUrl] || null;
    const cOpts = pMeta?.comicOpts || sceneMeta?.comicOpts || null;
    const pageNum = idxInHist >= 0 ? (idxInHist + 1) : 1;
    const note = toastr.info(
        regeneratePromptFromChunk
            ? `Составляем новый промпт по сюжету для страницы ${pageNum} и перерисовываем…`
            : `Перерисовываем кадры страницы ${pageNum} по текущему промпту…`,
        `🔄 Страница ${pageNum}`,
        { timeOut: 75000, extendedTimeOut: 15000 }
    );
    let res = null;
    try {
        if (regeneratePromptFromChunk) {
            const c = ctx();
            const msg = c.chat?.[mesId];
            const chunks = splitPostIntoComicChunks(msg?.mes || '');
            const chIdx = Number.isInteger(Number(cOpts?.chunkIndex)) ? Number(cOpts.chunkIndex) : Math.max(0, pageNum - 1);
            const chObj = chunks[chIdx] || chunks[0] || null;
            const freshOpts = {
                ...(cOpts || { enabled: true, stripMode: true, framesPerPage: 3, styleId: settings().comicStyleId || 'comicbright', linesMode: 'auto' }),
                chunkIndex: chObj ? chObj.index : chIdx,
                chunkTotal: chunks.length || 1,
                chunkText: chObj ? chObj.text : '',
            };
            // старые «канон главы» и паспорт сохранены вместе со страницей — если та страница была ошибочной, они повторяют ошибку
            delete freshOpts.chapterCanonByGender;
            if (freshOpts.chapterCharPassport) {
                const stR = store();
                freshOpts.chapterCharPassport = stripAbsentCardCanons(String(freshOpts.chapterCharPassport), stR, [], freshOpts.chunkText || '');
                if (pageNum === 1) delete freshOpts.chapterCharPassport; // паспорт и есть промпт этой самой страницы
            }
            logImageDiag(`Новый промпт по кусочку #${(freshOpts.chunkIndex || 0) + 1}: старый канон главы сброшен, паспорт ${freshOpts.chapterCharPassport ? 'очищен' : 'не используется'}`);
            res = await drawScene(null, mesId, sceneMeta.camMode || 'third', null, sceneMeta.cast?.filter(x => x !== '__none__') || null, '', freshOpts);
        } else {
            const reusePageObj = {
                ...sceneMeta,
                ...(pMeta || {}),
                comicOpts: cOpts,
            };
            res = await drawScene(null, mesId, sceneMeta.camMode || 'third', reusePageObj, null, '', cOpts);
        }
    } finally {
        sceneDrawing = false;
        try { toastr.clear(note); } catch (e) { /* ignore */ }
    }
    if (res?.url) {
        if (Array.isArray(sceneMeta.history) && idxInHist >= 0) {
            sceneMeta.history[idxInHist] = res.url;
        }
        sceneMeta.pageMetaMap = { ...(sceneMeta.pageMetaMap || {}), ...(res.sceneMeta?.pageMetaMap || {}) };
        sceneMeta.cleanUrlMap = { ...(sceneMeta.cleanUrlMap || {}), ...(res.sceneMeta?.cleanUrlMap || {}) };
        sceneMeta.url = res.url;
        sceneMeta.replaceHistory = true;
        await attachToLastMessage(res.url, mesId, sceneMeta, true);
        delete sceneMeta.replaceHistory;
        toastr.success(`Страница ${pageNum} успешно обновлена на своём месте в ленте!`, '🔄 Страница обновлена');
    }
}

async function openManhwaVerticalReaderModal(mesId, sceneMeta) {
    const urls = getSortedManhwaHistoryUrls(sceneMeta);
    if (!urls.length) return;
    let modalCleanMode = !!sceneMeta?.showCleanUnlettered;
    const hasAnyClean = urls.some(u => !!getCleanUrlForManhwaPage(sceneMeta, u));
    const el = $('<div class="nnb-pop nnb-pop-visual"></div>');
    el.append(`<h3>📜 Чтение и скачивание манхвы лентой (${urls.length} стр.)</h3>`);
    const dlBar = $('<div style="display:flex; gap:8px; flex-wrap:wrap; margin-bottom:10px;"></div>');
    dlBar.append($('<div class="menu_button nnb-btn-primary" style="margin:0; padding:6px 12px; font-weight:700;"><i class="fa-solid fa-file-arrow-down"></i> 📥 Скачать всю главу одним длинным свитком (JPG)</div>').on('click', () => downloadAllPagesAsSingleVerticalStrip(mesId, sceneMeta, modalCleanMode)));
    dlBar.append($(`<div class="menu_button" style="margin:0; padding:6px 12px; font-weight:600;"><i class="fa-solid fa-download"></i> 📦 Скачать все страницы по отдельности (${urls.length} шт.)</div>`).on('click', () => downloadAllManhwaPagesSequentially(mesId, sceneMeta, modalCleanMode)));
    const stripWrap = $('<div style="display:flex; flex-direction:column; align-items:center; gap:14px; max-height:70vh; overflow-y:auto; padding:6px;"></div>');
    const modalImgs = [];
    if (hasAnyClean) {
        const toggleCleanModalBtn = $(`<div class="menu_button" style="margin:0; padding:6px 12px; font-weight:600;"></div>`);
        const updateModalCleanUi = () => {
            toggleCleanModalBtn.html(modalCleanMode ? '<i class="fa-solid fa-comments"></i> 💬 Показать с текстом' : '<i class="fa-solid fa-eye-slash"></i> 👁 Показать без текста');
            modalImgs.forEach(item => {
                const targetSrc = (modalCleanMode && item.cleanUrl) ? item.cleanUrl : item.letteredUrl;
                item.im.attr('src', targetSrc);
            });
        };
        toggleCleanModalBtn.on('click', () => {
            modalCleanMode = !modalCleanMode;
            updateModalCleanUi();
        });
        dlBar.append(toggleCleanModalBtn);
        setTimeout(updateModalCleanUi, 0);
    }
    el.append(dlBar);
    urls.forEach((u, idx) => {
        const pageCard = $('<div style="width:100%; max-width:680px; text-align:center;"></div>');
        const pMeta = sceneMeta?.pageMetaMap?.[u];
        const cleanU = getCleanUrlForManhwaPage(sceneMeta, u);
        const initSrc = (modalCleanMode && cleanU) ? cleanU : u;
        const chBadge = (pMeta?.comicOpts?.chunkTotal > 1) ? ` · Кусочек #${(Number(pMeta.comicOpts.chunkIndex) || 0) + 1} из ${pMeta.comicOpts.chunkTotal}` : '';
        pageCard.append($('<div style="font-size:0.8em; font-weight:700; opacity:0.8; margin-bottom:4px;"></div>').text(`Страница ${idx + 1} из ${urls.length}${chBadge}`));
        const im = $('<img alt="" style="width:100%; height:auto; border-radius:10px; box-shadow:0 4px 18px rgba(0,0,0,0.35); cursor:pointer;">').attr('src', initSrc).on('click', function () { window.open($(this).attr('src') || u, '_blank'); });
        modalImgs.push({ im, letteredUrl: u, cleanUrl: cleanU });
        pageCard.append(im);
        stripWrap.append(pageCard);
    });
    el.append(stripWrap);
    await openPopup(el, true);
}

// Окно выбора открываем, когда картинка уже готова (или не получилась)
const presentWaiting = { looks: null, accents: null, gacha: null };
function openWhenReady(kind, openFn) {
    const a = activeOf(kind);
    const [field, failField] = PIC_FIELDS[kind];
    const needsPic = wantImages() && a && (kind !== 'accents' || (a.accents || []).length);
    if (!needsPic || a[field] || a[failField]) return openFn();
    if (presentWaiting[kind]) return; // уже ждём — окно откроется само
    const msg = { looks: 'Рисую образы… Окно выбора откроется само, а пока можно читать чат.', accents: 'Рисую штрихи… Окно откроется само.', gacha: 'Раскладываю находки на прилавке… Окно откроется само.' }[kind];
    presentWaiting[kind] = toastr.info(msg, kind === 'gacha' ? '🎰 Находки' : '🎨 Гардероб', { timeOut: 0, extendedTimeOut: 0, tapToDismiss: false });
    ensurePicture(kind, false, () => {
        try { toastr.clear(presentWaiting[kind]); } catch (e) { /* ignore */ }
        presentWaiting[kind] = null;
        openFn();
    });
}
const presentLooks = () => openWhenReady('looks', showWardrobePopup);
const presentAccents = () => openWhenReady('accents', showAccentPopup);

// Общий визуальный выбор: картинка с зонами, кнопки с названиями, свёрнутые описания
// Находим на общей картинке, где стоит каждая фигура/предмет: делим на N колонок и в каждой
// ищем область, заметно отличную от фона. Возвращает [{x,y,w,h}] в долях картинки.
const cropCache = new Map();
function smartCrops(url, n, kind, layout) {
    const rowsN = layout?.rows || 1, colsN = layout?.cols || n;
    const key = `${url}|${n}|${kind}|${rowsN}x${colsN}`;
    if (cropCache.has(key)) return cropCache.get(key);
    if (typeof Image !== 'function') return Promise.resolve([]);
    const job = new Promise(resolve => {
        const img = new Image();
        img.onload = () => {
            try {
                const W = 240, H = Math.max(1, Math.round(240 * img.naturalHeight / img.naturalWidth));
                const cv = document.createElement('canvas');
                cv.width = W; cv.height = H;
                const g = cv.getContext('2d', { willReadFrequently: true });
                g.drawImage(img, 0, 0, W, H);
                const d = g.getImageData(0, 0, W, H).data;
                // цвет фона — по углам
                const px = (x, y) => { const i = (y * W + x) * 4; return [d[i], d[i + 1], d[i + 2]]; };
                // фон оцениваем построчно по левому и правому краю: у фото он часто плавно меняется сверху вниз
                const mx = Math.max(1, Math.round(W * 0.03));
                const rowBg = [];
                for (let y = 0; y < H; y++) {
                    const pts = [];
                    for (let x = mx; x < mx + 4; x++) pts.push(px(x, y));
                    for (let x = W - mx - 4; x < W - mx; x++) pts.push(px(x, y));
                    rowBg.push([0, 1, 2].map(k => pts.reduce((s2, c) => s2 + c[k], 0) / pts.length));
                }
                const isFg = (x, y) => { const c = px(x, y), b = rowBg[y]; return Math.abs(c[0] - b[0]) + Math.abs(c[1] - b[1]) + Math.abs(c[2] - b[2]) > 70; };
                const mid = rowBg[Math.floor(H / 2)] || [244, 241, 238];
                const bg = `rgb(${mid.map(v => Math.round(v)).join(',')})`;
                // предметы в ряд: художник редко ставит их ровно по третям — ищем каждый предмет по пустым промежуткам
                if (kind !== 'looks' && rowsN === 1) {
                    const segs = itemSegments(W, H, isFg, n);
                    if (segs) { segs.bg = bg; resolve(segs); return; }
                }
                const out = [];
                for (let i = 0; i < n; i++) {
                    const r = Math.floor(i / colsN), c = i % colsN;
                    const x0 = Math.floor(c * W / colsN), x1 = Math.floor((c + 1) * W / colsN);
                    const y0 = Math.floor(r * H / rowsN), y1 = Math.floor((r + 1) * H / rowsN);
                    const colW = x1 - x0, cellH = y1 - y0;
                    // плотность «не фона» по строкам и столбцам ячейки — шум и тени не считаем
                    const rows = new Array(cellH).fill(0), cols = new Array(colW).fill(0);
                    for (let y = y0; y < y1; y++) for (let x = x0; x < x1; x++) if (isFg(x, y)) { rows[y - y0]++; cols[x - x0]++; }
                    const rowsOk = rows.map(v => v > colW * 0.04), colsOk = cols.map(v => v > cellH * 0.03);
                    let minY = rowsOk.indexOf(true), maxY = rowsOk.lastIndexOf(true);
                    let minX = colsOk.indexOf(true), maxX = colsOk.lastIndexOf(true);
                    if (minY < 0 || minX < 0) { out.push(null); continue; }
                    minX += x0; maxX += x0; minY += y0; maxY += y0;
                    const pad = 0.08;
                    let w = (maxX - minX) * (1 + pad * 2), h = (maxY - minY) * (1 + pad * 2);
                    const cx = (minX + maxX) / 2, cy = (minY + maxY) / 2;
                    const target = kind === 'looks' ? (rowsN === 2 ? 2 / 3 : 0.5) : 1;
                    if (w / h < target) w = Math.min(colW * 0.88, h * target);
                    if (w / h > target) h = Math.min(cellH * 0.88, w / target);
                    w = Math.min(w, colW * 0.88); h = Math.min(h, cellH * 0.88);
                    const safePadX = colW * 0.06, safePadY = cellH * 0.06;
                    const x = Math.max(x0 + safePadX, Math.min(x1 - safePadX - w, cx - w / 2));
                    const y = Math.max(y0 + safePadY, Math.min(y1 - safePadY - h, cy - h / 2));
                    out.push({ x: x / W, y: y / H, w: w / W, h: h / H });
                }
                out.bg = bg;
                resolve(out);
            } catch (e) {
                resolve([]); // картинка с другого сайта без разрешения — режем поровну
            }
        };
        img.onerror = () => resolve([]);
        img.crossOrigin = 'anonymous';
        img.src = url;
    });
    cropCache.set(key, job);
    return job;
}
// Делим полосу с предметами на n кусков по пустым промежуткам между ними; null — если не вышло
function itemSegments(W, H, isFg, n) {
    const colCnt = new Array(W).fill(0);
    for (let x = 0; x < W; x++) for (let y = 0; y < H; y++) if (isFg(x, y)) colCnt[x]++;
    const peak = Math.max(...colCnt);
    const on = colCnt.map(v => v > Math.max(H * 0.015, peak * 0.08)); // фон с виньеткой тоже даёт немного «не фона» — считаем от самого плотного столбца
    let runs = [];
    for (let x = 0; x < W; x++) {
        if (!on[x]) continue;
        const last = runs[runs.length - 1];
        if (last && x - last.x1 <= Math.max(2, W * 0.015)) last.x1 = x; else runs.push({ x0: x, x1: x });
    }
    runs.forEach(r => { r.mass = colCnt.slice(r.x0, r.x1 + 1).reduce((a, b) => a + b, 0); });
    runs = runs.filter(r => r.mass > H * 2); // соринки и тени не считаем
    if (!runs.length) return null;
    // предметы слиплись — режем самый широкий кусок по самому «пустому» месту в его середине
    while (runs.length < n) {
        const wi = runs.reduce((b, r, i) => (r.x1 - r.x0 > runs[b].x1 - runs[b].x0 ? i : b), 0);
        const r = runs[wi];
        if (r.x1 - r.x0 < W * 0.12) return null;
        const a0 = Math.round(r.x0 + (r.x1 - r.x0) * 0.2), a1 = Math.round(r.x1 - (r.x1 - r.x0) * 0.2);
        let cut = a0;
        for (let x = a0; x <= a1; x++) if (colCnt[x] < colCnt[cut]) cut = x;
        const m = (x0, x1) => colCnt.slice(x0, x1 + 1).reduce((a, b) => a + b, 0);
        runs.splice(wi, 1, { x0: r.x0, x1: cut - 1, mass: m(r.x0, cut - 1) }, { x0: cut + 1, x1: r.x1, mass: m(cut + 1, r.x1) });
    }
    // если кусков больше — склеиваем ближайшие соседние, пока не останется n
    while (runs.length > n) {
        let best = 0, gap = Infinity;
        for (let i = 0; i < runs.length - 1; i++) { const g = runs[i + 1].x0 - runs[i].x1; if (g < gap) { gap = g; best = i; } }
        const a = runs[best], b = runs[best + 1];
        runs.splice(best, 2, { x0: a.x0, x1: b.x1, mass: a.mass + b.mass });
    }
    const out = [];
    for (let i = 0; i < n; i++) {
        const r = runs[i];
        const left = i ? Math.ceil((runs[i - 1].x1 + r.x0) / 2) : 0;
        const right = i < n - 1 ? Math.floor((r.x1 + runs[i + 1].x0) / 2) : W - 1;
        let minY = H, maxY = -1;
        for (let y = 0; y < H; y++) {
            let c = 0;
            for (let x = r.x0; x <= r.x1; x++) if (isFg(x, y)) c++;
            if (c > (r.x1 - r.x0 + 1) * 0.04) { if (y < minY) minY = y; maxY = y; }
        }
        if (maxY < 0) return null;
        const cx = (r.x0 + r.x1) / 2, cy = (minY + maxY) / 2;
        const padX = Math.round((right - left) * 0.06);
        const safeLeft = left + padX, safeRight = right - padX;
        const h = Math.min(H * 0.9, Math.max(r.x1 - r.x0, maxY - minY) * 1.2);
        const w = Math.min(safeRight - safeLeft, Math.max(h, (r.x1 - r.x0) * 1.15));
        const x = Math.max(safeLeft, Math.min(safeRight - w, cx - w / 2));
        const y = Math.max(0, Math.min(H - h, cy - h / 2));
        out.push({ x: x / W, y: y / H, w: w / W, h: h / H });
    }
    return out;
}

function applyCrop(el, url, box, imgRatio) {
    if (el.hasClass('nnb-card-img')) {
        let inner = el.children('.nnb-card-crop');
        if (!inner.length) inner = $('<div class="nnb-card-crop"></div>').appendTo(el);
        el = inner;
    }
    const bw = Math.max(0.01, Math.min(1, box.w));
    const bh = Math.max(0.01, Math.min(1, box.h));
    const posX = bw >= 1 ? 50 : Math.max(0, Math.min(1, box.x / (1 - bw))) * 100;
    const posY = bh >= 1 ? 50 : Math.max(0, Math.min(1, box.y / (1 - bh))) * 100;
    el.css({
        'background-image': `url("${String(url).replace(/"/g, '%22')}")`,
        'background-size': `${100 / bw}% ${100 / bh}%`,
        'background-position': `${posX}% ${posY}%`,
        'aspect-ratio': `${(bw * imgRatio) / bh}`,
    });
}

// Общая картинка нарезается на карточки: в каждой своя фигура или предмет и название
function visualPicker({ kind, items, title, label, onPick, field, failField, a, cardClass }) {
    const box = $('<div class="nnb-visual"></div>');
    const n = Math.min(items.length, kind === 'gacha' ? 3 : 5);
    const layoutOf = () => a[field + 'Layout'] || (kind === 'accents' ? accentsLayout(n) : { rows: 1, cols: n });
    const cell = i => {
        const L = layoutOf();
        const r = Math.floor(i / L.cols), c = i % L.cols;
        const colW = 1 / L.cols, rowH = 1 / L.rows;
        const padX = colW * 0.08, padY = rowH * 0.08;
        return {
            x: c * colW + padX,
            y: r * rowH + padY,
            w: colW - padX * 2,
            h: rowH - padY * 2
        };
    };
    const render = url => {
        box.empty();
        const head = $('<div class="nnb-visual-tools" style="display:flex; align-items:center; gap:6px; flex-wrap:wrap;"></div>');
        const histList = Array.isArray(a[field + 'History']) && a[field + 'History'].length
            ? a[field + 'History']
            : (url ? [{ url, layout: a[field + 'Layout'] }] : []);
        let curHistIdx = histList.findIndex(h => h.url === url);
        if (curHistIdx < 0) curHistIdx = histList.length - 1;
        const isLastHist = curHistIdx >= histList.length - 1;

        if (url) {
            const prevVarBtn = $(`<div class="menu_button" style="padding:2px 8px; font-size:0.8em; margin:0; ${curHistIdx <= 0 ? 'opacity:0.35; pointer-events:none;' : ''}" title="Предыдущий сгенерированный вариант (◀)"><i class="fa-solid fa-chevron-left"></i></div>`).on('click', () => {
                if (curHistIdx <= 0) return;
                const prevEntry = histList[curHistIdx - 1];
                a[field] = prevEntry.url;
                if (prevEntry.layout) a[field + 'Layout'] = prevEntry.layout;
                ctx().saveMetadata();
                render(prevEntry.url);
            });
            const nextVarBtn = $(`<div class="menu_button ${isLastHist ? 'nnb-btn-primary' : ''}" style="padding:2px 9px; font-size:0.8em; margin:0;" title="${isLastHist ? 'Сделать ещё одну генерацию по тому же промпту (▶)' : 'Следующий вариант (▶)'}"><i class="fa-solid fa-chevron-right"></i>${isLastHist ? ' + Ещё' : ''}</div>`).on('click', () => {
                if (!isLastHist) {
                    const nextEntry = histList[curHistIdx + 1];
                    a[field] = nextEntry.url;
                    if (nextEntry.layout) a[field + 'Layout'] = nextEntry.layout;
                    ctx().saveMetadata();
                    render(nextEntry.url);
                } else {
                    wait();
                    ensurePicture(kind, !drawingKind[kind], render);
                }
            });
            head.append(prevVarBtn);
            histList.forEach((hEntry, hIdx) => {
                const vBtn = $(`<div class="menu_button" style="padding:2px 8px; font-size:0.78em; margin:0; ${hEntry.url === url ? 'border-color:var(--SmartThemeQuoteColor, #8b78c4); font-weight:700;' : 'opacity:0.75;'}">Вариант ${hIdx + 1}</div>`).on('click', () => {
                    a[field] = hEntry.url;
                    if (hEntry.layout) a[field + 'Layout'] = hEntry.layout;
                    ctx().saveMetadata();
                    render(hEntry.url);
                });
                head.append(vBtn);
            });
            head.append(nextVarBtn);
        }
        const redraw = $('<div class="nnb-icon-btn fa-solid fa-palette" title="Перерисовать по тому же промпту (предыдущая картинка тоже сохранится!)" tabindex="0"></div>').on('click', () => { wait(); ensurePicture(kind, !drawingKind[kind], render); });
        head.append(redraw);
        if (url) head.append($('<div class="nnb-icon-btn fa-solid fa-up-right-and-down-left-from-center" title="Во весь экран" tabindex="0"></div>').on('click', () => window.open(url, '_blank')));
        box.append(head);
        const grid = $(`<div class="nnb-cards nnb-cards-${kind}${url ? ' nnb-carousel' : ' nnb-cards-text'}${layoutOf().rows === 2 ? ' nnb-grid22' : ''}"></div>`);
        const imgs = [];
        const activeHistEntry = histList.find(h => h.url === url);
        const indivList = activeHistEntry?.individualImages
            || (kind === 'gacha' ? a.individualGachaImages : kind === 'accents' ? a.individualAccentImages : a.individualImages);
        items.forEach((it, i) => {
            const card = $('<div class="nnb-card-pick" tabindex="0"><div class="nnb-card-body"><div class="nnb-card-kind"></div><div class="nnb-card-title"></div></div></div>');
            if (cardClass) card.addClass(cardClass(it));
            const singleItemUrl = (Array.isArray(indivList) && indivList[i]) ? indivList[i] : ((it.isSingleImage && it.image) ? it.image : null);
            if (singleItemUrl) {
                const img = $('<div class="nnb-card-img"></div>');
                applyCrop(img, singleItemUrl, { x: 0, y: 0, w: 1, h: 1 }, 1);
                card.prepend(img);
            } else if (url && i < n) {
                const img = $('<div class="nnb-card-img"></div>');
                // пока ищем фигуру — режем поровну
                applyCrop(img, url, cell(i), layoutOf().rows === 2 ? 2 / 3 : 1.5);
                card.prepend(img);
                imgs.push(img);
            }
            const kindText = label ? label(it) : '';
            if (kindText) card.find('.nnb-card-kind').text(kindText); else card.find('.nnb-card-kind').remove();
            card.find('.nnb-card-title').text(title(it));
            if (it.desc) card.find('.nnb-card-body').append($('<div class="nnb-card-desc"></div>').text(it.desc));
            card.on('click', () => onPick(i));
            grid.append(card);
        });
        box.append(grid);
        // карусель: по одной карточке на экран, листаем пальцем или кнопками ◀ ▶; точки внизу показывают, где мы
        if (url && items.length > 1) {
            const navWrap = $('<div style="display:flex; align-items:center; justify-content:center; gap:12px; margin:8px 0 4px;"></div>');
            const prevBtn = $('<div class="menu_button" style="padding:4px 10px; font-size:0.85em;"><i class="fa-solid fa-chevron-left"></i></div>');
            const nextBtn = $('<div class="menu_button" style="padding:4px 10px; font-size:0.85em;"><i class="fa-solid fa-chevron-right"></i></div>');
            const dots = $('<div class="nnb-dots" style="margin:0;"></div>');
            const goToIdx = idx => {
                const el = grid[0];
                if (!el) return;
                const clamped = Math.max(0, Math.min(items.length - 1, idx));
                el.scrollTo?.({ left: clamped * el.clientWidth, behavior: 'smooth' });
            };
            const curIdx = () => {
                const el = grid[0];
                return (el && el.clientWidth) ? Math.round(el.scrollLeft / el.clientWidth) : 0;
            };
            prevBtn.on('click', e => { e.stopPropagation(); goToIdx(curIdx() - 1); });
            nextBtn.on('click', e => { e.stopPropagation(); goToIdx(curIdx() + 1); });
            items.forEach((_, i) => dots.append($('<span tabindex="0"></span>').on('click', () => goToIdx(i))));
            const mark = () => {
                const i = curIdx();
                dots.children().each((j, d) => $(d).toggleClass('active', j === i));
                prevBtn.css('opacity', i <= 0 ? 0.35 : 1);
                nextBtn.css('opacity', i >= items.length - 1 ? 0.35 : 1);
            };
            grid.on('scroll', mark);
            mark();
            navWrap.append(prevBtn, dots, nextBtn);
            box.append(navWrap);
        }
        if (url && imgs.length && typeof Image === 'function') {
            const probe = new Image();
            probe.onload = async () => {
                const ratio = probe.naturalWidth / probe.naturalHeight || 1.5;
                const crops = await smartCrops(url, n, kind, layoutOf());
                imgs.forEach((el, i) => { applyCrop(el, url, crops[i] || cell(i), ratio); if (crops.bg) el.css('background-color', crops.bg); });
            };
            probe.src = url;
        }
    };
    const wait = () => box.html('').append($('<div class="nnb-pop-sub nnb-wait"></div>').text(`🎨 Рисую через ${imageSourceName()}… обычно до пары минут`));
    if (a[field]) render(a[field]);
    else if (a[failField] && !drawingKind[kind]) render('');
    else { wait(); ensurePicture(kind, false, render); }
    return box;
}

function parseLooks(raw) {
    const looks = [];
    const accents = [];
    let appearance = '';
    let last = null;
    for (const line of answerLines(raw)) {
        let m = line.match(/^APPEARANCE\s*[:：—–-]\s*(.+)$/i);
        if (m) { appearance = m[1].trim().replace(/\]$/, '').trim(); continue; }
        m = line.match(/^EN\s*[:：—–-]\s*(.+)$/i);
        if (m) { if (last) last.en = m[1].trim().replace(/\]$/, ''); continue; }
        m = line.match(/^LOOK\s*\d*\s*[:：—–-]\s*(.+)$/i);
        if (m) {
            const parts = m[1].split('|').map(x => x.trim());
            let category = 'Повседневный';
            let title = '';
            let desc = '';
            if (parts.length >= 3 && /^(повседнев|рабоч|учеб|на выход|вечер|домаш|по погоде|улич|спорт|актив)/i.test(parts[0])) {
                category = normalizeClosetCat(parts[0]);
                title = parts[1].replace(/^[«"]|[»"]$/g, '');
                desc = parts.slice(2).join(' | ').trim();
            } else {
                title = (parts[0] || '').replace(/^[«"]|[»"]$/g, '');
                desc = parts.slice(1).join(' | ').trim();
            }
            last = { category, title, desc, effects: '' };
            looks.push(last);
            continue;
        }
        m = line.match(/^ACCENT\s*\d*\s*[:：—–-]\s*(.+)$/i);
        if (m) {
            const parts = m[1].split('|').map(x => x.trim());
            const kind = accentKind(parts[0]);
            const title = (parts.length >= 3 ? parts[1] : parts[0]).replace(/^[«"]|[»"]$/g, '');
            const desc = parts.length >= 3 ? parts.slice(2).join(' | ') : (parts[1] || '');
            last = { kind, title, desc: desc.replace(/\]$/, ''), effects: '' };
            if (title) accents.push(last);
            continue;
        }
        m = line.match(/^EFFECTS?\s*[:：—–-]\s*(.+)$/i);
        if (m && last) last.effects = m[1].trim().replace(/\]$/, '');
    }
    const out = looks.filter(l => l.title);
    out.appearance = appearance;
    out.accents = accents;
    return out;
}

async function generateOutfits(st, occasion, exclude = []) {
    const raw = await quietGenerate(wardrobePrompt(st, occasion, exclude));
    st.lastRaw = String(raw ?? '');
    const looks = parseLooks(raw);
    if (looks.length < 2) {
        toastr.warning('Модель не предложила образы по формату — загляни в «Последний ответ модели»', 'Блокнот рассказчика');
        return false;
    }
    const bestApp = st.wardrobe.customAppearanceEn || looks.appearance || st.wardrobe.appearance || '';
    if (bestApp) st.wardrobe.appearance = bestApp;
    st.wardrobe.active = { occasion: occasion || '', options: looks.slice(0, 5), appearance: bestApp, accents: looks.accents || [], status: 'choosing', at: ctx().chat.length, date: st.time.date || '' };
    return true;
}

async function promptGenerateNewOutfits(defaultOccasion = '') {
    const st = store();
    if (!st) return toastr.warning('Сначала открой чат', 'Блокнот рассказчика');
    const occasion = await askText('Под какой повод или сезон сгенерировать 5 новых образов? (Оставь пустым — модель поймёт по текущей сцене)', defaultOccasion);
    if (occasion === null) return;
    st.wardrobe.active = null;
    const ok = await withBusy('👗 Модель придумывает 5 новых образов…', s2 => generateOutfits(s2, occasion.trim()));
    if (ok) presentLooks();
}

async function wearFromCloset(item, occasion = '', skipAccentPrompt = false) {
    const st = store();
    if (!st || !item) return;
    const prevAccents = getActiveAccents(st);
    st.wardrobe.active = {
        occasion: occasion || item.category || 'Из шкафа',
        look: {
            title: item.title,
            desc: item.desc,
            en: item.en || '',
            effects: item.effects || '',
            category: item.category,
            image: item.image || '',
            crop: item.crop || null,
            imageLayout: item.imageLayout || null,
            isSingleImage: !!item.isSingleImage,
        },
        options: [item],
        accents: [],
        selectedAccents: prevAccents,
        accent: prevAccents[0] || null,
        status: 'worn',
        at: ctx().chat.length,
        date: st.time.date || '',
    };
    await commit();
    if (!skipAccentPrompt && accentsOn(st) && wearableBox(st).length && !prevAccents.length) {
        presentAccents();
        return;
    }
    toastr.success(`Надет образ «${escapeHtml(item.title)}» (${escapeHtml(item.category || 'Из шкафа')}).`, '👗 Гардероб', { escapeHtml: false });
    await checkPendingTravel();
}

// Рисуем пакетно картинки для нарядов в шкафу, духов и аксессуаров
async function drawClosetSheetBatch(st, items) {
    if (!items.length) return false;
    const batch = items.slice(0, 5);
    const n = batch.length;
    const who = settings().imageSource === 'novelai'
        ? await ensureHeroineAppearanceEnForNai(st)
        : getHeroineAppearanceEn(st);

    if (settings().imageSource === 'novelai') {
        let drawnAny = false;
        for (let i = 0; i < n; i++) {
            const it = batch[i];
            setStatus(`🎨 NovelAI рисует наряд для шкафа ${i + 1} из ${n} («${it.title}»)…`);
            const singlePrompt = buildSingleOutfitPromptForNai(who, it);
            const singleUrl = await drawViaNovelAi(singlePrompt, 'portrait', { extraNeg: 'blush, blushing, nose blush, full-face blush, heavy blush, embarrassed, shy, flustered, timid, awkward smile' });
            if (!singleUrl) continue;
            drawnAny = true;
            it.image = singleUrl;
            it.imageLayout = { rows: 1, cols: 1 };
            it.crop = { x: 0, y: 0, w: 1, h: 1 };
            it.isSingleImage = true;
            if (st.wardrobe?.active?.look?.title === it.title) {
                st.wardrobe.active.look.image = singleUrl;
                st.wardrobe.active.look.imageLayout = { rows: 1, cols: 1 };
                st.wardrobe.active.look.crop = { x: 0, y: 0, w: 1, h: 1 };
                st.wardrobe.active.look.isSingleImage = true;
            }
        }
        return drawnAny;
    }

    const layout = { rows: 1, cols: n };
    const pos = ['first', 'second', 'third', 'fourth', 'fifth'];
    const common = 'full body, standing, plain light background, the same face, hair and body in every figure, evenly spaced side by side, not overlapping';
    const prompt = cleanForCommand(`character outfit sheet, the same ${who} shown ${n} times side by side in a single row, each figure centered in its own equal column of the image, ${common}, ` +
        batch.map((o, i) => `${pos[i]} from the left wearing ${o.en || o.desc || o.title}`).join('; ') + ', no text, no captions');
    let refs = null;
    if (settings().imageRef && settings().naiCharRefMode !== 'off') {
        const me = await personaAvatarDataUrl();
        if (me) {
            refs = { images: [me], note: 'The input picture is the reference: keep exactly this character — the same face, hair, eyes and body — and only change the clothes.' };
        }
    }
    const url = await drawPicture(prompt, refs, 'landscape');
    if (!url) return false;
    let crops = [];
    try { crops = await smartCrops(url, n, 'looks', layout); } catch (e) { crops = []; }
    batch.forEach((it, i) => {
        const fallback = { x: i / n + 0.01, y: 0.04, w: 1 / n - 0.02, h: 0.92 };
        it.image = url;
        it.imageLayout = layout;
        it.crop = crops[i] || fallback;
        if (st.wardrobe?.active?.look?.title === it.title) {
            st.wardrobe.active.look.image = url;
            st.wardrobe.active.look.imageLayout = layout;
            st.wardrobe.active.look.crop = it.crop;
        }
    });
    return true;
}

async function drawBoxItemsSheetBatch(st, items, kindGroup = 'perfume') {
    if (!items.length) return false;
    const batch = items.slice(0, 5);
    const n = batch.length;
    if (settings().imageSource === 'novelai') {
        let drawnAny = false;
        for (let i = 0; i < n; i++) {
            const x = batch[i];
            setStatus(`🎨 NovelAI рисует предмет ${i + 1} из ${n} («${x.title}»)…`);
            const itemDesc = x.en || x.desc || x.title;
            const singlePrompt = cleanForCommand(`1item, solo, ${ITEM_STYLE}, solid plain light cream background, centered ${kindGroup === 'perfume' ? 'luxury glass perfume bottle' : 'object or accessory'}: ${itemDesc}, no people, no hands, no text, no captions`);
            const singleUrl = await drawViaNovelAi(singlePrompt, 'square', null);
            if (!singleUrl) continue;
            drawnAny = true;
            x.image = singleUrl;
            x.imageLayout = { rows: 1, cols: 1 };
            x.crop = { x: 0, y: 0, w: 1, h: 1 };
            x.isSingleImage = true;
        }
        return drawnAny;
    }
    const layout = { rows: 1, cols: n };
    const pos = ['first', 'second', 'third', 'fourth', 'fifth'];
    const groupDesc = kindGroup === 'perfume' ? 'luxury glass perfume bottles' : 'stylish vintage items, accessories and curiosities';
    const prompt = n === 1
        ? cleanForCommand(`${ITEM_STYLE}, a single centered ${kindGroup === 'perfume' ? 'luxury glass perfume bottle' : 'object or accessory'} on a solid plain light cream background: ${batch[0].en || batch[0].desc || batch[0].title}, no people, no hands, no text, no captions`)
        : cleanForCommand(`${ITEM_STYLE}, ${n} separate ${groupDesc} in a single horizontal row, evenly spaced, each item small and centered in its own equal column of the image with wide empty space between items, nothing overlapping, solid plain light cream background, ` +
            batch.map((x, i) => `${pos[i]} from the left: ${x.en || x.desc || x.title}`).join('; ') + ', no people, no hands, no text, no captions');
    const url = await drawPicture(prompt, null, n === 1 ? 'square' : 'landscape');
    if (!url) return false;
    let crops = [];
    if (n > 1) {
        try { crops = await smartCrops(url, n, 'gacha', layout); } catch (e) { crops = []; }
    }
    batch.forEach((x, i) => {
        const fallback = n === 1
            ? { x: 0.04, y: 0.04, w: 0.92, h: 0.92 }
            : { x: i / n + 0.02, y: 0.08, w: 1 / n - 0.04, h: 0.84 };
        x.image = url;
        x.imageLayout = layout;
        x.crop = crops[i] || fallback;
        (st.wardrobe?.active?.selectedAccents || []).forEach(ac => {
            if (ac.title.toLowerCase() === x.title.toLowerCase()) {
                ac.image = url;
                ac.crop = x.crop;
                ac.imageLayout = x.imageLayout;
                ac.isSingleImage = !!x.isSingleImage;
            }
        });
    });
    return true;
}

async function drawWorldStarterVisuals(st, forceAll = false) {
    if (!canDrawScene()) {
        toastr.warning('Чтобы рисовать картинки гардероба и штрихов, выбери источник картинок в настройках «🎨 Картинки».', '🎨 Картинки');
        return false;
    }
    let anyDrawn = false;
    const closetNeed = (st.wardrobe?.closet || []).filter(c => forceAll || !c.image).slice(0, 5);
    if (closetNeed.length) {
        setStatus('🎨 Рисуем 5 сезонных нарядов в шкаф…');
        try {
            if (await drawClosetSheetBatch(st, closetNeed)) anyDrawn = true;
        } catch (e) {
            console.warn('[npc_notebook] closet sheet draw error:', e);
            toastr.warning(`Наряды нарисовать не вышло: ${escapeHtml(e?.message || e)}`, '🎨 Гардероб', { escapeHtml: false });
        }
    }
    const perfumesNeed = personalBoxItems(st).filter(x => x.kind === 'perfume' && (forceAll || !x.image)).slice(0, 5);
    if (perfumesNeed.length) {
        setStatus('🌸 Рисуем 5 флаконов духов…');
        try {
            if (await drawBoxItemsSheetBatch(st, perfumesNeed, 'perfume')) anyDrawn = true;
        } catch (e) {
            console.warn('[npc_notebook] perfumes sheet draw error:', e);
            toastr.warning(`Духи нарисовать не вышло: ${escapeHtml(e?.message || e)}`, '🌸 Духи', { escapeHtml: false });
        }
    }
    const accNeed = personalBoxItems(st).filter(x => x.kind !== 'perfume' && (forceAll || !x.image)).slice(0, 5);
    if (accNeed.length) {
        setStatus('💍 Рисуем 5 аксессуаров…');
        try {
            if (await drawBoxItemsSheetBatch(st, accNeed, 'accessory')) anyDrawn = true;
        } catch (e) {
            console.warn('[npc_notebook] accessories sheet draw error:', e);
            toastr.warning(`Аксессуары нарисовать не вышло: ${escapeHtml(e?.message || e)}`, '💍 Аксессуары', { escapeHtml: false });
        }
    }
    const trendsNeed = (st.trends || []).filter(t => forceAll || !t.image).slice(0, 4);
    if (trendsNeed.length) {
        setStatus('🔥 Рисуем картинки для трендов сезона…');
        try {
            if (await drawTrendsSheetBatch(st, trendsNeed)) anyDrawn = true;
        } catch (e) {
            console.warn('[npc_notebook] trends sheet draw error:', e);
        }
    }
    await ctx().saveMetadata();
    return anyDrawn;
}

async function runDrawStarterVisuals(forceAll = false) {
    await withBusy('🎨 Рисуем картинки нарядов, духов и аксессуаров…', async s2 => {
        const ok = await drawWorldStarterVisuals(s2, forceAll);
        if (ok) toastr.success('Картинки гардероба, духов и аксессуаров готовы!', '🎨 Гардероб');
    });
    renderDirection();
}

function renderReadyAccentsBlock(st, onRefresh) {
    const wrap = $('<div style="margin-top:10px;"></div>');
    const perfumes = personalBoxItems(st).filter(x => x.kind === 'perfume');
    const accessories = personalBoxItems(st).filter(x => x.kind !== 'perfume');

    const activeAccs = getActiveAccents(st);
    const isAccActive = x => activeAccs.some(a => a.title.toLowerCase() === x.title.toLowerCase());

    const buildAccentGrid = (title, list, emptyHint, stateKey, kindDefault) => {
        const isOpen = st[stateKey] !== undefined ? !!st[stateKey] : true;
        const sec = $(`<details ${isOpen ? 'open' : ''} class="nnb-section" style="margin-top:8px;"><summary></summary></details>`);
        const activeInGroup = list.filter(isAccActive).map(x => x.title);
        const summarySuffix = activeInGroup.length ? ` · надето: ${activeInGroup.join(', ')}` : ' — нажми на карточку, чтобы надеть или сменить';
        sec.find('summary').text(`${title} (${list.length})${summarySuffix}`);
        sec.on('toggle', function () {
            st[stateKey] = this.open;
        });
        if (!list.length) {
            sec.append($('<div class="nnb-empty" style="margin-top:6px;"></div>').text(emptyHint));
        } else {
            const grid = $('<div style="display:grid; grid-template-columns:repeat(auto-fill, minmax(200px, 1fr)); gap:8px; margin-top:6px;"></div>');
            list.forEach(x => {
                const active = isAccActive(x);
                const card = $('<div class="nnb-note" style="display:flex; gap:8px; align-items:center; cursor:pointer; margin:0; padding:8px; transition:all 0.15s ease;"></div>');
                if (active) {
                    card.css({
                        'border': '2px solid var(--SmartThemeQuoteColor, #8b78c4)',
                        'background': 'color-mix(in srgb, var(--SmartThemeQuoteColor, #8b78c4) 16%, transparent)',
                    });
                }
                if (x.image) {
                    card.append(findThumb(x, '56px').css('flex-shrink', '0'));
                }
                const info = $('<div style="flex:1; min-width:0;"></div>');
                info.append($('<div style="font-weight:600; font-size:0.91em; line-height:1.25;"></div>').text(`${x.title}${active ? ' ✓ (надето)' : ''}`));
                if (x.desc) info.append($('<div class="nnb-npc-status" style="font-size:0.8em; margin-top:2px;"></div>').text(x.desc));
                card.append(info);

                const acts = $('<div class="nnb-actions" style="flex-direction:column; gap:4px; flex-shrink:0;"></div>');
                const editIcon = $('<i class="fa-solid fa-pen" title="Изменить"></i>').on('click', async e => {
                    e.stopPropagation();
                    const t = await askText('Название', x.title);
                    if (t === null) return;
                    const d = await askText('Описание', x.desc || '');
                    if (d === null) return;
                    if (t.trim()) x.title = t.trim();
                    x.desc = d.trim();
                    await commit();
                    if (onRefresh) onRefresh();
                });
                const delIcon = $('<i class="fa-solid fa-trash" title="Удалить"></i>').on('click', async e => {
                    e.stopPropagation();
                    st.wardrobe.box = (st.wardrobe.box || []).filter(y => y !== x);
                    await commit();
                    if (onRefresh) onRefresh();
                });
                acts.append(editIcon, delIcon);
                card.append(acts);

                card.on('click', async e => {
                    e.stopPropagation();
                    await toggleClosetAccent(st, x);
                    if (onRefresh) onRefresh();
                });
                grid.append(card);
            });
            sec.append(grid);
        }

        const btnRow = $('<div class="nnb-buttons" style="margin-top:6px;"></div>');
        const addBtn = $(`<div class="menu_button" style="padding:3px 9px; font-size:0.83em;"><i class="fa-solid fa-plus"></i> Добавить ${kindDefault === 'perfume' ? 'духи' : 'аксессуар'}</div>`).on('click', async () => {
            const t = await askText(kindDefault === 'perfume' ? 'Название духов (например «Вечерний бергамот и ваниль»)' : 'Название аксессуара (например «Серебряные серьги-капли»)');
            if (!t || !t.trim()) return;
            const d = await askText('Краткое описание (можно оставить пустым)');
            if (d === null) return;
            st.wardrobe.box.push({
                id: st.wardrobe.nextItemId++,
                kind: kindDefault,
                title: t.trim(),
                desc: d.trim(),
                origin: 'гардероб',
                onCounter: false,
                at: ctx().chat?.length ?? 0,
            });
            await commit();
            if (onRefresh) onRefresh();
        });
        btnRow.append(addBtn);
        if (!perfumes.length && !accessories.length) {
            const genBtn = $('<div class="menu_button nnb-btn-primary" style="padding:3px 9px; font-size:0.83em;"><i class="fa-solid fa-wand-magic-sparkles"></i> Сгенерировать 5 духов и 5 аксессуаров</div>').on('click', async () => {
                await generateStarterAccentsOnly();
                if (onRefresh) onRefresh();
            });
            btnRow.append(genBtn);
        }
        sec.append(btnRow);
        return sec;
    };

    wrap.append(buildAccentGrid('Духи', perfumes, 'Духов пока нет — добавь свои или сгенерируй набор.', '_uiOpenPerfumes', 'perfume'));
    wrap.append(buildAccentGrid('Аксессуары и украшения', accessories, 'Аксессуаров пока нет — добавь свои или сгенерируй набор.', '_uiOpenAccessories', 'accessory'));
    return wrap;
}

function renderActiveWornBanner(st, onRefresh) {
    const a = st?.wardrobe?.active;
    if (!a || a.status !== 'worn' || !a.look) return null;
    const acList = getActiveAccents(st);
    const curBox = $('<div class="nnb-note nnb-event" style="margin-bottom:10px; display:flex; gap:12px; align-items:flex-start; flex-wrap:wrap;"></div>');
    const visualsRow = $('<div style="display:flex; gap:8px; align-items:center; flex-shrink:0;"></div>');
    const closetMatch = (st.wardrobe.closet || []).find(c => c.title.toLowerCase() === a.look.title.toLowerCase());
    const lookImgItem = a.look.image ? a.look : closetMatch;
    if (lookImgItem?.image) {
        const th = lookThumb(lookImgItem, '76px', '110px').attr('title', 'Нажми, чтобы открыть полный лист образов');
        th.css('cursor', 'pointer').on('click', () => window.open(lookImgItem.image, '_blank'));
        visualsRow.append(th);
    }
    acList.forEach(ac => {
        const boxMatch = personalBoxItems(st).find(x => x.title.toLowerCase() === ac.title.toLowerCase());
        const imgObj = ac.image ? ac : boxMatch;
        if (imgObj?.image) {
            const fth = findThumb(imgObj, '62px').attr('title', `${ac.title} (нажми, чтобы открыть картинку)`);
            fth.css('cursor', 'pointer').on('click', () => window.open(imgObj.image, '_blank'));
            visualsRow.append(fth);
        }
    });
    if (visualsRow.children().length) curBox.append(visualsRow);

    const body = $('<div style="flex:1; min-width:200px;"></div>');
    body.append($('<div class="nnb-event-title"></div>').text(`👕 Сейчас надето: «${a.look.title}»${a.occasion ? ` (${a.occasion})` : ''}`));
    body.append($('<div class="nnb-npc-text" style="margin-top:4px;"></div>').text(a.look.desc));
    if (acList.length) {
        const acStr = acList.map(ac => `${(ACCENT_KINDS[ac.kind] || ACCENT_KINDS.accessory).icon} ${ac.title}${ac.desc ? ` (${ac.desc})` : ''}`).join('  ·  ');
        body.append($('<div class="nnb-npc-status" style="margin-top:4px; color:var(--SmartThemeQuoteColor, #e0c068);"></div>').text(`Штрихи образа: ${acStr}`));
    }
    const curBtns = $('<div class="nnb-pop-row" style="margin-top:8px; gap:6px; flex-wrap:wrap;"></div>');
    if (Array.isArray(a.options) && a.options.length > 1) {
        curBtns.append($('<div class="menu_button nnb-btn-primary" style="padding:3px 9px; font-size:0.85em;" title="Вернуться к 5 сгенерированным нарядам, чтобы добрать понравившиеся в шкаф"><i class="fa-solid fa-arrow-left"></i> Назад к 5 нарядам</div>').on('click', async () => {
            a.status = 'choosing';
            await commit();
            closeBook();
            await showWardrobePopup();
        }));
    }
    if (Array.isArray(a.accents) && a.accents.length > 0) {
        curBtns.append($('<div class="menu_button" style="padding:3px 9px; font-size:0.85em;" title="Открыть выбор сгенерированных штрихов к этому образу"><i class="fa-solid fa-wand-magic-sparkles"></i> К новым штрихам</div>').on('click', async () => {
            closeBook();
            await showAccentPopup();
        }));
    }
    curBtns.append($('<div class="menu_button" style="padding:3px 8px; font-size:0.85em;"><i class="fa-solid fa-masks-theater"></i> Сцена прошла (итог)</div>').on('click', () => runReveal()));
    curBtns.append($('<div class="menu_button" style="padding:3px 8px; font-size:0.85em;"><i class="fa-solid fa-xmark"></i> Снять наряд</div>').on('click', async () => {
        st.wardrobe.active = null;
        await commit();
        renderDirection();
        if (onRefresh) onRefresh();
    }));
    body.append(curBtns);
    curBox.append(body);
    return curBox;
}

async function openClosetPopup() {
    const st = store();
    if (!st) return toastr.warning('Сначала открой чат', 'Блокнот рассказчика');
    if (st.wardrobe.active?.status === 'choosing') return presentLooks();

    if (!Array.isArray(st.wardrobe.closet)) st.wardrobe.closet = [];
    const el = $('<div class="nnb-pop nnb-pop-visual"><h3>👗 Гардероб, шкаф и готовые штрихи</h3></div>');

    const topBannerHost = $('<div></div>');
    el.append(topBannerHost);

    let curCat = 'Все';
    const catRow = $('<div class="nnb-chips-row" style="margin-bottom:8px;"></div>');
    const listWrap = $('<div class="nnb-looks" style="display:grid; grid-template-columns:repeat(auto-fill, minmax(240px, 1fr)); gap:10px; max-height:420px; overflow-y:auto;"></div>');
    const accentsHost = $('<div></div>');

    const refreshAll = () => {
        topBannerHost.empty();
        const banner = renderActiveWornBanner(st, refreshAll);
        if (banner) topBannerHost.append(banner);
        renderList();
        accentsHost.empty().append(renderReadyAccentsBlock(st, refreshAll));
    };

    const renderList = () => {
        listWrap.empty();
        const a = st.wardrobe.active;
        const items = st.wardrobe.closet.filter(c => curCat === 'Все' || c.category === curCat);
        if (!items.length) {
            listWrap.append(`<div class="nnb-empty" style="grid-column:1/-1;">${st.wardrobe.closet.length ? 'В этой категории пока нет сохранённых нарядов.' : 'Шкаф пока пуст. Сгенерируй 5 новых вариантов или создай стартовый мир!'}</div>`);
            return;
        }
        items.forEach(item => {
            const isWorn = a?.status === 'worn' && a.look?.title === item.title;
            const card = $('<div class="nnb-look" style="display:flex; gap:10px; align-items:flex-start; margin:0;"></div>');
            if (isWorn) card.css('border-color', 'var(--SmartThemeQuoteColor, #8b78c4)');
            if (item.image) {
                const th = lookThumb(item, '80px', '116px');
                th.css('cursor', 'pointer').attr('title', 'Нажми, чтобы надеть этот образ').on('click', async () => {
                    await wearFromCloset(item, '', true);
                    renderDirection();
                    refreshAll();
                });
                card.append(th);
            }
            const left = $('<div style="flex:1; min-width:0; cursor:pointer;"></div>');
            left.append($('<div class="nnb-look-title"></div>').text(`${isWorn ? '👕 ' : ''}«${item.title}» · ${item.category || 'Повседневный'}`));
            left.append($('<div class="nnb-look-desc" style="font-size:0.86em;"></div>').text(item.desc));
            left.on('click', async () => {
                await wearFromCloset(item, '', true);
                renderDirection();
                refreshAll();
            });
            const acts = $('<div class="nnb-actions" style="flex-shrink:0; display:flex; flex-direction:column; gap:6px;"></div>');
            const wearBtn = $('<i class="fa-solid fa-shirt" title="Надеть сейчас"></i>').on('click', async (e) => {
                e.stopPropagation();
                await wearFromCloset(item, '', true);
                renderDirection();
                refreshAll();
            });
            const editBtn = $('<i class="fa-solid fa-pen" title="Изменить"></i>').on('click', async (e) => {
                e.stopPropagation();
                const t = await askText('Название образа', item.title);
                if (t === null) return;
                const c = await askText('Категория (Повседневный, Рабочий, На выход, Домашний, По погоде, Спортивный)', item.category || 'Повседневный');
                if (c === null) return;
                const d = await askText('Описание наряда', item.desc);
                if (d === null) return;
                if (t.trim()) item.title = t.trim();
                item.category = normalizeClosetCat(c);
                item.desc = d.trim();
                await commit();
                refreshAll();
            });
            const delBtn = $('<i class="fa-solid fa-trash" title="Удалить из шкафа"></i>').on('click', async (e) => {
                e.stopPropagation();
                st.wardrobe.closet = st.wardrobe.closet.filter(x => x.id !== item.id);
                await commit();
                refreshAll();
            });
            acts.append(wearBtn, editBtn, delBtn);
            card.append(left, acts);
            listWrap.append(card);
        });
    };

    ['Все', ...CLOSET_CATEGORIES].forEach(cat => {
        const chip = $('<div class="nnb-travel-chip" tabindex="0"></div>').text(cat);
        if (cat === curCat) chip.addClass('active');
        chip.on('click', () => {
            curCat = cat;
            catRow.find('.nnb-travel-chip').removeClass('active');
            chip.addClass('active');
            renderList();
        });
        catRow.append(chip);
    });

    el.append('<div class="nnb-pop-sub">Переодевайся в 1 клик из шкафа (0 запросов) и выбирай готовые духи и аксессуары ниже:</div>');
    el.append(catRow, listWrap, accentsHost);
    refreshAll();

    const botRow = $('<div class="nnb-pop-row nnb-pop-links" style="margin-top:12px; flex-wrap:wrap; gap:8px;"></div>');
    const gen5Btn = $('<div class="menu_button nnb-btn-primary"><i class="fa-solid fa-wand-magic-sparkles"></i> Сгенерировать 5 новых нарядов</div>').on('click', async () => {
        closePopupOf(el);
        await promptGenerateNewOutfits(curCat !== 'Все' ? curCat : '');
    });
    const drawPicsBtn = $('<div class="menu_button"><i class="fa-solid fa-palette"></i> Нарисовать / обновить картинки шкафа и штрихов</div>').on('click', async () => {
        closePopupOf(el);
        await runDrawStarterVisuals(false);
        openClosetPopup();
    });
    const addManualBtn = $('<div class="menu_button"><i class="fa-solid fa-plus"></i> Свой наряд в шкаф</div>').on('click', async () => {
        const t = await askText('Название образа (например «Уютный осенний свитер»)');
        if (!t || !t.trim()) return;
        const c = await askText('Категория (Повседневный, Рабочий, На выход, Домашний, По погоде, Спортивный)', curCat !== 'Все' ? curCat : 'Повседневный');
        if (c === null) return;
        const d = await askText('Описание: что надето, обувь, причёска, детали');
        if (d === null) return;
        addLookToCloset(st, { title: t.trim(), category: c.trim(), desc: d.trim() });
        await commit();
        refreshAll();
    });
    botRow.append(gen5Btn, drawPicsBtn, addManualBtn);
    el.append(botRow);

    await openPopup(el, true);
}

async function startWardrobe() {
    const st = store();
    if (!st) return toastr.warning('Сначала открой чат', 'Блокнот рассказчика');
    if (st.wardrobe.active?.status === 'choosing') return presentLooks();
    return openClosetPopup();
}

async function rerollOutfits() {
    const st = store();
    const a = st?.wardrobe.active;
    if (!a) return;
    const exclude = a.options.map(o => o.title);
    const occasion = a.occasion;
    const ok = await withBusy('👗 Модель подбирает 5 других образов…', s2 => generateOutfits(s2, occasion, exclude));
    if (ok) presentLooks();
}

async function attachLookCropsFromActive(a) {
    if (!a?.image || !Array.isArray(a.options) || !a.options.length) return;
    const n = Math.min(a.options.length, 5);
    if (Array.isArray(a.individualImages) && a.individualImages.some(Boolean)) {
        for (let idx = 0; idx < a.options.length; idx++) {
            if (idx >= n) break;
            const singleUrl = a.options[idx].image || a.individualImages[idx] || a.image;
            a.options[idx].image = singleUrl;
            a.options[idx].imageLayout = { rows: 1, cols: 1 };
            a.options[idx].crop = { x: 0, y: 0, w: 1, h: 1 };
            a.options[idx].isSingleImage = true;
        }
        return;
    }
    const L = a.imageLayout || looksLayout(n);
    let crops = [];
    try {
        crops = await smartCrops(a.image, n, 'looks', L);
    } catch (e) { crops = []; }
    for (let idx = 0; idx < a.options.length; idx++) {
        if (idx >= n) break;
        if (a.options[idx].isSingleImage && a.options[idx].image) continue;
        const r = Math.floor(idx / L.cols), c = idx % L.cols;
        const colW = 1 / L.cols, rowH = 1 / L.rows;
        const fallback = { x: c * colW + colW * 0.05, y: r * rowH + rowH * 0.04, w: colW * 0.9, h: rowH * 0.92 };
        a.options[idx].image = a.image;
        a.options[idx].imageLayout = L;
        a.options[idx].crop = crops[idx] || fallback;
    }
}

async function chooseOutfit(i, customText, extraSaveIndices = []) {
    const st = store();
    const a = st?.wardrobe.active;
    if (!a) return;
    if (customText) {
        const customLook = { title: 'Свой образ', desc: customText, effects: '', custom: true, category: normalizeClosetCat(a.occasion) };
        addLookToCloset(st, customLook, customLook.category);
        a.look = customLook;
    } else {
        await attachLookCropsFromActive(a);
        const allToSave = new Set([i, ...(extraSaveIndices || [])].filter(idx => idx >= 0 && idx < a.options.length));
        allToSave.forEach(idx => addLookToCloset(st, a.options[idx], normalizeClosetCat(a.options[idx].category || a.occasion)));
        a.look = a.options[i];
        if (a.look?.image) a.image = a.look.image;
    }
    a.status = 'worn';
    await commit();
    if (accentsOn(st) && ((a.accents || []).length || wearableBox(st).length)) {
        presentAccents();
        return;
    }
    toastr.success(`Выбран образ «${escapeHtml(a.look.title)}» (сохранено в шкаф с картинкой).`, '👗 Гардероб', { escapeHtml: false });
    await checkPendingTravel();
}

async function attachAccentCropsFromActive(a) {
    if (!a?.accentImage || !Array.isArray(a.accents) || !a.accents.length) return;
    const n = Math.min(a.accents.length, 4);
    if (Array.isArray(a.individualAccentImages) && a.individualAccentImages.some(Boolean)) {
        for (let idx = 0; idx < a.accents.length; idx++) {
            if (idx >= n) break;
            const singleUrl = a.accents[idx].image || a.individualAccentImages[idx] || a.accentImage;
            a.accents[idx].image = singleUrl;
            a.accents[idx].imageLayout = { rows: 1, cols: 1 };
            a.accents[idx].crop = { x: 0, y: 0, w: 1, h: 1 };
            a.accents[idx].isSingleImage = true;
        }
        return;
    }
    const L = a.accentImageLayout || accentsLayout(n);
    let crops = [];
    try {
        crops = await smartCrops(a.accentImage, n, 'accents', L);
    } catch (e) { crops = []; }
    for (let idx = 0; idx < a.accents.length; idx++) {
        if (idx >= n) break;
        if (a.accents[idx].isSingleImage && a.accents[idx].image) continue;
        const r = Math.floor(idx / L.cols), c = idx % L.cols;
        const colW = 1 / L.cols, rowH = 1 / L.rows;
        const fallback = { x: c * colW + colW * 0.08, y: r * rowH + rowH * 0.08, w: colW * 0.84, h: rowH * 0.84 };
        a.accents[idx].image = a.accentImage;
        a.accents[idx].imageLayout = L;
        a.accents[idx].crop = crops[idx] || fallback;
    }
}

function saveAccentToBox(st, ac) {
    if (!st?.wardrobe || !ac?.title) return null;
    if (!Array.isArray(st.wardrobe.box)) st.wardrobe.box = [];
    if (!st.wardrobe.nextItemId) st.wardrobe.nextItemId = 1;
    const existing = st.wardrobe.box.find(x => !x.onCounter && x.title.toLowerCase() === ac.title.toLowerCase());
    if (existing) {
        if (ac.desc) existing.desc = ac.desc;
        if (ac.en) existing.en = ac.en;
        if (ac.effects) existing.effects = ac.effects;
        if (ac.image) existing.image = ac.image;
        if (ac.crop) existing.crop = ac.crop;
        if (ac.imageLayout) existing.imageLayout = ac.imageLayout;
        if (ac.isSingleImage !== undefined) existing.isSingleImage = !!ac.isSingleImage;
        return existing;
    }
    const item = {
        id: st.wardrobe.nextItemId++,
        kind: ac.kind === 'perfume' ? 'perfume' : 'accessory',
        title: ac.title.trim(),
        desc: ac.desc || '',
        en: ac.en || '',
        effects: ac.effects || '',
        origin: ac.origin || 'штрих к образу',
        image: ac.image || '',
        crop: ac.crop || null,
        imageLayout: ac.imageLayout || null,
        isSingleImage: !!ac.isSingleImage,
        onCounter: false,
        at: ctx().chat?.length ?? 0,
    };
    st.wardrobe.box.push(item);
    return item;
}

async function chooseAccent(accent, extraWearList = [], saveToClosetList = []) {
    const st = store();
    const a = st?.wardrobe.active;
    if (!a || a.status !== 'worn') return;
    await attachAccentCropsFromActive(a);

    const wearAll = [];
    if (accent) wearAll.push(accent);
    (extraWearList || []).forEach(ac => {
        if (ac && !wearAll.some(x => x.title.toLowerCase() === ac.title.toLowerCase())) {
            wearAll.push(ac);
        }
    });

    const saveAll = [...wearAll];
    (saveToClosetList || []).forEach(ac => {
        if (ac && !saveAll.some(x => x.title.toLowerCase() === ac.title.toLowerCase())) {
            saveAll.push(ac);
        }
    });
    saveAll.forEach(ac => {
        if (!ac.fromBox && ac.kind !== 'makeup') {
            saveAccentToBox(st, ac);
        }
    });

    a.selectedAccents = wearAll;
    a.accent = wearAll[0] || null;
    await commit();
    const wornNames = wearAll.map(x => `«${escapeHtml(x.title)}»`).join(', ');
    toastr.success(`Образ «${escapeHtml(a.look.title)}»${wornNames ? ` + ${wornNames}` : ''}${saveAll.length ? ` (сохранено штрихов в шкаф: ${saveAll.filter(x => x.kind !== 'makeup').length})` : ''}.`, '👗 Гардероб', { escapeHtml: false });
    await checkPendingTravel();
}

async function showAccentPopup() {
    const st = store();
    const a = st?.wardrobe.active;
    if (!a || a.status !== 'worn') return;
    const accents = a.accents || [];
    const visual = wantImages() && accents.length > 0;
    const icon = k => (ACCENT_KINDS[k] || ACCENT_KINDS.accessory).icon;

    const wearSet = new Set();
    const saveSet = new Set();
    const boxWearSet = new Set();
    let currentSlide = 0;

    if (accents.length) {
        wearSet.add(0);
        saveSet.add(0);
    }

    const el = $(`<div class="nnb-pop${visual ? ' nnb-pop-visual' : ''}"></div>`);

    // Верхняя шапка с кнопкой «⬅ Назад к нарядам»
    const topHead = $('<div style="display:flex; align-items:center; justify-content:space-between; gap:8px; flex-wrap:wrap;"></div>');
    const backToLooksBtn = $('<div class="menu_button" style="padding:5px 12px; font-weight:600;" title="Вернуться к выбору из 5 нарядов, чтобы добрать понравившиеся образы в шкаф"><i class="fa-solid fa-arrow-left"></i> Назад к нарядам</div>');
    backToLooksBtn.on('click', async () => {
        closePopupOf(el);
        a.status = 'choosing';
        await commit();
        await showWardrobePopup();
    });
    const headTitle = $('<h3 style="margin:0; flex:1; text-align:center;">✨ Штрихи к образу</h3>');
    const saveAllAccBtn = $('<div class="menu_button" style="padding:5px 10px; font-size:0.84em;"><i class="fa-solid fa-check-double"></i> Все в шкаф</div>');
    topHead.append(backToLooksBtn, headTitle, accents.length ? saveAllAccBtn : $('<span></span>'));
    el.append(topHead);

    el.append($('<div class="nnb-pop-sub"></div>').text(`К образу «${a.look.title}» — можно надеть сразу несколько штрихов (например духи + украшение), а остальные отметить галочкой «☑️ В шкаф», чтобы убрать в коллекцию:`));

    // Навигация карусели (по 1 карточке на экран)
    const carouselNav = $('<div style="display:flex; align-items:center; justify-content:space-between; gap:8px; margin:4px 0; padding:6px 10px; border-radius:10px; background:color-mix(in srgb, var(--SmartThemeQuoteColor, #8b78c4) 10%, transparent);"></div>');
    const prevBtn = $('<div class="menu_button" style="padding:5px 12px; font-weight:600;"><i class="fa-solid fa-chevron-left"></i> Предыдущий</div>');
    const slideInfo = $('<div style="font-weight:700; font-size:0.95em; text-align:center;"></div>');
    const nextBtn = $('<div class="menu_button" style="padding:5px 12px; font-weight:600;">Следующий <i class="fa-solid fa-chevron-right"></i></div>');
    carouselNav.append(prevBtn, slideInfo, nextBtn);
    if (accents.length > 1) el.append(carouselNav);

    const cardsHost = $('<div></div>');
    el.append(cardsHost);

    const dotsRow = $('<div class="nnb-dots" style="margin:6px 0;"></div>');
    if (accents.length > 1) el.append(dotsRow);

    const confirmBtn = $('<div class="menu_button nnb-btn-primary" style="padding:8px 14px;"></div>');
    const noneBtn = $('<div class="menu_button" style="padding:8px 12px;"><i class="fa-solid fa-xmark"></i> Без штрихов</div>');

    const n = Math.min(accents.length, 4);
    const layoutOf = () => a.accentImageLayout || accentsLayout(n);
    const cellOf = i => {
        const L = layoutOf();
        const r = Math.floor(i / L.cols), c = i % L.cols;
        const colW = 1 / L.cols, rowH = 1 / L.rows;
        const padX = colW * 0.08, padY = rowH * 0.08;
        return { x: c * colW + padX, y: r * rowH + padY, w: colW - padX * 2, h: rowH - padY * 2 };
    };

    const updateAccentsUI = () => {
        if (accents.length > 1) {
            slideInfo.text(`Штрих ${currentSlide + 1} из ${accents.length}`);
            prevBtn.css({ opacity: currentSlide <= 0 ? 0.4 : 1, pointerEvents: currentSlide <= 0 ? 'none' : 'auto' });
            nextBtn.css({ opacity: currentSlide >= accents.length - 1 ? 0.4 : 1, pointerEvents: currentSlide >= accents.length - 1 ? 'none' : 'auto' });
            dotsRow.children().each((j, d) => $(d).toggleClass('active', j === currentSlide));
        }

        cardsHost.find('.nnb-accent-slide').each(function (idx) {
            const cardEl = $(this);
            cardEl.toggle(idx === currentSlide);
            const isWear = wearSet.has(idx);
            const isSave = saveSet.has(idx);
            cardEl.css({
                'border-color': isWear ? 'var(--SmartThemeQuoteColor, #8b78c4)' : isSave ? 'color-mix(in srgb, var(--SmartThemeQuoteColor, #8b78c4) 60%, transparent)' : 'var(--SmartThemeBorderColor)',
                'border-width': isWear ? '2px' : '1px',
            });
            cardEl.find('.nnb-acc-save-cb').prop('checked', isSave);
            cardEl.find('.nnb-acc-save-label').text(isSave ? 'В шкаф (отмечено)' : 'Убрать в шкаф');
            cardEl.find('.nnb-acc-save-pill').css({
                'border-color': isSave ? 'var(--SmartThemeQuoteColor, #8b78c4)' : 'var(--SmartThemeBorderColor)',
                'background': isSave ? 'color-mix(in srgb, var(--SmartThemeQuoteColor, #8b78c4) 22%, transparent)' : 'transparent',
            });

            const wBtn = cardEl.find('.nnb-acc-wear-btn');
            if (isWear) {
                wBtn.addClass('nnb-btn-primary').html('<i class="fa-solid fa-check"></i> Надеть сейчас (выбрано)');
            } else {
                wBtn.removeClass('nnb-btn-primary').html('<i class="fa-solid fa-sparkles"></i> Надеть сейчас');
            }
        });

        const totalWear = wearSet.size + boxWearSet.size;
        const totalSave = new Set([...wearSet, ...saveSet]).size;
        confirmBtn.html(`<i class="fa-solid fa-check"></i> Применить (надеть: ${totalWear}, в шкаф: ${totalSave})`);
    };

    const renderAccentSlides = url => {
        cardsHost.empty();
        dotsRow.empty();
        const hasUrl = !!url;
        const imgs = [];

        accents.forEach((ac, i) => {
            const kObj = ACCENT_KINDS[ac.kind] || ACCENT_KINDS.accessory;
            const card = $('<div class="nnb-look nnb-accent-slide" style="display:flex; flex-direction:column; gap:8px; padding:12px; border-radius:12px; cursor:pointer;"></div>');

            // Верхняя панель карточки: галочка «☑️ Убрать в шкаф» + кнопка «✨ Надеть сейчас»
            const topBar = $('<div style="display:flex; justify-content:space-between; align-items:center; gap:8px; flex-wrap:wrap;"></div>');
            const savePill = $(`
                <label class="nnb-acc-save-pill" style="display:inline-flex; align-items:center; gap:7px; padding:5px 10px; border-radius:8px; border:1px solid var(--SmartThemeBorderColor); cursor:pointer; user-select:none; font-size:0.86em;">
                    <input type="checkbox" class="nnb-acc-save-cb" style="width:17px !important; height:17px !important; margin:0 !important; cursor:pointer; accent-color:var(--SmartThemeQuoteColor, #8b78c4); display:inline-block !important; opacity:1 !important; appearance:auto !important; -webkit-appearance:checkbox !important;">
                    <span class="nnb-acc-save-label">Убрать в шкаф</span>
                </label>
            `);
            savePill.on('click', e => e.stopPropagation());
            savePill.find('.nnb-acc-save-cb').on('change', function (e) {
                e.stopPropagation();
                if ($(this).prop('checked')) saveSet.add(i);
                else saveSet.delete(i);
                updateAccentsUI();
            });

            const wearBtn = $('<div class="menu_button nnb-acc-wear-btn" style="padding:5px 12px; font-size:0.86em; margin:0;"></div>');
            wearBtn.on('click', e => {
                e.stopPropagation();
                if (wearSet.has(i)) wearSet.delete(i);
                else { wearSet.add(i); saveSet.add(i); }
                updateAccentsUI();
            });

            topBar.append(savePill, wearBtn);
            card.append(topBar);

            const singleAccUrl = (ac.isSingleImage && ac.image) ? ac.image : (Array.isArray(a.individualAccentImages) && a.individualAccentImages[i]) ? a.individualAccentImages[i] : null;
            if (singleAccUrl) {
                const img = $('<div class="nnb-card-img" style="border-radius:10px; overflow:hidden; width:100%; aspect-ratio:1/1; max-height:320px; margin:2px auto;"></div>');
                applyCrop(img, singleAccUrl, { x: 0, y: 0, w: 1, h: 1 }, 1);
                card.append(img);
            } else if (hasUrl && i < n) {
                const img = $('<div class="nnb-card-img" style="border-radius:10px; overflow:hidden; width:100%; aspect-ratio:1/1; max-height:320px; margin:2px auto;"></div>');
                applyCrop(img, url, cellOf(i), layoutOf().rows === 2 ? 2 / 3 : 1.5);
                card.append(img);
                imgs.push(img);
            }

            card.append($('<div style="font-size:0.78em; text-transform:uppercase; opacity:0.7; letter-spacing:0.06em;"></div>').text(`${kObj.icon} ${kObj.name}`));
            card.append($('<div class="nnb-look-title" style="font-size:1.05em;"></div>').text(`«${ac.title}»`));
            if (ac.desc) card.append($('<div class="nnb-look-desc"></div>').text(ac.desc));

            // Переключение только кнопками-стрелками ◀ и ▶ (без свайпов)

            card.on('click', () => {
                if (saveSet.has(i)) saveSet.delete(i);
                else saveSet.add(i);
                updateAccentsUI();
            });

            cardsHost.append(card);
            dotsRow.append($('<span tabindex="0"></span>').on('click', () => { currentSlide = i; updateAccentsUI(); }));
        });

        updateAccentsUI();

        if (hasUrl && imgs.length && typeof Image === 'function') {
            const probe = new Image();
            probe.onload = async () => {
                const ratio = probe.naturalWidth / probe.naturalHeight || 1.5;
                const crops = await smartCrops(url, n, 'accents', layoutOf());
                imgs.forEach((elImg, idx) => {
                    applyCrop(elImg, url, crops[idx] || cellOf(idx), ratio);
                    if (crops.bg) elImg.css('background-color', crops.bg);
                });
            };
            probe.src = url;
        }
    };

    prevBtn.on('click', () => { if (currentSlide > 0) { currentSlide--; updateAccentsUI(); } });
    nextBtn.on('click', () => { if (currentSlide < accents.length - 1) { currentSlide++; updateAccentsUI(); } });
    saveAllAccBtn.on('click', () => {
        if (saveSet.size === accents.length) saveSet.clear();
        else accents.forEach((_, idx) => saveSet.add(idx));
        updateAccentsUI();
    });

    if (visual && !a.accentImage && !a.accentImageFailed) {
        cardsHost.html('<div class="nnb-pop-sub nnb-wait" style="padding:20px; text-align:center;">🎨 Рисую штрихи…</div>');
        ensurePicture('accents', false, url => renderAccentSlides(url || ''));
    } else if (accents.length) {
        renderAccentSlides(visual ? (a.accentImage || '') : '');
    }

    const fresh = wearableBox(st).filter(x => !accents.some(ac => ac.title.toLowerCase() === x.title.toLowerCase()));
    if (fresh.length) {
        el.append('<div class="nnb-pop-sub nnb-box-head" style="margin-top:6px;">🎁 Или добавь из своих готовых штрихов / шкатулки (можно несколько):</div>');
        const boxRow = $('<div class="nnb-chips-row"></div>');
        fresh.forEach(x => {
            const ch = $('<div class="nnb-travel-chip" tabindex="0"></div>').text(`${icon(x.kind)} ${x.title}`).attr('title', x.origin || x.desc || '');
            ch.on('click', () => {
                if (boxWearSet.has(x)) {
                    boxWearSet.delete(x);
                    ch.removeClass('active');
                } else {
                    boxWearSet.add(x);
                    ch.addClass('active');
                }
                updateAccentsUI();
            });
            boxRow.append(ch);
        });
        el.append(boxRow);
    }

    let accentActionHandled = false;
    backToLooksBtn.off('click').on('click', async () => {
        accentActionHandled = true;
        closePopupOf(el);
        a.status = 'choosing';
        await commit();
        await showWardrobePopup();
    });

    confirmBtn.on('click', async () => {
        accentActionHandled = true;
        closePopupOf(el);
        const wornFromNew = [...wearSet].map(idx => accents[idx]).filter(Boolean);
        const wornFromBox = [...boxWearSet].map(x => ({
            id: x.id,
            kind: x.kind === 'find' ? 'pocket' : x.kind,
            title: x.title,
            desc: x.desc,
            origin: x.origin,
            image: x.image || '',
            crop: x.crop || null,
            effects: '',
            fromBox: true,
        }));
        const allWear = [...wornFromNew, ...wornFromBox];
        const allSave = [...saveSet].map(idx => accents[idx]).filter(Boolean);
        await chooseAccent(allWear[0] || null, allWear.slice(1), allSave);
    });

    noneBtn.on('click', async () => {
        accentActionHandled = true;
        closePopupOf(el);
        const allSave = [...saveSet].map(idx => accents[idx]).filter(Boolean);
        await chooseAccent(null, [], allSave);
    });

    const bottomBackBtn = $('<div class="menu_button" style="padding:8px 12px;"><i class="fa-solid fa-arrow-left"></i> Назад к нарядам</div>').on('click', async () => {
        accentActionHandled = true;
        closePopupOf(el);
        a.status = 'choosing';
        await commit();
        await showWardrobePopup();
    });

    el.append($('<div class="nnb-pop-row" style="margin-top:10px; gap:8px; flex-wrap:wrap;"></div>').append(bottomBackBtn, confirmBtn, noneBtn));
    if (!(await openPopup(el, visual))) {
        if (!accentActionHandled) await chooseAccent(null);
    } else if (!accentActionHandled && st?.map?.pendingTravel) {
        await chooseAccent(null);
    }
}

// ---------- 🎰 Находки и варианты (гача) ----------
const RARITIES = [
    {
        id: 'common', name: 'Обычная', icon: '⚪', stars: '★', w: 60,
        hint: 'качественная, симпатичная и практичная вещь своей категории; в сцене — приятная покупка или находка, повод улыбнуться',
        choiceHint: 'приятный, жизненный и уютный вариант; даёт живую бытовую деталь и хорошее настроение в сцене',
    },
    {
        id: 'rare', name: 'Редкая', icon: '🔵', stars: '★★', w: 28,
        hint: 'особенная, стильная или штучная вещь с яркой деталью, дизайнерским штрихом или историей — сразу притягивает взгляд и разговор',
        choiceHint: 'вариант с изюминкой, необычной атмосферой, интригующей деталью или совпадением — за него сразу цепляется разговор и действие',
    },
    {
        id: 'epic', name: 'Эпическая', icon: '🟣', stars: '★★★', w: 10,
        hint: 'роскошная или знаковая вещь, которая идеально попадает во вкусы/прошлое кого-то из героев — вызывает сильную реакцию и меняет настроение сцены',
        choiceHint: 'вариант тесно переплетён с прошлым, вкусами, мечтами или скрытыми чувствами кого-то из героев — вызывает сильный отклик и двигает отношения или сюжет',
    },
    {
        id: 'legendary', name: 'Легендарная', icon: '🟡', stars: '★★★★', w: 2,
        hint: 'уникальный, эксклюзивный предмет или вещь с тайной: открывает новую сюжетную линию, загадку или судьбоносный поворот',
        choiceHint: 'судьбоносный или таинственный вариант: открывает новую сюжетную линию, неожиданное знакомство, секрет или поворот, о котором ещё никто не подозревает',
    },
];
const GACHA_PITY = 10;          // столько прокруток без эпической — и следующая гарантирована
const GACHA_LIMIT = 3;          // прокруток на один пост
const rarityOf = id => RARITIES.find(r => r.id === id) || RARITIES[0];
function rollRarity() {
    let x = Math.random() * RARITIES.reduce((a, r) => a + r.w, 0);
    for (const r of RARITIES) { if ((x -= r.w) < 0) return r.id; }
    return 'common';
}
// три редкости на прокрутку; гарант считает прокрутки без эпической и выше
function rollGacha(g) {
    const out = [rollRarity(), rollRarity(), rollRarity()];
    const high = id => id === 'epic' || id === 'legendary';
    if (!out.some(high) && (g.pity || 0) + 1 >= GACHA_PITY) out[Math.floor(Math.random() * 3)] = 'epic';
    g.pity = out.some(high) ? 0 : (g.pity || 0) + 1;
    return out;
}
function gachaOn(st) {
    return !!st?.direction?.gacha;
}
function gachaSpinsLeft(st) {
    const len = ctx().chat?.length ?? 0;
    st.gacha.spins = st.gacha.spins.filter(at => at === len); // с новым постом счёт начинается заново
    return Math.max(0, GACHA_LIMIT - st.gacha.spins.length);
}

function gachaPrompt(st, rarities, hint, mode = 'items') {
    const names = storyNames();
    const t = st.time;
    const when = [t.date ? `${formatDate(t.date)}, ${season(t.date).name}` : '', placeLine(st)].filter(Boolean).join('; ');
    if (mode === 'choices') {
        const recentChoices = (st.gacha.choices || []).slice(-12).map(x => x.title);
        const lines = [
            '[OOC: Пауза в ролевой игре. Сейчас ты НЕ пишешь ответ персонажа. Ты — помощник автора и устраиваешь «гачу вариантов»: игрок испытывает удачу и получает три варианта на выбор (НЕ предметы для инвентаря, а события, занятия, места, профессии, книги/фильмы, знакомства или решения).',
            hint
                ? `Тема розыгрыша от игрока: «${hint}». Придумай три разных варианта именно на эту тему (например, если это книга или фильм — три конкретных названия с жанром и о чём они; если профессия или подработка — три вакансии/роли с условиями; если куда пойти — три колоритных места; если знакомство — три интересных человека).`
                : `Пойми по последним сообщениям чата, какой выбор или случай сейчас интереснее всего для ${names.user}: куда сходить, какую книгу почитать или фильм посмотреть на вечер, какую подработку/профессию выбрать, какое блюдо заказать, с кем случайно познакомиться или чем заняться. Выбери одну самую подходящую к сцене тему и предложи три варианта внутри неё.`,
            when ? `Когда и где: ${when}. Учитывай реалии, атмосферу и местную валюту (если уместно).` : '',
            buildDirection(st),
            recentChoices.length ? `Уже выпадало ранее (не повторяй): ${recentChoices.join(', ')}.` : '',
            'Редкость каждого варианта уже выпала, придумай их строго под неё, в этом порядке:',
            ...rarities.map((r, i) => `${i + 1}) ${rarityOf(r).name.toUpperCase()} — ${rarityOf(r).choiceHint}`),
            `Все три варианта должны заметно отличаться по настроению и сути. У каждого — скрытый «крючок»: чем обернётся этот выбор в сюжете, если ${names.user} выберет именно его (какая сцена начнётся, кто как отреагирует, что откроется). Крючок — для автора, игрок его заранее не видит. Персонажи и тайны — только из этой истории.`,
            'Формат, без пояснений:',
            'PLACE: короткое название темы (например «Книга на вечер», «Вакансия», «Куда пойти», «Случайная встреча»)',
            'Затем по одной строке на каждый из 3 вариантов:',
            'ITEM: название варианта | описание в 1–2 предложениях | короткая деталь (жанр, условия, особенность или где это) | сюжетный крючок',
        ];
        return lines.filter(Boolean).join('\n') + ']';
    }
    const owned = st.wardrobe.box.slice(-12).map(x => x.title);
    const images = wantImages();
    const lines = [
        '[OOC: Пауза в ролевой игре. Сейчас ты НЕ пишешь ответ персонажа. Ты — помощник автора и устраиваешь «гачу покупок и находок»: игрок выбирает из трёх осязаемых вещей или покупок.',
        hint
            ? `ВАЖНО — ЧТО ИМЕННО ИЩЕТ ИЛИ ВЫБИРАЕТ ИГРОК: «${hint}». Придумай 3 конкретных предмета СТРОГО ЭТОЙ КАТЕГОРИИ! (Например, если игрок указал обувь — предложи 3 разные пары обуви: туфли, ботильоны, сапожки и т.д.; если платье/одежду — 3 вещи гардероба; если сумочку, книгу, мебель или подарок — строго их! СТРОГО ЗАПРЕЩЕНО подменять запрос игрока на мелкие безделушки у кассы!)`
            : `Пойми по последним сообщениям чата, в каком магазине или месте сейчас находится ${names.user} и что там продаётся или лежит! ВАЖНО: предлагай основной товар этого места, а НЕ мелочёвку у кассы! Если героиня в обувном магазине — предложи 3 разные пары обуви; если в бутике одежды — 3 наряда/вещи; если в книжном — 3 книги; если в ювелирном — 3 украшения; если в мебельном/интерьерном — 3 предмета для дома; и только на барахолке или в лавке редкостей — винтажные диковинки.`,
        when ? `Когда и где: ${when}. Цену пиши в местной валюте (${st.wallet?.currency || '£'}) сообразно категории вещи.` : 'Цену пиши в валюте, уместной для этого мира.',
        buildDirection(st),
        owned.length ? `У ${names.user} уже есть: ${owned.join(', ')} — не повторяй.` : '',
        'Редкость каждого варианта уже выпала, придумай 3 предмета строго под неё, в этом порядке:',
        ...rarities.map((r, i) => `${i + 1}) ${rarityOf(r).name.toUpperCase()} — ${rarityOf(r).hint}`),
        `Все три предмета должны быть полноценными вещами нужной категории (не мелочёвкой, если только игрок сам не ищет мелочь). У каждого — «крючок»: чем обернётся эта покупка/находка в сцене, кто из персонажей как отреагирует и что заметит.`,
        'Формат, без пояснений:',
        'PLACE: короткое название магазина, отдела или места (и что выбираем)',
        `Затем по ${images ? 'две строки' : 'одной строке'} на каждый из 3 предметов:`,
        'ITEM: название предмета | как выглядит, фасон/материал/детали — 1–2 предложения | цена | крючок',
    ];
    if (images) lines.push('EN: этот же предмет коротко по-английски для художника, только как он выглядит (без людей и рук)');
    return lines.filter(Boolean).join('\n') + ']';
}
function parseGacha(raw, rarities) {
    const text = String(raw || '').replace(/\*\*/g, '');
    const place = (text.match(/^\s*(?:PLACE|TOPIC)\s*[:：—–-]\s*(.+)$/im) || [])[1]?.trim() || '';
    const items = [];
    for (const line of text.split(/\r?\n/)) {
        let m = line.match(/^\s*ITEM\s*\d*\s*[:：—–-]\s*(.+)$/i);
        if (m) {
            const [title, desc, price, ...hook] = m[1].split('|').map(x => x.trim());
            if (title) items.push({ title: title.replace(/^[«"]|[»"]$/g, ''), desc: desc || '', price: price || '', hook: hook.join(' | '), en: '' });
            continue;
        }
        m = line.match(/^\s*EN\s*[:：—–-]\s*(.+)$/i);
        if (m && items.length) items[items.length - 1].en = m[1].trim();
    }
    items.slice(0, 3).forEach((it, i) => { it.rarity = rarities[i] || 'common'; });
    return { place, items: items.slice(0, 3) };
}
function gachaPicPrompt(a) {
    const pos = ['first', 'second', 'third'];
    return cleanForCommand(`${ITEM_STYLE}, ${a.options.length} separate items in a row, evenly spaced, each item small and centered in its own third of the image with wide empty space between items, nothing overlapping, plain light cream background, ` +
        a.options.map((x, i) => `${pos[i]} from the left: ${x.en || x.title}`).join('; ') + ', no people, no hands, no text, no captions');
}

async function askChoicesTopicModal(initialTopic = '') {
    return new Promise(resolve => {
        const el = $('<div class="nnb-pop"><h3>✨ Варианты: что сгенерировать?</h3></div>');
        el.append('<div class="nnb-pop-sub">Введи вручную, варианты чего именно ты бы хотела получить, или <b>оставь поле пустым</b> — тогда нейросеть сама решит, что предложить по текущей сцене!</div>');
        const inp = $('<input type="text" class="text_pole" style="margin:8px 0 8px 0; width:100%;" placeholder="Оставь пустым (нейросеть решит сама) или напиши тему вручную…">').val(initialTopic);
        el.append(inp);

        const chipsWrap = $('<div class="nnb-chips-row" style="margin-bottom:12px; gap:6px;"></div>');
        const presets = [
            '🎬 Фильм на вечер',
            '📚 Книга для чтения',
            '☕ Куда пойти',
            '💼 Профессия / подработка',
            '🤝 Случайное знакомство',
            '🍰 Что заказать из еды',
            '🎲 Неожиданное событие',
        ];
        presets.forEach(p => {
            const cleanP = p.replace(/^[^а-яА-Яa-zA-Z]+/, '').trim();
            const ch = $('<div class="nnb-travel-chip" style="font-size:0.82em; padding:3px 8px;" tabindex="0"></div>').text(p);
            ch.on('click', () => {
                inp.val(cleanP).trigger('focus');
                chipsWrap.find('.nnb-travel-chip').removeClass('active');
                ch.addClass('active');
            });
            chipsWrap.append(ch);
        });
        el.append(chipsWrap);

        let settled = false;
        const finish = val => {
            if (settled) return;
            settled = true;
            closePopupOf(el);
            resolve(val);
        };
        inp.on('keydown', e => {
            if (e.key === 'Enter') {
                e.preventDefault();
                finish(String(inp.val() || '').trim());
            }
        });
        const row = $('<div class="nnb-pop-row" style="gap:8px; flex-wrap:wrap;"></div>');
        const goBtn = $('<div class="menu_button nnb-btn-primary"><i class="fa-solid fa-wand-magic-sparkles"></i> Сгенерировать 3 варианта</div>').on('click', () => {
            finish(String(inp.val() || '').trim());
        });
        const autoBtn = $('<div class="menu_button"><i class="fa-solid fa-dice"></i> На усмотрение нейросети</div>').on('click', () => {
            finish('');
        });
        const cancelBtn = $('<div class="menu_button"><i class="fa-solid fa-xmark"></i> Отмена</div>').on('click', () => {
            finish(null);
        });
        row.append(goBtn, autoBtn, cancelBtn);
        el.append(row);
        setTimeout(() => inp.trigger('focus'), 60);
        openPopup(el).then(() => {
            if (!settled) { settled = true; resolve(null); }
        });
    });
}

async function openGachaLauncher() {
    const st = store();
    if (!st) return toastr.warning('Сначала открой чат', 'Блокнот рассказчика');
    if (!gachaOn(st)) return toastr.info('Гача выключена в этом чате — включи её в блокноте, вкладка «Сюжет»', '🎰 Гача');
    if (st.gacha.active?.status === 'choosing') return presentGacha();
    const left = gachaSpinsLeft(st);
    if (!left) return toastr.info(`На этом посте удачу уже испытывали ${GACHA_LIMIT} раза. Снова можно будет со следующим постом.`, '🎰 Гача');

    const el = $('<div class="nnb-pop"><h3>🎰 Испытать удачу</h3></div>');
    el.append($('<div class="nnb-pop-sub"></div>').text(`Прокруток на этом посте: ${left} из ${GACHA_LIMIT} · до гарантированной эпической: ${Math.max(1, GACHA_PITY - (st.gacha.pity || 0))}`));

    el.append('<div class="nnb-pop-sub" style="margin-top:4px;">Укажи вручную, что именно ты ищешь или выбираешь (или нажми на быструю кнопку ниже). Если оставить пустым — модель сама посмотрит, в каком магазине или месте ты сейчас:</div>');
    const hintInput = $('<input type="text" class="text_pole" style="margin: 6px 0 8px 0; width: 100%;" placeholder="Что ищем? Напр.: туфли на каблуке, вечернее платье, сумочка, книга, подарок…">');
    el.append(hintInput);

    const itemPresetRow = $('<div class="nnb-chips-row" style="margin-bottom:10px; gap:6px; justify-content:flex-start;"></div>');
    [
        '👠 Обувь (туфли, сапожки, ботильоны)',
        '👗 Одежда и платья',
        '👜 Сумочка / Шарф / Аксессуар',
        '💍 Украшения и часы',
        '🌸 Духи и косметика',
        '🛋 Декор и уют для дома',
        '📚 Книги и редкие издания',
        '🎁 Подарок для персонажа',
        '🕰 Винтаж и диковинки',
    ].forEach(preset => {
        const cleanP = preset.replace(/^[^а-яА-Яa-zA-Z]+/, '').trim();
        const ch = $('<div class="nnb-travel-chip" style="font-size:0.8em; padding:3px 8px;" tabindex="0"></div>').text(preset);
        ch.on('click', () => {
            hintInput.val(cleanP).trigger('focus');
            itemPresetRow.find('.nnb-travel-chip').removeClass('active');
            ch.addClass('active');
        });
        itemPresetRow.append(ch);
    });
    el.append(itemPresetRow);

    const grid = $('<div class="nnb-cards nnb-cards-text" style="gap: 10px;"></div>');

    const itemCard = $('<div class="nnb-card-pick" tabindex="0" style="cursor:pointer;"><div class="nnb-card-body"><div class="nnb-card-kind">Категория 1 · Покупки, одежда, обувь, вещи</div><div class="nnb-card-title">🎁 Предметы, покупки и находки</div><div class="nnb-card-desc">Обувь, платья, сумочки, украшения, духи, книги, декор для дома или диковинки — строго по твоему запросу или текущему магазину в сцене!</div></div></div>');
    itemCard.on('click', async () => {
        const h = String(hintInput.val() || '').trim();
        closePopupOf(el);
        await runGachaRoll('items', h);
    });

    const choiceCard = $('<div class="nnb-card-pick" tabindex="0" style="cursor:pointer;"><div class="nnb-card-body"><div class="nnb-card-kind">Категория 2 · Для сюжета (авто или своя тема)</div><div class="nnb-card-title">✨ Варианты и случаи</div><div class="nnb-card-desc">Куда пойти, книга или фильм на вечер, профессия, блюдо, случайное знакомство. Можно задать тему вручную или оставить пустым на выбор нейросети!</div></div></div>');
    choiceCard.on('click', async () => {
        const pre = String(hintInput.val() || '').trim();
        closePopupOf(el);
        if (pre) {
            await runGachaRoll('choices', pre);
        } else {
            const topic = await askChoicesTopicModal('');
            if (topic === null) return;
            await runGachaRoll('choices', topic);
        }
    });

    grid.append(itemCard, choiceCard);
    el.append(grid);
    await openPopup(el);
}

async function runGachaRoll(mode = 'items', hint = '') {
    const st = store();
    if (!st) return toastr.warning('Сначала открой чат', 'Блокнот рассказчика');
    if (!gachaOn(st)) return toastr.info('Гача выключена в этом чате — включи её в блокноте, вкладка «Сюжет»', '🎰 Гача');
    if (st.gacha.active?.status === 'choosing') return presentGacha();
    if (!gachaSpinsLeft(st)) return toastr.info(`На этом посте удачу уже испытывали ${GACHA_LIMIT} раза. Снова можно будет со следующим постом.`, '🎰 Гача');
    const rarities = rollGacha(st.gacha);
    const statusText = mode === 'choices' ? '🎰 Модель придумывает варианты…' : '🎰 Крутим удачу…';
    const ok = await withBusy(statusText, async s2 => {
        const raw = await quietGenerate(gachaPrompt(s2, rarities, hint, mode));
        s2.lastRaw = String(raw ?? '');
        const { place, items } = parseGacha(raw, rarities);
        if (items.length < 2) {
            toastr.warning('Модель не выложила варианты по формату — загляни в «Последний ответ модели»', '🎰 Гача');
            return false;
        }
        s2.gacha.spins.push(ctx().chat.length);
        s2.gacha.total = (s2.gacha.total || 0) + 1;
        s2.gacha.stats = s2.gacha.stats || {};
        rarities.forEach(r => { s2.gacha.stats[r] = (s2.gacha.stats[r] || 0) + 1; });
        s2.gacha.active = { mode, place: place || (mode === 'choices' ? (hint || 'Случайный выбор') : 'Находки'), options: items, status: 'choosing', at: ctx().chat.length, date: s2.time.date || '' };
        return true;
    });
    if (ok) presentGacha();
}

async function startGacha(hintArg, modeArg) {
    const st = store();
    if (!st) return toastr.warning('Сначала открой чат', 'Блокнот рассказчика');
    if (st.gacha.active?.status === 'choosing') return presentGacha();
    if (modeArg === 'items' || modeArg === 'choices') {
        const hint = typeof hintArg === 'string' ? hintArg : '';
        return runGachaRoll(modeArg, hint);
    }
    return openGachaLauncher();
}
const presentGacha = () => {
    const a = store()?.gacha?.active;
    if (a?.mode === 'choices') return showGachaPopup();
    return openWhenReady('gacha', showGachaPopup);
};

async function showGachaPopup() {
    const st = store();
    const a = st?.gacha.active;
    if (!a || a.status !== 'choosing') return;
    const isChoices = a.mode === 'choices';
    const visual = !isChoices && wantImages();
    const el = $(`<div class="nnb-pop${visual ? ' nnb-pop-visual' : ''}"><h3></h3></div>`);
    el.find('h3').text(`${isChoices ? '✨' : '🎰'} ${a.place || (isChoices ? 'Варианты' : 'Находки')}`);
    el.append($('<div class="nnb-pop-sub"></div>').text(isChoices
        ? 'Выбери подходящий вариант — он сразу вплетётся в сюжет (в шкатулку не кладётся).'
        : 'Бери, что приглянулось, — можно несколько. Остальное уйдёт другим.'));
    const pick = async i => {
        if (a.options[i]?.taken) return;
        await chooseFind(i);
        el.find('.nnb-card-pick').eq(i).addClass('nnb-taken');
        leave.html('<i class="fa-solid fa-check"></i> Готово');
        if (playNowBtn) playNowBtn.show();
        if (a.options.every(o => o.taken)) closePopupOf(el);
    };
    const label = x => `${rarityOf(x.rarity).stars} ${rarityOf(x.rarity).name}${x.price ? ` · ${x.price}` : ''}`;
    if (visual) {
        el.append(visualPicker({ kind: 'gacha', items: a.options, title: x => x.title, label, onPick: pick, field: 'image', failField: 'imageFailed', a, cardClass: x => `nnb-rar nnb-rar-${x.rarity}${x.taken ? ' nnb-taken' : ''}` }));
    } else {
        const grid = $('<div class="nnb-cards nnb-cards-text"></div>');
        a.options.forEach((x, i) => {
            const card = $(`<div class="nnb-card-pick nnb-rar nnb-rar-${x.rarity}${x.taken ? ' nnb-taken' : ''}" tabindex="0"><div class="nnb-card-body"><div class="nnb-card-kind"></div><div class="nnb-card-title"></div><div class="nnb-card-desc"></div></div></div>`);
            card.find('.nnb-card-kind').text(label(x));
            card.find('.nnb-card-title').text(x.title);
            card.find('.nnb-card-desc').text(x.desc);
            card.on('click', () => pick(i));
            grid.append(card);
        });
        el.append(grid);
    }
    const anyTaken = () => a.options.some(o => o.taken);
    let playNowBtn = null;
    if (isChoices) {
        playNowBtn = $('<div class="menu_button nnb-btn-primary"></div>')
            .html('<i class="fa-solid fa-wand-magic-sparkles"></i> Отыграть сразу')
            .toggle(anyTaken())
            .on('click', async () => {
                closePopupOf(el);
                if (st.gacha.active === a) await finishGacha();
                const send = $('#send_but');
                if (send.length) send.trigger('click');
                else if (typeof ctx().generate === 'function') ctx().generate('normal');
            });
    }
    const rerollTopicBtn = $('<div class="menu_button"><i class="fa-solid fa-sliders"></i> Указать, что ищем / Перебросить</div>').on('click', async () => {
        closePopupOf(el);
        let topic = null;
        if (isChoices) {
            topic = await askChoicesTopicModal('');
        } else {
            topic = await askText('Что именно мы ищем или выбираем? (Например: «туфли или ботильоны в обувном», «платье на вечер», «сумочка», «книга», «предмет интерьера в комнату»)', a.place || '');
        }
        if (topic === null) return;
        st.gacha.active = null;
        if (st.gacha.spins.length) st.gacha.spins.pop();
        await commit();
        await runGachaRoll(isChoices ? 'choices' : 'items', topic.trim());
    });
    const leave = $('<div class="menu_button"></div>').html(anyTaken() ? '<i class="fa-solid fa-check"></i> Готово' : '<i class="fa-solid fa-person-walking-arrow-right"></i> Уйти ни с чем').on('click', async () => {
        closePopupOf(el);
        if (!anyTaken()) { st.gacha.active = null; await commit(); }
    });
    const row = $(`<div class="nnb-pop-row${visual ? ' nnb-pop-links' : ''}" style="flex-wrap:wrap; gap:6px;"></div>`);
    if (playNowBtn) row.append(playNowBtn);
    if (rerollTopicBtn) row.append(rerollTopicBtn);
    row.append(leave);
    el.append(row);
    await openPopup(el, visual);
    if (anyTaken() && st.gacha.active === a) await finishGacha();
}

async function finishGacha() {
    const st = store();
    const a = st?.gacha.active;
    if (!a) return;
    const left = a.options.filter(o => !o.taken).map(o => o.title);
    (Array.isArray(st.gacha.pending) ? st.gacha.pending : []).forEach(p => { if (p.spin === a.spin) p.others = left; });
    st.gacha.active = null;
    await commit();
}

async function chooseFind(i) {
    const st = store();
    const a = st?.gacha.active;
    const x = a?.options[i];
    if (!x) return;
    if (!a.spin) a.spin = Date.now();
    x.taken = true;
    const isChoices = a.mode === 'choices';
    const others = a.options.filter(o => !o.taken).map(o => o.title);
    const len = ctx().chat.length;

    if (isChoices) {
        if (!Array.isArray(st.gacha.choices)) st.gacha.choices = [];
        if (!st.gacha.nextChoiceId) st.gacha.nextChoiceId = 1;
        const choiceEntry = {
            id: st.gacha.nextChoiceId++,
            topic: a.place || 'Выбор',
            title: x.title,
            desc: x.desc,
            detail: x.price || '',
            hook: x.hook || '',
            rarity: x.rarity,
            pinned: false,
            date: a.date || st.time?.date || '',
            at: len,
        };
        st.gacha.choices.push(choiceEntry);
        if (st.gacha.choices.length > 30) st.gacha.choices.shift();
        const prev = Array.isArray(st.gacha.pending) ? st.gacha.pending.filter(p => p.at === len) : [];
        st.gacha.pending = [...prev, { mode: 'choices', title: x.title, desc: x.desc, hook: x.hook, rarity: x.rarity, place: a.place, price: x.price, others, at: len, spin: a.spin }];
        if (x.rarity === 'legendary' && st.direction.intrigues && x.hook) {
            st.intrigues.push({ id: st.nextIntrigueId++, tag: a.place || 'случай', text: `${x.title}: ${x.hook}`, clues: [], at: len });
        }
        await commit();
        const r = rarityOf(x.rarity);
        toastr.success(`${r.icon} ${escapeHtml(r.name)}: «${escapeHtml(x.title)}» — выбрано для сюжета!`, '✨ Варианты', { escapeHtml: false, timeOut: 7000 });
        return;
    }

    const singleGachaUrl = (x.isSingleImage && x.image) ? x.image : (Array.isArray(a.individualGachaImages) && a.individualGachaImages[i]) ? a.individualGachaImages[i] : '';
    const itemImageUrl = singleGachaUrl || a.image || '';
    const isSingleItemImg = !!singleGachaUrl;
    let crop = null;
    if (isSingleItemImg) {
        crop = { x: 0, y: 0, w: 1, h: 1 };
    } else if (a.image) {
        try {
            const crops = await smartCrops(a.image, a.options.length, 'gacha', a.imageLayout);
            crop = crops[i] || null;
        } catch (e) { /* режем поровну */ }
        if (!crop) { const n = a.imageLayout?.cols || a.options.length; crop = { x: i / n, y: 0, w: 1 / n, h: 1 }; }
    }
    const cost = parsePriceNumber(x.price);
    let spentText = '';
    if (cost > 0 && st.wallet) {
        if (st.wallet.balance < cost) {
            if (!confirm(`В кошельке ${formatMoney(st.wallet.balance, st)}, а «${x.title}» стоит ${formatMoney(cost, st)}. Всё равно купить (кошелёк уйдёт в 0)?`)) {
                x.taken = false;
                return;
            }
            st.wallet.balance = 0;
        } else {
            st.wallet.balance -= cost;
        }
        spentText = ` (−${formatMoney(cost, st)}, остаток: ${formatMoney(st.wallet.balance, st)})`;
    }
    const where = [a.place, a.date ? formatDate(a.date) : ''].filter(Boolean).join(', ');
    const newItem = {
        id: st.wardrobe.nextItemId++, kind: findKind(`${x.title} ${a.place || ''}`), title: x.title, desc: x.desc, en: x.en || '', origin: where ? `находка: ${where}` : 'находка',
        rarity: x.rarity, hook: x.hook, price: x.price, buyPrice: cost, onCounter: false, image: itemImageUrl, crop, imageLayout: isSingleItemImg ? { rows: 1, cols: 1 } : (a.imageLayout || null), isSingleImage: isSingleItemImg, at: len,
    };
    st.wardrobe.box.push(newItem);
    if (/одежд|плать|пальто|куртк|костюм|тренч|юбк|блуз|свитер|кардиган|пижам|бель[её]|рубашк|брюк|джинс/i.test(`${x.title} ${a.place || ''}`)) {
        addLookToCloset(st, {
            category: 'Повседневный',
            title: x.title,
            desc: x.desc,
            en: x.en || x.title,
            effects: x.hook || '',
            image: itemImageUrl,
            crop,
            imageLayout: isSingleItemImg ? { rows: 1, cols: 1 } : (a.imageLayout || null),
            isSingleImage: isSingleItemImg,
        });
    }
    const prev = Array.isArray(st.gacha.pending) ? st.gacha.pending.filter(p => p.at === len) : [];
    st.gacha.pending = [...prev, { mode: 'items', title: x.title, desc: x.desc, hook: x.hook, rarity: x.rarity, place: a.place, price: x.price, others, at: len, spin: a.spin }];
    // легендарная находка открывает тайну
    if (x.rarity === 'legendary' && st.direction.intrigues && x.hook) {
        st.intrigues.push({ id: st.nextIntrigueId++, tag: 'находка', text: `${x.title}: ${x.hook}`, clues: [], at: len });
    }
    await commit();
    const r = rarityOf(x.rarity);
    toastr.success(`${r.icon} ${escapeHtml(r.name)}: «${escapeHtml(x.title)}» — в личной шкатулке${escapeHtml(spentText)}. Можно выставить на прилавок в один клик!`, '🎰 Находки', { escapeHtml: false, timeOut: 7000 });
}

function gachaInjection(st, mode = 'all') {
    if (!gachaOn(st)) return '';
    const names = storyNames();
    const out = [];

    const pinned = (st?.gacha?.choices || []).filter(c => c.pinned);
    if (pinned.length && mode !== 'dynamic') {
        out.push(`[Закреплённые выборы ${names.user}: ${pinned.map(c => `${c.topic ? `${c.topic}: ` : ''}«${c.title}»${c.detail ? ` (${c.detail})` : ''}${c.desc ? ` — ${c.desc}` : ''}`).join('; ')}.]`);
    }
    if (mode === 'static') return out.join('\n\n');

    let list = st?.gacha?.pending;
    if (list) {
        if (!Array.isArray(list)) list = [list];
        const itemsList = list.filter(p => p.mode !== 'choices');
        const choicesList = list.filter(p => p.mode === 'choices');

        if (itemsList.length) {
            const oneItem = p => {
                const r = rarityOf(p.rarity);
                return `${p.price ? `купил(а) за ${p.price}` : 'взял(а)'}${p.place ? ` (${p.place})` : ''} ${r.name.toLowerCase().replace(/ая$/, 'ую')} находку — «${p.title}»${p.desc ? `: ${p.desc}` : ''}.${p.hook ? ` Как её обыграть: ${p.hook}.` : ''}${p.others?.length && !itemsList.some(q => q !== p && q.spin && q.spin === p.spin && itemsList.indexOf(q) > itemsList.indexOf(p)) ? ` Остальное (${p.others.join(', ')}) осталось на прилавке или досталось другим.` : ''}`;
            };
            const body = itemsList.length === 1 ? `${names.user} только что ${oneItem(itemsList[0])}` : `${names.user} только что сделал(а) несколько находок:\n${itemsList.map((p, i) => `${i + 1}) ${oneItem(p)}`).join('\n')}`;
            out.push(`[Находка: ${body}\nВ СЛЕДУЮЩЕМ ответе обязательно обыграй ${itemsList.length === 1 ? 'её' : 'их'}. Чем реже находка, тем заметнее её след в сюжете.]`);
        }

        if (choicesList.length) {
            const oneChoice = p => {
                const r = rarityOf(p.rarity);
                return `в теме «${p.place || 'выбор'}» выпал ${r.name.toLowerCase().replace(/ая$/, 'ый')} вариант — «${p.title}»${p.price ? ` (${p.price})` : ''}${p.desc ? `: ${p.desc}` : ''}.${p.hook ? ` Сюжетный крючок (обыграй естественно): ${p.hook}.` : ''}${p.others?.length && !choicesList.some(q => q !== p && q.spin && q.spin === p.spin && choicesList.indexOf(q) > choicesList.indexOf(p)) ? ` Другие варианты (${p.others.join(', ')}) не выбраны.` : ''}`;
            };
            const body = choicesList.length === 1 ? `Для ${names.user} только что ${oneChoice(choicesList[0])}` : `Для ${names.user} только что выпали следующие варианты:\n${choicesList.map((p, i) => `${i + 1}) ${oneChoice(p)}`).join('\n')}`;
            out.push(`[Выбор судьбы: ${body}\nВ СЛЕДУЮЩЕМ ответе обязательно естественно вплети и обыграй этот выбор в сцене (будь то книга/фильм на вечер, поход куда-то, работа/вакансия, знакомство или занятие). Чем выше редкость, тем ярче последствия для сюжета.]`);
        }
    }
    return out.join('\n\n');
}
function clearGachaPending() {
    const st = store();
    if (!st?.gacha?.pending) return;
    const list = Array.isArray(st.gacha.pending) ? st.gacha.pending : [st.gacha.pending];
    const last = ctx().chat?.[ctx().chat.length - 1];
    if (!last || last.is_user || ctx().chat.length <= Math.max(...list.map(p => p.at))) return;
    st.gacha.pending = null;
    ctx().saveMetadata();
}

function revealPrompt(st) {
    const a = st.wardrobe.active;
    const names = storyNames();
    const arcs = st.direction.arcs && st.arcs.length ? `\nТекущие арки:\n${formatArcs(st, true)}` : '';
    return [
        '[OOC: Пауза в ролевой игре. Сейчас ты НЕ пишешь ответ персонажа. Ты — помощник автора.',
        `${names.user} выбрал(а) наряд «${a.look.title}» — ${a.look.desc}${a.occasion ? ` (для: ${a.occasion})` : ''}.`,
        a.look.effects ? `Задуманные последствия: ${a.look.effects}.` : '',
        a.accent ? `Штрих к образу: ${a.accent.title}${a.accent.effects ? ` (задумано: ${a.accent.effects})` : ''}.` : '',
        'Перечитай чат: как этот выбор на самом деле сыграл в сцене?' + arcs,
        'Ответь строками, без пояснений:',
        'RESULT: итог в 1–2 предложениях, с юмором и теплом — кто как отреагировал и чем этот образ запомнится',
        st.direction.arcs && st.arcs.length ? 'STIMULUS #A1: что изменилось — только если наряд действительно подтолкнул чью-то арку (иначе не пиши)' : '',
        st.direction.npcs && st.npcs.length ? 'SCALE [Имя]: дружба=+2 — только если наряд действительно заметно повлиял на отношение NPC (иначе не пиши)' : '',
        ']',
    ].filter(Boolean).join('\n');
}

async function revealOutfit(st) {
    const a = st.wardrobe.active;
    if (!a || a.status !== 'worn') return false;
    const raw = await quietGenerate(revealPrompt(st));
    let result = '';
    for (const line of answerLines(raw)) {
        const m = line.match(/^RESULT\s*[:：—–-]\s*(.+)$/i);
        if (m) { result = m[1].trim().replace(/\]$/, ''); break; }
    }
    const res = parseAndApply(raw.split('\n').filter(l => /STIMULUS|SCALE/i.test(l)).join('\n'));
    const entry = {
        occasion: a.occasion, title: a.look.title, desc: a.look.desc, effects: a.look.effects,
        result: result || 'Сцена прошла — каждый запомнил этот образ по-своему.',
        others: (a.options || []).filter(o => o !== a.look).map(o => ({ title: o.title, effects: o.effects })),
        accent: a.accent ? { kind: a.accent.kind, title: a.accent.title, effects: a.accent.effects || '', origin: a.accent.origin || '' } : null,
        otherAccents: (a.accents || []).filter(x => !a.accent || x.title !== a.accent.title).map(x => ({ kind: x.kind, title: x.title, effects: x.effects })),
        image: a.image || '',
        date: st.time.date || '', stimuli: res.stimuli || 0,
    };
    if (a.accent?.kind === 'stone') {
        st.wardrobe.aura = { title: a.accent.title, desc: a.accent.desc || '', effects: a.accent.effects || '', until: st.time.date ? addDays(st.time.date, 3) : '', untilMsg: (ctx().chat?.length ?? 0) + 40 };
    }
    st.wardrobe.history.push(entry);
    if (st.wardrobe.history.length > 20) st.wardrobe.history.shift();
    st.wardrobe.active = null;
    if (st.direction.time && st.time.date) addEvent(st, st.time.date, `Образ «${entry.title}»${entry.occasion ? ` (${entry.occasion})` : ''}: ${entry.result}`);
    st.wardrobe.lastReveal = entry;
    return true;
}

async function runReveal() {
    const ok = await withBusy('🎭 Модель подводит итог образа…', st => revealOutfit(st));
    if (ok) showRevealPopup();
}

function closePopupOf(el) {
    let dlg = $(el).closest('dialog');
    if (!dlg.length) dlg = $(el).closest('.popup');
    const btn = dlg.find('.popup-button-ok').add(dlg.find('.popup-button-cancel')).first();
    if (btn.length) btn.trigger('click');
    else dlg[0]?.close?.();
}

async function openPopup(el, wide = false) {
    const c = ctx();
    if (typeof c.callGenericPopup === 'function' && c.POPUP_TYPE) {
        await c.callGenericPopup(el[0], c.POPUP_TYPE.TEXT, '', { okButton: 'Закрыть', allowVerticalScrolling: true, wide, large: wide });
        return true;
    }
    return false;
}

async function showWardrobePopup() {
    const st = store();
    const a = st?.wardrobe.active;
    if (!a || a.status !== 'choosing') return;
    const selected = new Set([0]);
    let wearIndex = 0;
    let carouselMode = true; // Всегда показываем по 1 карточке на экран с удобным перелистыванием!
    let currentSlide = 0;

    const visual = wantImages();
    const el = $(`<div class="nnb-pop${visual ? ' nnb-pop-visual' : ''}"><h3>👗 Выбери образы (можно несколько!)</h3></div>`);
    if (a.occasion) el.append($('<div class="nnb-pop-sub"></div>').text(`Повод: ${a.occasion}`));
    el.append('<div class="nnb-pop-sub">Нажатие на карточку <b>не закрывает окно</b> — спокойно рассмотри все 5 вариантов, отметь галочками <b>«☑️ В шкаф»</b> все понравившиеся наряды и нажми кнопку подтверждения внизу:</div>');

    // Верхняя панель управления выбором и видом
    const topToolbar = $('<div style="display:flex; justify-content:space-between; align-items:center; gap:8px; flex-wrap:wrap; margin:4px 0;"></div>');
    const leftTools = $('<div style="display:flex; gap:6px; flex-wrap:wrap; align-items:center;"></div>');
    const selectAllBtn = $('<div class="menu_button" style="padding:4px 10px; font-size:0.85em;"><i class="fa-solid fa-check-double"></i> Отметить все 5 в шкаф</div>');
    leftTools.append(selectAllBtn);

    const rightTools = $('<div style="display:flex; gap:6px; flex-wrap:wrap; align-items:center;"></div>');
    const viewModeBtn = $('<div class="menu_button" style="padding:4px 10px; font-size:0.85em;" title="Переключить вид: все 5 сразу или по одному крупно"></div>');
    const redrawBtn = $('<div class="menu_button" style="padding:4px 10px; font-size:0.85em;" title="Перерисовать картинку образов"><i class="fa-solid fa-palette"></i> Перерисовать</div>');
    const fullImgBtn = $('<div class="menu_button" style="padding:4px 10px; font-size:0.85em;" title="Открыть общий лист образов во весь экран"><i class="fa-solid fa-up-right-and-down-left-from-center"></i> Весь лист</div>');
    if (visual) {
        rightTools.append(redrawBtn, fullImgBtn);
    }
    topToolbar.append(leftTools, rightTools);
    el.append(topToolbar);

    // Навигация стрелками ◀ и ▶ (без свайпов, чтобы ничего не сбивалось)
    const carouselNav = $('<div style="display:flex; align-items:center; justify-content:space-between; gap:8px; margin:4px 0; padding:6px 10px; border-radius:10px; background:color-mix(in srgb, var(--SmartThemeQuoteColor, #8b78c4) 10%, transparent);"></div>');
    const prevSlideBtn = $('<div class="menu_button" style="padding:6px 14px; font-weight:700;"><i class="fa-solid fa-arrow-left"></i> Назад</div>');
    const slideIndicator = $('<div style="font-weight:700; font-size:0.95em; text-align:center;"></div>');
    const nextSlideBtn = $('<div class="menu_button" style="padding:6px 14px; font-weight:700;">Вперёд <i class="fa-solid fa-arrow-right"></i></div>');
    carouselNav.append(prevSlideBtn, slideIndicator, nextSlideBtn);
    el.append(carouselNav);

    const cardsHost = $('<div class="nnb-looks-host"></div>');
    el.append(cardsHost);

    const confirmBtn = $('<div class="menu_button nnb-btn-primary" style="padding:8px 14px; font-size:0.95em;"></div>');
    const saveOnlyBtn = $('<div class="menu_button" style="padding:8px 12px;"></div>');
    const saveAllQuickBtn = $('<div class="menu_button" style="padding:8px 12px;"><i class="fa-solid fa-layer-group"></i> Сохранить все 5 в шкаф</div>');

    const n = Math.min(a.options.length, 5);
    const layoutOf = () => a.imageLayout || looksLayout(n);
    const cellOf = i => {
        const L = layoutOf();
        const r = Math.floor(i / L.cols), c = i % L.cols;
        const colW = 1 / L.cols, rowH = 1 / L.rows;
        const padX = colW * 0.08, padY = rowH * 0.08;
        return {
            x: c * colW + padX,
            y: r * rowH + padY,
            w: colW - padX * 2,
            h: rowH - padY * 2,
        };
    };

    const updateSelectionUI = () => {
        const allSelected = selected.size === a.options.length;
        selectAllBtn.html(allSelected
            ? '<i class="fa-solid fa-square-minus"></i> Снять отметки (кроме надеваемого)'
            : `<i class="fa-solid fa-check-double"></i> Отметить все ${a.options.length} в шкаф`);

        viewModeBtn.html(carouselMode
            ? '<i class="fa-solid fa-table-cells-large"></i> Показать все 5 сразу'
            : '<i class="fa-solid fa-maximize"></i> Листать по одному крупно');
        fullImgBtn.toggle(!!a.image);

        if (carouselMode) {
            carouselNav.css('display', 'flex');
            slideIndicator.text(`Наряд ${currentSlide + 1} из ${a.options.length}`);
            prevSlideBtn.css({ opacity: currentSlide <= 0 ? 0.4 : 1, pointerEvents: currentSlide <= 0 ? 'none' : 'auto' });
            nextSlideBtn.css({ opacity: currentSlide >= a.options.length - 1 ? 0.4 : 1, pointerEvents: currentSlide >= a.options.length - 1 ? 'none' : 'auto' });
        } else {
            carouselNav.hide();
        }

        cardsHost.find('.nnb-look-unified').each(function (idx) {
            const cardEl = $(this);
            const isSel = selected.has(idx);
            const isWear = wearIndex === idx;

            if (carouselMode) {
                cardEl.toggle(idx === currentSlide);
            } else {
                cardEl.show();
            }

            cardEl.css({
                'border-color': isWear
                    ? 'var(--SmartThemeQuoteColor, #8b78c4)'
                    : isSel
                        ? 'color-mix(in srgb, var(--SmartThemeQuoteColor, #8b78c4) 65%, transparent)'
                        : 'var(--SmartThemeBorderColor)',
                'border-width': isWear ? '2px' : '1px',
                'background': isWear
                    ? 'color-mix(in srgb, var(--SmartThemeQuoteColor, #8b78c4) 14%, transparent)'
                    : isSel
                        ? 'color-mix(in srgb, var(--SmartThemeQuoteColor, #8b78c4) 6%, transparent)'
                        : 'color-mix(in srgb, var(--SmartThemeBodyColor, #888) 4%, transparent)',
            });

            const cbInput = cardEl.find('.nnb-look-cb');
            cbInput.prop('checked', isSel);

            const cbPill = cardEl.find('.nnb-look-check-pill');
            cbPill.css({
                'border-color': isSel ? 'var(--SmartThemeQuoteColor, #8b78c4)' : 'var(--SmartThemeBorderColor)',
                'background': isSel ? 'color-mix(in srgb, var(--SmartThemeQuoteColor, #8b78c4) 24%, transparent)' : 'transparent',
                'font-weight': isSel ? '700' : '500',
            });
            cardEl.find('.nnb-look-cb-label').text(isSel ? 'В шкаф (отмечено)' : 'Сохранить в шкаф');

            const wearBtn = cardEl.find('.nnb-look-wear-btn');
            if (isWear) {
                wearBtn.addClass('nnb-btn-primary').html('<i class="fa-solid fa-shirt"></i> Выбран, чтобы надеть');
            } else {
                wearBtn.removeClass('nnb-btn-primary').html('<i class="fa-solid fa-shirt"></i> Надеть этот');
            }
        });

        const saveCount = new Set([wearIndex, ...selected]).size;
        confirmBtn.html(`<i class="fa-solid fa-shirt"></i> Надеть «${escapeHtml(a.options[wearIndex]?.title || '')}» и сохранить в шкаф (${saveCount})`);
        saveOnlyBtn.html(`<i class="fa-solid fa-box-archive"></i> Только сохранить отмеченные в шкаф (${selected.size || 1})`);
    };

    const renderCards = (url) => {
        cardsHost.empty();
        const hasUrl = !!url;
        const grid = $('<div></div>');
        const applyGridStyle = () => {
            if (carouselMode) {
                grid.css({
                    display: 'block',
                });
            } else if (hasUrl) {
                grid.css({
                    display: 'grid',
                    gridTemplateColumns: 'repeat(auto-fill, minmax(210px, 1fr))',
                    gap: '12px',
                    alignItems: 'stretch',
                });
            } else {
                grid.css({
                    display: 'flex',
                    flexDirection: 'column',
                    gap: '8px',
                });
            }
        };
        applyGridStyle();

        const imgs = [];
        a.options.forEach((o, i) => {
            const card = $('<div class="nnb-look nnb-look-unified" tabindex="0" style="display:flex; flex-direction:column; justify-content:space-between; gap:8px; padding:10px; border-radius:12px; cursor:pointer;"></div>');

            // 1. Верхняя панель карточки: заметная галочка «☑️ Сохранить в шкаф» + кнопка «👕 Надеть этот»
            const topBar = $('<div style="display:flex; justify-content:space-between; align-items:center; gap:6px; flex-wrap:wrap;"></div>');

            const checkPill = $(`
                <label class="nnb-look-check-pill" style="display:inline-flex; align-items:center; gap:7px; padding:5px 10px; border-radius:8px; border:1px solid var(--SmartThemeBorderColor); cursor:pointer; user-select:none; font-size:0.86em; transition:all 0.15s ease;">
                    <input type="checkbox" class="nnb-look-cb" style="width:17px !important; height:17px !important; margin:0 !important; cursor:pointer; accent-color:var(--SmartThemeQuoteColor, #8b78c4); display:inline-block !important; opacity:1 !important; appearance:auto !important; -webkit-appearance:checkbox !important;">
                    <span class="nnb-look-cb-label">Сохранить в шкаф</span>
                </label>
            `);

            checkPill.on('click', e => {
                e.stopPropagation();
            });
            checkPill.find('.nnb-look-cb').on('change', function (e) {
                e.stopPropagation();
                if ($(this).prop('checked')) {
                    selected.add(i);
                } else {
                    selected.delete(i);
                }
                updateSelectionUI();
            });

            const wearBtn = $('<div class="menu_button nnb-look-wear-btn" style="padding:4px 10px; font-size:0.83em; margin:0; white-space:nowrap;"></div>');
            wearBtn.on('click', e => {
                e.stopPropagation();
                wearIndex = i;
                selected.add(i);
                updateSelectionUI();
            });

            topBar.append(checkPill, wearBtn);
            card.append(topBar);

            // 2. Картинка образа (если есть)
            const singleUrlForCard = (o.isSingleImage && o.image) ? o.image : (Array.isArray(a.individualImages) && a.individualImages[i]) ? a.individualImages[i] : null;
            if (singleUrlForCard) {
                const imgWrap = $('<div style="position:relative; width:100%; margin:2px 0;"></div>');
                const img = $('<div class="nnb-card-img" style="border-radius:8px; overflow:hidden; width:100%; aspect-ratio:2/3; max-height:400px;"></div>');
                applyCrop(img, singleUrlForCard, { x: 0, y: 0, w: 1, h: 1 }, 832 / 1216);
                const redrawOneBtn = $('<div class="menu_button" style="position:absolute; right:8px; bottom:8px; padding:4px 9px; font-size:0.78em; background:rgba(20,16,30,0.82); border-radius:8px;" title="Перерисовать только этот наряд отдельным запросом"><i class="fa-solid fa-rotate"></i> Перерисовать этот</div>');
                redrawOneBtn.on('click', async e => {
                    e.stopPropagation();
                    redrawOneBtn.css({ opacity: 0.6, pointerEvents: 'none' }).html('<i class="fa-solid fa-spinner fa-spin"></i> Рисую…');
                    try {
                        const who = await ensureHeroineAppearanceEnForNai(st, a);
                        const newSingleUrl = await drawViaNovelAi(buildSingleOutfitPromptForNai(who, o), 'portrait', { extraNeg: 'blush, blushing, nose blush, full-face blush, heavy blush, embarrassed, shy, flustered, timid, awkward smile' });
                        if (newSingleUrl) {
                            o.image = newSingleUrl;
                            o.imageLayout = { rows: 1, cols: 1 };
                            o.crop = { x: 0, y: 0, w: 1, h: 1 };
                            o.isSingleImage = true;
                            if (!Array.isArray(a.individualImages)) a.individualImages = [];
                            a.individualImages[i] = newSingleUrl;
                            if (i === 0) a.image = newSingleUrl;
                            await ctx().saveMetadata();
                            renderCards(a.image || newSingleUrl);
                        }
                    } catch (err) {
                        toastr.warning(`Не удалось перерисовать наряд: ${escapeHtml(err?.message || err)}`, '👗 Гардероб', { escapeHtml: false });
                        redrawOneBtn.css({ opacity: 1, pointerEvents: 'auto' }).html('<i class="fa-solid fa-rotate"></i> Перерисовать этот');
                    }
                });
                imgWrap.append(img, redrawOneBtn);
                card.append(imgWrap);
            } else if (hasUrl && i < n) {
                const img = $('<div class="nnb-card-img" style="border-radius:8px; overflow:hidden; width:100%; aspect-ratio:1/2; max-height:380px; margin:2px 0;"></div>');
                applyCrop(img, url, cellOf(i), layoutOf().rows === 2 ? 2 / 3 : 1.5);
                card.append(img);
                imgs.push(img);
            }

            // 3. Название, категория и описание
            const body = $('<div style="flex:1; display:flex; flex-direction:column; gap:4px;"></div>');
            const catBadge = o.category ? ` · ${o.category}` : '';
            body.append($('<div class="nnb-look-title" style="font-size:0.98em; line-height:1.3;"></div>').text(`${i + 1}. «${o.title}»${catBadge}`));
            if (o.desc) {
                body.append($('<div class="nnb-look-desc" style="font-size:0.86em; line-height:1.38; opacity:0.88;"></div>').text(o.desc));
            }
            card.append(body);

            // Переключение только кнопками-стрелками ◀ и ▶ (без свайпов)

            // Клик по самой карточке ТОЛЬКО переключает галочку «В шкаф» (и НЕ закрывает окно!)
            card.on('click', () => {
                if (selected.has(i)) {
                    if (selected.size > 1) selected.delete(i);
                } else {
                    selected.add(i);
                    wearIndex = i;
                }
                updateSelectionUI();
            });

            grid.append(card);
        });

        cardsHost.append(grid);
        updateSelectionUI();

        if (hasUrl && imgs.length && typeof Image === 'function') {
            const probe = new Image();
            probe.onload = async () => {
                const ratio = probe.naturalWidth / probe.naturalHeight || 1.5;
                const crops = await smartCrops(url, n, 'looks', layoutOf());
                imgs.forEach((elImg, idx) => {
                    applyCrop(elImg, url, crops[idx] || cellOf(idx), ratio);
                    if (crops.bg) elImg.css('background-color', crops.bg);
                });
            };
            probe.src = url;
        }
    };

    selectAllBtn.on('click', () => {
        if (selected.size === a.options.length) {
            selected.clear();
            selected.add(wearIndex);
        } else {
            a.options.forEach((_, idx) => selected.add(idx));
        }
        updateSelectionUI();
    });

    viewModeBtn.on('click', () => {
        carouselMode = !carouselMode;
        currentSlide = wearIndex;
        renderCards(a.image || '');
    });

    prevSlideBtn.on('click', () => {
        if (currentSlide > 0) {
            currentSlide--;
            updateSelectionUI();
        }
    });
    nextSlideBtn.on('click', () => {
        if (currentSlide < a.options.length - 1) {
            currentSlide++;
            updateSelectionUI();
        }
    });

    const versionBar = $('<div style="display:none; gap:6px; flex-wrap:wrap; align-items:center; margin:4px 0; padding:6px 10px; border-radius:8px; background:color-mix(in srgb, var(--SmartThemeQuoteColor, #8b78c4) 12%, transparent);"></div>');
    el.insertBefore ? null : null;
    topToolbar.after(versionBar);

    const refreshVersionBar = () => {
        versionBar.empty();
        const hist = a.imageHistory || [];
        if (hist.length <= 1) {
            versionBar.hide();
            return;
        }
        versionBar.css('display', 'flex');
        versionBar.append('<span style="font-size:0.84em; font-weight:600;">🖼 Сохранённые генерации:</span>');
        hist.forEach((hEntry, hIdx) => {
            const isCur = hEntry.url === a.image;
            const btn = $(`<div class="menu_button ${isCur ? 'nnb-btn-primary' : ''}" style="padding:3px 10px; font-size:0.82em; margin:0;">Вариант ${hIdx + 1}</div>`).on('click', () => {
                a.image = hEntry.url;
                if (hEntry.layout) a.imageLayout = hEntry.layout;
                if (Array.isArray(hEntry.individualImages) && hEntry.individualImages.length) {
                    a.individualImages = [...hEntry.individualImages];
                    a.options.forEach((opt, oIdx) => {
                        if (hEntry.individualImages[oIdx]) {
                            opt.image = hEntry.individualImages[oIdx];
                            opt.isSingleImage = true;
                        }
                    });
                }
                ctx().saveMetadata();
                renderCards(a.image);
                refreshVersionBar();
            });
            versionBar.append(btn);
        });
        const saveBothBtn = $('<div class="menu_button" style="padding:3px 10px; font-size:0.82em; margin:0;" title="Сохранить отмеченные образы в шкаф сразу со ВСЕМИ сгенерированными вариантами картинок!"><i class="fa-solid fa-clone"></i> Сохранить обе версии в шкаф</div>').on('click', async () => {
            const toSave = selected.size ? [...selected] : [wearIndex];
            let countAdded = 0;
            for (let vIdx = 0; vIdx < hist.length; vIdx++) {
                const hEntry = hist[vIdx];
                a.image = hEntry.url;
                if (hEntry.layout) a.imageLayout = hEntry.layout;
                if (Array.isArray(hEntry.individualImages) && hEntry.individualImages.length) {
                    a.individualImages = [...hEntry.individualImages];
                    a.options.forEach((opt, oIdx) => {
                        if (hEntry.individualImages[oIdx]) {
                            opt.image = hEntry.individualImages[oIdx];
                            opt.isSingleImage = true;
                            opt.imageLayout = { rows: 1, cols: 1 };
                            opt.crop = { x: 0, y: 0, w: 1, h: 1 };
                        }
                    });
                } else {
                    a.individualImages = null;
                    a.options.forEach(opt => { opt.isSingleImage = false; });
                }
                await attachLookCropsFromActive(a);
                toSave.forEach(idx => {
                    const baseOpt = a.options[idx];
                    if (!baseOpt) return;
                    const suffix = hist.length > 1 ? ` (рис. ${vIdx + 1})` : '';
                    addLookToCloset(st, { ...baseOpt, title: `${baseOpt.title}${suffix}` }, normalizeClosetCat(baseOpt.category || a.occasion));
                    countAdded++;
                });
            }
            await commit();
            toastr.success(`В шкаф сохранены обе версии рисовки (${countAdded} обр.)!`, '👗 Гардероб');
        });
        versionBar.append(saveBothBtn);
    };

    redrawBtn.on('click', () => {
        cardsHost.html('<div class="nnb-pop-sub nnb-wait" style="padding:20px; text-align:center;">🎨 Рисую новый вариант образов (предыдущая картинка тоже сохранится!) через ' + escapeHtml(imageSourceName()) + '…</div>');
        ensurePicture('looks', !drawingKind.looks, url => {
            renderCards(url || '');
            refreshVersionBar();
        });
    });

    fullImgBtn.on('click', () => {
        if (a.image) window.open(a.image, '_blank');
    });

    if (visual && !a.image && !a.imageFailed) {
        cardsHost.html('<div class="nnb-pop-sub nnb-wait" style="padding:20px; text-align:center;">🎨 Рисую образы через ' + escapeHtml(imageSourceName()) + '…</div>');
        ensurePicture('looks', false, url => { renderCards(url || ''); refreshVersionBar(); });
    } else {
        renderCards(visual ? (a.image || '') : '');
        refreshVersionBar();
    }

    confirmBtn.on('click', async () => {
        closePopupOf(el);
        selected.add(wearIndex);
        await chooseOutfit(wearIndex, null, [...selected]);
    });
    saveOnlyBtn.on('click', async () => {
        await attachLookCropsFromActive(a);
        const toSave = selected.size ? [...selected] : [wearIndex];
        toSave.forEach(idx => addLookToCloset(st, a.options[idx], normalizeClosetCat(a.options[idx].category || a.occasion)));
        st.wardrobe.active = null;
        await commit();
        closePopupOf(el);
        toastr.success(`Сохранено в шкаф: ${toSave.length} обр. (без смены текущего наряда)`, '👗 Гардероб');
        await checkPendingTravel();
    });
    saveAllQuickBtn.on('click', async () => {
        await attachLookCropsFromActive(a);
        a.options.forEach(opt => addLookToCloset(st, opt, normalizeClosetCat(opt.category || a.occasion)));
        st.wardrobe.active = null;
        await commit();
        closePopupOf(el);
        toastr.success(`Все ${a.options.length} образов сохранены в шкаф!`, '👗 Гардероб');
        await checkPendingTravel();
    });

    const actRow = $('<div class="nnb-pop-row" style="margin-top:12px; flex-wrap:wrap; gap:8px;"></div>').append(confirmBtn, saveOnlyBtn, saveAllQuickBtn);
    el.append(actRow);

    const row = $(`<div class="nnb-pop-row${visual ? ' nnb-pop-links' : ''}" style="margin-top:8px;"></div>`);
    const closetBtn = $('<div class="menu_button"><i class="fa-solid fa-door-open"></i> Открыть шкаф</div>').on('click', () => {
        closePopupOf(el);
        openClosetPopup();
    });
    const own = $('<div class="menu_button"><i class="fa-solid fa-pen"></i> Свой вариант</div>');
    own.on('click', async () => {
        closePopupOf(el);
        const t = await askText('Опиши, что надето');
        if (t && t.trim()) await chooseOutfit(-1, t.trim());
    });
    const reroll = $('<div class="menu_button"><i class="fa-solid fa-dice"></i> Другие 5 образов</div>');
    reroll.on('click', () => { closePopupOf(el); rerollOutfits(); });
    row.append(closetBtn, own, reroll);
    if (st?.map?.pendingTravel) {
        const cancelTravel = $('<div class="menu_button"><i class="fa-solid fa-xmark"></i> Отмена поездки</div>');
        cancelTravel.on('click', async () => {
            closePopupOf(el);
            delete st.map.pendingTravel;
            st.wardrobe.active = null;
            await commit();
            toastr.info('Поездка отменена', '🗺 Карта');
        });
        row.append(cancelTravel);
    }
    el.append(row);
    if (!(await openPopup(el, true))) toastr.info('Образы готовы — выбери в блокноте, вкладка «Гардероб»', '👗 Гардероб');
}

function revealCard(entry) {
    const el = $('<div class="nnb-pop"><h3>🎭 Чем обернулся образ</h3></div>');
    el.append($('<div class="nnb-look-title"></div>').text(`«${entry.title}»${entry.occasion ? ` — ${entry.occasion}` : ''}`));
    el.append($('<div class="nnb-pop-result"></div>').text(entry.result));
    if (entry.effects) el.append($('<div class="nnb-pop-sub"></div>').text('Задумано было: ' + entry.effects));
    if (entry.accent) el.append($('<div class="nnb-pop-sub"></div>').text(`${(ACCENT_KINDS[entry.accent.kind] || ACCENT_KINDS.accessory).icon} Штрих «${entry.accent.title}»${entry.accent.effects ? `: ${entry.accent.effects}` : ''}`));
    if (entry.others?.length || entry.otherAccents?.length) {
        const det = $('<details><summary>А что было бы, если…</summary></details>');
        (entry.others || []).forEach(o => det.append($('<div class="nnb-pop-other"></div>').text(`«${o.title}»: ${o.effects || 'реакции не записаны'}`)));
        (entry.otherAccents || []).forEach(o => det.append($('<div class="nnb-pop-other"></div>').text(`${(ACCENT_KINDS[o.kind] || ACCENT_KINDS.accessory).icon} «${o.title}»: ${o.effects || 'реакции не записаны'}`)));
        el.append(det);
    }
    return el;
}

async function showRevealPopup() {
    const st = store();
    const entry = st?.wardrobe.lastReveal;
    if (!entry) return;
    delete st.wardrobe.lastReveal;
    ctx().saveMetadata();
    if (!(await openPopup(revealCard(entry)))) toastr.success(escapeHtml(entry.result), '🎭 ' + escapeHtml(entry.title), { escapeHtml: false, timeOut: 12000 });
}

// ---------- 🗺 Карта: места, куда можно пойти ----------
// кавычки снимаем только парные — «Кафе «Сова»» должно остаться целым
function unquote(t) {
    t = String(t || '').trim();
    const m = t.match(/^[«"](.*)[»"]$/);
    return (m && !/[«»]/.test(m[1].replace(/«[^»]*»/g, '')) ? m[1] : t).trim();
}
function mapOn(st) {
    return !!st?.direction?.map;
}
function findPlace(st, title) {
    const t = unquote(title).toLowerCase();
    return t ? st.map.places.find(p => p.title.toLowerCase() === t) : null;
}
function addPlace(st, line, origin) {
    const parts = String(line || '').split('|').map(x => x.trim());
    const title = parts[0] || '';
    const desc = (parts[1] || '').replace(/\]$/, '').trim();
    const hooks = parts.slice(2).join(' | ').replace(/\]$/, '').trim();
    const t = unquote(String(title || '').replace(/\]$/, ''));
    if (!t || t.length > 80 || findPlace(st, t) || st.map.places.length >= 40) return null;
    const pl = { id: st.map.nextId++, title: t, desc, hooks, origin, visits: 0, at: ctx().chat?.length ?? 0 };
    st.map.places.push(pl);
    return pl;
}
function buildMapSection(st) {
    if (!mapOn(st)) return '';
    const known = st.map.places.map(p => p.title).join('; ');
    return `Карта мест. Уже на карте: ${known || '(пусто)'}.
MAP: название | что это за место | 2–3 конкретных крючка и зацепки этого места через точку с запятой (необычная деталь, колоритный завсегдатай, слух или микро-ситуация) — если в чате появилось новое место, куда можно сходить, и его ещё нет на карте.
HERE: название — если герои сейчас в месте с карты.`;
}
function isGenericPlaceHint(text) {
    const s = String(text || '').trim().toLowerCase();
    if (!s) return false;
    if (/^(како[еяй]-?нибудь|что-?нибудь|любо[ейя]|незнаком|интересн|новое место|куда-?нибудь)/i.test(s)) return true;
    const genericWords = [
        'достопримечательность', 'туристическое место', 'бар', 'паб', 'кафе', 'кофейня', 'ресторан', 'пекарня',
        'кондитерская', 'парк', 'сквер', 'сад', 'музей', 'галерея', 'театр', 'кинотеатр', 'библиотека',
        'книжный', 'книжный магазин', 'рынок', 'блошиный рынок', 'ярмарка', 'лавка', 'антикварная лавка',
        'магазин', 'торговый центр', 'клуб', 'ночной клуб', 'пляж', 'набережная', 'смотровая площадка',
        'храм', 'церковь', 'собор', 'замок', 'руины', 'лес', 'озеро', 'отель', 'гостиница', 'спа', 'спортзал',
    ];
    return genericWords.includes(s) || (s.split(/\s+/).length <= 3 && genericWords.some(w => s === w || s.endsWith(' ' + w) || s.startsWith(w + ' ')));
}

function mapSeedPrompt(st, customHint = '') {
    const names = storyNames();
    const t = st.time;
    const when = [t.date ? `${formatDate(t.date)}, ${season(t.date).name}` : '', placeLine(st)].filter(Boolean).join('; ');
    const known = st.map.places.map(p => p.title);
    const hintInstruction = customHint
        ? `Игрок просит придумать место по запросу/категории: «${customHint}». НЕ записывай запрос буквально как «${customHint}» — придумай конкретное, атмосферное, правдоподобное название и описание такого места для этого города/мира (например, если игрок написал «бар» или «достопримечательность» — придумай конкретный колоритный бар или конкретную достопримечательность со своим именем и характером). Предложи 1 такое место (или 2–3, если игрок попросил несколько).`
        : `Предложи ${known.length ? 4 : 5} мест поблизости, куда ${names.user} и другие персонажи могут пойти в этой истории. Места разные по настроению: уютные, людные, тайные, деловые, на природе. Учитывай город или мир, жанр, где живут и работают герои и что уже упоминалось в чате. Реальные места — только если они правда есть в этом городе, иначе придумай правдоподобные.`;
    return [
        '[OOC: Пауза в ролевой игре. Сейчас ты НЕ пишешь ответ персонажа. Ты — помощник автора и рисуешь карту мест для этой истории.',
        when ? `Когда и где: ${when}.` : '',
        buildDirection(st),
        hintInstruction,
        'В КАЖДОЕ место сразу заложи 2–3 конкретных крючка (точки интереса, необычные детали, местные слухи, странности или колоритных завсегдатаев), за которые интересно зацепиться в игре.',
        known.length ? `Уже на карте (не повторяй): ${known.join(', ')}.` : '',
        'Формат, без пояснений:',
        'MAP: конкретное название места | одно предложение, что это за место | крючок 1; крючок 2; крючок 3',
    ].filter(Boolean).join('\n') + ']';
}

async function seedMap(customHint = '') {
    let hint = typeof customHint === 'string' ? customHint.trim() : '';
    const st0 = store();
    if (!hint && st0?.map?.places?.length) {
        const asked = await askText('Какое место добавить? Можешь написать просто тип места («достопримечательность», «бар», «книжный», «туристическое место») — модель сама придумает ему название и описание! Или оставь поле пустым, чтобы модель предложила 4 разных места вокруг.');
        if (asked === null) return [];
        hint = asked.trim();
    }
    const statusMsg = hint ? `🗺 Модель придумывает место («${hint}»)…` : '🗺 Модель набрасывает карту…';
    const added = await withBusy(statusMsg, async st => {
        const raw = await quietGenerate(mapSeedPrompt(st, hint));
        st.lastRaw = String(raw ?? '');
        const out = [];
        for (const line of String(raw || '').replace(/\*\*/g, '').split(/\r?\n/)) {
            const m = line.match(/^\s*MAP\s*[:：—–-]\s*(.+)$/i);
            if (m) { const pl = addPlace(st, m[1], hint ? 'user' : 'start'); if (pl) out.push(pl); }
        }
        if (!out.length) toastr.warning('Модель не прислала места по формату — загляни в «Последний ответ модели»', '🗺 Карта');
        else if (hint) toastr.success(`Добавлено на карту: ${out.map(p => `«${escapeHtml(p.title)}»`).join(', ')}`, '🗺 Карта', { escapeHtml: false });
        return out;
    });
    return added || [];
}

async function checkPendingTravel() {
    const st = store();
    if (!st?.map?.pendingTravel) return;
    const pt = st.map.pendingTravel;
    delete st.map.pendingTravel;
    await ctx().saveMetadata();
    const pl = (pt.placeId && st.map.places.find(p => p.id === pt.placeId)) || { id: pt.placeId, title: pt.title, desc: pt.desc, hooks: pt.hooks };
    await finalizeTravel(pl, { skipDays: pt.skipDays, companion: pt.companion });
}

async function finalizeTravel(pl, { skipDays = 0, companion = '' } = {}) {
    const st = store();
    if (!st) return;
    let moved = 0;
    if (skipDays > 0) {
        moved = skipDays;
        if (st.direction.time && st.time.date) {
            st.time.date = addDays(st.time.date, skipDays);
            st.time.dayStartedAtMsg = ctx().chat?.length ?? 0;
            // holidayStep по ручному вызову
        }
    }
    if (pl.id) {
        pl.visits = (pl.visits || 0) + 1;
        st.map.current = pl.id;
        st.map.enteredAt = ctx().chat?.length ?? 0;
    }
    await ctx().saveMetadata();
    updateInjection();
    renderPanel();

    const names = storyNames();
    const when = moved
        ? (moved === 1 ? ' Наступил следующий день.' : ` Прошло ${daysWord(moved)}.`) +
          (st.direction.time && st.time.date ? ` Сейчас ${weekday(st.time.date)}, ${formatDate(st.time.date)}.` : '')
        : '';
    const isSolo = !companion || !companion.trim() || /^в одиночку$/i.test(companion.trim());
    st.map.currentCompanion = isSolo ? 'solo' : companion.trim();
    const mainCharCandidates = names.chars.length ? names.chars : [names.char];
    const companionHasMainChar = !isSolo && mainCharCandidates.some(cn => cn && (matchesCharacterName(cn, companion) || isNameMentionedInText(cn, companion)));
    const compText = isSolo ? ' В одиночку.' : ` Вместе с: ${companion.trim()}.`;
    const hooksInfo = pl.hooks ? ` Известные особенности и зацепки этого места: ${String(pl.hooks).replace(/[.\s]+$/, '')}.` : '';
    const poiPrompt = livingWorldOn(st)
        ? ` Сразу при входе вплети в описание 2–3 конкретные точки интереса (живые крючки, за которые можно зацепиться): например, необычную деталь обстановки/объявление/забытый предмет, приметного человека со своим занятием и обрывок чужого разговора или микро-сценку поблизости.`
        : '';
    const text = `${FF_MARKER} игрок решил отправиться: «${pl.title}»${pl.desc ? ` — ${String(pl.desc).replace(/[.\s]+$/, '')}` : ''}.${hooksInfo}${compText}${when} Сверни текущую сцену одной-двумя фразами и начни новую уже там: дорога коротко (если она не важна), прибытие, какое это место сейчас, кто там и что происходит.${poiPrompt} ${pl.visits > 1 ? `${names.user} здесь уже бывал(а) — что-то знакомое, что-то изменилось.` : ''} Пиши как обычный ответ, не упоминай карту.]`;

    setSceneAdvancePrompt(text);

    const timeLabel = moved ? (moved === 1 ? ' · завтра' : ` · +${daysWord(moved)}`) : '';
    const compLabel = companion && !/^в одиночку$/i.test(companion.trim()) ? ` · с ${escapeHtml(companion.trim())}` : '';
    toastr.info(`Отправляемся: ${escapeHtml(pl.title)}${timeLabel}${compLabel}`, '🗺 Карта', { escapeHtml: false, timeOut: 4500 });

    const send = $('#send_but');
    if (send.length) send.trigger('click');
    else if (typeof ctx().generate === 'function') ctx().generate('normal');
}

async function executeTravel(place, { skipDays = 0, companion = '', changeOutfit = false } = {}) {
    const st = store();
    if (!st) return toastr.warning('Сначала открой чат', 'Блокнот рассказчика');
    if (busy) return toastr.info('Модель уже занята — подожди пару секунд', 'Блокнот рассказчика');
    let pl = place;
    if (!pl?.title) return;

    if (changeOutfit && st.direction.wardrobe) {
        st.map.pendingTravel = {
            placeId: pl.id || null,
            title: pl.title,
            desc: pl.desc || '',
            hooks: pl.hooks || '',
            skipDays,
            companion: companion || '',
        };
        await ctx().saveMetadata();
        st.wardrobe.active = null;
        const occasion = `поездка: ${pl.title}`;
        const ok = await withBusy(`👗 Подбираем наряды для: ${pl.title}…`, s2 => generateOutfits(s2, occasion));
        if (ok) presentLooks();
        return;
    }
    await finalizeTravel(pl, { skipDays, companion });
}

async function openTravelModal(place, customText) {
    const st = store();
    if (!st) return toastr.warning('Сначала открой чат', 'Блокнот рассказчика');
    if (busy) return toastr.info('Модель уже занята — подожди пару секунд', 'Блокнот рассказчика');

    let pl = place;
    if (!pl && customText) {
        pl = findPlace(st, customText);
        if (!pl && isGenericPlaceHint(customText)) {
            const gen = await seedMap(customText);
            pl = gen[0] || null;
        }
        if (!pl) pl = addPlace(st, customText, 'user') || { title: customText.trim(), desc: '' };
    }
    if (!pl?.title) return;

    const el = $('<div class="nnb-pop nnb-travel-pop"></div>');
    el.append($('<h3></h3>').text(`🧳 Сборы: ${pl.title}`));

    const metaParts = [];
    if (pl.desc) metaParts.push(pl.desc);
    if (pl.visits) metaParts.push(`бывали здесь: ${pl.visits}×`);
    if (metaParts.length) el.append($('<div class="nnb-pop-sub"></div>').text(metaParts.join(' · ')));

    // 1. Когда отправляемся
    el.append('<div class="nnb-travel-sec-title">📅 Когда отправляемся?</div>');
    const timeChips = $('<div class="nnb-chips-row nnb-travel-chips"></div>');
    let skipDays = 0;

    const timeOptions = [
        { label: '☀️ Сегодня', days: 0 },
        { label: '🌅 Завтра', days: 1 },
        { label: '📅 Через 2 дня', days: 2 },
        { label: '⏳ Через неделю', days: 7 },
    ];

    const dateHint = $('<div class="nnb-pop-sub nnb-travel-date-hint"></div>');
    const updateDateHint = () => {
        if (!st.direction.time || !st.time.date) {
            dateHint.text(skipDays === 0 ? 'Текущий день истории' : skipDays === 1 ? 'Сцена начнётся на следующий день' : `Сцена начнётся через ${daysWord(skipDays)}`);
            return;
        }
        const targetDate = addDays(st.time.date, skipDays);
        dateHint.text(`Дата: ${weekday(targetDate)}, ${formatDate(targetDate)}${skipDays > 0 ? ` (+${daysWord(skipDays)})` : ' (сегодня)'}`);
    };

    const customDaysChip = $('<div class="nnb-travel-chip" tabindex="0">✏️ Свой срок…</div>');
    const customDaysInput = $('<input type="number" min="1" max="365" class="text_pole nnb-travel-custom-days" style="display:none; width:75px; margin:0 4px;" placeholder="дней">');

    timeOptions.forEach(opt => {
        const chip = $('<div class="nnb-travel-chip" tabindex="0"></div>').text(opt.label);
        if (opt.days === skipDays) chip.addClass('active');
        chip.on('click', () => {
            skipDays = opt.days;
            customDaysInput.val('').hide();
            timeChips.find('.nnb-travel-chip').removeClass('active');
            chip.addClass('active');
            updateDateHint();
        });
        timeChips.append(chip);
    });

    customDaysChip.on('click', () => {
        timeChips.find('.nnb-travel-chip').removeClass('active');
        customDaysChip.addClass('active');
        customDaysInput.show().trigger('focus');
        skipDays = Math.max(1, Number(customDaysInput.val()) || 1);
        updateDateHint();
    });
    customDaysInput.on('input change', () => {
        skipDays = Math.max(1, Number(customDaysInput.val()) || 1);
        updateDateHint();
    });
    timeChips.append(customDaysChip, customDaysInput);
    el.append(timeChips, dateHint);
    updateDateHint();

    // 2. Что надеть
    let changeOutfit = false;
    if (st.direction.wardrobe) {
        el.append('<div class="nnb-travel-sec-title">👗 Что надеть?</div>');
        const wardChips = $('<div class="nnb-chips-row nnb-travel-chips"></div>');
        const wardHint = $('<div class="nnb-pop-sub nnb-travel-ward-hint"></div>');

        const curOutfit = st.wardrobe?.active?.status === 'worn' ? st.wardrobe.active.look.title : '';
        const keepChip = $('<div class="nnb-travel-chip active" tabindex="0">🧥 Пойти как есть</div>');
        const changeChip = $('<div class="nnb-travel-chip" tabindex="0">✨ Подобрать наряд под место</div>');

        const updateWardHint = () => {
            if (!changeOutfit) {
                wardHint.text(curOutfit ? `Сейчас надето: «${curOutfit}»` : 'Без смены наряда');
            } else {
                wardHint.text(`Перед отправлением откроется выбор образов для «${pl.title}»`);
            }
        };

        keepChip.on('click', () => {
            changeOutfit = false;
            keepChip.addClass('active');
            changeChip.removeClass('active');
            updateWardHint();
        });
        changeChip.on('click', () => {
            changeOutfit = true;
            changeChip.addClass('active');
            keepChip.removeClass('active');
            updateWardHint();
        });

        wardChips.append(keepChip, changeChip);
        el.append(wardChips, wardHint);
        updateWardHint();
    }

    // 3. С кем идём
    el.append('<div class="nnb-travel-sec-title">👥 Кто с нами?</div>');
    const compChips = $('<div class="nnb-chips-row nnb-travel-chips"></div>');
    let companion = '';

    const soloChip = $('<div class="nnb-travel-chip active" tabindex="0">🚶 В одиночку</div>');
    compChips.append(soloChip);

    const names = storyNames();
    const candidateCompanions = [];
    (st.npcs || []).filter(n => n.favorite).forEach(n => {
        if (n.name && !candidateCompanions.includes(n.name)) candidateCompanions.push(n.name);
    });
    if (!st.worldProfile?.freeWorld) {
        (names.chars || []).forEach(cName => {
            if (cName && !candidateCompanions.includes(cName)) candidateCompanions.push(cName);
        });
    }
    (st.npcs || []).slice(0, 8).forEach(n => {
        if (n.name && !candidateCompanions.includes(n.name)) candidateCompanions.push(n.name);
    });

    candidateCompanions.forEach(cName => {
        const chip = $('<div class="nnb-travel-chip" tabindex="0"></div>').text(`С ${cName}`);
        chip.on('click', () => {
            companion = cName;
            compChips.find('.nnb-travel-chip').removeClass('active');
            chip.addClass('active');
            compInput.val(cName);
        });
        compChips.append(chip);
    });

    const compInput = $('<input type="text" class="text_pole nnb-travel-comp-input" placeholder="Или напиши имя/компанию…">');
    soloChip.on('click', () => {
        companion = '';
        compChips.find('.nnb-travel-chip').removeClass('active');
        soloChip.addClass('active');
        compInput.val('');
    });
    compInput.on('input', () => {
        companion = compInput.val().trim();
        compChips.find('.nnb-travel-chip').removeClass('active');
        if (!companion) soloChip.addClass('active');
    });

    el.append(compChips, compInput);

    // 4. Кнопки
    const actRow = $('<div class="nnb-pop-row nnb-travel-actions"></div>');
    const goBtn = $('<div class="menu_button nnb-btn-primary" tabindex="0"><i class="fa-solid fa-person-walking"></i> Отправиться</div>');
    const cancelBtn = $('<div class="menu_button" tabindex="0"><i class="fa-solid fa-xmark"></i> Отмена</div>');

    goBtn.on('click', async () => {
        closePopupOf(el);
        await executeTravel(pl, { skipDays, companion, changeOutfit });
    });
    cancelBtn.on('click', () => closePopupOf(el));

    actRow.append(goBtn, cancelBtn);
    el.append(actRow);

    await openPopup(el);
}

async function goToPlace(place, customText) {
    return openTravelModal(place, customText);
}

function placeRow(st, pl, onGo, tools) {
    const row = $('<div class="nnb-note nnb-place"><div class="nnb-place-main"><div class="nnb-npc-text"></div><div class="nnb-npc-status"></div></div></div>');
    const here = st.map.current === pl.id;
    if (here) row.addClass('nnb-place-here');
    row.find('.nnb-npc-text').text(`${here ? '📍 ' : ''}${pl.title}`);
    const meta = [pl.desc, here ? 'вы здесь' : pl.visits ? `уже бывали: ${pl.visits}×` : ''].filter(Boolean).join(' · ');
    if (meta) row.find('.nnb-npc-status').first().text(meta); else row.find('.nnb-npc-status').first().remove();
    row.find('.nnb-place-main').css('cursor', 'pointer').on('click', () => onGo(pl));
    if (tools) {
        const act = $('<div class="nnb-actions"><i class="fa-solid fa-pen" title="Изменить"></i><i class="fa-solid fa-trash" title="Убрать с карты"></i></div>');
        act.find('.fa-pen').on('click', async () => {
            const t = await askText('Название места', pl.title);
            if (t === null) return;
            const d = await askText('Что это за место? (краткая подпись)', pl.desc);
            if (d === null) return;
            if (t.trim()) pl.title = t.trim();
            pl.desc = d.trim();
            await commit();
        });
        act.find('.fa-trash').on('click', async () => { st.map.places = st.map.places.filter(x => x !== pl); if (st.map.current === pl.id) st.map.current = null; await commit(); });
        row.append(act);
    }
    return row;
}
function sortedPlaces(st) {
    // сначала свежие находки сюжета, потом остальное по порядку
    return [...st.map.places].sort((a, b) => (b.origin === 'story' && !b.visits) - (a.origin === 'story' && !a.visits) || a.id - b.id);
}

async function showMapPopup() {
    const st = store();
    if (!st) return toastr.warning('Сначала открой чат', 'Блокнот рассказчика');
    if (!mapOn(st)) return toastr.info('Карта выключена в этом чате — включи её в блокноте, вкладка «Сюжет»', '🗺 Карта');
    if (!st.map.places.length) {
        const added = await seedMap();
        if (!added.length) return;
    }
    const el = $('<div class="nnb-pop nnb-map-pop"><h3>🗺 Куда пойти?</h3></div>');
    const homeBanner = $('<div class="nnb-note" style="display:flex; justify-content:space-between; align-items:center; gap:10px; border-color:var(--SmartThemeQuoteColor, #8b78c4); cursor:pointer; padding:8px 12px; margin-bottom:4px;"></div>');
    homeBanner.append($('<div><b>🏠 Мой дом (Комната)</b><div class="nnb-npc-status">Расставить полученные предметы в интерьере (0 токенов) и обновить картинку комнаты</div></div>'));
    homeBanner.append('<div class="menu_button nnb-btn-primary" style="margin:0; white-space:nowrap;"><i class="fa-solid fa-couch"></i> Открыть дом</div>');
    homeBanner.on('click', () => { closePopupOf(el); openHomeModal(); });
    el.append(homeBanner);
    const go = async pl => { closePopupOf(el); await goToPlace(pl); };
    const list = $('<div class="nnb-places"></div>');
    sortedPlaces(st).forEach(pl => list.append(placeRow(st, pl, go, false)));
    el.append(list);
    const custom = $('<div class="nnb-pop-row nnb-map-custom"><input type="text" class="text_pole" placeholder="Свой вариант: куда идём?"><div class="menu_button"><i class="fa-solid fa-person-walking"></i> Пойти</div></div>');
    const doCustom = async () => { const t = String(custom.find('input').val() || '').trim(); if (!t) return; closePopupOf(el); await goToPlace(null, t); };
    custom.find('.menu_button').on('click', doCustom);
    custom.find('input').on('keydown', e => { if (e.key === 'Enter') { e.preventDefault(); doCustom(); } });
    el.append(custom);
    const bottomLinks = $('<div class="nnb-pop-row nnb-pop-links" style="gap:8px; flex-wrap:wrap;"></div>');
    const findNewPlacesBtn = $('<div class="menu_button nnb-btn-primary"><i class="fa-solid fa-compass"></i> Найти новые места</div>').on('click', async () => {
        closePopupOf(el);
        const added = await seedMap();
        if (added.length || store()?.map?.places?.length) {
            await showMapPopup();
        }
    });
    const openMapBookBtn = $('<div class="menu_button"><i class="fa-solid fa-book-open"></i> Карта в блокноте</div>').on('click', () => {
        closePopupOf(el);
        openBook('map');
    });
    bottomLinks.append(findNewPlacesBtn, openMapBookBtn);
    el.append(bottomLinks);
    await openPopup(el);
}

function renderMap(st) {
    const root = $('#nnb_map_box').empty();
    if (!mapOn(st)) return;
    const m = st.map;
    const det = $('<details open class="nnb-section"><summary></summary></details>');
    det.find('summary').text(`🗺 Карта (${m.places.length})`);
    const cur = m.places.find(p => p.id === m.current);
    if (cur) det.append($('<div class="nnb-npc-status"></div>').text(`📍 Сейчас: ${cur.title}`));
    if (!m.places.length) det.append('<div class="nnb-empty">Карта пока пустая. Набросай её — модель предложит несколько мест вокруг, а дальше карта будет расти сама, когда в сюжете появятся новые места.</div>');
    sortedPlaces(st).forEach(pl => det.append(placeRow(st, pl, pl2 => { closeBook(); goToPlace(pl2); }, true)));
    const btns = $('<div class="nnb-buttons"></div>');
    btns.append($('<div class="menu_button nnb-btn-primary"><i class="fa-solid fa-house-chimney"></i> 🏠 Мой дом (Комната)</div>').on('click', () => { closeBook(); openHomeModal(); }));
    btns.append($('<div class="menu_button"><i class="fa-solid fa-map"></i> Куда пойти?</div>').on('click', () => { closeBook(); showMapPopup(); }));
    btns.append($(`<div class="menu_button"><i class="fa-solid fa-wand-magic-sparkles"></i> ${m.places.length ? 'Ещё мест' : 'Набросать карту'}</div>`).on('click', () => seedMap()));
    btns.append($('<div class="menu_button"><i class="fa-solid fa-plus"></i> Добавить место</div>').on('click', async () => {
        const t = await askText('Название места или просто идея («достопримечательность», «бар», «уютная кофейня» — если напишешь общую идею, модель сама придумает название и описание!)');
        if (!t || !t.trim()) return;
        if (isGenericPlaceHint(t.trim())) {
            await seedMap(t.trim());
            return;
        }
        const d = await askText('Что это за место? (краткая подпись — или оставь пустым, чтобы модель додумала описание сама)');
        if (d === null) return;
        if (!d.trim()) {
            await seedMap(t.trim());
            return;
        }
        addPlace(st, `${t.trim()} | ${d.trim()}`, 'user');
        await commit();
    }));
    det.append(btns);
    root.append(det);
}

// 🎁 Шкатулка и 🎰 находки — своя вкладка
function boxOn(st) {
    return accentsOn(st) || gachaOn(st);
}
function findThumb(x, size) {
    const el = $('<div class="nnb-card-img nnb-find-thumb"></div>').css({ width: size, height: size });
    const isSingle = !!(x?.isSingleImage || (x?.imageLayout?.cols === 1 && x?.imageLayout?.rows === 1));
    const ratio = isSingle ? 1 : 1.5;
    const cropBox = isSingle ? { x: 0, y: 0, w: 1, h: 1 } : (x?.crop || { x: 0, y: 0, w: 1, h: 1 });
    applyCrop(el, x.image, cropBox, ratio);
    return el;
}

// ---------- Активные предметы из шкатулки ----------
async function toggleEquipped(x) {
    const st = store();
    if (!st) return;
    if (!Array.isArray(st.wardrobe.equipped)) st.wardrobe.equipped = [];
    const idx = st.wardrobe.equipped.indexOf(x.id);
    if (idx >= 0) {
        st.wardrobe.equipped.splice(idx, 1);
        toastr.info(`«${escapeHtml(x.title)}» убран в шкатулку`, '🎒 Предмет', { escapeHtml: false });
    } else {
        if (st.wardrobe.equipped.length >= 3) st.wardrobe.equipped.shift();
        st.wardrobe.equipped.push(x.id);
        toastr.success(`«${escapeHtml(x.title)}» взят с собой (наготове)`, '🎒 Активный предмет', { escapeHtml: false });
    }
    await commit();
}

async function applyItemInScene(x, customAction) {
    const st = store();
    if (!st) return toastr.warning('Сначала открой чат', 'Блокнот рассказчика');
    if (busy) return toastr.info('Модель уже занята — подожди пару секунд', 'Блокнот рассказчика');
    const names = storyNames();
    const place = st.map?.places?.find(p => p.id === st.map?.current);
    const where = place ? ` в месте «${place.title}»` : '';
    const act = customAction ? ` Действие: ${customAction}.` : '';
    const text = `${FF_MARKER} ${names.user} достаёт и применяет предмет: «${x.title}»${x.desc ? ` — ${x.desc}` : ''}${where}.${act} Опиши реакцию персонажей и последствия этого действия. Пиши как обычный ответ, не упоминай команды.]`;
    setSceneAdvancePrompt(text);
    toastr.info(`Применяем: ${escapeHtml(x.title)}`, '🪄 Активный предмет', { escapeHtml: false, timeOut: 4000 });
    const send = $('#send_but');
    if (send.length) send.trigger('click');
    else if (typeof ctx().generate === 'function') ctx().generate('normal');
}

async function giftItemToNpc(x, npcName) {
    const st = store();
    if (!st) return;
    x.giftedTo = npcName.trim();
    x.giftedAt = ctx().chat.length;
    st.wardrobe.equipped = (st.wardrobe.equipped || []).filter(id => id !== x.id);
    await commit();
    const names = storyNames();
    const text = `${FF_MARKER} ${names.user} дарит «${x.title}» персонажу ${x.giftedTo}. Это подарок (${x.origin || x.desc || 'особенная вещь'}). Опиши реакцию ${x.giftedTo} в характере и как этот жест отразится на их отношениях.]`;
    setSceneAdvancePrompt(text);
    toastr.success(`🎁 «${escapeHtml(x.title)}» теперь у ${escapeHtml(x.giftedTo)}`, 'Подарок', { escapeHtml: false, timeOut: 5000 });
    const send = $('#send_but');
    if (send.length) send.trigger('click');
    else if (typeof ctx().generate === 'function') ctx().generate('normal');
}

async function promptGiftItem(x) {
    const st = store();
    if (!st) return;
    const npcs = (st.npcs || []).map(n => n.name);
    let target = '';
    if (npcs.length) {
        target = await askText(`Кому подарить «${x.title}»? Персонажи: ${npcs.join(', ')}`);
    } else {
        target = await askText(`Кому подарить «${x.title}»? Назови имя персонажа`);
    }
    if (!target || !target.trim()) return;
    await giftItemToNpc(x, target.trim());
}

async function toggleItemOnCounter(x) {
    const st = store();
    if (!st) return;
    if (x.onCounter) {
        x.onCounter = false;
        await commit();
        toastr.info(`«${escapeHtml(x.title)}» убрано с прилавка в личную шкатулку`, '🎁 Личная шкатулка', { escapeHtml: false });
    } else {
        delete x.giftedTo;
        delete x.giftedAt;
        st.wardrobe.equipped = (st.wardrobe.equipped || []).filter(id => id !== x.id);
        x.onCounter = true;
        ensureCounterPrice(x, st);
        await commit();
        const profit = Math.max(0, x.sellPrice - (x.buyPrice || 0));
        toastr.success(
            `«${escapeHtml(x.title)}» выставлено на прилавок за <b>${escapeHtml(formatMoney(x.sellPrice, st))}</b>${x.buyPrice ? ` (чистая прибыль: +${escapeHtml(formatMoney(profit, st))})` : ''}`,
            '🏪 Прилавок лавки',
            { escapeHtml: false, timeOut: 6000 }
        );
    }
}

async function sellCounterItemNow(x, inScene = false) {
    const st = store();
    if (!st) return;
    ensureCounterPrice(x, st);
    const revenue = x.sellPrice;
    const profit = Math.max(0, revenue - (x.buyPrice || 0));
    st.wallet.balance = (st.wallet.balance || 0) + revenue;
    st.wardrobe.box = st.wardrobe.box.filter(y => y !== x);
    if (st.direction.time && st.time.date) {
        addEvent(st, st.time.date, `Продано в лавке: «${x.title}» за ${formatMoney(revenue, st)}`);
    }
    await commit();
    toastr.success(
        `Продано: «${escapeHtml(x.title)}» за <b>+${escapeHtml(formatMoney(revenue, st))}</b>${x.buyPrice ? ` (прибыль: +${escapeHtml(formatMoney(profit, st))})` : ''}! В кошельке: ${escapeHtml(formatMoney(st.wallet.balance, st))}`,
        '💰 Выручка лавки',
        { escapeHtml: false, timeOut: 7000 }
    );
    if (inScene) {
        const names = storyNames();
        const text = `${FF_MARKER} Посетитель в лавке ${names.user} покупает с витрины товар «${x.title}»${x.desc ? ` (${x.desc})` : ''} за ${formatMoney(revenue, st)}.${x.hook ? ` Сюжетная деталь вещи: ${x.hook}.` : ''} Опиши живую сцену покупки: кто именно заинтересовался этой вещью, короткий диалог у прилавка, звон монет/оплату и интересную деталь или зацепку, которую оставляет покупатель. Метку SOLD добавлять не нужно — деньги уже зачислены.]`;
        setSceneAdvancePrompt(text);
        closeBook();
        const send = $('#send_but');
        if (send.length) send.trigger('click');
        else if (typeof ctx().generate === 'function') ctx().generate('normal');
    }
}

async function nextShopCustomer() {
    const st = store();
    if (!st) return toastr.warning('Сначала открой чат', '🏪 Лавка');
    if (busy) return toastr.info('Модель уже занята — подожди пару секунд', '🏪 Лавка');
    const customWish = await askText('Кто заглянет в лавку? (Оставь поле пустым — нейросеть сама придумает колоритного покупателя со своей историей, или напиши пожелание: например «богатый коллекционер», «странный незнакомец с вещью на продажу», «знакомый NPC»)');
    if (customWish === null) return;

    const names = storyNames();
    const counter = shopCounterItems(st);
    counter.forEach(x => ensureCounterPrice(x, st));
    const counterDesc = counter.length
        ? `Сейчас на витрине выставлены на продажу: ${counter.map(x => `«${x.title}» (цена на ценнике: ${formatMoney(x.sellPrice, st)}${x.desc ? `, ${x.desc}` : ''}${x.hook ? `; история вещи: ${x.hook}` : ''})`).join('; ')}.`
        : `На витрине сейчас пусто или товары ещё выкладываются — покупатель может спросить редкую вещь на заказ, принести необычную диковинку на оценку/продажу для ${names.user} или завязать интригующий разговор.`;
    const wishLine = customWish.trim() ? ` Пожелание игрока к этому визитёру: ${customWish.trim()}.` : '';

    const text = `${FF_MARKER} Звенит колокольчик над дверью лавки ${names.user} — заходит следующий посетитель.${wishLine} ${counterDesc} Опиши живую, атмосферную сцену: кто именно вошёл (внешность, манера держаться, любопытная деталь), как он осматривается у прилавка, чем интересуется из товаров на витрине (или с каким необычным предложением/запросом пришёл к ${names.user}) и с какой реплики начинается ваш диалог. Не завершай сделку сразу за один пост — дай ${names.user} поговорить с покупателем, поторговаться или обсудить диковинку! Пиши как обычный ответ.]`;

    setSceneAdvancePrompt(text);
    closeBook();
    toastr.info('Звенит колокольчик над дверью — в лавку заходит покупатель…', '🛎 Следующий покупатель', { timeOut: 5000 });
    const send = $('#send_but');
    if (send.length) send.trigger('click');
    else if (typeof ctx().generate === 'function') ctx().generate('normal');
}

function showFind(x) {
    const st = store();
    const r = x.rarity ? rarityOf(x.rarity) : null;
    const isEquipped = (st?.wardrobe?.equipped || []).includes(x.id);
    if (x.onCounter && st) ensureCounterPrice(x, st);
    const el = $('<div class="nnb-pop"></div>');
    if (x.image) el.append(findThumb(x, '240px').addClass('nnb-find-big' + (r ? ` nnb-rar nnb-rar-${x.rarity}` : '')));
    el.append($('<h3></h3>').text(`${(ACCENT_KINDS[x.kind] || ACCENT_KINDS.find).icon} ${x.title}`));
    let sub = [
        r ? `${r.stars} ${r.name}` : '',
        x.onCounter ? `🏪 На прилавке за ${formatMoney(x.sellPrice, st)}` : (x.price ? `Куплено: ${x.price}` : ''),
        x.giftedTo ? `🎁 у ${x.giftedTo}` : isEquipped ? '🎒 с собой' : '',
    ].filter(Boolean).join(' · ');
    if (sub) el.append($('<div class="nnb-pop-sub"></div>').text(sub));
    if (x.desc) el.append($('<div class="nnb-look-desc"></div>').text(x.desc));
    if (x.origin) el.append($('<div class="nnb-pop-sub"></div>').text(x.origin));

    if (x.onCounter && st) {
        const priceSec = $('<div style="margin:10px 0; padding:8px 10px; border-radius:8px; border:1px solid var(--SmartThemeBorderColor); background:color-mix(in srgb, var(--SmartThemeQuoteColor, #8b78c4) 10%, transparent);"></div>');
        const updatePriceLabel = () => {
            const base = x.buyPrice || autoBasePrice(x, st);
            const profit = Math.max(0, x.sellPrice - base);
            priceInfo.html(`🏷 Цена продажи: <b>${escapeHtml(formatMoney(x.sellPrice, st))}</b> <span style="opacity:0.8;">(себестоимость: ${escapeHtml(formatMoney(base, st))}, наценка +${escapeHtml(formatMoney(profit, st))})</span>`);
        };
        const priceInfo = $('<div style="font-size:0.92em; margin-bottom:6px;"></div>');
        updatePriceLabel();
        const multRow = $('<div class="nnb-chips-row" style="gap:6px;"></div>');
        [
            { m: 1.2, label: 'Быстро (×1.2)' },
            { m: 1.5, label: 'Обычная (×1.5)' },
            { m: 2.5, label: 'Коллекционеру (×2.5)' },
        ].forEach(preset => {
            const btn = $('<div class="menu_button nnb-look-chip" style="padding:3px 8px; font-size:0.82em;"></div>').text(preset.label);
            if (Math.abs((x.marginMult || 1.5) - preset.m) < 0.05) btn.addClass('active');
            btn.on('click', async () => {
                x.marginMult = preset.m;
                x.sellPrice = calcAutoSellPrice(x, st, preset.m);
                multRow.find('.nnb-look-chip').removeClass('active');
                btn.addClass('active');
                updatePriceLabel();
                await commit();
            });
            multRow.append(btn);
        });
        const customPriceBtn = $('<div class="menu_button nnb-look-chip" style="padding:3px 8px; font-size:0.82em;"><i class="fa-solid fa-pen"></i> Своя цена</div>').on('click', async () => {
            const val = await askText(`Какую цену поставить для «${x.title}» (в ${st.wallet.currency})?`, String(x.sellPrice));
            if (val === null) return;
            const num = parsePriceNumber(val);
            if (num > 0) {
                x.sellPrice = num;
                multRow.find('.nnb-look-chip').removeClass('active');
                updatePriceLabel();
                await commit();
            }
        });
        multRow.append(customPriceBtn);
        priceSec.append(priceInfo, multRow);
        el.append(priceSec);
    }

    const acts = $('<div class="nnb-pop-row nnb-item-actions" style="flex-wrap:wrap; gap:6px;"></div>');
    if (x.onCounter) {
        const sellSceneBtn = $('<div class="menu_button nnb-btn-primary"><i class="fa-solid fa-comments-dollar"></i> Отыграть продажу в сцене</div>').on('click', async () => {
            closePopupOf(el);
            await sellCounterItemNow(x, true);
        });
        const sellQuickBtn = $('<div class="menu_button"><i class="fa-solid fa-coins"></i> Продать сразу (+в кошелёк)</div>').on('click', async () => {
            closePopupOf(el);
            await sellCounterItemNow(x, false);
        });
        const toPersonalBtn = $('<div class="menu_button"><i class="fa-solid fa-box-open"></i> Убрать в личную шкатулку</div>').on('click', async () => {
            closePopupOf(el);
            await toggleItemOnCounter(x);
        });
        acts.append(sellSceneBtn, sellQuickBtn, toPersonalBtn);
    } else if (x.giftedTo) {
        const reclaimBtn = $(`<div class="menu_button"><i class="fa-solid fa-rotate-left"></i> Вернуть в шкатулку</div>`);
        reclaimBtn.on('click', async () => {
            closePopupOf(el);
            delete x.giftedTo;
            delete x.giftedAt;
            await commit();
            toastr.info(`«${escapeHtml(x.title)}» возвращён в шкатулку`, 'Шкатулка', { escapeHtml: false });
        });
        acts.append(reclaimBtn);
    } else {
        const toCounterBtn = shopModeOn(st) ? $('<div class="menu_button"><i class="fa-solid fa-store"></i> На прилавок (на продажу)</div>').on('click', async () => {
            closePopupOf(el);
            await toggleItemOnCounter(x);
        }) : null;
        const eqBtn = $(`<div class="menu_button"><i class="fa-solid fa-briefcase"></i> ${isEquipped ? 'Убрать в шкатулку' : 'Взять с собой'}</div>`);
        eqBtn.on('click', async () => {
            closePopupOf(el);
            await toggleEquipped(x);
        });
        const giftBtn = $('<div class="menu_button"><i class="fa-solid fa-gift"></i> Подарить…</div>');
        giftBtn.on('click', async () => {
            closePopupOf(el);
            await promptGiftItem(x);
        });
        const applyBtn = $('<div class="menu_button"><i class="fa-solid fa-wand-magic-sparkles"></i> Применить в сцене</div>');
        applyBtn.on('click', async () => {
            closePopupOf(el);
            const act = await askText(`Как применить «${x.title}» в сцене? Оставь пустым — модель решит сама.`);
            if (act === null) return;
            await applyItemInScene(x, act.trim());
        });
        if (toCounterBtn) acts.append(toCounterBtn); acts.append(eqBtn, giftBtn, applyBtn);
    }

    el.append(acts);
    openPopup(el);
}

function renderBox(st) {
    const root = $('#nnb_box_box').empty();
    if (!boxOn(st)) return;
    const w = st.wardrobe;

    // 1. 💰 Кошелёк и бюджет
    const walletBar = $('<div class="nnb-note" style="display:flex; justify-content:space-between; align-items:center; flex-wrap:wrap; gap:8px; margin-bottom:10px; padding:8px 12px; border:1px solid color-mix(in srgb, var(--SmartThemeQuoteColor, #8b78c4) 40%, transparent);"></div>');
    const walletLeft = $('<div style="display:flex; align-items:center; gap:8px; font-weight:600; font-size:1.02em;"></div>');
    walletLeft.html(`💰 Кошелёк: <span style="color:var(--SmartThemeQuoteColor, #e0c068);">${escapeHtml(formatMoney(st.wallet?.balance || 0, st))}</span>`);
    const walletActions = $('<div style="display:flex; gap:6px; align-items:center;"></div>');
    const addMoneyBtn = $('<div class="menu_button" style="padding:3px 8px; font-size:0.85em;" title="Прибавить или убавить деньги"><i class="fa-solid fa-plus-minus"></i> Сумма</div>').on('click', async () => {
        const raw = await askText(`Изменить баланс кошелька (введи новое число или +100 / -50). Сейчас: ${formatMoney(st.wallet.balance, st)}`, String(st.wallet.balance));
        if (raw === null || !raw.trim()) return;
        const s = raw.trim().replace(/\s+/g, '');
        if (/^[+-]\d+/.test(s)) {
            st.wallet.balance = Math.max(0, st.wallet.balance + Number(s));
        } else {
            const n = parsePriceNumber(s);
            st.wallet.balance = n;
        }
        await commit();
    });
    const curBtn = $('<div class="menu_button" style="padding:3px 8px; font-size:0.85em;" title="Сменить валюту"><i class="fa-solid fa-coins"></i> Валюта</div>').on('click', async () => {
        const c = await askText('Символ или название валюты (например: £, $, €, ₽, ¥, золотых)', st.wallet.currency || '£');
        if (c && c.trim()) {
            st.wallet.currency = c.trim();
            await commit();
        }
    });
    walletActions.append(addMoneyBtn, curBtn);
    walletBar.append(walletLeft, walletActions);
    root.append(walletBar);

    // 2. 🎰 Гача: находки и варианты
    if (gachaOn(st)) {
        const g = st.gacha;
        const det = $('<details open class="nnb-section"><summary>🎰 Гача: находки и варианты</summary></details>');
        if (g.active?.status === 'choosing') {
            const isChoices = g.active.mode === 'choices';
            const card = $('<div class="nnb-note nnb-event"><div class="nnb-event-title"></div><div class="nnb-meta"></div></div>');
            card.find('.nnb-event-title').text(`${isChoices ? '✨' : '🎁'} ${g.active.place || (isChoices ? 'Варианты' : 'Прилавок')}`);
            card.find('.nnb-meta').text(isChoices ? 'Варианты ждут выбора' : 'Находки ждут выбора');
            card.append($('<div class="menu_button"><i class="fa-solid fa-eye"></i> Посмотреть</div>').on('click', presentGacha));
            card.append($('<div class="menu_button"><i class="fa-solid fa-xmark"></i> Уйти ни с чем</div>').on('click', async () => { if (g.active.options.some(o => o.taken)) await finishGacha(); else { g.active = null; await commit(); } }));
            det.append(card);
        } else {
            const left = gachaSpinsLeft(st);
            det.append($('<div class="nnb-npc-status"></div>').text(`Прокруток на этом посте: ${left} из ${GACHA_LIMIT}${left ? '' : ' (снова — со следующим постом)'} · до гарантированной эпической: ${Math.max(1, GACHA_PITY - (g.pity || 0))}`));
            const btns = $('<div class="nnb-buttons" style="display:flex; gap:6px; flex-wrap:wrap; margin:6px 0;"></div>');
            btns.append($('<div class="menu_button" style="flex:1;"><i class="fa-solid fa-gift"></i> Предметы (купить / найти)</div>').on('click', async () => {
                const h = await askText('Где ищем или что за предмет? (например «оптовая закупка у старьёвщика для лавки», «блошиный рынок»). Оставь пустым — модель сама подстроится под сцену.');
                if (h === null) return;
                await runGachaRoll('items', h.trim());
            }));
            btns.append($('<div class="menu_button" style="flex:1;"><i class="fa-solid fa-wand-magic-sparkles"></i> Варианты (для сюжета)</div>').on('click', async () => {
                const h = await askChoicesTopicModal('');
                if (h === null) return;
                await runGachaRoll('choices', h);
            }));
            det.append(btns);
            const stt = g.stats || {};
            const seen = RARITIES.reduce((a2, r) => a2 + (stt[r.id] || 0), 0);
            if (seen) det.append($('<div class="nnb-npc-status"></div>').text(`Выпадало за ${g.total || 0} прокр. (${seen}): ` + RARITIES.map(r => `${r.icon} ${stt[r.id] || 0}`).join(' · ') + ' — шансы: ' + RARITIES.map(r => `${r.w}%`).join(' / ')));
        }
        if (Array.isArray(g.choices) && g.choices.length) {
            det.append($('<div class="nnb-subhead" style="margin-top:8px;"></div>').text(`✨ Выпавшие варианты сюжета (${g.choices.length})`));
            [...g.choices].reverse().forEach(c => {
                const r = c.rarity ? rarityOf(c.rarity) : RARITIES[0];
                const row = $(`<div class="nnb-note nnb-rar nnb-rar-${c.rarity || 'common'}"><div class="nnb-meta"></div><div class="nnb-npc-text"></div><div class="nnb-npc-status"></div><div class="nnb-actions"></div></div>`);
                row.find('.nnb-meta').text(`${r.stars} ${r.name} · ${c.topic || 'Вариант'}${c.detail ? ` · ${c.detail}` : ''}${c.pinned ? ' · 📌 закреплено' : ''}`);
                row.find('.nnb-npc-text').text(c.title);
                if (c.desc) row.find('.nnb-npc-status').text(c.desc); else row.find('.nnb-npc-status').remove();
                const acts = row.find('.nnb-actions');
                const pinBtn = $(`<i class="fa-solid fa-thumbtack" title="${c.pinned ? 'Открепить (не держать постоянно в памяти)' : 'Закрепить в памяти (для профессии, хобби и постоянных статусов)'}" style="${c.pinned ? 'color: var(--SmartThemeQuoteColor, #8b78c4); opacity: 1;' : 'opacity: 0.55;'}"></i>`).on('click', async () => {
                    c.pinned = !c.pinned;
                    await commit();
                    toastr.info(c.pinned ? `«${c.title}» закреплено как постоянный факт` : `«${c.title}» откреплено`, '✨ Варианты');
                });
                const playBtn = $('<i class="fa-solid fa-wand-magic-sparkles" title="Отыграть в следующей сцене"></i>').on('click', async () => {
                    const names = storyNames();
                    const text = `${FF_MARKER} ${names.user} решает воплотить выбранный вариант (${c.topic || 'выбор'}): «${c.title}»${c.detail ? ` (${c.detail})` : ''}${c.desc ? ` — ${c.desc}` : ''}.${c.hook ? ` Сюжетный крючок: ${c.hook}.` : ''} Естественно вплети это в сцену. Пиши как обычный ответ.]`;
                    setSceneAdvancePrompt(text);
                    closeBook();
                    toastr.info(`Отыгрываем: «${escapeHtml(c.title)}»`, '✨ Варианты', { escapeHtml: false });
                    const send = $('#send_but');
                    if (send.length) send.trigger('click');
                    else if (typeof ctx().generate === 'function') ctx().generate('normal');
                });
                const mapBtn = $('<i class="fa-solid fa-map-location-dot" title="Добавить как место на карту"></i>').on('click', async () => {
                    const pl = addPlace(st, `${c.title} | ${c.desc || c.detail || ''}`, 'user');
                    if (pl) {
                        await commit();
                        toastr.success(`Место «${escapeHtml(pl.title)}» добавлено на карту!`, '🗺 Карта', { escapeHtml: false });
                    } else {
                        toastr.info('Это место уже есть на карте', '🗺 Карта');
                    }
                });
                const delBtn = $('<i class="fa-solid fa-trash" title="Удалить"></i>').on('click', async () => {
                    g.choices = g.choices.filter(x => x !== c);
                    await commit();
                });
                acts.append(pinBtn, playBtn, mapBtn, delBtn);
                det.append(row);
            });
        }
        root.append(det);
    }

    // 3. 🏪 Прилавок лавки (только когда включён режим хозяйки лавки / продавца!)
    if (shopModeOn(st)) {
    const counterList = shopCounterItems(st);
    const shopDet = $('<details open class="nnb-section"><summary></summary></details>');
    shopDet.find('summary').text(`🏪 Прилавок лавки — на продажу (${counterList.length})`);
    shopDet.append('<div class="nnb-npc-status">Посетители видят и покупают ТОЛЬКО товары с этого прилавка. Наценка (+50%) ставится автоматически, чтобы ты всегда была в плюсе без лишних подсчётов!</div>');
    if (!counterList.length) {
        shopDet.append('<div class="nnb-empty">Прилавок пока пуст. Нажми 🏪 на любой вещи в личной шкатулке ниже, чтобы выставить её на продажу с авто-наценкой, или добавь товар сразу на витрину.</div>');
    }
    [...counterList].reverse().forEach(x => {
        ensureCounterPrice(x, st);
        const r = x.rarity ? rarityOf(x.rarity) : null;
        const base = x.buyPrice || autoBasePrice(x, st);
        const profit = Math.max(0, x.sellPrice - base);
        const row = $('<div class="nnb-note nnb-box-item"><div class="nnb-box-main"><div class="nnb-npc-text"></div><div class="nnb-npc-status"></div></div><div class="nnb-actions"></div></div>');
        if (x.rarity) row.addClass(`nnb-rar nnb-rar-${x.rarity}`);
        row.find('.nnb-npc-text').text(`${x.title}${r ? ` ${r.stars}` : ''} · ${formatMoney(x.sellPrice, st)}`);
        const statusParts = [
            x.buyPrice ? `закупка: ${formatMoney(x.buyPrice, st)} (прибыль +${formatMoney(profit, st)})` : `чистая прибыль +${formatMoney(x.sellPrice, st)}`,
            x.desc,
        ].filter(Boolean);
        row.find('.nnb-npc-status').text(statusParts.join(' · '));
        if (x.image) row.prepend(findThumb(x, '64px'));
        row.find('.nnb-box-main, .nnb-find-thumb').css('cursor', 'pointer').on('click', () => showFind(x));

        const acts = row.find('.nnb-actions');
        const sellSceneIcon = $('<i class="fa-solid fa-comments-dollar" title="Отыграть покупку посетителем в сцене (+деньги в кошелёк)"></i>').on('click', async e => {
            e.stopPropagation();
            await sellCounterItemNow(x, true);
        });
        const sellQuickIcon = $('<i class="fa-solid fa-coins" title="Продать сразу (+деньги в кошелёк)"></i>').on('click', async e => {
            e.stopPropagation();
            await sellCounterItemNow(x, false);
        });
        const backToBoxIcon = $('<i class="fa-solid fa-box-open" title="Убрать с прилавка в личную шкатулку"></i>').on('click', async e => {
            e.stopPropagation();
            await toggleItemOnCounter(x);
        });
        const delIcon = $('<i class="fa-solid fa-trash" title="Удалить"></i>').on('click', async e => {
            e.stopPropagation();
            w.box = w.box.filter(y => y !== x);
            await commit();
        });
        acts.append(sellSceneIcon, sellQuickIcon, backToBoxIcon, delIcon);
        shopDet.append(row);
    });
    const addShopItemBtn = $('<div class="menu_button"><i class="fa-solid fa-store"></i> Добавить товар на прилавок</div>').on('click', async () => {
        const t = await askText('Название товара для прилавка (например «Старинный латунный компас», «Флакон лунных духов»)');
        if (!t || !t.trim()) return;
        const d = await askText('Краткое описание или история диковинки (можно оставить пустым)');
        if (d === null) return;
        const p = await askText(`Закупочная цена (или оставь пустым — плагин сам назначит выгодную цену в ${st.wallet.currency})`);
        if (p === null) return;
        const buyCost = parsePriceNumber(p);
        const item = {
            id: w.nextItemId++,
            kind: findKind(t),
            title: t.trim(),
            desc: d.trim(),
            origin: 'товар лавки',
            buyPrice: buyCost,
            onCounter: true,
            at: ctx().chat.length,
        };
        ensureCounterPrice(item, st);
        w.box.push(item);
        await commit();
        toastr.success(`Товар «${escapeHtml(item.title)}» выставлен по цене ${escapeHtml(formatMoney(item.sellPrice, st))}!`, '🏪 Прилавок лавки', { escapeHtml: false });
    });
    const shopBtnsRow = $('<div class="nnb-buttons" style="display:flex; gap:6px; flex-wrap:wrap; margin-top:6px;"></div>');
    const nextCustBtn = $('<div class="menu_button nnb-btn-primary"><i class="fa-solid fa-bell-concierge"></i> Следующий покупатель</div>').on('click', () => nextShopCustomer());
    shopBtnsRow.append(nextCustBtn, addShopItemBtn);
    shopDet.append(shopBtnsRow);
    root.append(shopDet);
    }

    // 4. 🎁 Личная шкатулка (личные вещи, не для продажи)
    const personalList = personalBoxItems(st);
    const det = $('<details open class="nnb-section"><summary></summary></details>');
    det.find('summary').text(`🎁 Личная шкатулка (${personalList.length})`);
    const autoBoxLabel = $('<label class="checkbox_label" style="margin:4px 0 6px; font-size:0.88em;"><input type="checkbox"> <span>Автоматически складывать полученные по сюжету долговечные вещи в шкатулку (без еды и сладостей)</span></label>');
    autoBoxLabel.find('input').prop('checked', st.direction?.autoBoxItems !== false).on('change', async function () {
        st.direction.autoBoxItems = $(this).prop('checked');
        await commit();
    });
    det.append(autoBoxLabel);
    const junkItems = personalList.filter(x => /(шоколад|карамел|конфет|леденец|леденц|мармелад|зефир|печень|пирожн|торт|булочк|круассан|хлеб|бутерброд|сэндвич|яблок|фрукт|морожен|жвачк|вафл|орех|фундук|кофе|какао|чай|сок|вода|вино|пиво|отдал[аи]?|раздал[аи]?|детям)/i.test(`${x.title} ${x.desc || ''} ${x.origin || ''}`));
    if (junkItems.length) {
        const cleanJunkBtn = $(`<div class="menu_button" style="margin-bottom:6px; font-size:0.84em;"><i class="fa-solid fa-broom"></i> Убрать случайную еду/сладости из шкатулки (${junkItems.length}: ${junkItems.map(j => j.title).slice(0, 3).join(', ')})</div>`).on('click', async () => {
            const junkIds = new Set(junkItems.map(j => j.id));
            w.box = w.box.filter(x => !junkIds.has(x.id));
            await commit();
            toastr.success(`Убрано лишних съедобных/отданных предметов: ${junkItems.length}`, '🎁 Шкатулка');
        });
        det.append(cleanJunkBtn);
    }
    if (!personalList.length) det.append('<div class="nnb-empty">Здесь хранятся только твои личные вещи, духи, подарки и украшения (посетители лавки на них не покушаются). Нажми 🏪 на любой вещи, если захочешь выставить её на прилавок.</div>');
    [...personalList].reverse().forEach(x => {
        const row = $('<div class="nnb-note nnb-box-item"><div class="nnb-box-main"><div class="nnb-npc-text"></div><div class="nnb-npc-status"></div></div><div class="nnb-actions"><i class="fa-solid fa-pen" title="Изменить"></i><i class="fa-solid fa-trash" title="Убрать из шкатулки"></i></div></div>');
        if (x.rarity) row.addClass(`nnb-rar nnb-rar-${x.rarity}`);
        const r = x.rarity ? rarityOf(x.rarity) : null;
        row.find('.nnb-npc-text').text(`${x.title}${r ? ` ${r.stars}` : ''}`);
        if (x.origin || x.desc) row.find('.nnb-npc-status').text([x.desc, x.origin].filter(Boolean).join(' · ')); else row.find('.nnb-npc-status').remove();
        if (x.image) row.prepend(findThumb(x, '64px'));
        row.find('.nnb-box-main, .nnb-find-thumb').css('cursor', 'pointer').on('click', () => showFind(x));
        row.find('.fa-pen').on('click', async () => {
            const t = await askText('Что это за вещь?', x.title);
            if (t === null) return;
            const o = await askText('Откуда она? Например «подарок Кайлара на годовщину»', x.origin);
            if (o === null) return;
            if (t.trim()) { x.title = t.trim(); x.kind = x.rarity ? findKind(t) : accentKind(t); }
            x.origin = o.trim();
            await commit();
        });
        if ((st.wardrobe.equipped || []).includes(x.id)) {
            row.find('.nnb-meta, .nnb-npc-status').prepend('<span class="nnb-item-badge nnb-badge-equipped">🎒 с собой</span> ');
        } else if (x.giftedTo) {
            row.find('.nnb-meta, .nnb-npc-status').prepend(`<span class="nnb-item-badge nnb-badge-gifted">🎁 у ${escapeHtml(x.giftedTo)}</span> `);
        }
        const quickAct = $('<i class="fa-solid fa-wand-magic-sparkles" title="Применить в сцене"></i>').on('click', async (e) => {
            e.stopPropagation();
            const act = await askText(`Как применить «${x.title}» в сцене? Оставь пустым — модель решит сама.`);
            if (act === null) return;
            await applyItemInScene(x, act.trim());
        });
        row.find('.nnb-actions').prepend(quickAct);
        if (shopModeOn(st)) {
            const quickCounter = $('<i class="fa-solid fa-store" title="Выставить на прилавок лавки (с авто-наценкой)"></i>').on('click', async (e) => {
                e.stopPropagation();
                await toggleItemOnCounter(x);
            });
            row.find('.nnb-actions').prepend(quickCounter);
        }
        row.find('.fa-trash').on('click', async () => {
            w.box = w.box.filter(y => y !== x);
            w.equipped = (w.equipped || []).filter(id => id !== x.id);
            await commit();
        });
        det.append(row);
    });
    const boxBtns = $('<div class="nnb-buttons" style="display:flex; gap:6px; flex-wrap:wrap; margin-top:6px;"></div>');
    boxBtns.append($('<div class="menu_button"><i class="fa-solid fa-gem"></i> Добавить личную вещь</div>').on('click', async () => {
        const t = await askText('Что это? Например «духи с бергамотом», «кулон с аметистом», «старое письмо»');
        if (!t || !t.trim()) return;
        const o = await askText('Откуда она? Можно оставить пустым');
        if (o === null) return;
        const newItem = { id: w.nextItemId++, kind: findKind(t), title: t.trim(), desc: '', origin: o.trim(), onCounter: false, at: ctx().chat.length };
        w.box.push(newItem);
        await commit();
        if (wantImages() && canDrawScene()) {
            await withBusy('🎨 Рисую картинку для нового предмета…', async s2 => {
                await drawBoxItemsSheetBatch(s2, [newItem], newItem.kind === 'perfume' ? 'perfume' : 'accessory');
            });
        }
    }));
    const missingPicItems = personalList.filter(x => !x.image);
    if (missingPicItems.length) {
        boxBtns.append($(`<div class="menu_button"><i class="fa-solid fa-palette"></i> Нарисовать картинки вещам без фото (${missingPicItems.length})</div>`).on('click', async () => {
            if (!canDrawScene()) return toastr.warning('Выбери источник картинок в настройках «🎨 Картинки»', '🎨 Картинки');
            await withBusy('🎨 Рисую картинки предметам в шкатулке…', async s2 => {
                const needPerf = personalBoxItems(s2).filter(x => !x.image && x.kind === 'perfume').slice(0, 5);
                const needAcc = personalBoxItems(s2).filter(x => !x.image && x.kind !== 'perfume').slice(0, 5);
                if (needPerf.length) await drawBoxItemsSheetBatch(s2, needPerf, 'perfume');
                if (needAcc.length) await drawBoxItemsSheetBatch(s2, needAcc, 'accessory');
            });
        }));
    }
    det.append(boxBtns);
    root.append(det);
}

function renderWardrobe(st) {
    const root = $('#nnb_wardrobe_box').empty();
    if (!st.direction.wardrobe) return;
    const w = st.wardrobe;
    const det = $('<details open class="nnb-section"><summary>👗 Гардероб</summary></details>');
    root.append(det);

    // Поле точной внешности героини для примерочной NovelAI (цвет волос, глаз, фигура из Персоны)
    const appBox = $('<div class="nnb-note" style="margin-bottom:8px; padding:8px 10px;"></div>');
    appBox.append('<div style="font-weight:700; font-size:0.86em; margin-bottom:3px;">🎨 Моя внешность для примерочной NovelAI (цвет волос, глаз, рост и фигура на английском):</div>');
    appBox.append('<div class="nnb-npc-status" style="font-size:0.8em; margin-bottom:5px;">Эти теги с весом <code>1.3::...::</code> подставляются в каждый из 5 запросов гардероба, чтобы NovelAI всегда рисовал именно твою героиню из Персоны:</div>');
    const appRow = $('<div style="display:flex; gap:6px; align-items:flex-start; flex-wrap:wrap;"></div>');
    const appInput = $('<textarea class="text_pole" rows="2" style="flex:1; min-width:200px; margin:0; font-size:0.84em;" placeholder="Напр.: adult woman, long wavy auburn hair, green eyes, tall, slender hourglass figure, medium breasts, fair skin…"></textarea>')
        .val(w.customAppearanceEn || w.appearance || '');
    appInput.on('change', async function () {
        w.customAppearanceEn = String($(this).val() || '').trim();
        if (w.customAppearanceEn) {
            w.appearance = w.customAppearanceEn;
            if (w.active) w.active.appearance = w.customAppearanceEn;
        }
        await commit();
        toastr.success('Внешность для примерочной сохранена!', '👗 Гардероб');
    });
    const syncPersonaBtn = $('<div class="menu_button" style="margin:0; padding:6px 10px; font-size:0.82em; width:auto;" title="Автоматически вытащить цвет волос, глаз и фигуру из твоей анкеты Персоны и перевести в английские теги для NovelAI"><i class="fa-solid fa-wand-magic-sparkles"></i> Взять из Персоны</div>').on('click', async function () {
        const btn = $(this);
        btn.css({ opacity: 0.6, pointerEvents: 'none' }).html('<i class="fa-solid fa-spinner fa-spin"></i> Перевожу…');
        try {
            w.customAppearanceEn = '';
            const extracted = await ensureHeroineAppearanceEnForNai(st, w.active);
            appInput.val(extracted || '');
            toastr.success('Теги внешности из анкеты Персоны переведены и закреплены для гардероба!', '👗 Гардероб');
        } finally {
            btn.css({ opacity: 1, pointerEvents: 'auto' }).html('<i class="fa-solid fa-wand-magic-sparkles"></i> Взять из Персоны');
        }
    });
    appRow.append(appInput, syncPersonaBtn);
    appBox.append(appRow);
    det.append(appBox);
    const a = w.active;
    if (a?.status === 'choosing') {
        const box = $('<div class="nnb-note nnb-event"><div class="nnb-event-title">Образы ждут выбора</div><div class="nnb-meta"></div></div>');
        box.find('.nnb-meta').text(a.occasion || 'для ближайшей сцены');
        const open = $('<div class="menu_button"><i class="fa-solid fa-shirt"></i> Выбрать образ</div>').on('click', presentLooks);
        const cancel = $('<div class="menu_button"><i class="fa-solid fa-xmark"></i> Не нужно</div>').on('click', async () => {
            w.active = null;
            if (st.map?.pendingTravel) delete st.map.pendingTravel;
            await commit();
        });
        box.append(open, cancel);
        det.append(box);
    } else if (a?.status === 'worn') {
        const banner = renderActiveWornBanner(st, () => renderPanel());
        if (banner) det.append(banner);
    } else {
        det.append('<div class="nnb-empty">Модель сама предложит выбрать наряд, когда он будет важен для сцены. Или выбери из шкафа ниже.</div>');
    }
    const wardBtns = $('<div class="nnb-buttons" style="margin-top:8px; display:flex; gap:6px; flex-wrap:wrap;"></div>');
    wardBtns.append($(`<div class="menu_button"><i class="fa-solid fa-shirt"></i> Открыть шкаф и штрихи (${(w.closet || []).length})</div>`).on('click', openClosetPopup));
    wardBtns.append($('<div class="menu_button"><i class="fa-solid fa-wand-magic-sparkles"></i> Сгенерировать 5 новых образов</div>').on('click', () => promptGenerateNewOutfits()));
    wardBtns.append($('<div class="menu_button"><i class="fa-solid fa-palette"></i> Нарисовать картинки шкафа и штрихов</div>').on('click', () => runDrawStarterVisuals(false)));
    det.append(wardBtns);

    if ((w.closet || []).length) {
        const clDet = $('<details open class="nnb-section"><summary></summary></details>');
        clDet.find('summary').text(`👚 Наряды в шкафу (${w.closet.length})`);
        const grid = $('<div style="display:grid; grid-template-columns:repeat(auto-fill, minmax(230px, 1fr)); gap:8px; margin-top:6px;"></div>');
        w.closet.forEach(item => {
            const isWorn = a?.status === 'worn' && a.look?.title === item.title;
            const row = $('<div class="nnb-note" style="display:flex; gap:10px; align-items:flex-start; margin:0;"></div>');
            if (isWorn) row.css('border-color', 'var(--SmartThemeQuoteColor, #8b78c4)');
            if (item.image) {
                const th = lookThumb(item, '72px', '104px');
                th.css('cursor', 'pointer').on('click', () => wearFromCloset(item, '', true));
                row.append(th);
            }
            const mid = $('<div style="flex:1; min-width:0; cursor:pointer;"></div>').on('click', () => wearFromCloset(item, '', true));
            mid.append($('<div class="nnb-meta"></div>').text(`${item.category || 'Повседневный'}${item.season ? ` · ${item.season}` : ''}${isWorn ? ' · 👕 надето' : ''}`));
            mid.append($('<div class="nnb-npc-text" style="font-weight:600;"></div>').text(`«${item.title}»`));
            mid.append($('<div class="nnb-npc-status" style="font-size:0.84em;"></div>').text(item.desc));
            const acts = $('<div class="nnb-actions" style="display:flex; flex-direction:column; gap:5px;"></div>');
            acts.append($('<i class="fa-solid fa-shirt" title="Надеть сейчас"></i>').on('click', () => wearFromCloset(item, '', true)));
            acts.append($('<i class="fa-solid fa-pen" title="Изменить"></i>').on('click', async () => {
                const t = await askText('Название наряда', item.title);
                if (t === null) return;
                const c = await askText('Категория (Повседневный, Рабочий, На выход, Домашний, По погоде, Спортивный)', item.category || 'Повседневный');
                if (c === null) return;
                const d = await askText('Описание наряда', item.desc);
                if (d === null) return;
                if (t.trim()) item.title = t.trim();
                item.category = normalizeClosetCat(c);
                item.desc = d.trim();
                await commit();
            }));
            acts.append($('<i class="fa-solid fa-trash" title="Удалить"></i>').on('click', async () => {
                w.closet = w.closet.filter(x => x.id !== item.id);
                await commit();
            }));
            row.append(mid, acts);
            grid.append(row);
        });
        clDet.append(grid);
        det.append(clDet);
    }

    // Готовые штрихи: Духи и Аксессуары с картинками прямо во вкладке Гардероба
    det.append(renderReadyAccentsBlock(st, () => renderPanel()));

    const aura = auraInjection(st);
    if (aura) det.append($('<div class="nnb-npc-status" style="margin-top:8px;"></div>').text(`💎 Сейчас действует талисман: ${w.aura.title}${w.aura.effects ? ` — ${w.aura.effects}` : ''}`));
    if (w.history.length) {
        const hist = $('<details style="margin-top:8px;"><summary></summary></details>');
        hist.find('summary').text(`История образов (${w.history.length})`);
        [...w.history].reverse().forEach(h => {
            const row = $('<div class="nnb-note"><div class="nnb-meta"></div><div class="nnb-npc-text"></div><div class="nnb-npc-status"></div></div>');
            row.find('.nnb-meta').text([h.date ? formatDate(h.date) : '', h.occasion].filter(Boolean).join(' · '));
            row.find('.nnb-npc-text').text(`«${h.title}»${h.accent ? ` + ${(ACCENT_KINDS[h.accent.kind] || ACCENT_KINDS.accessory).icon} ${h.accent.title}` : ''}`);
            row.find('.nnb-npc-status').text(h.result);
            row.css('cursor', 'pointer').on('click', () => openPopup(revealCard(h)));
            hist.append(row);
        });
        det.append(hist);
    }
}

// Метки в ответе модели: <!--✓2--> (задача праздника выполнена), <!--день+1--> (наступил следующий день)

function parseActionPrompts(raw) {
    if (!raw) return [];
    let text = String(raw).trim().replace(/[*_~`]/g, '');
    let parts = [];
    if (text.includes('|')) {
        parts = text.split('|');
    } else if (text.includes('\n')) {
        parts = text.split(/\r?\n/);
    } else if (text.includes(' / ')) {
        parts = text.split(' / ');
    } else {
        parts = text.split(/(?:^|\s+)(?:\d+[.)]\s*|[•-]\s*)/).filter(Boolean);
    }
    return parts.map(p => {
        return p.trim()
            .replace(/^[-*•\d.)\s]+/, '')
            .replace(/^[\[«"']|[\]»"']$/g, '')
            .replace(/^[-—–\s]+/, '')
            .trim();
    }).filter(p => p.length > 1 && !/^actions?$/i.test(p)).slice(0, 5);
}

function chooseActionPrompt(text, autoSend = false) {
    const textarea = $('#send_textarea');
    if (!textarea.length) return;
    textarea.val(text).trigger('input').focus();
    try {
        textarea[0].dispatchEvent(new Event('input', { bubbles: true }));
    } catch (e) { /* ignore */ }
    try {
        textarea[0]?.scrollIntoView?.({ behavior: 'smooth', block: 'nearest' });
    } catch (e) { /* ignore */ }
    if (autoSend) {
        const sendBtn = $('#send_but');
        if (sendBtn.length) {
            setTimeout(() => sendBtn.trigger('click'), 60);
        }
    }
}

