function pickRandom(arr) {
    return arr[Math.floor(Math.random() * arr.length)];
}

function isShopOwnerJob(jobStr) {
    return /лавк|антиквар|редкост|магазин|бутик|витрин/i.test(String(jobStr || ''));
}

function buildWorldCreationPrompt(st, cfg) {
    const names = storyNames();
    const sName = cfg.date ? season(cfg.date).name : 'осень';
    const hobbiesStr = (cfg.hobbies || []).join(', ') || 'прогулки по городу';
    const charLine = cfg.freeWorld
        ? `Формат игры: СВОБОДНОЕ ИССЛЕДОВАНИЕ МИРА без привязки к одному стартовому фавориту. Не привязывай всё к ${names.char} — создай живое окружение вокруг ${names.user}, включая 1–2 харизматичных новых NPC с потенциалом интересного знакомства или романтической линии.`
        : `Отношения с ${names.char} на старте: ${cfg.charRel}.`;
    const hasShop = isShopOwnerJob(cfg.job);
    const cur = detectCurrencyForPlace(cfg.countryCode, cfg.countryName, cfg.city);

    return `[OOC: Пауза в ролевой игре. Сейчас ты НЕ пишешь ответ персонажа. Ты — ведущий автор и создаёшь полный стартовый набор мира и персонажа (${names.user}) по выбранным параметрам.

Параметры старта:
— Место действия: ${cfg.city}${cfg.countryName ? `, ${cfg.countryName}` : ''}.
— Дата и сезон: ${cfg.date ? `${formatDate(cfg.date)} (${sName})` : sName}.
— Жильё ${names.user}: ${cfg.home}.
— Точка старта: ${cfg.startVibe}.
— Профессия / занятие ${names.user}: ${cfg.job}.
— Хобби и увлечения ${names.user}: ${hobbiesStr}.
— Достаток: ${cfg.wealth} (валюта места: ${cur}).${cfg.pet && cfg.pet !== 'Без питомца' ? ` Питомец дома: ${cfg.pet}.` : ''}
— ${charLine}
${buildDirection(st)}

Сгенерируй за один раз весь стартовый пакет строго по шаблону ниже, без вступлений и пояснений:

1) Местный колорит и внешность для художника (2 строки):
FLAVOR: 2–3 предложения о колорите места (еда, валюта, транспорт, погода в сезон «${sName}», атмосфера улиц и привычки местных)
APPEARANCE: внешность ${names.user} по-английски для художника — пол, возраст, волосы, глаза, телосложение, заметные черты

2) 5 стартовых локаций на Карте (дом ${names.user}, место работы/лавка, место под хобби, уютное кафе/бар и одно необычное/тайное место города). В КАЖДУЮ локацию обязательно заложи сразу 2–3 конкретных сюжетных крючка через точку с запятой (необычная деталь, слух, местная странность, колоритный завсегдатай или микро-сценка):
MAP: название места | что это за место (1 предложение) | крючок 1; крючок 2; крючок 3
(ровно 5 строк MAP)

3) 4 стартовых NPC из окружения ${names.user} (например: коллега/поставщик/постоянный клиент по работе «${cfg.job}», подруга или сосед, знакомый по хобби «${hobbiesStr}», интересный незнакомец/потенциальный фаворит) и их связи с ${names.user}:
NPC [Имя]: кто это, возраст, подробная внешность, характер, биография и отношение к ${names.user} (3–6 предложений в одну строку)
REL [${names.user} ↔ Имя]: тип связи | что между ними сейчас
(4 пары строк NPC и REL)

4) Стартовый гардероб ${names.user} на сезон «${sName}» — ровно 5 нарядов под разные поводы (Повседневный, Рабочий, На выход, Домашний, По погоде), учитывая достаток (${cfg.wealth}) и профессию (${cfg.job}), с коротким английским описанием для рисования картинки:
CLOSET: категория (Повседневный|Рабочий|На выход|Домашний|По погоде) | название образа | подробное описание по-русски: что надето, обувь, причёска (1–2 предложения) | коротко по-английски только одежда, обувь и причёска для художника
(ровно 5 строк CLOSET)

5) 5 готовых вариантов духов (штрихов к образу) для ${names.user} под разное настроение — с английским описанием флакона для рисования картинки:
PERF_ITEM: название духов | описание аромата, нот и настроения по-русски в 1 предложении | коротко по-английски как выглядит флакон духов (elegant perfume bottle...)
(ровно 5 строк PERF_ITEM)

6) 5 готовых аксессуаров и украшений (штрихов к образу) для ${names.user} — с английским описанием предмета для рисования картинки:
ACC_ITEM: название аксессуара | описание украшения, шарфа, часов или сумочки по-русски в 1 предложении | коротко по-английски как выглядит этот предмет (vintage silver locket, silk scarf...)
(ровно 5 строк ACC_ITEM)

7) Семья и династия (по 1 строке для ${names.user} и ${names.char} — кто их родители/родня и какая у семьи атмосфера или история) + базовое описание комнаты дома ${names.user} по-английски для художника:
FAMILY_USER: кто в семье ${names.user}, какие у них отношения и семейная деталь
FAMILY_CHAR: кто в семье и близком кругу ${names.char}, семейная история или деталь
HOME_ROOM: описание уютной комнаты ${names.user} («${cfg.home}») по-английски для генерации картинки интерьера (cozy bedroom/studio interior, furniture, window, lighting, no people)

8) 5 стартовых тем для разговора (о чём ${names.user} может заговорить с персонажами в первых сценах — по 5 разным эмоциональным и сюжетным крючкам):
TOPIC: короткое название темы | реплика или идея от лица ${names.user}, с чего начать этот разговор
(ровно 5 строк TOPIC)

9) 3 оригинальных, самобытных тренда сезона в этом городе и сеттинге (1 — модная вещь гардероба или аксессуар, 2 — гастрономический хит сезона, выпечка, десерт или напиток из местного заведения, 3 — коллекционная вещица, сувенир или предмет для этого сезона) с коротким английским описанием внешнего вида для рисования картинки:
TREND: Одежда|Еда|Коллекция | название тренда | что это такое и почему вокруг этого сейчас ажиотаж в городе (1–2 предложения) | коротко по-английски как выглядит этот предмет, одежда, десерт или вещица для художника (без людей и рук)
(ровно 3 строки TREND)${hasShop ? `

10) Стартовые товары на прилавке лавки ${names.user} («${cfg.job}») — 3 колоритных диковинки/товара на продажу посетителям (плагин сам добавит наценку +50% к закупочной цене):
COUNTER: редкость (common|rare|epic) | название товара | описание и интригующая деталь/история вещи в 1 предложении | закупочная цена числом в ${cur}
(ровно 3 строки COUNTER)` : ''}]`;
}

function applyWorldCreationResult(st, cfg, raw) {
    const counts = { places: 0, npcs: 0, closet: 0, perfumes: 0, accessories: 0, counter: 0 };
    const rawLines = answerLines(raw);
    const WORLD_CMD_RE = /^(?:FLAVOR|APPEARANCE|MAP|NPC|REL|CLOSET|PERF_?ITEM|ACC_?ITEM|BOX|TREND|COUNTER|FAMILY_?USER|FAMILY_?CHAR|SOCIAL_?CIRCLE|HOME_?ROOM|TOPIC)(?:\b|[\s\[:：—–-])/i;
    const lines = [];
    for (const rl of rawLines) {
        if (WORLD_CMD_RE.test(rl) || !lines.length) {
            lines.push(rl);
        } else if (/[:：—–-]\s*$/.test(lines[lines.length - 1])) {
            lines[lines.length - 1] = `${lines[lines.length - 1]} ${rl}`;
        } else {
            lines[lines.length - 1] = `${lines[lines.length - 1]} // ${rl}`;
        }
    }
    const len = ctx().chat?.length ?? 0;

    for (const line of lines) {
        let m = line.match(/^FLAVOR\s*[:：—–-]\s*(.+)$/i);
        if (m) {
            st.time.flavor = cleanFlavor(m[1]);
            continue;
        }
        m = line.match(/^APPEARANCE\s*[:：—–-]\s*(.+)$/i);
        if (m) {
            st.wardrobe.appearance = m[1].trim().replace(/\]$/, '');
            continue;
        }
        m = line.match(/^MAP\s*[:：—–-]\s*(.+)$/i);
        if (m) {
            const pl = addPlace(st, m[1], 'start');
            if (pl) {
                counts.places++;
                if (counts.places === 1 && !st.map.current) st.map.current = pl.id;
            }
            continue;
        }
        m = line.match(/^NPC(?!STATE)\s*[:：]?\s*(?:\[([^\]]{1,60})\]|([^:：—–\n]{1,45}?))\s*(?:[:：]|\s+[—–-]\s+)\s*(.+)$/i);
        if (m) {
            const name = (m[1] || m[2] || '').trim();
            const desc = (m[3] || '').trim().replace(/\]$/, '').replace(/\s*\/\/\s*/g, '\n').trim();
            if (name && desc && !findNpc(st, name)) {
                st.npcs.push({ id: st.nextNpcId++, name, card: desc, status: '', locked: true, at: len });
                counts.npcs++;
            }
            continue;
        }
        m = line.match(/^REL\s*[:：]?\s*\[?([^\]:：—–\n]+?)\s*(↔|<->|->|→)\s*([^\]:：—–\n]+?)\]?\s*[:：—–-]\s*(.+)$/i);
        if (m) {
            const a = m[1].trim();
            const arrow = (m[2] === '->' || m[2] === '→') ? '→' : '↔';
            const b = m[3].trim();
            const rest = m[4].trim().replace(/\]$/, '');
            const parts = rest.split('|').map(x => x.trim());
            const type = parts.length > 1 ? parts[0] : 'знакомые';
            const desc = parts.length > 1 ? parts.slice(1).join(' | ') : rest;
            if (!findRel(st, a, b)) {
                st.relationships.push({ id: st.nextRelId++, a, b, arrow, type, desc, locked: false, at: len });
            }
            continue;
        }
        m = line.match(/^CLOSET\s*[:：—–-]\s*(.+)$/i);
        if (m) {
            const parts = m[1].split('|').map(x => x.trim());
            if (parts.length >= 2) {
                const cat = parts.length >= 3 ? parts[0] : 'Повседневный';
                const title = (parts.length >= 3 ? parts[1] : parts[0]).replace(/^[«"]|[»"]$/g, '');
                const desc = (parts.length >= 3 ? parts[2] : parts[1]).replace(/\]$/, '');
                const en = parts.length >= 4 ? parts.slice(3).join(' | ').replace(/\]$/, '') : '';
                if (addLookToCloset(st, { category: cat, title, desc, en })) counts.closet++;
            }
            continue;
        }
        m = line.match(/^PERF_ITEM\s*[:：—–-]\s*(.+)$/i);
        if (m) {
            const parts = m[1].split('|').map(x => x.trim());
            if (parts.length >= 1) {
                const title = parts[0].replace(/^[«"]|[»"]$/g, '');
                const desc = (parts[1] || '').replace(/\]$/, '');
                const en = (parts[2] || `elegant glass perfume bottle, ${title}`).replace(/\]$/, '');
                if (title && !st.wardrobe.box.some(x => x.title.toLowerCase() === title.toLowerCase())) {
                    st.wardrobe.box.push({ id: st.wardrobe.nextItemId++, kind: 'perfume', title, desc, en, origin: 'стартовая коллекция духов', onCounter: false, at: len });
                    counts.perfumes++;
                }
            }
            continue;
        }
        m = line.match(/^ACC_ITEM\s*[:：—–-]\s*(.+)$/i);
        if (m) {
            const parts = m[1].split('|').map(x => x.trim());
            if (parts.length >= 1) {
                const title = parts[0].replace(/^[«"]|[»"]$/g, '');
                const desc = (parts[1] || '').replace(/\]$/, '');
                const en = (parts[2] || `stylish fashion accessory, ${title}`).replace(/\]$/, '');
                if (title && !st.wardrobe.box.some(x => x.title.toLowerCase() === title.toLowerCase())) {
                    st.wardrobe.box.push({ id: st.wardrobe.nextItemId++, kind: 'accessory', title, desc, en, origin: 'стартовая шкатулка аксессуаров', onCounter: false, at: len });
                    counts.accessories++;
                }
            }
            continue;
        }
        m = line.match(/^BOX\s*[:：—–-]\s*(.+)$/i);
        if (m) {
            const parts = m[1].split('|').map(x => x.trim());
            if (parts.length >= 2) {
                const kind = accentKind(parts[0]);
                const title = (parts.length >= 3 ? parts[1] : parts[0]).replace(/^[«"]|[»"]$/g, '');
                const desc = (parts.length >= 3 ? parts[2] : parts[1]).replace(/\]$/, '');
                const en = parts.length >= 4 ? parts[3].replace(/\]$/, '') : '';
                if (title && !st.wardrobe.box.some(x => x.title.toLowerCase() === title.toLowerCase())) {
                    st.wardrobe.box.push({ id: st.wardrobe.nextItemId++, kind, title, desc, en, origin: 'стартовый набор', onCounter: false, at: len });
                    if (kind === 'perfume') counts.perfumes++; else counts.accessories++;
                }
            }
            continue;
        }
        m = line.match(/^FAMILY_USER\s*[:：—–-]\s*(.+)$/i);
        if (m) {
            st.dynasty = st.dynasty || {};
            st.dynasty.userFamily = m[1].trim().replace(/\]$/, '');
            continue;
        }
        m = line.match(/^FAMILY_CHAR\s*[:：—–-]\s*(.+)$/i);
        if (m) {
            st.dynasty = st.dynasty || {};
            st.dynasty.charFamily = m[1].trim().replace(/\]$/, '');
            continue;
        }
        m = line.match(/^HOME_ROOM\s*[:：—–-]\s*(.+)$/i);
        if (m) {
            st.home = st.home || { roomName: cfg.home || 'Моя комната', placed: [] };
            st.home.baseEn = m[1].trim().replace(/\]$/, '');
            st.home.roomName = cfg.home || 'Моя комната';
            continue;
        }
        m = line.match(/^TOPIC\s*[:：—–-]\s*(.+)$/i);
        if (m) {
            const parts = m[1].split('|').map(x => x.trim());
            const title = (parts[0] || '').replace(/^[«"]|[»"]$/g, '');
            const promptText = (parts.slice(1).join(' | ') || title).replace(/\]$/, '').trim();
            if (title) {
                if (!Array.isArray(st.topics)) st.topics = [];
                if (!st.nextTopicId) st.nextTopicId = 1;
                st.topics.push({ id: st.nextTopicId++, title, prompt: promptText, at: len });
            }
            continue;
        }
        m = line.match(/^TREND\s*[:：—–-]\s*(.+)$/i);
        if (m) {
            const parts = m[1].split('|').map(x => x.trim());
            if (parts.length >= 2) {
                const category = parts[0] || 'Тренд';
                const title = (parts[1] || '').replace(/^[«"]|[»"]$/g, '');
                const desc = (parts[2] || '').replace(/\]$/, '');
                const en = (parts[3] || `${title}, ${category}`).replace(/\]$/, '');
                if (title) {
                    if (!Array.isArray(st.trends)) st.trends = [];
                    if (!st.nextTrendId) st.nextTrendId = 1;
                    st.trends.push({ id: st.nextTrendId++, category, title, desc, en, at: len });
                }
            }
            continue;
        }
        m = line.match(/^COUNTER\s*[:：—–-]\s*(.+)$/i);
        if (m) {
            const parts = m[1].split('|').map(x => x.trim());
            if (parts.length >= 2) {
                const rarRaw = parts[0].toLowerCase();
                const rarity = ['common', 'rare', 'epic', 'legendary'].includes(rarRaw) ? rarRaw : 'rare';
                const title = (parts.length >= 3 ? parts[1] : parts[0]).replace(/^[«"]|[»"]$/g, '');
                const desc = (parts.length >= 3 ? parts[2] : parts[1]).replace(/\]$/, '');
                const buyCost = parts.length >= 4 ? parsePriceNumber(parts[3]) : 0;
                if (title && !st.wardrobe.box.some(x => x.title.toLowerCase() === title.toLowerCase())) {
                    const item = {
                        id: st.wardrobe.nextItemId++,
                        kind: findKind(title),
                        title,
                        desc,
                        rarity,
                        origin: 'стартовая витрина лавки',
                        buyPrice: buyCost,
                        onCounter: true,
                        at: len,
                    };
                    ensureCounterPrice(item, st);
                    st.wardrobe.box.push(item);
                    counts.counter++;
                }
            }
            continue;
        }
    }

    // Надеваем первый повседневный наряд + первые духи и первый аксессуар как готовые штрихи (только если на героине ещё ничего не надето!)
    if (st.wardrobe.closet.length && !st.wardrobe.active) {
        const firstLook = st.wardrobe.closet.find(c => c.category === 'Повседневный') || st.wardrobe.closet[0];
        const firstPerfume = personalBoxItems(st).find(x => x.kind === 'perfume');
        const firstAcc = personalBoxItems(st).find(x => x.kind !== 'perfume');
        const selectedAccents = [firstPerfume, firstAcc].filter(Boolean).map(x => ({
            id: x.id,
            kind: x.kind,
            title: x.title,
            desc: x.desc || '',
            origin: x.origin || '',
            image: x.image || '',
            crop: x.crop || null,
            fromBox: true,
        }));
        st.wardrobe.active = {
            occasion: firstLook.category || 'Стартовый образ',
            look: { ...firstLook },
            options: [firstLook],
            accents: [],
            selectedAccents,
            accent: selectedAccents[0] || null,
            status: 'worn',
            at: len,
            date: st.time.date || '',
        };
    }

    return counts;
}

// ===================== 🏠 Мой дом (Комната с расстановкой предметов за 0 токенов и картинкой по референсам) =====================
const HOME_SPOTS = [
    'на прикроватном столике',
    'на книжной полке',
    'на рабочем столе',
    'на подоконнике у окна',
    'на стене (как декор)',
    'на комоде у зеркала',
    'на журнальном столике',
];

// Вырезаем точную картинку предмета из общего листа в отдельный dataURL через canvas, чтобы передать генератору как референс!
async function cropItemToDataUrl(item) {
    if (!item?.image) return '';
    try {
        const srcDataUrl = await fileToDataUrl(item.image);
        const imgSrc = srcDataUrl || item.image;
        return await new Promise(resolve => {
            const img = new Image();
            img.crossOrigin = 'anonymous';
            img.onload = () => {
                try {
                    const W = img.naturalWidth || 512;
                    const H = img.naturalHeight || 512;
                    const c = item.crop || { x: 0, y: 0, w: 1, h: 1 };
                    const sx = Math.max(0, Math.round(c.x * W));
                    const sy = Math.max(0, Math.round(c.y * H));
                    const sw = Math.max(16, Math.min(W - sx, Math.round(c.w * W)));
                    const sh = Math.max(16, Math.min(H - sy, Math.round(c.h * H)));
                    const cv = document.createElement('canvas');
                    cv.width = 384;
                    cv.height = 384;
                    const g = cv.getContext('2d');
                    g.fillStyle = '#f4f1ee';
                    g.fillRect(0, 0, 384, 384);
                    const scale = Math.min(360 / sw, 360 / sh);
                    const dw = Math.round(sw * scale);
                    const dh = Math.round(sh * scale);
                    g.drawImage(img, sx, sy, sw, sh, Math.round((384 - dw) / 2), Math.round((384 - dh) / 2), dw, dh);
                    resolve(cv.toDataURL('image/png'));
                } catch (e) {
                    resolve(srcDataUrl || '');
                }
            };
            img.onerror = () => resolve(srcDataUrl || '');
            img.src = imgSrc;
        });
    } catch (e) {
        return '';
    }
}

async function drawHomeRoom(st, forceBaseReset = false) {
    if (!canDrawScene()) {
        toastr.warning('Выбери источник картинок в настройках «🎨 Картинки»', '🏠 Мой дом');
        return '';
    }
    if (!st.home) st.home = { roomName: st.worldProfile?.home || 'Моя комната', styleDesc: '', baseEn: '', image: '', placed: [] };
    const home = st.home;
    const sName = st.time?.date ? season(st.time.date).name : 'осень';
    const baseRoomEn = home.baseEn || `cozy detailed room interior (${home.roomName || st.worldProfile?.home || 'apartment bedroom and living area'}), warm inviting lighting, window with ${sName} view outside, bed, desk, shelves, nightstand`;

    const placedItems = (home.placed || []).map(p => {
        const it = (st.wardrobe?.box || []).find(x => x.id === p.itemId);
        return it ? { item: it, spot: p.spot } : null;
    }).filter(Boolean);

    const spotEnMap = {
        'на прикроватном столике': 'on the nightstand next to the bed',
        'на книжной полке': 'on the wooden bookshelf',
        'на рабочем столе': 'on the writing desk',
        'на подоконнике у окна': 'on the windowsill by the window',
        'на стене (как декор)': 'mounted/displayed on the wall',
        'на комоде у зеркала': 'on the dresser near the mirror',
        'на журнальном столике': 'on the coffee table',
    };

    const placedPromptParts = placedItems.map((p, idx) => {
        const itemEn = p.item.en || p.item.desc || p.item.title;
        const whereEn = spotEnMap[p.spot] || p.spot;
        return `${idx + 1}) ${itemEn} (${p.item.title}) placed ${whereEn}`;
    });

    const isNai = settings().imageSource === 'novelai';
    let resolvedBaseRoomEn = baseRoomEn;
    let resolvedPlacedParts = placedPromptParts;

    // Если выбран NovelAI, а стиль комнаты или названия предметов написаны по-русски — автоматически переводим их в точные английские теги интерьера Danbooru!
    if (isNai && (/[а-яА-ЯёЁ]/.test(resolvedBaseRoomEn) || placedItems.some(p => /[а-яА-ЯёЁ]/.test(p.item.en || p.item.desc || p.item.title)))) {
        try {
            const itemsListRu = placedItems.map((p, idx) => `${idx + 1}) "${p.item.title}" (${p.item.en || p.item.desc || p.item.title}) — location: ${spotEnMap[p.spot] || p.spot}`).join('\n');
            const trPrompt = `[OOC: Translate this room interior description and placed items into concise English Danbooru/NovelAI tags for an anime background illustration (scenery, indoors, no humans).
Room description: ${resolvedBaseRoomEn}
${itemsListRu ? `Placed items in the room:\n${itemsListRu}` : ''}
Reply strictly with one single line of English comma-separated tags describing the room architecture, lighting, furniture, and each placed item in its location. Do NOT include any people or characters.]`;
            const rawTr = await quietGenerateImagePrompt(trPrompt);
            const cleanedTr = String(rawTr || '').replace(/^(?:ROOM|PROMPT|SCENE)\s*[:：—–-]\s*/i, '').replace(/[\r\n]+/g, ', ').trim();
            if (cleanedTr && /[a-zA-Z]{4,}/.test(cleanedTr)) {
                resolvedBaseRoomEn = cleanedTr;
                resolvedPlacedParts = [];
            }
        } catch (e) {
            console.warn('[npc_notebook] room translation for NovelAI failed:', e);
        }
    }

    // Собираем картинки-референсы только для генераторов, поддерживающих редактирование интерьеров (НЕ для NovelAI Character Reference, который предназначен только для лиц людей!)
    const refImages = [];
    const refNotes = [];
    if (!isNai) {
        if (home.image && !forceBaseReset) {
            const roomDataUrl = await fileToDataUrl(home.image);
            if (roomDataUrl) {
                refImages.push(roomDataUrl);
                refNotes.push('Image #1 is the existing room interior: keep the exact same room architecture, furniture layout, camera angle, walls, window, and lighting.');
            }
        }
        for (const p of placedItems) {
            if (refImages.length >= 5) break;
            if (p.item.image) {
                const croppedUrl = await cropItemToDataUrl(p.item);
                if (croppedUrl) {
                    refImages.push(croppedUrl);
                    const whereEn = spotEnMap[p.spot] || p.spot;
                    refNotes.push(`Image #${refImages.length} is the exact visual reference for the item "${p.item.en || p.item.title}" — draw this exact item (matching its design, colors, and shape from the reference image) ${whereEn}.`);
                }
            }
        }
    }

    const refs = isNai
        ? { extraNeg: '1girl, 1boy, person, character, human, multiple girls, multiple boys, face, hands, text, watermark' }
        : (refImages.length ? {
            images: refImages,
            note: refNotes.join(' ') + ' Keep the room cohesive and natural.',
        } : null);

    const fullPrompt = cleanForCommand(
        (isNai ? 'no humans, scenery, indoors, detailed room interior, ' : `${ITEM_STYLE}, detailed cozy room interior illustration: `) +
        `${resolvedBaseRoomEn}. ` +
        (resolvedPlacedParts.length ? `Visible personal items arranged in the room: ${resolvedPlacedParts.join('; ')}. ` : '') +
        `No people, no characters, no text, no captions.`
    );

    const prevImg = home.image;
    const url = await drawPicture(fullPrompt, refs, 'landscape');
    if (url) {
        if (!Array.isArray(home.images)) home.images = [];
        if (prevImg && !home.images.includes(prevImg)) home.images.push(prevImg);
        if (!home.images.includes(url)) home.images.push(url);
        home.image = url;
        await ctx().saveMetadata();
    }
    return url;
}

async function openHomeModal() {
    const st = store();
    if (!st) return toastr.warning('Сначала открой чат', '🏠 Мой дом');
    if (!st.home || typeof st.home !== 'object') {
        st.home = { roomName: st.worldProfile?.home || 'Уютная комната', styleDesc: '', baseEn: '', image: '', images: [], placed: [] };
    }
    if (!Array.isArray(st.home.placed)) st.home.placed = [];
    if (!Array.isArray(st.home.images)) st.home.images = st.home.image ? [st.home.image] : [];
    (st.wardrobe?.box || []).forEach(item => {
        if (item && (typeof item.id !== 'number' || Number.isNaN(item.id))) {
            item.id = st.wardrobe.nextItemId++;
        }
    });

    const batchChecked = new Set();
    const batchSpotMap = new Map();

    const flushCheckedIntoPlaced = () => {
        let added = 0;
        batchChecked.forEach(itemId => {
            const spot = batchSpotMap.get(itemId) || HOME_SPOTS[0];
            const existing = st.home.placed.find(p => p.itemId === itemId);
            if (existing) {
                existing.spot = spot;
            } else {
                st.home.placed.push({ itemId, spot });
                added++;
            }
        });
        batchChecked.clear();
        return added;
    };

    const el = $('<div class="nnb-pop nnb-pop-visual"></div>');
    const renderRoomUI = () => {
        el.empty();
        const home = st.home;
        el.append($('<h3></h3>').text(`🏠 ${home.roomName || st.worldProfile?.home || 'Мой дом: Комната'}`));
        el.append('<div class="nnb-pop-sub">Отметь галочками вещи из шкатулки (или нажми «➕ Поставить» на нужной вещи), выбери для каждой место и обнови картинку комнаты! Все сгенерированные варианты комнаты сохраняются — между ними можно свободно переключаться.</div>');

        if (home.image) {
            const imgWrap = $('<div style="text-align:center; margin:8px 0;"></div>');
            const img = $('<img alt="Комната" style="max-width:100%; max-height:360px; border-radius:12px; border:2px solid var(--SmartThemeQuoteColor, #8b78c4); box-shadow:0 4px 16px rgba(0,0,0,0.3); cursor:pointer;">')
                .attr('src', home.image)
                .attr('title', 'Нажми, чтобы открыть во весь экран')
                .on('click', () => window.open(home.image, '_blank'));
            imgWrap.append(img);

            const homeImgs = Array.isArray(home.images) && home.images.length ? home.images : [home.image];
            let curHomeIdx = homeImgs.indexOf(home.image);
            if (curHomeIdx < 0) curHomeIdx = homeImgs.length - 1;
            const isLastHome = curHomeIdx >= homeImgs.length - 1;
            const verRow = $('<div style="display:flex; justify-content:center; gap:6px; flex-wrap:wrap; margin-top:6px; align-items:center;"></div>');
            const prevHomeBtn = $(`<div class="menu_button" style="padding:3px 9px; font-size:0.82em; margin:0; ${curHomeIdx <= 0 ? 'opacity:0.35; pointer-events:none;' : ''}" title="Предыдущий вариант комнаты (◀)"><i class="fa-solid fa-chevron-left"></i></div>`).on('click', async () => {
                if (curHomeIdx <= 0) return;
                home.image = homeImgs[curHomeIdx - 1];
                await commit();
                renderRoomUI();
            });
            verRow.append(prevHomeBtn);
            homeImgs.forEach((imgUrl, vIdx) => {
                const isCur = imgUrl === home.image;
                const vBtn = $(`<div class="menu_button ${isCur ? 'nnb-btn-primary' : ''}" style="padding:3px 9px; font-size:0.8em; margin:0;">Вариант ${vIdx + 1}</div>`).on('click', async () => {
                    home.image = imgUrl;
                    await commit();
                    renderRoomUI();
                });
                verRow.append(vBtn);
            });
            const nextHomeBtn = $(`<div class="menu_button ${isLastHome ? 'nnb-btn-primary' : ''}" style="padding:3px 10px; font-size:0.82em; margin:0;" title="${isLastHome ? 'Сделать ещё одну генерацию комнаты по тому же промпту (▶)' : 'Следующий вариант комнаты (▶)'}"><i class="fa-solid fa-chevron-right"></i>${isLastHome ? ' + Ещё' : ''}</div>`).on('click', async () => {
                if (!isLastHome) {
                    home.image = homeImgs[curHomeIdx + 1];
                    await commit();
                    renderRoomUI();
                } else {
                    if (batchChecked.size > 0) {
                        flushCheckedIntoPlaced();
                        await commit();
                    }
                    await withBusy('🎨 Рисую ещё один вариант комнаты по тому же промпту…', async s2 => {
                        await drawHomeRoom(s2, false);
                    });
                    renderRoomUI();
                }
            });
            verRow.append(nextHomeBtn);
            imgWrap.append(verRow);
            el.append(imgWrap);
        } else {
            el.append('<div class="nnb-empty" style="text-align:center; padding:12px; border:1px dashed var(--SmartThemeBorderColor); border-radius:10px; margin:6px 0;">Картинка комнаты ещё не создана. Можешь сразу отметить предметы ниже и нажать «Расставить и нарисовать комнату»!</div>');
        }

        const drawBtns = $('<div class="nnb-pop-row" style="gap:8px; flex-wrap:wrap; margin-bottom:10px;"></div>');
        const updatePicBtn = $(`<div class="menu_button nnb-btn-primary"><i class="fa-solid fa-wand-magic-sparkles"></i> ${home.image ? 'Обновить картинку комнаты (по референсам)' : 'Нарисовать комнату'}</div>`).on('click', async () => {
            if (batchChecked.size > 0) {
                flushCheckedIntoPlaced();
                await commit();
            }
            const toastWait = toastr.info('Рисую интерьер комнаты с твоими предметами (предыдущая картинка тоже сохранится)…', '🏠 Мой дом', { timeOut: 60000 });
            try {
                await withBusy('🎨 Рисую комнату с твоими предметами…', async s2 => {
                    const ok = await drawHomeRoom(s2, false);
                    if (ok) toastr.success('Интерьер комнаты обновлён!', '🏠 Мой дом');
                });
            } finally {
                try { toastr.clear(toastWait); } catch (e) { /* ignore */ }
            }
            renderRoomUI();
        });
        const redrawNewBaseBtn = $('<div class="menu_button" title="Перерисовать базовый вид комнаты с нуля (предыдущий вариант тоже сохранится!)"><i class="fa-solid fa-rotate"></i> Новый ракурс с нуля</div>').on('click', async () => {
            if (batchChecked.size > 0) {
                flushCheckedIntoPlaced();
                await commit();
            }
            await withBusy('🎨 Рисую новый вид комнаты…', async s2 => {
                const ok = await drawHomeRoom(s2, true);
                if (ok) toastr.success('Новый интерьер комнаты готов (оба варианта сохранены)!', '🏠 Мой дом');
            });
            renderRoomUI();
        });
        const editStyleBtn = $('<div class="menu_button" title="Описать стиль комнаты для художника"><i class="fa-solid fa-pen"></i> Стиль интерьера</div>').on('click', async () => {
            const val = await askText('Опиши стиль комнаты (например «уютная мансарда с тёплым светом гирлянд, деревянными полками и большим окном»)', home.baseEn || home.roomName || '');
            if (val === null) return;
            home.baseEn = val.trim();
            await commit();
            renderRoomUI();
        });
        drawBtns.append(updatePicBtn, editStyleBtn);
        if (home.image) drawBtns.append(redrawNewBaseBtn);
        el.append(drawBtns);

        // Уже расставленные в комнате предметы
        const placedSec = $('<div class="nnb-note" style="padding:10px 12px; margin-bottom:10px;"></div>');
        placedSec.append($('<div style="font-weight:700; margin-bottom:6px;"></div>').text(`Сейчас стоит в комнате (${home.placed.length})`));
        if (!home.placed.length) {
            placedSec.append('<div class="nnb-npc-status">Пока ничего не выставлено. Отметь галочками вещи из шкатулки ниже или нажми «➕ Поставить»!</div>');
        } else {
            const pGrid = $('<div style="display:grid; grid-template-columns:repeat(auto-fill, minmax(210px, 1fr)); gap:8px;"></div>');
            home.placed.forEach((p, idx) => {
                const it = (st.wardrobe?.box || []).find(x => x.id === p.itemId);
                if (!it) return;
                const card = $('<div class="nnb-note" style="display:flex; gap:8px; align-items:center; margin:0; border-color:var(--SmartThemeQuoteColor, #8b78c4);"></div>');
                if (it.image) card.append(findThumb(it, '50px').css('flex-shrink', '0'));
                const info = $('<div style="flex:1; min-width:0;"></div>');
                info.append($('<div style="font-weight:600; font-size:0.9em;"></div>').text(it.title));
                info.append($('<div class="nnb-npc-status" style="font-size:0.78em;"></div>').text(p.spot));
                const removeBtn = $('<i class="fa-solid fa-xmark" style="cursor:pointer; padding:4px; opacity:0.75;" title="Убрать обратно в шкатулку"></i>').on('click', async () => {
                    home.placed.splice(idx, 1);
                    await commit();
                    renderRoomUI();
                });
                card.append(info, removeBtn);
                pGrid.append(card);
            });
            placedSec.append(pGrid);
        }
        el.append(placedSec);

        // Мультивыбор предметов из шкатулки для пакетной расстановки
        const placedIds = new Set(home.placed.map(p => p.itemId));
        const available = personalBoxItems(st).filter(x => !placedIds.has(x.id));
        const availSec = $('<div class="nnb-note" style="padding:10px 12px;"></div>');
        availSec.append($('<div style="font-weight:700; margin-bottom:6px;"></div>').text(`Вещи в шкатулке, которые можно поставить в комнату (${available.length})`));

        if (!available.length) {
            availSec.append('<div class="nnb-npc-status">Все вещи из шкатулки уже расставлены или шкатулка пока пуста.</div>');
        } else {
            const batchBar = $('<div style="display:flex; gap:8px; flex-wrap:wrap; margin-bottom:10px; align-items:center;"></div>');
            const selectAllAvailBtn = $('<div class="menu_button" style="margin:0; padding:6px 10px;"><i class="fa-solid fa-check-double"></i> Выбрать все</div>');
            const placeOnlyBtn = $('<div class="menu_button" style="margin:0; padding:6px 12px;"></div>');
            const placeAndDrawBtn = $('<div class="menu_button nnb-btn-primary" style="margin:0; padding:6px 12px;"></div>');
            const updateBatchBtns = () => {
                const cnt = batchChecked.size;
                placeOnlyBtn.html(`<i class="fa-solid fa-couch"></i> Расставить выбранные (${cnt}) без перерисовки`);
                placeAndDrawBtn.html(`<i class="fa-solid fa-wand-magic-sparkles"></i> Расставить выбранные (${cnt}) и нарисовать комнату`);
                selectAllAvailBtn.html(cnt === available.length
                    ? '<i class="fa-solid fa-square-minus"></i> Снять отметки'
                    : `<i class="fa-solid fa-check-double"></i> Выбрать все (${available.length})`);
            };

            selectAllAvailBtn.on('click', () => {
                if (batchChecked.size === available.length) {
                    batchChecked.clear();
                } else {
                    available.forEach(it => batchChecked.add(it.id));
                }
                renderRoomUI();
            });

            const applyBatchToRoom = async (andDraw) => {
                if (!batchChecked.size) {
                    toastr.info('Сначала отметь галочками хотя бы один предмет ниже (или нажми «➕ Поставить» прямо на карточке предмета)!', '🏠 Мой дом');
                    return;
                }
                const addedCount = flushCheckedIntoPlaced();
                await commit();
                renderRoomUI();
                if (andDraw) {
                    await withBusy('🎨 Рисую комнату со всеми расставленными предметами…', async s2 => {
                        await drawHomeRoom(s2, false);
                    });
                    toastr.success(`Размещено предметов: ${addedCount}, картинка комнаты обновлена!`, '🏠 Мой дом');
                    renderRoomUI();
                } else {
                    toastr.success(`Размещено в комнате: ${addedCount} предм. (0 токенов)! Теперь они отображаются в блоке «Сейчас стоит в комнате» выше.`, '🏠 Мой дом');
                }
            };

            placeOnlyBtn.on('click', () => applyBatchToRoom(false));
            placeAndDrawBtn.on('click', () => applyBatchToRoom(true));
            batchBar.append(placeAndDrawBtn, placeOnlyBtn, selectAllAvailBtn);
            availSec.append(batchBar);

            const aGrid = $('<div style="display:grid; grid-template-columns:repeat(auto-fill, minmax(240px, 1fr)); gap:8px; max-height:340px; overflow-y:auto;"></div>');
            available.forEach((it, idx) => {
                if (!batchSpotMap.has(it.id)) batchSpotMap.set(it.id, HOME_SPOTS[idx % HOME_SPOTS.length]);
                const card = $('<div class="nnb-note" style="display:flex; flex-direction:column; gap:6px; margin:0; padding:8px; cursor:pointer;"></div>');
                const cb = $('<input type="checkbox" style="width:18px !important; height:18px !important; margin:0 !important; cursor:pointer; accent-color:var(--SmartThemeQuoteColor, #8b78c4); display:inline-block !important; opacity:1 !important; appearance:auto !important; -webkit-appearance:checkbox !important;">');

                const syncCardStyle = () => {
                    const checked = batchChecked.has(it.id);
                    card.css({
                        'border-color': checked ? 'var(--SmartThemeQuoteColor, #8b78c4)' : 'var(--SmartThemeBorderColor)',
                        'background': checked ? 'color-mix(in srgb, var(--SmartThemeQuoteColor, #8b78c4) 14%, transparent)' : '',
                    });
                    cb.prop('checked', checked);
                };

                const topRow = $('<div style="display:flex; gap:8px; align-items:center;"></div>');
                cb.on('click', e => e.stopPropagation());
                cb.on('change', function () {
                    if ($(this).prop('checked')) batchChecked.add(it.id);
                    else batchChecked.delete(it.id);
                    syncCardStyle();
                    updateBatchBtns();
                });
                topRow.append(cb);
                if (it.image) topRow.append(findThumb(it, '46px').css('flex-shrink', '0'));
                const info = $('<div style="flex:1; min-width:0;"></div>');
                info.append($('<div style="font-weight:600; font-size:0.9em;"></div>').text(it.title));
                if (it.desc) info.append($('<div class="nnb-npc-status" style="font-size:0.76em;"></div>').text(it.desc));
                topRow.append(info);

                const spotRow = $('<div style="display:flex; gap:6px; align-items:center;"></div>');
                const spotSel = $('<select class="text_pole" style="flex:1; margin:0; font-size:0.82em; padding:3px 6px;"></select>');
                HOME_SPOTS.forEach(sp => spotSel.append($('<option></option>').val(sp).text(`Куда: ${sp}`)));
                spotSel.val(batchSpotMap.get(it.id));
                spotSel.on('click', e => e.stopPropagation());
                spotSel.on('change', function () {
                    batchSpotMap.set(it.id, String($(this).val() || HOME_SPOTS[0]));
                    batchChecked.add(it.id);
                    syncCardStyle();
                    updateBatchBtns();
                });

                const placeSingleBtn = $('<div class="menu_button" style="margin:0; padding:3px 8px; font-size:0.8em; white-space:nowrap;" title="Сразу поставить этот предмет на выбранное место в комнате"><i class="fa-solid fa-plus"></i> Поставить</div>').on('click', async e => {
                    e.stopPropagation();
                    const spot = batchSpotMap.get(it.id) || HOME_SPOTS[0];
                    if (!home.placed.some(p => p.itemId === it.id)) {
                        home.placed.push({ itemId: it.id, spot });
                    }
                    batchChecked.delete(it.id);
                    await commit();
                    toastr.success(`«${escapeHtml(it.title)}» поставлено ${escapeHtml(spot)}!`, '🏠 Мой дом', { escapeHtml: false });
                    renderRoomUI();
                });

                spotRow.append(spotSel, placeSingleBtn);

                card.on('click', () => {
                    if (batchChecked.has(it.id)) batchChecked.delete(it.id);
                    else batchChecked.add(it.id);
                    syncCardStyle();
                    updateBatchBtns();
                });

                card.append(topRow, spotRow);
                syncCardStyle();
                aGrid.append(card);
            });
            updateBatchBtns();
            availSec.append(aGrid);
        }
        el.append(availSec);
    };

    renderRoomUI();
    await openPopup(el, true);
}

// ===================== 💬 Заготовленные темы для разговора =====================
async function generateTopicsNow() {
    const st = store();
    if (!st) return;
    const names = storyNames();
    const ok = await withBusy('💬 Модель придумывает 5 новых тем для разговора…', async s2 => {
        if (!Array.isArray(s2.pastTopics)) s2.pastTopics = [];
        (s2.topics || []).forEach(t => {
            const label = `«${t.title}» (${t.prompt.slice(0, 60)})`;
            if (!s2.pastTopics.includes(label)) s2.pastTopics.push(label);
        });
        if (s2.pastTopics.length > 20) s2.pastTopics = s2.pastTopics.slice(-20);

        const chat = ctx().chat || [];
        const lastMsgs = chat.filter(m => m && !m.is_system && m.mes).slice(-3).map(m => {
            const who = m.is_user ? names.user : (m.name || names.char);
            return `${who}: ${stripTags(stripActionTags(String(m.mes || ''))).replace(/<[^>]+>/g, '').slice(-1600)}`;
        }).join('\n');

        const mc = ensureMainCharCard(s2);
        const allKnownChars = [
            mc ? `— ${mc.name} (основной персонаж): ${mc.card || ''}${mc.status ? ` | Сейчас: ${mc.status}` : ''}${mc.petPeeves ? ` | Бытовая заноза: ${mc.petPeeves}` : ''}${mc.jealousyTriggers ? ` | Триггеры ревности: ${mc.jealousyTriggers}` : ''}${mc.fear ? ` | Скрытый страх: ${mc.fear}` : ''}${mc.dream ? ` | Мечта: ${mc.dream}` : ''}` : '',
            ...(s2.npcs || []).slice(0, 12).map(n => `— ${n.name}: ${n.card || ''}${n.status ? ` | Сейчас: ${n.status}` : ''}${n.fear ? ` | Страх: ${n.fear}` : ''}${n.dream ? ` | Мечта: ${n.dream}` : ''}`),
        ].filter(Boolean).join('\n');
        const companionHint = (s2.map?.currentCompanion && s2.map.currentCompanion !== 'solo')
            ? `Сейчас ${names.user} отправилась по карте вместе с: ${s2.map.currentCompanion}.`
            : '';
        const intContext = (s2.intrigues || []).length ? `Активные тайны и слухи в сюжете: ${s2.intrigues.map(i => i.text).join('; ')}.` : '';
        const notesContext = (s2.notes || []).length ? `Задумки автора на ближайшее будущее: ${s2.notes.slice(-4).map(n => n.text).join('; ')}.` : '';
        const avoidContext = s2.pastTopics.length ? `СТРОГО ЗАПРЕЩЕНО повторять или перефразировать эти старые темы: ${s2.pastTopics.join('; ')}.` : '';

        const prompt = `${SELF_CONTAINED_PROMPT_MARKER}
[OOC: Пауза в ролевой игре. Ты — автор истории.
СНАЧАЛА определи по последним сообщениям чата ниже, КТО ИМЕННО находится рядом с ${names.user} в текущей сцене прямо сейчас (это может быть ${names.char}, конкретный NPC — например, подруга, коллега или случайный собеседник, — либо несколько персонажей сразу).
Придумай РОВНО 5 СОВЕРШЕННО НОВЫХ, цепляющих, живых и небанальных тем для разговора, адресованных ИМЕННО тем персонажам, которые реально присутствуют в текущей сцене с ${names.user}! (Если в сцене сейчас подруга или другой NPC, а не ${names.char} — генерируй темы для разговора именно с этим NPC и укажи его имя в начале названия темы!)

Последние сообщения текущей сцены:
${lastMsgs || '(начало истории)'}
${companionHint}

Карточки известных персонажей (используй тех, кто сейчас в сцене):
${allKnownChars}
${intContext}
${notesContext}
${avoidContext}

ВАЖНЫЕ ПРАВИЛА (АНТИ-СКУКА):
— СТРОГО ЗАПРЕЩЕНО предлагать пресную бытовую болтовню про погоду, сквозняки, ремонт, уборку, расписание или случайные хобби из анкеты!
— Все 5 тем должны быть эмоционально заряженными, интригующими и бить прямо в нерв отношений и сюжета. Сделай 5 РАЗНЫХ по настроению крючков:
  1) 🔥 [Момент между нами] — живая, чувственная или очень личная реплика/действие прямо по следам того, что только что произошло между ${names.user} и ${names.char} в последнем посте.
  2) 🗝 [Больная точка / Тайна прошлого] — проницательный вопрос или наблюдение, задевающее скрытый страх, уязвимость, тайну прошлого или странную деталь в поведении ${names.char}.
  3) 🌶 [Бытовая заноза / Ревность / Недопонимание] — живая перепалка из-за упрямой бытовой привычки, острый повод для ревности/собственничества или выяснение двусмысленного недопонимания (без скучного соглашательства!).
  4) 🕵️‍♀️ [Интрига / Слух] — вывести разговор на одну из тайн сюжета, подозрительного человека, странную находку или недосказанность.
  5) ✨ [Неожиданная выходка / Поворот] — внезапное смелое предложение от лица ${names.user}, которое собьёт ${names.char} с привычного ритма или развернёт сцену в новое русло.

Ответь строго 5 строками без пояснений:
TOPIC: короткое название темы (2–4 слова) | живая реплика (и при желании короткое действие) от лица ${names.user}, без внешних кавычек]`;

        const raw = await quietGenerate(prompt);
        const newTopics = [];
        if (!s2.nextTopicId) s2.nextTopicId = 1;
        for (const line of answerLines(raw)) {
            const m = line.match(/^TOPIC\s*[:：—–-]\s*(.+)$/i);
            if (m) {
                const parts = m[1].split('|').map(x => x.trim());
                const title = (parts[0] || '').replace(/^[«"']|[»"']$/g, '').trim();
                const promptText = (parts.slice(1).join(' | ') || title).replace(/\]$/, '').replace(/^[«"']|[»"']$/g, '').trim();
                if (title && promptText) {
                    newTopics.push({ id: s2.nextTopicId++, title, prompt: promptText, at: ctx().chat?.length ?? 0 });
                }
            }
        }
        if (newTopics.length) {
            s2.topics = newTopics;
            await commit();
            return true;
        }
        return false;
    });
    if (ok) toastr.success('Сгенерированы 5 свежих тем для разговора!', '💬 Темы');
}

async function openTopicsPopup() {
    const st = store();
    if (!st) return toastr.warning('Сначала открой чат', '💬 Темы');
    const el = $('<div class="nnb-pop"><h3>💬 Темы для разговора</h3></div>');
    el.append('<div class="nnb-pop-sub">Острые вопросы, личные крючки, интриги и поводы сблизиться прямо по текущей сцене. Нажми на любую тему, чтобы подставить её в поле ввода:</div>');

    const listBox = $('<div style="display:flex; flex-direction:column; gap:8px; margin:8px 0;"></div>');
    const renderTopics = () => {
        listBox.empty();
        const topics = st.topics || [];
        if (!topics.length) {
            listBox.append('<div class="nnb-empty">Пока нет заготовленных тем. Нажми «Сгенерировать 5 новых тем» ниже!</div>');
            return;
        }
        topics.forEach(t => {
            const row = $('<div class="nnb-look" style="display:flex; justify-content:space-between; align-items:flex-start; gap:10px; cursor:pointer;"></div>');
            const main = $('<div style="flex:1;"></div>');
            main.append($('<div class="nnb-look-title"></div>').text(`💬 ${t.title}`));
            main.append($('<div class="nnb-look-desc"></div>').text(t.prompt));
            main.on('click', async () => {
                closePopupOf(el);
                chooseActionPrompt(t.prompt, false);
                if (!Array.isArray(st.pastTopics)) st.pastTopics = [];
                st.pastTopics.push(`«${t.title}» (${t.prompt.slice(0, 60)})`);
                st.topics = (st.topics || []).filter(x => x.id !== t.id);
                await commit();
                toastr.info(`Тема «${escapeHtml(t.title)}» подставлена в поле ввода!`, '💬 Разговор', { escapeHtml: false });
            });
            const delBtn = $('<i class="fa-solid fa-xmark" title="Убрать эту тему" style="cursor:pointer; opacity:0.65; padding:4px;"></i>').on('click', async e => {
                e.stopPropagation();
                if (!Array.isArray(st.pastTopics)) st.pastTopics = [];
                st.pastTopics.push(`«${t.title}» (${t.prompt.slice(0, 60)})`);
                st.topics = (st.topics || []).filter(x => x.id !== t.id);
                await commit();
                renderTopics();
            });
            row.append(main, delBtn);
            listBox.append(row);
        });
    };
    renderTopics();
    el.append(listBox);

    const botRow = $('<div style="display:flex; flex-direction:column; gap:8px; margin-top:10px;"></div>');
    const genBtn = $('<div class="menu_button nnb-btn-primary" style="width:100%; justify-content:center; padding:8px 12px;"><i class="fa-solid fa-arrows-rotate"></i> Сгенерировать 5 новых тем (полная замена)</div>').on('click', async () => {
        closePopupOf(el);
        await generateTopicsNow();
        openTopicsPopup();
    });
    const addCustomBtn = $('<div class="menu_button" style="width:100%; justify-content:center; padding:7px 12px;"><i class="fa-solid fa-plus"></i> Добавить свою тему на заметку</div>').on('click', async () => {
        const title = await askText('Короткое название темы (например «Спросить про прошлое»)');
        if (!title || !title.trim()) return;
        const pr = await askText('С какой фразы или действия начать?', title.trim());
        if (pr === null) return;
        if (!Array.isArray(st.topics)) st.topics = [];
        if (!st.nextTopicId) st.nextTopicId = 1;
        st.topics.push({ id: st.nextTopicId++, title: title.trim(), prompt: pr.trim() || title.trim(), at: ctx().chat?.length ?? 0 });
        await commit();
        renderTopics();
    });
    botRow.append(genBtn, addCustomBtn);
    el.append(botRow);
    await openPopup(el);
}

// ===================== 🔥 Система Моды и Трендов сезона (с иллюстрациями) =====================
async function drawTrendsSheetBatch(st, items = null) {
    const list = (items || st.trends || []).slice(0, 4);
    if (!list.length || !canDrawScene()) return false;
    const n = list.length;
    if (settings().imageSource === 'novelai') {
        let drawnAny = false;
        for (let i = 0; i < n; i++) {
            const tr = list[i];
            setStatus(`🎨 NovelAI рисует тренд ${i + 1} из ${n} («${tr.title}»)…`);
            const singlePrompt = cleanForCommand(`1item, solo, ${ITEM_STYLE}, solid plain light cream background, centered trendy item: ${tr.en || tr.desc || tr.title}, no people, no hands, no text, no captions`);
            const singleUrl = await drawViaNovelAi(singlePrompt, 'square', null);
            if (!singleUrl) continue;
            drawnAny = true;
            tr.image = singleUrl;
            tr.imageLayout = { rows: 1, cols: 1 };
            tr.crop = { x: 0, y: 0, w: 1, h: 1 };
            tr.isSingleImage = true;
        }
        if (drawnAny) await ctx().saveMetadata();
        return drawnAny;
    }
    const layout = { rows: 1, cols: n };
    const pos = ['first', 'second', 'third', 'fourth'];
    const prompt = n === 1
        ? cleanForCommand(`${ITEM_STYLE}, a single centered trendy item on a solid plain light cream background: ${list[0].en || list[0].desc || list[0].title}, no people, no hands, no text, no captions`)
        : cleanForCommand(`${ITEM_STYLE}, ${n} separate seasonal trend items in a single horizontal row, evenly spaced, each item centered in its own equal column of the image with wide empty space between items, nothing overlapping, solid plain light cream background, ` +
            list.map((x, i) => `${pos[i]} from the left: ${x.en || x.desc || x.title}`).join('; ') + ', no people, no hands, no text, no captions');
    const url = await drawPicture(prompt, null, n === 1 ? 'square' : 'landscape');
    if (!url) return false;
    if (!Array.isArray(st.trendsImageHistory)) st.trendsImageHistory = [];
    const prevUrl = list[0]?.image;
    if (prevUrl && !st.trendsImageHistory.includes(prevUrl)) st.trendsImageHistory.push(prevUrl);
    if (!st.trendsImageHistory.includes(url)) st.trendsImageHistory.push(url);
    let crops = [];
    if (n > 1) {
        try { crops = await smartCrops(url, n, 'gacha', layout); } catch (e) { crops = []; }
    }
    list.forEach((tr, i) => {
        const fallback = n === 1
            ? { x: 0.04, y: 0.04, w: 0.92, h: 0.92 }
            : { x: i / n + 0.02, y: 0.08, w: 1 / n - 0.04, h: 0.84 };
        tr.image = url;
        tr.imageLayout = layout;
        tr.crop = crops[i] || fallback;
    });
    await ctx().saveMetadata();
    return true;
}

async function generateTrendsNow() {
    const st = store();
    if (!st) return;
    const sName = st.time?.date ? season(st.time.date).name : 'осень';
    const ok = await withBusy('🔥 Модель придумывает тренды сезона…', async s2 => {
        const prompt = `[OOC: Пауза в ролевой игре. Ты — автор истории. Придумай 4 оригинальных, самобытных тренда сезона («${sName}», ${placeLine(s2) || 'город истории'}), которые органично подходят именно к этому миру, городу и атмосфере ролевой:
1) модная вещь гардероба или заметный аксессуар;
2) гастрономический хит сезона (необычный десерт, выпечка, уличная еда или сезонный напиток из местного заведения со своим названием);
3) коллекционная вещица, лимитированный сувенир или предмет декора;
4) популярное городское увлечение или желанная новинка сезона.
ВАЖНО: придумай СВОИ свежие, правдоподобные названия и бренды внутри мира игры — НЕ копируй буквальные примеры из реальных соцсетей! Не расписывай заранее отношение конкретных героев — как кто отреагирует, выяснится только в самой сцене.
Ответь строго 4 строками без пояснений:
TREND: категория (Одежда|Еда|Коллекция|Увлечение) | название тренда | что это такое и почему вокруг него сейчас ажиотаж в городе (1–2 предложения) | коротко по-английски как выглядит этот предмет, одежда, десерт или атрибут для художника (без людей и рук)]`;
        const raw = await quietGenerate(prompt);
        const newTrends = [];
        for (const line of answerLines(raw)) {
            const m = line.match(/^TREND\s*[:：—–-]\s*(.+)$/i);
            if (m) {
                const parts = m[1].split('|').map(x => x.trim());
                if (parts.length >= 2) {
                    const cat = parts[0] || 'Тренд';
                    const title = (parts[1] || '').replace(/^[«"]|[»"]$/g, '');
                    const desc = (parts[2] || '').replace(/\]$/, '');
                    const en = (parts[3] || `${title}, ${cat}`).replace(/\]$/, '');
                    newTrends.push({
                        id: (s2.nextTrendId = (s2.nextTrendId || 1) + 1),
                        category: cat,
                        title,
                        desc,
                        en,
                        at: ctx().chat?.length ?? 0,
                    });
                }
            }
        }
        if (newTrends.length) {
            s2.trends = newTrends;
            s2.trendsImageHistory = [];
            await commit();
            if (wantImages() && canDrawScene()) {
                setStatus('🎨 Рисуем иллюстрации трендов сезона…');
                try { await drawTrendsSheetBatch(s2, newTrends); } catch (e) { console.warn('[npc_notebook] drawTrends error:', e); }
            }
            return true;
        }
        return false;
    });
    if (ok) toastr.success('Тренды сезона обновлены (они также теперь влияют на гардероб)!', '🔥 Мода и тренды');
}

async function openTrendsModal() {
    const st = store();
    if (!st) return toastr.warning('Сначала открой чат', '🔥 Тренды');
    const el = $('<div class="nnb-pop nnb-pop-visual"><h3>🔥 Мода и тренды сезона</h3></div>');
    el.append('<div class="nnb-pop-sub">Модные новинки, гастрономические хиты и увлечения города (также попадают в подборки гардероба!). Отношение героев заранее не раскрывается и выясняется в самой сцене по их личному характеру.</div>');

    const topTools = $('<div style="display:flex; gap:8px; flex-wrap:wrap; align-items:center; margin:6px 0;"></div>');
    const listBox = $('<div style="display:flex; flex-direction:column; gap:8px; margin:8px 0;"></div>');

    const renderTrends = () => {
        topTools.empty();
        listBox.empty();
        const trends = st.trends || [];
        if (!trends.length) {
            listBox.append('<div class="nnb-empty">Тренды сезона ещё не сгенерированы. Нажми «Сгенерировать новые тренды сезона» ниже!</div>');
            return;
        }

        if (canDrawScene()) {
            const hasPics = trends.some(t => t.image);
            const drawBtn = $(`<div class="menu_button" style="padding:4px 10px; font-size:0.84em;"><i class="fa-solid fa-palette"></i> ${hasPics ? 'Перерисовать картинки трендов (предыдущие сохранятся)' : 'Нарисовать картинки трендов'}</div>`).on('click', async () => {
                await withBusy('🎨 Рисуем иллюстрации для трендов сезона…', async s2 => {
                    const ok = await drawTrendsSheetBatch(s2, s2.trends);
                    if (ok) toastr.success('Картинки трендов готовы!', '🔥 Тренды');
                });
                renderTrends();
            });
            topTools.append(drawBtn);
        }

        if (Array.isArray(st.trendsImageHistory) && st.trendsImageHistory.length > 1) {
            const curUrl = trends[0]?.image || '';
            st.trendsImageHistory.forEach((hUrl, idx) => {
                const vBtn = $(`<div class="menu_button ${hUrl === curUrl ? 'nnb-btn-primary' : ''}" style="padding:3px 9px; font-size:0.8em; margin:0;">Вариант ${idx + 1}</div>`).on('click', async () => {
                    const n = Math.min(trends.length, 4);
                    const layout = { rows: 1, cols: n };
                    let crops = [];
                    if (n > 1) {
                        try { crops = await smartCrops(hUrl, n, 'gacha', layout); } catch (e) { crops = []; }
                    }
                    trends.forEach((tr, i) => {
                        tr.image = hUrl;
                        tr.imageLayout = layout;
                        tr.crop = crops[i] || { x: i / n + 0.02, y: 0.08, w: 1 / n - 0.04, h: 0.84 };
                    });
                    await commit();
                    renderTrends();
                });
                topTools.append(vBtn);
            });
        }

        trends.forEach(tr => {
            const card = $('<div class="nnb-note" style="padding:10px 12px; display:flex; gap:12px; align-items:flex-start;"></div>');
            if (tr.image) {
                const th = findThumb(tr, '78px').css({ 'flex-shrink': '0', 'border-radius': '10px', cursor: 'pointer' })
                    .attr('title', 'Нажми, чтобы открыть общий лист во весь экран')
                    .on('click', () => window.open(tr.image, '_blank'));
                card.append(th);
            }
            const rightCol = $('<div style="flex:1; min-width:0;"></div>');
            rightCol.append($('<div style="font-weight:700; font-size:1em;"></div>').text(`🔥 [${tr.category}] «${tr.title}»`));
            if (tr.desc) rightCol.append($('<div class="nnb-npc-text" style="margin-top:4px;"></div>').text(tr.desc));

            const btnRow = $('<div class="nnb-buttons" style="margin-top:8px;"></div>');
            const getBtn = $('<div class="menu_button" style="padding:4px 10px; font-size:0.84em;"><i class="fa-solid fa-bag-shopping"></i> Заполучить себе (в шкаф / шкатулку)</div>').on('click', async () => {
                const isClothes = /одежд|плать|куртк|костюм|пальто|юбк|свитер|блуз|образ/i.test(tr.category + ' ' + tr.title);
                const effectsText = `Это громкий тренд сезона («${tr.title}»)! Окружающие реагируют на него по своему личному характеру и вкусу (без шаблонного позитивного биаса: даже друзья могут подшутить над хайпом или счесть пустой тратой денег, а неожиданные персонажи — заинтересоваться или оценить).`;
                if (isClothes) {
                    addLookToCloset(st, {
                        category: 'На выход',
                        title: tr.title,
                        desc: `${tr.desc} (Тренд сезона)`,
                        en: tr.en || tr.title,
                        effects: effectsText,
                        image: tr.image || '',
                        crop: tr.crop || null,
                        imageLayout: tr.imageLayout || null,
                    });
                    toastr.success(`Трендовый образ «${escapeHtml(tr.title)}» добавлен в твой 👗 Шкаф!`, '🔥 Тренд', { escapeHtml: false });
                } else {
                    st.wardrobe.box.push({
                        id: st.wardrobe.nextItemId++,
                        kind: 'accessory',
                        title: tr.title,
                        desc: tr.desc,
                        en: tr.en || tr.title,
                        effects: effectsText,
                        origin: `тренд сезона (${tr.category})`,
                        image: tr.image || '',
                        crop: tr.crop || null,
                        imageLayout: tr.imageLayout || null,
                        onCounter: false,
                        at: ctx().chat?.length ?? 0,
                    });
                    toastr.success(`Трендовая вещь «${escapeHtml(tr.title)}» добавлена в твою 🎁 Шкатулку и готовые штрихи!`, '🔥 Тренд', { escapeHtml: false });
                }
                await commit();
            });
            const playSceneBtn = $('<div class="menu_button" style="padding:4px 10px; font-size:0.84em;"><i class="fa-solid fa-wand-magic-sparkles"></i> Отыграть в сцене</div>').on('click', async () => {
                closePopupOf(el);
                const names = storyNames();
                const text = `${FF_MARKER} В сцене всплывает заметный тренд сезона — «${tr.title}» (${tr.desc}). Обыграй это живо и органично для текущего момента. ВАЖНО — избегай позитивного биаса по отношениям: реакция каждого персонажа на этот тренд должна зависеть ТОЛЬКО от его личного характера, вкусов, прагматичности или скрытых слабостей, а НЕ от того, друг он или недруг для ${names.user} (близкая подруга или фаворит вполне могут отнестись к модному хайпу скептически или с иронией, а хмурый скептик или соперник — неожиданно заинтересоваться или тайно любить эту вещь). Пиши как обычный ответ.]`;
                setSceneAdvancePrompt(text);
                const send = $('#send_but');
                if (send.length) send.trigger('click');
                else if (typeof ctx().generate === 'function') ctx().generate('normal');
            });
            btnRow.append(getBtn, playSceneBtn);
            rightCol.append(btnRow);
            card.append(rightCol);
            listBox.append(card);
        });
    };
    renderTrends();
    el.append(topTools, listBox);

    const botRow = $('<div class="nnb-pop-row" style="gap:8px; flex-wrap:wrap;"></div>');
    botRow.append($('<div class="menu_button nnb-btn-primary"><i class="fa-solid fa-fire"></i> Сгенерировать новые тренды сезона</div>').on('click', async () => {
        closePopupOf(el);
        await generateTrendsNow();
        openTrendsModal();
    }));
    el.append(botRow);
    await openPopup(el, true);
}

// ===================== 📓 Личный дневник НПС (с защитой от ясновидения и пакетной записью всех дневников за день) =====================
function isHeroPhysicallyPresentInMessage(n, msgObj) {
    if (!n || !msgObj || !msgObj.mes) return false;
    const rawWithLines = stripTags(stripActionTags(String(msgObj.mes || ''))).replace(/<[^>]+>/g, '').trim();
    if (!rawWithLines) return false;
    // Если имя персонажа вообще не встречается в посте — его в этой сцене ТОЧНО нет! (Даже если это главный {{char}}, когда героиня общается наедине с другим НПС!)
    if (!isNameMentionedInText(n.name, rawWithLines)) return false;
    // Вырезаем прямую речь в кавычках («...», "...") И русскую прямую речь через тире (— Реплика, — сказал Х / — Реплика.),
    // чтобы персонаж, о котором просто сплетничают за его спиной, не считался физически присутствующим в комнате!
    const narrationOutsideQuotes = rawWithLines
        .replace(/«[^»]*»/g, ' ')
        .replace(/"[^"]*"/g, ' ')
        .replace(/„[^“”]*[“”]/g, ' ')
        .replace(/(?:^|\n|(?<=[.!?])\s+)[—–-]\s*[^—–\n]+?(?=\s*[—–-]\s*[а-яёa-z]|\r?\n|$)/gi, ' ');
    if (isNameMentionedInText(n.name, narrationOutsideQuotes)) return true;
    // Если в авторском повествовании вне прямой речи его имени нет, значит о нём просто говорили за его спиной!
    return false;
}

function buildStrictPersonalContextForDiary(n, st, useDate = '') {
    const c = ctx();
    const names = storyNames();
    const allChat = (c.chat || []).filter(m => m && !m.is_system && m.mes);
    const personalPosts = [];
    for (let i = 0; i < allChat.length; i++) {
        const m = allChat[i];
        if (isHeroPhysicallyPresentInMessage(n, m)) {
            const who = m.is_user ? names.user : (m.name || names.char);
            const clean = stripTags(stripActionTags(String(m.mes || ''))).replace(/<[^>]+>/g, '').replace(/\s+/g, ' ').trim();
            personalPosts.push(`[Пост #${i + 1}, где ${n.name} присутствовал(а) лично] ${who}: ${clean.slice(0, 1600)}`);
        }
    }
    const recent8 = allChat.slice(-8);
    const wasInRecentScene = recent8.some(m => isHeroPhysicallyPresentInMessage(n, m));

    // Из хроники и саммари берём ТОЛЬКО те строки, где прямо участвовал сам этот персонаж (чтобы он не знал чужих тайн и закрытых сцен!)
    const personalEvents = (st?.time?.timeline || [])
        .filter(e => (!useDate || e.date === useDate) && isNameMentionedInText(n.name, e.text || ''))
        .map(e => e.text)
        .filter(Boolean);

    const personalSummaryLines = String(st?.storySummary || '')
        .split(/(?<=[.!?\n])\s+/)
        .filter(sent => isNameMentionedInText(n.name, sent))
        .slice(-8)
        .join(' ');

    const relHits = (st?.relationships || [])
        .filter(r => matchesCharacterName(r.a, n.name) || matchesCharacterName(r.b, n.name))
        .map(r => `${r.a} ${r.arrow || '↔'} ${r.b}${r.type ? ` [${r.type}]` : ''}: ${r.desc}`)
        .join('; ');

    const presenceNote = wasInRecentScene
        ? `В последних сценах ${n.name} лично присутствовал(а) в кадре.`
        : `⚠️ ВАЖНО: в последних постах чата персонажа «${n.name}» В СЦЕНЕ НЕ БЫЛО (другие герои общались без него/неё, а ${n.name} в это время занимался(ась) своими собственными делами за кадром: ${n.status || 'работа и личные дела'})! Поэтому ${n.name} ПОНЯТИЯ НЕ ИМЕЕТ, что происходило у других героев без него, и пишет в дневнике о своём собственном дне за кадром и только о тех прошлых встречах, где присутствовал(а) лично!`;

    const scenesBlock = personalPosts.length
        ? personalPosts.slice(-8).join('\n\n')
        : `(В текущем чате ещё не было прямых сцен с личным присутствием ${n.name} в комнате — персонаж весь день занимался своими делами за кадром: ${n.status || 'своя работа и быт'}).`;

    return {
        wasInRecentScene,
        presenceNote,
        personalEventsLine: personalEvents.length ? `События с личным участием ${n.name}: ${personalEvents.join('; ')}.` : '',
        personalSummaryLines: personalSummaryLines ? `Из прошлых глав с участием ${n.name}: ${personalSummaryLines}` : '',
        relHits: relHits ? `Связи ${n.name}: ${relHits}` : '',
        scenesBlock,
    };
}

async function generateNpcDiaryForDate(n, targetDate = '') {
    const st = store();
    if (!st || !n) return false;
    const names = storyNames();
    const useDate = targetDate || st.time?.date || '';
    const dateLabel = useDate && /^\d{4}-\d{2}-\d{2}$/.test(useDate) ? formatDate(useDate) : (useDate || 'сегодня');

    const toastNote = toastr.info(
        `Окно свернулось, пока ${escapeHtml(n.name)} делает запись за ${escapeHtml(dateLabel)}… Дневник откроется сам, когда будет готово!`,
        '📓 Личный дневник',
        { timeOut: 60000, extendedTimeOut: 15000, tapToDismiss: true, escapeHtml: false }
    );

    let ok = false;
    try {
        await withBusy(`📓 ${n.name} пишет в дневнике (${dateLabel})…`, async s2 => {
            const pCtx = buildStrictPersonalContextForDiary(n, s2, useDate);
            const prevDiaryTexts = (n.diary || []).slice(-3).map(d => d.text.slice(0, 180)).join(' | ');
            const antiRepeatLine = prevDiaryTexts
                ? `Предыдущие записи дневника (СТРОГО ЗАПРЕЩЕНО повторять их темы, метафоры и старые фразы!): ${prevDiaryTexts}`
                : '';

            const prompt = `${SELF_CONTAINED_PROMPT_MARKER}
[OOC: Пауза в ролевой игре. Напиши страницу из личного дневника персонажа «${n.name}» от ПЕРВОГО ЛИЦА («Я...») за дату: ${dateLabel}.
Кто ведёт дневник: ${n.name} (${n.card || 'персонаж истории'}). Чем занят сейчас: ${n.status || 'свои дела'}. Отношение к ${names.user}: дружба ${n.friendship}/100${isRomanticTarget(n) ? `, романтика ${n.romance}/100` : ''}.
${pCtx.relHits}
${pCtx.personalEventsLine}
${pCtx.personalSummaryLines}
${pCtx.presenceNote}

Сцены, которые ${n.name} видел(а) СВОИМИ ГЛАЗАМИ (в чужих закрытых сценах этот персонаж свечку НЕ держал и о них ничего не знает!):
${pCtx.scenesBlock}
${antiRepeatLine}

СТРОГИЕ ПРАВИЛА ДЛЯ ЖИВОГО ДНЕВНИКА (ЗАЩИТА ОТ ЯСНОВИДЕНИЯ):
1) НИКАКОГО ЯСНОВИДЕНИЯ («НЕ ДЕРЖАЛ СВЕЧКУ»): ${n.name} может писать ТОЛЬКО о том, что видел(а) своими глазами и слышал(а) лично, находясь в одной комнате! КАТЕГОРИЧЕСКИ ЗАПРЕЩЕНО упоминать разговоры, чаепития, встречи или действия, которые происходили между ${names.user} и другими персонажами без личного присутствия ${n.name}! Если ${n.name} не было в последних сценах — пиши о том, как прошёл его/её собственный день за кадром (работа, дела, личные мысли).
2) ОБЪЁМ И ФОРМАТ: напиши 1–2 абзаца (в сумме около 6–8 предложений — не раздувай в длинную поэму, но и не пиши совсем сухой телеграф).
3) СВОЯ ГОЛОВА НА ПЛЕЧАХ (БЕЗ СЛЕПОГО ОПРАВДАНИЯ ${names.user}):
   — Мир ${n.name} не крутится вокруг ${names.user} 24/7: основная часть записи — это его собственные дела, работа, мотивы, выгода/принципы и взгляд на ситуацию.
   — Даже если ${n.name} хорошо относится к ${names.user}, у него есть собственное критическое мышление и свой характер.
4) Пиши живо, в характерной манере речи ${n.name}, без кавычек и без служебных меток.]`;
            const raw = await quietGenerate(prompt);
            const text = stripActionTags(raw);
            if (text) {
                if (!Array.isArray(n.diary)) n.diary = [];
                n.diary.push({ date: useDate || s2.time?.date || '', text });
                if (n.diary.length > 30) n.diary.shift();
                await commit();
                ok = true;
            }
        });
    } finally {
        try { toastr.clear(toastNote); } catch (e) { /* ignore */ }
    }
    return ok;
}

// Пакетная генерация дневников СРАЗУ ДЛЯ ВСЕХ ГЕРОЕВ за выбранный день (1 запросом, со строгой информационной изоляцией каждого героя!)
async function generateAllNpcDiariesForDay(targetDate = '') {
    const st = store();
    if (!st) return 0;
    const names = storyNames();
    const mc = ensureMainCharCard(st);
    const sortedNpcs = [...(st.npcs || [])].sort((a, b) => (!!b.favorite - !!a.favorite) || a.id - b.id);
    const allHeroes = mc ? [mc, ...sortedNpcs] : sortedNpcs;
    if (!allHeroes.length) {
        toastr.warning('В блокноте пока нет персонажей для записи дневников', '📓 Дневники за день');
        return 0;
    }

    const useDate = targetDate || st.time?.date || '';
    const dateLabel = useDate && /^\d{4}-\d{2}-\d{2}$/.test(useDate) ? formatDate(useDate) : (useDate || 'сегодня');
    const toastNote = toastr.info(
        `Герои (${allHeroes.length} чел.) пишут свои дневники за ${escapeHtml(dateLabel)} одним общим запросом… Окно откроется само по готовности!`,
        '📓 Дневники всех героев',
        { timeOut: 75000, extendedTimeOut: 20000, tapToDismiss: true, escapeHtml: false }
    );

    let addedCount = 0;
    try {
        await withBusy(`📓 Заполняем дневники всех героев (${allHeroes.length} чел.) за ${dateLabel}…`, async s2 => {
            const heroBlocks = allHeroes.map((h, idx) => {
                ensureNpcScales(h, s2);
                const pCtx = buildStrictPersonalContextForDiary(h, s2, useDate);
                const prevLast = (h.diary || []).slice(-1)[0]?.text?.slice(0, 140) || '';
                return `=== ГЕРОЙ #${idx + 1}: [${h.name}] ===
Кто это: ${h.card || 'персонаж истории'}. Чем занят: ${h.status || 'свои дела'}. Отношение к ${names.user}: дружба ${h.friendship}/100${isRomanticTarget(h) ? `, романтика ${h.romance}/100` : ''}.
${pCtx.presenceNote}
Что видел(а) ТОЛЬКО ЛИЧНО [${h.name}] (СВОИМИ ГЛАЗАМИ):
${pCtx.scenesBlock}
${prevLast ? `Прошлая запись (не повторяй её): ${prevLast}` : ''}`;
            }).join('\n\n');

            const prompt = `${SELF_CONTAINED_PROMPT_MARKER}
[OOC: Пауза в ролевой игре. Напиши личные записи в дневниках за дату «${dateLabel}» сразу для каждого из перечисленных ниже персонажей (${allHeroes.map(h => h.name).join(', ')}) от ПЕРВОГО ЛИЦА («Я...»).

${heroBlocks}

СТРОЖАЙШИЕ ПРАВИЛА ПРОТИВ ЯСНОВИДЕНИЯ («НИКТО НЕ ДЕРЖАЛ СВЕЧКУ»):
1) СТРОГАЯ ИНФОРМАЦИОННАЯ ИЗОЛЯЦИЯ КАЖДОГО ГЕРОЯ: каждый персонаж знает ТОЛЬКО то, что указано в ЕГО собственном блоке «Что видел(а) ТОЛЬКО ЛИЧНО [Имя]»!
2) КАТЕГОРИЧЕСКИ ЗАПРЕЩЕНО приписывать одному персонажу знание о том, что происходило в закрытых сценах у других героев (например, если ${names.user} пила чай, разговаривала или была дома наедине с Персонажем А, то Персонаж Б / коллега / знакомый об этом НЕ ЗНАЕТ, свечку не держал и ни слова об этом писать не может!).
3) Если героя сегодня не было в сценах чата — он пишет о своём собственном дне за кадром (о своей работе, заботах, планах или мыслях), не выдумывая несуществующих встреч с ${names.user}.
4) Для КАЖДОГО героя напиши живую запись от первого лица в его собственном характере и манере речи (5–7 предложений в одну строку без переносов внутри записи).

Ответь СТРОГО списком строк в следующем формате (по одной строке на каждого героя, без лишних вступлений):
${allHeroes.map(h => `DIARY [${h.name}]: текст дневниковой записи от первого лица`).join('\n')}]`;

            const raw = await quietGenerate(prompt);
            const cleaned = stripActionTags(raw || '');
            const parsedMap = new Map();
            let currentHero = null;

            for (const rawLine of cleaned.split(/\r?\n/)) {
                const line = rawLine.trim().replace(/^[-*•>\d.)\s]+/, '');
                if (!line) continue;
                const m = line.match(/^DIARY\s*\[([^\]]+)\]\s*[:：—–-]?\s*(.*)$/i)
                    || line.match(/^(?:ДНЕВНИК|ЗАПИСЬ)\s*\[([^\]]+)\]\s*[:：—–-]?\s*(.*)$/i)
                    || line.match(/^(?:DIARY|ДНЕВНИК|ЗАПИСЬ)\s+([^\[:：—–-]{2,45}?)\s*[:：—–-]\s*(.+)$/i);
                if (m) {
                    const rawName = m[1].trim();
                    const foundHero = allHeroes.find(h => normName(h.name) === normName(rawName) || isNameMentionedInText(h.name, rawName) || isNameMentionedInText(rawName, h.name));
                    currentHero = foundHero || null;
                    if (currentHero && m[2].trim()) {
                        parsedMap.set(currentHero, m[2].trim());
                    }
                    continue;
                }
                if (currentHero && !/^(DIARY|ДНЕВНИК|===)/i.test(line)) {
                    const prevTxt = parsedMap.get(currentHero) || '';
                    parsedMap.set(currentHero, (prevTxt ? prevTxt + ' ' : '') + line);
                }
            }

            const saveDate = useDate || s2.time?.date || '';
            for (const [heroObj, entryTxt] of parsedMap.entries()) {
                const finalTxt = String(entryTxt || '').replace(/^["«]|["»]$/g, '').trim();
                if (!finalTxt) continue;
                if (!Array.isArray(heroObj.diary)) heroObj.diary = [];
                heroObj.diary.push({ date: saveDate, text: finalTxt });
                if (heroObj.diary.length > 30) heroObj.diary.shift();
                addedCount++;
            }
            if (addedCount > 0) {
                await commit();
                toastr.success(`Записаны дневники сразу для ${addedCount} из ${allHeroes.length} героев за ${escapeHtml(dateLabel)}!`, '📓 Дневники всех героев', { escapeHtml: false });
            } else {
                toastr.warning('Модель не вернула строки DIARY [Имя] — попробуй ещё раз', '📓 Дневники всех героев');
            }
        });
    } finally {
        try { toastr.clear(toastNote); } catch (e) { /* ignore */ }
    }
    return addedCount;
}

async function openAllDiariesForDayModal(initialDate = '') {
    const st = store();
    if (!st) return toastr.warning('Сначала открой чат', '📓 Дневники героев');
    const mc = ensureMainCharCard(st);
    const sortedNpcs = [...(st.npcs || [])].sort((a, b) => (!!b.favorite - !!a.favorite) || a.id - b.id);
    const allHeroes = mc ? [mc, ...sortedNpcs] : sortedNpcs;

    const allDatesSet = new Set();
    if (st.time?.date) allDatesSet.add(st.time.date);
    (st.time?.timeline || []).forEach(e => { if (e.date) allDatesSet.add(e.date); });
    allHeroes.forEach(h => {
        (h.diary || []).forEach(d => { if (d.date) allDatesSet.add(d.date); });
    });
    const knownDates = Array.from(allDatesSet).filter(Boolean).sort().reverse();
    let selectedDate = initialDate || st.time?.date || knownDates[0] || '';

    const el = $('<div class="nnb-pop"></div>');
    const renderAll = () => {
        el.empty();
        el.append('<h3>📓 Личные дневники всех героев за день</h3>');
        el.append('<div class="nnb-pop-sub">Здесь можно одним нажатием получить дневниковые записи сразу всех персонажей за выбранный день. Каждый герой пишет строго со своей колокольни — только о том, что видел своими глазами (без ясновидения и чужих закрытых сцен!).</div>');

        const topBar = $('<div class="nnb-note" style="padding:10px 12px; margin:6px 0; display:flex; flex-direction:column; gap:8px;"></div>');
        const dateRow = $('<div style="display:flex; gap:8px; align-items:center; flex-wrap:wrap;"></div>');
        dateRow.append('<span style="font-weight:700; font-size:0.9em;">📅 День истории:</span>');
        const dateSel = $('<select class="text_pole" style="flex:1; min-width:180px; margin:0;"></select>');
        if (st.time?.date && !knownDates.includes(st.time.date)) {
            knownDates.unshift(st.time.date);
        }
        if (!knownDates.length) {
            dateSel.append('<option value="">Текущий день (по последним событиям)</option>');
        } else {
            knownDates.forEach(d => {
                const label = /^\d{4}-\d{2}-\d{2}$/.test(d) ? `${weekday(d)}, ${formatDate(d)}` : d;
                dateSel.append($('<option></option>').val(d).text(d === st.time?.date ? `Сегодня в истории: ${label}` : label));
            });
        }
        dateSel.append('<option value="__latest__">🕘 Показать последнюю запись каждого героя (за любой день)</option>');
        dateSel.append('<option value="__custom__">✏️ Вписать другую дату…</option>');
        if (selectedDate && (knownDates.includes(selectedDate) || selectedDate === '__latest__')) {
            dateSel.val(selectedDate);
        }

        const customInp = $('<input type="text" class="text_pole" style="display:none; width:100%;" placeholder="Например: 15 октября или Вечер пятницы">');
        dateSel.on('change', function () {
            const v = String($(this).val() || '');
            if (v === '__custom__') {
                customInp.show();
            } else {
                customInp.hide();
                selectedDate = v;
                renderAll();
            }
        });
        dateRow.append(dateSel);
        topBar.append(dateRow, customInp);

        const genAllBtn = $(`<div class="menu_button nnb-btn-primary" style="margin:0; padding:8px 12px; font-weight:700;"><i class="fa-solid fa-feather-pointed"></i> ✍️ Записать дневники сразу всех героев (${allHeroes.length} чел.) за этот день (1 запросом)</div>`).on('click', async () => {
            let targetD = String(dateSel.val() || '');
            if (targetD === '__latest__') targetD = st.time?.date || '';
            if (targetD === '__custom__') {
                const rawC = String(customInp.val() || '').trim();
                if (!rawC) return toastr.warning('Впиши дату или название дня', '📓 Дневники');
                targetD = parseDateText(rawC, st.time?.date || '2024-10-12') || rawC;
            }
            closePopupOf(el);
            const count = await generateAllNpcDiariesForDay(targetD);
            if (count > 0) {
                await openAllDiariesForDayModal(targetD || '__latest__');
            }
        });
        topBar.append(genAllBtn);
        el.append(topBar);

        const listWrap = $('<div style="display:flex; flex-direction:column; gap:8px; max-height:58vh; overflow-y:auto; padding-right:2px;"></div>');
        for (const h of allHeroes) {
            const entries = Array.isArray(h.diary) ? h.diary : [];
            const matching = selectedDate === '__latest__'
                ? (entries.length ? [entries[entries.length - 1]] : [])
                : entries.filter(e => (e.date || '') === selectedDate);
            const shownEntry = matching.length ? matching[matching.length - 1] : null;

            const card = $('<div class="nnb-note" style="padding:10px 12px; border-left:3px solid var(--SmartThemeQuoteColor, #8b78c4); margin:0;"></div>');
            const head = $('<div style="display:flex; justify-content:space-between; align-items:center; gap:8px; flex-wrap:wrap; margin-bottom:4px;"></div>');
            const titleLeft = $('<div style="display:flex; align-items:center; gap:8px;"></div>');
            if (h.avatar) {
                titleLeft.append($('<img alt="" style="width:30px; height:30px; border-radius:8px; object-fit:cover;">').attr('src', h.avatar));
            }
            const dateBadge = shownEntry?.date
                ? (/^\d{4}-\d{2}-\d{2}$/.test(shownEntry.date) ? formatDate(shownEntry.date) : shownEntry.date)
                : '';
            titleLeft.append($('<div style="font-weight:700; font-size:0.95em;"></div>').text(`${h.name}${h.favorite ? ' ❤️' : ''}${dateBadge ? ` · ${dateBadge}` : ''}`));
            head.append(titleLeft);

            const acts = $('<div style="display:flex; gap:6px; align-items:center;"></div>');
            const oneBtn = $('<div class="menu_button" style="margin:0; padding:3px 8px; font-size:0.78em; width:auto;" title="Сгенерировать/обновить запись только для этого героя"><i class="fa-solid fa-rotate"></i> Записать одному</div>').on('click', async () => {
                const useD = (selectedDate && selectedDate !== '__latest__' && selectedDate !== '__custom__') ? selectedDate : (st.time?.date || '');
                closePopupOf(el);
                const ok = await generateNpcDiaryForDate(h, useD);
                if (ok) await openAllDiariesForDayModal(useD || '__latest__');
            });
            const openFullBtn = $(`<div class="menu_button" style="margin:0; padding:3px 8px; font-size:0.78em; width:auto;" title="Открыть все страницы дневника ${escapeHtml(h.name)}"><i class="fa-solid fa-book-open"></i> Все записи (${entries.length})</div>`).on('click', () => {
                closePopupOf(el);
                openNpcDiaryPopup(h);
            });
            if (shownEntry) {
                const editBtn = $('<div class="menu_button" style="margin:0; padding:3px 7px; font-size:0.78em; width:auto;" title="Изменить эту запись"><i class="fa-solid fa-pen"></i></div>').on('click', async () => {
                    const updated = await askText(`Запись дневника (${h.name}):`, shownEntry.text);
                    if (updated && updated.trim()) {
                        shownEntry.text = stripActionTags(updated.trim());
                        await commit();
                        renderAll();
                    }
                });
                const delBtn = $('<div class="menu_button" style="margin:0; padding:3px 7px; font-size:0.78em; width:auto;" title="Удалить эту запись"><i class="fa-solid fa-trash"></i></div>').on('click', async () => {
                    const idx = h.diary.indexOf(shownEntry);
                    if (idx >= 0) h.diary.splice(idx, 1);
                    await commit();
                    renderAll();
                });
                acts.append(editBtn, delBtn);
            }
            acts.append(oneBtn, openFullBtn);
            head.append(acts);
            card.append(head);

            if (shownEntry) {
                card.append($('<div class="nnb-npc-text" style="font-style:italic; line-height:1.48; margin-top:4px;"></div>').text(shownEntry.text));
            } else {
                card.append('<div class="nnb-empty" style="margin:4px 0 0 0; font-size:0.85em;">За этот день записи ещё нет. Нажми «✍️ Записать дневники сразу всех героев» выше!</div>');
            }
            listWrap.append(card);
        }
        el.append(listWrap);
    };

    renderAll();
    await openPopup(el, true);
}

async function openNpcDiaryPopup(n, initialFilterDate = '') {
    const st = store();
    if (!st || !n) return;
    ensureNpcScales(n, st);

    // Автоматически очищаем старые записи от случайно попавших туда вариантов ответа (ACTIONS)
    if (Array.isArray(n.diary)) {
        n.diary.forEach(entry => {
            entry.text = stripActionTags(entry.text);
        });
    }

    let filterDate = initialFilterDate || '__all__';
    let pageIdx = Math.max(0, (n.diary || []).length - 1);

    const el = $('<div class="nnb-pop"></div>');
    const renderDiary = () => {
        el.empty();
        const headRow = $('<div style="display:flex; justify-content:space-between; align-items:center; gap:8px; flex-wrap:wrap;"></div>');
        headRow.append($('<h3 style="margin:0;"></h3>').text(`📓 Личный дневник: ${n.name}`));
        headRow.append($('<div class="menu_button" style="margin:0; padding:4px 10px; font-size:0.82em; width:auto;"><i class="fa-solid fa-books"></i> 📚 Дневники всех героев за день (разом)</div>').on('click', () => {
            closePopupOf(el);
            openAllDiariesForDayModal();
        }));
        el.append(headRow);
        el.append($('<div class="nnb-pop-sub"></div>').text(`Тайные записи от первого лица — о чём ${n.name} думает наедине с собой (строго по тем сценам, которые ${n.name} видел своими глазами, без ясновидения!).`));

        const entries = n.diary || [];

        // 1. Панель просмотра записей за определённые дни
        if (!entries.length) {
            el.append('<div class="nnb-empty" style="margin:10px 0;">В дневнике этого героя пока нет подсмотренных страниц. Выбери день ниже и нажми «Подсмотреть запись»!</div>');
        } else {
            const uniqueDates = [...new Set(entries.map(e => e.date || 'Без даты'))];
            const filterRow = $('<div style="display:flex; align-items:center; justify-content:space-between; gap:8px; margin:8px 0; flex-wrap:wrap; padding:6px 10px; border-radius:10px; background:color-mix(in srgb, var(--SmartThemeQuoteColor, #8b78c4) 10%, transparent);"></div>');

            const prevBtn = $('<div class="menu_button" style="padding:4px 10px; font-weight:600;"><i class="fa-solid fa-arrow-left"></i></div>');
            const nextBtn = $('<div class="menu_button" style="padding:4px 10px; font-weight:600;"><i class="fa-solid fa-arrow-right"></i></div>');
            const dateFilterSel = $('<select class="text_pole" style="flex:1; min-width:170px; margin:0;"></select>');
            dateFilterSel.append($('<option value="__single__"></option>').text(`📄 По страницам (${pageIdx + 1} из ${entries.length})`));
            dateFilterSel.append($('<option value="__all__"></option>').text(`📚 Все записи списком (${entries.length})`));
            uniqueDates.forEach(d => {
                const label = /^\d{4}-\d{2}-\d{2}$/.test(d) ? `📅 За день: ${formatDate(d)}` : `📅 ${d}`;
                dateFilterSel.append($('<option></option>').val(d).text(label));
            });
            if (filterDate !== '__all__' && filterDate !== '__single__' && !uniqueDates.includes(filterDate)) {
                filterDate = '__single__';
            }
            dateFilterSel.val(filterDate);

            dateFilterSel.on('change', function () {
                filterDate = String($(this).val() || '__single__');
                renderDiary();
            });
            prevBtn.on('click', () => {
                filterDate = '__single__';
                if (pageIdx > 0) pageIdx--;
                renderDiary();
            });
            nextBtn.on('click', () => {
                filterDate = '__single__';
                if (pageIdx < entries.length - 1) pageIdx++;
                renderDiary();
            });
            if (filterDate === '__single__') {
                prevBtn.css({ opacity: pageIdx <= 0 ? 0.35 : 1, pointerEvents: pageIdx <= 0 ? 'none' : 'auto' });
                nextBtn.css({ opacity: pageIdx >= entries.length - 1 ? 0.35 : 1, pointerEvents: pageIdx >= entries.length - 1 ? 'none' : 'auto' });
            }

            filterRow.append(prevBtn, dateFilterSel, nextBtn);
            el.append(filterRow);

            const shownEntries = filterDate === '__all__'
                ? [...entries].reverse()
                : filterDate === '__single__'
                    ? [entries[Math.max(0, Math.min(entries.length - 1, pageIdx))]].filter(Boolean)
                    : entries.filter(e => (e.date || 'Без даты') === filterDate);

            shownEntries.forEach(entry => {
                const page = $('<div class="nnb-note" style="padding:12px 14px; border-left:3px solid var(--SmartThemeQuoteColor, #8b78c4); margin:6px 0;"></div>');
                const head = $('<div style="display:flex; justify-content:space-between; align-items:center; margin-bottom:4px;"></div>');
                const dText = entry.date ? (/^\d{4}-\d{2}-\d{2}$/.test(entry.date) ? `${weekday(entry.date)}, ${formatDate(entry.date)}` : entry.date) : 'Запись дня';
                head.append($('<div class="nnb-meta" style="font-weight:700;"></div>').text(`📅 ${dText}`));
                const acts = $('<div class="nnb-actions"></div>');
                const editBtn = $('<i class="fa-solid fa-pen" title="Изменить запись"></i>').on('click', async () => {
                    const updated = await askText('Текст записи дневника', entry.text);
                    if (updated && updated.trim()) {
                        entry.text = stripActionTags(updated.trim());
                        await commit();
                        renderDiary();
                    }
                });
                const delBtn = $('<i class="fa-solid fa-trash" title="Удалить запись"></i>').on('click', async () => {
                    const idx = n.diary.indexOf(entry);
                    if (idx >= 0) n.diary.splice(idx, 1);
                    pageIdx = Math.max(0, n.diary.length - 1);
                    await commit();
                    renderDiary();
                });
                acts.append(editBtn, delBtn);
                head.append(acts);
                page.append(head);
                page.append($('<div class="nnb-npc-text" style="font-style:italic; line-height:1.5;"></div>').text(entry.text));
                el.append(page);
            });
        }

        // 2. Выбор дня и генерация новой записи (с авто-сворачиванием окна!)
        const genBox = $('<div class="nnb-note" style="margin-top:10px; padding:10px 12px;"></div>');
        genBox.append('<div style="font-weight:700; margin-bottom:6px;">✍️ Подсмотреть запись за выбранный день</div>');

        const knownStoryDates = [];
        if (st.time?.date) knownStoryDates.push(st.time.date);
        (st.time?.timeline || []).forEach(e => {
            if (e.date && !knownStoryDates.includes(e.date)) knownStoryDates.push(e.date);
        });
        knownStoryDates.sort().reverse();

        const dayRow = $('<div style="display:flex; gap:6px; align-items:center; flex-wrap:wrap; margin-bottom:8px;"></div>');
        const daySel = $('<select class="text_pole" style="flex:1; min-width:180px; margin:0;"></select>');
        if (st.time?.date) {
            daySel.append($('<option></option>').val(st.time.date).text(`Сегодня в истории: ${formatDate(st.time.date)}`));
        } else {
            daySel.append('<option value="">Текущий день (по последним событиям чата)</option>');
        }
        knownStoryDates.forEach(d => {
            if (d === st.time?.date) return;
            const evPreview = (st.time?.timeline || []).find(e => e.date === d)?.text || '';
            const shortEv = evPreview ? ` — ${evPreview.slice(0, 38)}${evPreview.length > 38 ? '…' : ''}` : '';
            daySel.append($('<option></option>').val(d).text(`${/^\d{4}-\d{2}-\d{2}$/.test(d) ? formatDate(d) : d}${shortEv}`));
        });
        daySel.append('<option value="__custom__">✏️ Вписать другую дату или день…</option>');

        const customDateInp = $('<input type="text" class="text_pole" style="display:none; width:100%; margin-top:4px;" placeholder="Напиши дату (например «14 октября» или «Вчера после вечеринки»)">');
        daySel.on('change', function () {
            customDateInp.toggle($(this).val() === '__custom__');
        });
        dayRow.append(daySel, customDateInp);
        genBox.append(dayRow);

        const genBtn = $('<div class="menu_button nnb-btn-primary"><i class="fa-solid fa-feather-pointed"></i> Подсмотреть запись за выбранный день (окно свернётся на время генерации)</div>').on('click', async () => {
            let targetDate = String(daySel.val() || '');
            if (targetDate === '__custom__') {
                const rawCustom = String(customDateInp.val() || '').trim();
                if (!rawCustom) return toastr.warning('Укажи дату или событие для записи', '📓 Дневник');
                const parsedIso = parseDateText(rawCustom, st.time?.date || '2024-10-12');
                targetDate = parsedIso || rawCustom;
            }
            // Сворачиваем окно на время генерации!
            closePopupOf(el);
            const ok = await generateNpcDiaryForDate(n, targetDate);
            if (ok) {
                await openNpcDiaryPopup(n, '__single__');
            }
        });
        genBox.append(genBtn);
        el.append(genBox);
    };

    renderDiary();
    await openPopup(el, true);
}

// ===================== 🪪 Готовая карточка персонажа и гардероб со штрихами =====================
async function generateDynastyFromChat() {
    const st = store();
    if (!st) return;
    const names = storyNames();
    await withBusy('Семейный архив: определяем семью и близкий круг по чату…', async s2 => {
        const prompt = `[OOC: Пауза в ролевой игре. Проанализируй текущий чат и описание персонажей (${names.user} и ${names.char}) и сформулируй их семейную историю (династию, родителей/родню, семейные традиции или конфликты) и близкий социальный круг (соседи, коллеги, друзья или недоброжелатели). Если каких-то деталей в чате ещё не было, органично додумай их в духе сеттинга и характеров героев.
Ответь ровно 3 строками без пояснений:
FAMILY_USER: кто в семье ${names.user}, какие у них отношения и семейная история (1–2 предложения)
FAMILY_CHAR: кто в семье ${names.char}, какие у них отношения и семейная история (1–2 предложения)
SOCIAL_CIRCLE: 2–3 человека из социального круга (коллеги, соседи, знакомые) и их роль]`;
        const raw = await quietGenerate(prompt);
        s2.dynasty = s2.dynasty || {};
        for (const line of answerLines(raw)) {
            let m = line.match(/^FAMILY_USER\s*[:：—–-]\s*(.+)$/i);
            if (m) { s2.dynasty.userFamily = m[1].trim().replace(/\]$/, ''); continue; }
            m = line.match(/^FAMILY_CHAR\s*[:：—–-]\s*(.+)$/i);
            if (m) { s2.dynasty.charFamily = m[1].trim().replace(/\]$/, ''); continue; }
            m = line.match(/^SOCIAL_CIRCLE\s*[:：—–-]\s*(.+)$/i);
            if (m) { s2.dynasty.socialCircle = m[1].trim().replace(/\]$/, ''); }
        }
        await commit();
    });
    toastr.success('Семья, династия и социальный круг сформированы по текущему чату!', 'Семья и круг общения');
}

function buildCharacterAndWardrobeView(st, opts = {}) {
    const wp = st.worldProfile || {};
    const names = storyNames();
    const wrap = $('<div class="nnb-char-sheet"></div>');

    const refreshSelf = () => {
        if (opts.inPopup) {
            const replacement = buildCharacterAndWardrobeView(st, opts);
            wrap.replaceWith(replacement);
        } else {
            renderDirection();
        }
    };

    // 1. Шапка карточки персонажа
    const cardBox = $('<div class="nnb-note" style="padding:12px 14px; border-radius:12px; border:1px solid color-mix(in srgb, var(--SmartThemeQuoteColor, #8b78c4) 45%, transparent); background:color-mix(in srgb, var(--SmartThemeQuoteColor, #8b78c4) 8%, transparent); margin-bottom:12px;"></div>');
    const topBar = $('<div style="display:flex; justify-content:space-between; align-items:flex-start; gap:10px; flex-wrap:wrap; margin-bottom:10px;"></div>');
    const titleBlock = $('<div style="display:flex; gap:12px; align-items:center;"></div>');
    const avatarHolder = $('<div style="width:60px; height:60px; border-radius:50%; overflow:hidden; border:2px solid var(--SmartThemeQuoteColor, #8b78c4); flex-shrink:0; display:none; background-size:cover; background-position:center;"></div>');
    const avPath = getPersonaAvatarPath();
    if (avPath) avatarHolder.css({ 'background-image': `url("${avPath}")`, display: 'block' });
    const nameAndPlace = $('<div></div>');
    nameAndPlace.append($('<div style="font-size:1.15em; font-weight:700;"></div>').text(names.user));
    const placeStr = [st.time?.city || wp.city, COUNTRIES[st.time?.country || wp.countryCode]?.name || st.time?.countryName || wp.countryName].filter(Boolean).join(', ');
    const dateStr = st.time?.date ? `${formatDate(st.time.date)} (${season(st.time.date).name})` : '';
    nameAndPlace.append($('<div class="nnb-npc-status" style="margin-top:2px;"></div>').text([placeStr, dateStr, formatMoney(st.wallet?.balance || 0, st)].filter(Boolean).join(' · ')));
    titleBlock.append(avatarHolder, nameAndPlace);

    const headBtns = $('<div style="display:flex; gap:6px; flex-wrap:wrap;"></div>');
    headBtns.append($('<div class="menu_button nnb-btn-primary" style="padding:4px 10px; font-size:0.85em;" title="Открыть комнату дома и расставить предметы (0 токенов)"><i class="fa-solid fa-house-chimney"></i> Мой дом</div>').on('click', () => {
        if (opts.closeModal) opts.closeModal();
        closeBook();
        openHomeModal();
    }));
    headBtns.append($(`<div class="menu_button" style="padding:4px 10px; font-size:0.85em;" title="Заготовленные темы для разговора"><i class="fa-solid fa-comments"></i> Темы (${(st.topics || []).length})</div>`).on('click', () => {
        if (opts.closeModal) opts.closeModal();
        closeBook();
        openTopicsPopup();
    }));
    headBtns.append($(`<div class="menu_button" style="padding:4px 10px; font-size:0.85em;" title="Мода и тренды сезона"><i class="fa-solid fa-fire"></i> Тренды (${(st.trends || []).length})</div>`).on('click', () => {
        if (opts.closeModal) opts.closeModal();
        closeBook();
        openTrendsModal();
    }));
    headBtns.append($('<div class="menu_button" style="padding:4px 10px; font-size:0.85em;" title="Изменить параметры мира или пересоздать"><i class="fa-solid fa-sliders"></i> Параметры мира</div>').on('click', () => {
        if (opts.closeModal) opts.closeModal();
        closeBook();
        openWorldCreator(true);
    }));
    topBar.append(titleBlock, headBtns);
    cardBox.append(topBar);

    const grid = $('<div style="display:grid; grid-template-columns:repeat(auto-fill, minmax(220px, 1fr)); gap:6px 12px; font-size:0.9em;"></div>');
    const addField = (label, val) => {
        if (!val) return;
        const item = $('<div style="line-height:1.35;"></div>');
        item.append($('<span style="opacity:0.75;"></span>').text(`${label}: `));
        item.append($('<span style="font-weight:600;"></span>').text(val));
        grid.append(item);
    };
    addField('Профессия', wp.job);
    addField('Жильё', wp.home);
    addField('Точка старта', wp.startVibe);
    addField('Достаток', wp.wealth);
    if (wp.pet && wp.pet !== 'Без питомца') addField('Питомец', wp.pet);
    const favNpcs = (st.npcs || []).filter(n => n.favorite).map(n => n.name);
    if (favNpcs.length) {
        addField('Фаворит', favNpcs.join(', '));
    } else if (wp.charRel) {
        addField('Романтическая линия', wp.freeWorld ? 'Свободная игра (фаворита выбираем по сюжету через ❤️)' : wp.charRel);
    }
    cardBox.append(grid);

    if (Array.isArray(wp.hobbies) && wp.hobbies.length) {
        const hobWrap = $('<div style="margin-top:8px; display:flex; gap:6px; flex-wrap:wrap; align-items:center;"></div>');
        hobWrap.append('<span style="font-size:0.85em; opacity:0.75;">Хобби:</span>');
        wp.hobbies.forEach(h => {
            hobWrap.append($('<span class="nnb-travel-chip active" style="padding:2px 8px; font-size:0.82em; cursor:default;"></span>').text(h));
        });
        cardBox.append(hobWrap);
    }

    // Сворачиваемый блок: Семья, династия и близкий круг (можно сгенерировать и в текущей ролевой!)
    const dynDet = $('<details class="nnb-section" style="margin-top:8px; padding-top:4px; border-top:1px solid var(--SmartThemeBorderColor);"><summary style="font-size:0.9em;">Семья, династия и социальный круг (нажми, чтобы раскрыть)</summary></details>');
    const dynInner = $('<div style="margin-top:6px; font-size:0.88em; display:flex; flex-direction:column; gap:4px;"></div>');
    if (st.dynasty?.userFamily || st.dynasty?.charFamily || st.dynasty?.socialCircle) {
        if (st.dynasty.userFamily) dynInner.append($('<div class="nnb-npc-status"></div>').text(`Семья ${names.user}: ${st.dynasty.userFamily}`));
        if (st.dynasty.charFamily) dynInner.append($('<div class="nnb-npc-status"></div>').text(`Семья ${names.char}: ${st.dynasty.charFamily}`));
        if (st.dynasty.socialCircle) dynInner.append($('<div class="nnb-npc-status"></div>').text(`Окружение: ${st.dynasty.socialCircle}`));
    } else {
        dynInner.append('<div class="nnb-npc-status" style="opacity:0.7;">Пока не заполнено. Нажми «Сгенерировать по чату» или впиши вручную!</div>');
    }
    const dynBtns = $('<div class="nnb-buttons" style="margin-top:4px;"></div>');
    dynBtns.append($('<div class="menu_button nnb-btn-primary" style="padding:3px 9px; font-size:0.82em;"><i class="fa-solid fa-wand-magic-sparkles"></i> Сгенерировать по текущему чату</div>').on('click', async () => {
        await generateDynastyFromChat();
        refreshSelf();
    }));
    dynBtns.append($('<div class="menu_button" style="padding:3px 9px; font-size:0.82em;"><i class="fa-solid fa-pen"></i> Изменить вручную</div>').on('click', async () => {
        st.dynasty = st.dynasty || {};
        const uf = await askText(`Семья и семейная история ${names.user}`, st.dynasty.userFamily || '');
        if (uf === null) return;
        const cf = await askText(`Семья и близкий круг ${names.char}`, st.dynasty.charFamily || '');
        if (cf === null) return;
        const sc = await askText('Социальный круг (соседи, коллеги, знакомые)', st.dynasty.socialCircle || '');
        if (sc === null) return;
        st.dynasty.userFamily = uf.trim();
        st.dynasty.charFamily = cf.trim();
        st.dynasty.socialCircle = sc.trim();
        await commit();
        refreshSelf();
    }));
    dynInner.append(dynBtns);
    dynDet.append(dynInner);
    cardBox.append(dynDet);

    // Сворачиваемый блок: Местный колорит (виден только при нажатии!)
    if (st.time?.flavor) {
        const flvDet = $('<details class="nnb-section" style="margin-top:6px;"><summary style="font-size:0.9em;">Местный колорит (нажми, чтобы раскрыть)</summary></details>');
        flvDet.append($('<div class="nnb-npc-status" style="margin-top:4px;"></div>').text(st.time.flavor));
        cardBox.append(flvDet);
    }

    wrap.append(cardBox);

    // 2. Сейчас надето (Наряд + Штрихи)
    const wornBanner = renderActiveWornBanner(st, refreshSelf);
    if (wornBanner) wrap.append(wornBanner);

    // 3. Гардероб по сезону
    const closet = st.wardrobe?.closet || [];
    const isWardOpen = st._uiOpenCloset !== undefined ? !!st._uiOpenCloset : false;
    const wardSec = $(`<details ${isWardOpen ? 'open' : ''} class="nnb-section" style="margin-top:10px;"><summary></summary></details>`);
    wardSec.find('summary').text(`Гардероб в шкафу (${closet.length}) — нажми на наряд, чтобы переодеться`);
    wardSec.on('toggle', function () { st._uiOpenCloset = this.open; });
    if (!closet.length) {
        wardSec.append('<div class="nnb-empty">В шкафу пока нет нарядов. Сгенерируй 5 новых вариантов одежды ниже!</div>');
    } else {
        const cGrid = $('<div style="display:grid; grid-template-columns:repeat(auto-fill, minmax(220px, 1fr)); gap:8px; margin-top:6px;"></div>');
        const a = st.wardrobe.active;
        closet.forEach(item => {
            const isWorn = a?.status === 'worn' && a.look?.title === item.title;
            const card = $('<div class="nnb-note" style="display:flex; gap:10px; align-items:flex-start; margin:0; cursor:pointer; transition:all 0.15s ease;"></div>');
            if (isWorn) {
                card.css({
                    'border': '2px solid var(--SmartThemeQuoteColor, #8b78c4)',
                    'background': 'color-mix(in srgb, var(--SmartThemeQuoteColor, #8b78c4) 14%, transparent)',
                });
            }
            if (item.image) {
                card.append(lookThumb(item, '76px', '110px'));
            }
            const info = $('<div style="flex:1; min-width:0;"></div>');
            info.append($('<div class="nnb-meta"></div>').text(`${item.category || 'Повседневный'}${isWorn ? ' · надето' : ''}`));
            info.append($('<div style="font-weight:600; font-size:0.95em; margin-top:2px;"></div>').text(`«${item.title}»`));
            info.append($('<div class="nnb-npc-status" style="font-size:0.82em; margin-top:3px;"></div>').text(item.desc));
            card.append(info);
            card.on('click', async () => {
                await wearFromCloset(item, '', true);
                refreshSelf();
            });
            cGrid.append(card);
        });
        wardSec.append(cGrid);
    }

    const missingPicsCount = closet.filter(c => !c.image).length + personalBoxItems(st).filter(x => !x.image).length;
    const wardActions = $('<div class="nnb-buttons" style="margin-top:8px; display:flex; gap:6px; flex-wrap:wrap;"></div>');
    wardActions.append($('<div class="menu_button"><i class="fa-solid fa-wand-magic-sparkles"></i> +5 новых вариантов одежды</div>').on('click', () => {
        if (opts.closeModal) opts.closeModal();
        closeBook();
        promptGenerateNewOutfits();
    }));
    wardActions.append($('<div class="menu_button"><i class="fa-solid fa-door-open"></i> Открыть полный шкаф</div>').on('click', () => {
        if (opts.closeModal) opts.closeModal();
        closeBook();
        openClosetPopup();
    }));
    if (missingPicsCount > 0) {
        wardActions.append($(`<div class="menu_button" title="Генерирует иллюстрации для тех нарядов, духов и аксессуаров в шкафу, у которых ещё нет картинки"><i class="fa-solid fa-palette"></i> Дорисовать картинки вещам без фото (${missingPicsCount})</div>`).on('click', async () => {
            if (opts.closeModal) opts.closeModal();
            await runDrawStarterVisuals(false);
            if (opts.inPopup) openCharacterCardPopup();
        }));
    }
    wardSec.append(wardActions);
    wrap.append(wardSec);

    // 4. Готовые штрихи: духи и аксессуары
    wrap.append(renderReadyAccentsBlock(st, refreshSelf));

    return wrap;
}

async function openCharacterCardPopup() {
    const st = store();
    if (!st) return toastr.warning('Сначала открой чат', 'Блокнот рассказчика');
    const el = $('<div class="nnb-pop nnb-pop-visual"><h3>🪪 Карточка героини и гардероб со штрихами</h3></div>');
    const view = buildCharacterAndWardrobeView(st, {
        inPopup: true,
        closeModal: () => closePopupOf(el),
    });
    el.append(view);
    await openPopup(el, true);
}

async function openWorldOverviewOrCreator() {
    const st = store();
    if (!st) return toastr.warning('Сначала открой чат', 'Блокнот рассказчика');
    if (st.worldProfile) {
        return openCharacterCardPopup();
    }
    return openWorldCreator(true);
}

async function openWorldCreator(forceEditor = false) {
    const st = store();
    if (!st) return toastr.warning('Сначала открой чат', 'Блокнот рассказчика');
    if (busy) return toastr.info('Модель уже занята — подожди пару секунд', 'Блокнот рассказчика');
    if (st.worldProfile && !forceEditor) {
        return openCharacterCardPopup();
    }

    const prev = st.worldProfile || {};
    const initStartVibe = prev.startVibe && WORLD_PRESETS.startVibes.includes(prev.startVibe) ? prev.startVibe : WORLD_PRESETS.startVibes[0];
    const cfg = {
        countryCode: st.time?.country || prev.countryCode || 'UK',
        countryName: st.time?.countryName || prev.countryName || '',
        city: st.time?.city || prev.city || 'Лондон',
        date: st.time?.date || prev.date || '2024-10-12',
        home: prev.home || WORLD_PRESETS.homes[0],
        startVibe: initStartVibe,
        job: prev.job || WORLD_PRESETS.jobs[0],
        hobbies: Array.isArray(prev.hobbies) && prev.hobbies.length ? [...prev.hobbies] : [WORLD_PRESETS.hobbies[0], WORLD_PRESETS.hobbies[2]],
        wealth: prev.wealth || WORLD_PRESETS.wealths[0],
        pet: prev.pet || WORLD_PRESETS.pets[0],
        charRel: prev.charRel || WORLD_PRESETS.charModes[0].label.replace(/\{\{char\}\}/g, storyNames().char),
        freeWorld: prev.freeWorld !== undefined ? prev.freeWorld : true,
    };

    const el = $('<div class="nnb-pop nnb-world-creator"><h3>🌍 Создание мира и стартового набора</h3></div>');
    el.append('<div class="nnb-pop-sub">Компактный конструктор старта: выбирай из выпадающих списков, крути 🎲 или вписывай своё через ✏️. По кнопке <b>«Создать мир»</b> плагин сгенерирует 5 локаций с крючками, NPC, <b>5 нарядов по сезону с картинками, 5 духов и 5 аксессуаров с картинками</b> и сразу откроет готовую карточку персонажа!</div>');

    if (st.worldProfile) {
        const backRow = $('<div style="margin-bottom:8px;"></div>');
        backRow.append($('<div class="menu_button" style="display:inline-flex; width:auto; padding:4px 10px; font-size:0.85em;"><i class="fa-solid fa-id-card"></i> Открыть готовую карточку персонажа и гардероб</div>').on('click', () => {
            closePopupOf(el);
            openCharacterCardPopup();
        }));
        el.append(backRow);
    }

    const buildSelectSection = (title, options, getVal, setVal, askLabel, onAfterChange) => {
        const sec = $('<div style="margin-top:10px;"></div>');
        sec.append($('<div class="nnb-travel-sec-title" style="margin-bottom:4px;"></div>').text(title));
        const row = $('<div style="display:flex; gap:6px; align-items:center;"></div>');
        const select = $('<select class="text_pole" style="flex:1; margin:0;"></select>');
        const diceBtn = $('<div class="menu_button" style="padding:5px 9px;" title="Случайный вариант"><i class="fa-solid fa-dice"></i></div>');
        const penBtn = $('<div class="menu_button" style="padding:5px 9px;" title="Вписать свой вариант"><i class="fa-solid fa-pen"></i></div>');

        const renderOptions = () => {
            select.empty();
            const cur = getVal();
            const allOpts = options.includes(cur) || !cur ? options : [...options, cur];
            allOpts.forEach(opt => {
                select.append($('<option></option>').val(opt).text(opt));
            });
            select.val(cur);
        };
        select.on('change', () => {
            setVal(String(select.val() || ''));
            if (onAfterChange) onAfterChange();
        });
        diceBtn.on('click', () => {
            setVal(pickRandom(options));
            renderOptions();
            if (onAfterChange) onAfterChange();
        });
        penBtn.on('click', async () => {
            const custom = await askText(askLabel || title, getVal());
            if (custom && custom.trim()) {
                setVal(custom.trim());
                renderOptions();
                if (onAfterChange) onAfterChange();
            }
        });
        renderOptions();
        row.append(select, diceBtn, penBtn);
        sec.append(row);
        el.append(sec);
        return sec;
    };

    // 1. Страна и город
    const locSec = $('<div style="margin-top:10px;"></div>');
    locSec.append('<div class="nnb-travel-sec-title" style="margin-bottom:4px;">🗺 1. Страна и город (или мир)</div>');
    const locRow = $('<div style="display:flex; gap:6px; align-items:center; flex-wrap:wrap;"></div>');
    const countrySelect = $('<select class="text_pole" style="flex:1; min-width:140px; margin:0;"></select>');
    const citySelect = $('<select class="text_pole" style="flex:1; min-width:140px; margin:0;"></select>');
    const locDice = $('<div class="menu_button" style="padding:5px 9px;" title="Случайная страна и город"><i class="fa-solid fa-dice"></i></div>');
    const locPen = $('<div class="menu_button" style="padding:5px 9px;" title="Вписать свою страну и город"><i class="fa-solid fa-pen"></i></div>');

    let selectedPresetCountry = WORLD_PRESETS.countries.find(c => c.code === cfg.countryCode && c.code !== 'other') || WORLD_PRESETS.countries[0];
    let updateWalletPreview = () => {};

    const renderLocSelects = () => {
        countrySelect.empty();
        WORLD_PRESETS.countries.forEach((cObj, idx) => {
            countrySelect.append($('<option></option>').val(String(idx)).text(cObj.label));
        });
        const cIdx = Math.max(0, WORLD_PRESETS.countries.indexOf(selectedPresetCountry));
        countrySelect.val(String(cIdx));

        citySelect.empty();
        const cities = [...selectedPresetCountry.cities];
        if (cfg.city && !cities.includes(cfg.city)) cities.push(cfg.city);
        cities.forEach(cStr => {
            citySelect.append($('<option></option>').val(cStr).text(cStr));
        });
        citySelect.val(cfg.city);
        updateWalletPreview();
    };

    countrySelect.on('change', () => {
        const idx = Number(countrySelect.val()) || 0;
        selectedPresetCountry = WORLD_PRESETS.countries[idx] || WORLD_PRESETS.countries[0];
        cfg.countryCode = selectedPresetCountry.code === 'other' ? '' : selectedPresetCountry.code;
        cfg.countryName = selectedPresetCountry.code === 'other' ? selectedPresetCountry.countryName : '';
        cfg.city = selectedPresetCountry.cities[0];
        renderLocSelects();
    });

    citySelect.on('change', () => {
        const cityStr = String(citySelect.val() || '');
        if (cityStr.includes(',')) {
            const [cPart, cnPart] = cityStr.split(',').map(x => x.trim());
            cfg.city = cPart;
            cfg.countryName = cnPart;
            cfg.countryCode = '';
        } else {
            cfg.city = cityStr;
        }
        updateWalletPreview();
    });

    locDice.on('click', () => {
        selectedPresetCountry = pickRandom(WORLD_PRESETS.countries);
        const rawCity = pickRandom(selectedPresetCountry.cities);
        if (rawCity.includes(',')) {
            const [cPart, cnPart] = rawCity.split(',').map(x => x.trim());
            cfg.city = cPart;
            cfg.countryName = cnPart;
            cfg.countryCode = '';
        } else {
            cfg.city = rawCity;
            cfg.countryCode = selectedPresetCountry.code === 'other' ? '' : selectedPresetCountry.code;
            cfg.countryName = selectedPresetCountry.code === 'other' ? selectedPresetCountry.countryName : '';
        }
        renderLocSelects();
    });

    locPen.on('click', async () => {
        const cn = await askText('Страна или название мира (например «Италия», «Южная Корея», «Королевство Эльфов»)', COUNTRIES[cfg.countryCode]?.name || cfg.countryName || '');
        if (cn === null) return;
        const ct = await askText('Город или конкретное место старта', cfg.city);
        if (ct === null) return;
        const detected = detectCountry(cn);
        cfg.countryCode = detected || '';
        cfg.countryName = detected ? '' : cn.trim();
        if (ct.trim()) cfg.city = ct.trim();
        renderLocSelects();
    });

    locRow.append(countrySelect, citySelect, locDice, locPen);
    locSec.append(locRow);
    el.append(locSec);

    // 2. Сезон и стартовая дата
    const seasSec = $('<div style="margin-top:10px;"></div>');
    seasSec.append('<div class="nnb-travel-sec-title" style="margin-bottom:4px;">🍂 2. Сезон и стартовая дата</div>');
    const seasRow = $('<div style="display:flex; gap:6px; align-items:center;"></div>');
    const seasSelect = $('<select class="text_pole" style="flex:1; margin:0;"></select>');
    WORLD_PRESETS.seasons.forEach(sObj => {
        seasSelect.append($('<option></option>').val(sObj.date).text(sObj.label));
    });
    const dateInput = $('<input type="date" class="text_pole" style="width:150px; margin:0;">').val(cfg.date);
    const syncSeasonSelect = () => {
        const curS = cfg.date ? season(cfg.date).name : 'осень';
        const match = WORLD_PRESETS.seasons.find(sObj => sObj.label.toLowerCase().includes(curS)) || WORLD_PRESETS.seasons[0];
        seasSelect.val(match.date);
    };
    syncSeasonSelect();
    seasSelect.on('change', () => {
        cfg.date = String(seasSelect.val() || '2024-10-12');
        dateInput.val(cfg.date);
    });
    dateInput.on('change', () => {
        if (dateInput.val()) {
            cfg.date = dateInput.val();
            syncSeasonSelect();
        }
    });
    seasRow.append(seasSelect, dateInput);
    seasSec.append(seasRow);
    el.append(seasSec);

    // 3. Жильё героини
    buildSelectSection('🏢 3. Где живёт твоя героиня', WORLD_PRESETS.homes, () => cfg.home, v => { cfg.home = v; }, 'Где живёт твоя героиня?');

    // 4. Точка старта
    buildSelectSection('🧭 4. Точка старта в городе', WORLD_PRESETS.startVibes, () => cfg.startVibe, v => { cfg.startVibe = v; }, 'Точка старта / атмосфера');

    // 5. Профессия
    const jobHint = $('<div class="nnb-pop-sub" style="margin-top:3px;"></div>');
    const updateJobHint = () => {
        jobHint.text(isShopOwnerJob(cfg.job)
            ? '🏪 Для хозяйки лавки модель сразу создаст 3 стартовых товара на витрине с автоматической наценкой +50%!'
            : '');
        jobHint.toggle(isShopOwnerJob(cfg.job));
    };
    const jobSec = buildSelectSection('💼 5. Профессия / занятие героини', WORLD_PRESETS.jobs, () => cfg.job, v => { cfg.job = v; }, 'Профессия или занятие твоей героини', updateJobHint);
    jobSec.append(jobHint);
    updateJobHint();

    // 6. Хобби и увлечения
    const hobSec = $('<div style="margin-top:10px;"></div>');
    hobSec.append('<div class="nnb-travel-sec-title" style="margin-bottom:4px;">🎨 6. Хобби и увлечения (можно выбрать несколько)</div>');
    const hobRow = $('<div style="display:flex; gap:6px; align-items:center;"></div>');
    const hobSelect = $('<select class="text_pole" style="flex:1; margin:0;"></select>');
    const hobDice = $('<div class="menu_button" style="padding:5px 9px;" title="Выбрать 2–3 случайных хобби"><i class="fa-solid fa-dice"></i></div>');
    const hobPen = $('<div class="menu_button" style="padding:5px 9px;" title="Вписать своё хобби"><i class="fa-solid fa-pen"></i></div>');
    const hobTags = $('<div class="nnb-chips-row nnb-travel-chips" style="margin-top:6px;"></div>');
    const allHobbies = [...WORLD_PRESETS.hobbies];

    const renderHobbies = () => {
        cfg.hobbies.forEach(h => { if (!allHobbies.includes(h)) allHobbies.push(h); });
        hobSelect.empty();
        hobSelect.append($('<option value=""></option>').text(`Выбрано хобби: ${cfg.hobbies.length} — нажми, чтобы добавить/убрать…`));
        allHobbies.forEach(h => {
            const active = cfg.hobbies.includes(h);
            hobSelect.append($('<option></option>').val(h).text(`${active ? '✓ ' : '+ '}${h}`));
        });
        hobSelect.val('');

        hobTags.empty();
        cfg.hobbies.forEach(h => {
            const tag = $('<div class="nnb-travel-chip active" style="padding:3px 9px; font-size:0.84em;" title="Нажми, чтобы убрать" tabindex="0"></div>').text(`${h} ✕`);
            tag.on('click', () => {
                if (cfg.hobbies.length > 1) {
                    cfg.hobbies = cfg.hobbies.filter(x => x !== h);
                    renderHobbies();
                } else {
                    toastr.info('Оставь хотя бы одно увлечение или выбери другое из списка', '🎨 Хобби');
                }
            });
            hobTags.append(tag);
        });
    };

    hobSelect.on('change', () => {
        const val = String(hobSelect.val() || '');
        if (!val) return;
        if (cfg.hobbies.includes(val)) {
            if (cfg.hobbies.length > 1) cfg.hobbies = cfg.hobbies.filter(x => x !== val);
        } else {
            cfg.hobbies.push(val);
        }
        renderHobbies();
    });
    hobDice.on('click', () => {
        const count = 2 + (Math.random() < 0.5 ? 1 : 0);
        cfg.hobbies = shuffle(allHobbies).slice(0, count);
        renderHobbies();
    });
    hobPen.on('click', async () => {
        const custom = await askText('Добавить своё хобби или увлечение');
        if (custom && custom.trim()) {
            const val = custom.trim();
            if (!allHobbies.includes(val)) allHobbies.push(val);
            if (!cfg.hobbies.includes(val)) cfg.hobbies.push(val);
            renderHobbies();
        }
    });
    renderHobbies();
    hobRow.append(hobSelect, hobDice, hobPen);
    hobSec.append(hobRow, hobTags);
    el.append(hobSec);

    // 7. Достаток и стартовый кошелёк
    const walletHint = $('<div class="nnb-pop-sub" style="margin-top:3px;"></div>');
    updateWalletPreview = () => {
        const cur = detectCurrencyForPlace(cfg.countryCode, cfg.countryName, cfg.city);
        const bal = startingBalanceForWealth(cfg.wealth, cur);
        walletHint.text(`💰 Стартовый капитал в кошельке: ${bal.toLocaleString('ru-RU')} ${cur} (рассчитан автоматически по стране и достатку)`);
    };
    const wealthSec = buildSelectSection('💎 7. Достаток и стартовый бюджет', WORLD_PRESETS.wealths, () => cfg.wealth, v => { cfg.wealth = v; }, 'Достаток героини', updateWalletPreview);
    wealthSec.append(walletHint);
    renderLocSelects();

    // 8. Домашний питомец
    buildSelectSection('🐾 8. Домашний питомец', WORLD_PRESETS.pets, () => cfg.pet, v => { cfg.pet = v; }, 'Какой питомец живёт дома?');

    // 9. Формат романтики / Кем приходится {{char}}
    const charName = storyNames().char;
    const charModes = WORLD_PRESETS.charModes.map(m => ({ ...m, text: m.label.replace(/\{\{char\}\}/g, charName) }));
    const relSec = $('<div style="margin-top:10px;"></div>');
    relSec.append('<div class="nnb-travel-sec-title" style="margin-bottom:4px;">💞 9. Любовный интерес и роль карточки на старте</div>');
    const relRow = $('<div style="display:flex; gap:6px; align-items:center;"></div>');
    const relSelect = $('<select class="text_pole" style="flex:1; margin:0;"></select>');
    const relPen = $('<div class="menu_button" style="padding:5px 9px;" title="Вписать свой вариант"><i class="fa-solid fa-pen"></i></div>');
    const relHint = $('<div class="nnb-pop-sub" style="margin-top:4px;"></div>');

    const renderRelSelect = () => {
        relSelect.empty();
        charModes.forEach(m => {
            relSelect.append($('<option></option>').val(m.text).text(m.text));
        });
        if (cfg.charRel && !charModes.some(m => m.text === cfg.charRel)) {
            relSelect.append($('<option></option>').val(cfg.charRel).text(cfg.charRel));
        }
        relSelect.val(cfg.charRel);
        relHint.text(cfg.freeWorld
            ? '💡 В режиме «Свободная игра без стартового любовного интереса» переписывать карточку потом НЕ нужно — любого приглянувшегося NPC можно в 1 клик сделать главным фаворитом через ❤️ во вкладке «👥 Герои».'
            : `На старте учитывается связь с ${charName}: ${cfg.charRel}`);
    };
    relSelect.on('change', () => {
        const val = String(relSelect.val() || '');
        cfg.charRel = val;
        const found = charModes.find(m => m.text === val);
        cfg.freeWorld = found ? found.freeWorld : false;
        renderRelSelect();
    });
    relPen.on('click', async () => {
        const custom = await askText(`Кем приходится ${charName} на старте?`, cfg.charRel);
        if (custom && custom.trim()) {
            cfg.charRel = custom.trim();
            cfg.freeWorld = false;
            renderRelSelect();
        }
    });
    renderRelSelect();
    relRow.append(relSelect, relPen);
    relSec.append(relRow, relHint);
    el.append(relSec);

    // Кнопки запуска
    const actRow = $('<div class="nnb-pop-row" style="margin-top:16px; gap:10px;"></div>');
    const createBtn = $('<div class="menu_button nnb-btn-primary" style="flex:1; padding:10px 14px; font-weight:600; text-align:center;"><i class="fa-solid fa-wand-magic-sparkles"></i> Создать мир: 5 локаций + NPC + 5 нарядов, 5 духов и 5 аксессуаров с картинками</div>');
    const saveOnlyProfileBtn = $('<div class="menu_button" title="Сохранить настройки и открыть карточку персонажа"><i class="fa-solid fa-floppy-disk"></i> Только сохранить параметры</div>');

    const applyBaseSettings = () => {
        st.worldProfile = { ...cfg };
        st.direction.time = true;
        st.direction.map = true;
        st.direction.npcs = true;
        st.direction.wardrobe = true;
        st.direction.livingWorld = true;
        st.direction.shopMode = isShopOwnerJob(cfg.job);
        st.time.date = cfg.date;
        st.time.country = cfg.countryCode;
        st.time.countryName = cfg.countryName;
        st.time.city = cfg.city;
        const cur = detectCurrencyForPlace(cfg.countryCode, cfg.countryName, cfg.city);
        const bal = startingBalanceForWealth(cfg.wealth, cur);
        st.wallet = { balance: bal, currency: cur };
    };

    saveOnlyProfileBtn.on('click', async () => {
        applyBaseSettings();
        closePopupOf(el);
        await commit();
        renderDirection();
        toastr.success(`Параметры сохранены! Стартовый кошелёк: ${formatMoney(st.wallet.balance, st)}`, '🌍 Создание мира');
        await openCharacterCardPopup();
    });

    createBtn.on('click', async () => {
        applyBaseSettings();
        closePopupOf(el);
        await commit();
        renderDirection();
        await withBusy('🌍 Создаём мир, 5 локаций с крючками, NPC, 5 нарядов, 5 духов и 5 аксессуаров…', async s2 => {
            const raw = await quietGenerate(buildWorldCreationPrompt(s2, cfg));
            s2.lastRaw = String(raw ?? '');
            const counts = applyWorldCreationResult(s2, cfg, raw);
            if (settings().events && s2.time.date) await holidayStep(s2);
            if (wantImages()) {
                await drawWorldStarterVisuals(s2, false);
            }
            const counterNote = counts.counter ? ` · На прилавке: ${counts.counter} тов.` : '';
            toastr.success(
                `Готово! На карте: ${counts.places} лок. · NPC: ${counts.npcs} · В шкафу: ${counts.closet} нарядов · Духи: ${counts.perfumes} · Аксессуары: ${counts.accessories}${counterNote}`,
                '🌍 Мир создан!',
                { timeOut: 10000 }
            );
        });
        renderDirection();
        await openCharacterCardPopup();
    });

    actRow.append(createBtn, saveOnlyProfileBtn);
    el.append(actRow);

    await openPopup(el, true);
}

