                        const pPromptBtn = $('<div class="menu_button" style="padding:3px 8px; font-size:0.76em; margin:0;" title="Открыть промпт этой страницы или перерисовать её"><i class="fa-solid fa-pen-to-square"></i> Промпт / 🔄</div>');
